window.KG_DATA = {"strands": {"num": "Numbers & Operations", "alg": "Algebra, Sets & Functions", "geo": "Geometry", "mea": "Measurement & Mensuration", "dat": "Data, Statistics & Probability", "tri": "Trigonometry", "cal": "Calculus", "vec": "Vectors & 3D Geometry"}, "nodes": [{"id": "g1.num.counting-to-9", "title": "Counting and Numbers 1–9", "grade": 1, "strand": "num", "description": "Counting tells us how many things there are. We say one number name for each object, and the last number we say tells the size of the whole group. This idea — that numbers stand for 'how many' — is the foundation of all arithmetic.", "prereqs": [], "outcomes": ["Can count up to 9 objects, touching each object exactly once", "Can say how many objects there are after counting, without recounting", "Can recognise and write the numerals 1 to 9", "Can count out a requested number of objects from a larger pile"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": [{"id": "g1.num.counting-to-9.one-to-one-counting", "parent": "g1.num.counting-to-9", "title": "Touch and Count: One Number per Object", "description": "Counting a small group by touching each object exactly once while saying exactly one number name for it. Nothing gets skipped, nothing gets counted twice.", "outcomes": ["Can touch-count up to 9 objects, one number name per object", "Can slide counted objects into a 'done' pile so none are skipped or repeated"], "prereqs": [], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.num.counting-to-9.cardinality-last-number", "parent": "g1.num.counting-to-9", "title": "The Last Number Tells How Many", "description": "Understanding that after counting a group, the last number said is the size of the WHOLE group — you can answer 'how many?' without counting again.", "outcomes": ["Can answer 'how many?' with the last number counted, without recounting", "Can say how many objects are hiding after they are covered"], "prereqs": ["g1.num.counting-to-9.one-to-one-counting"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g1.num.counting-to-9.counting-any-order", "parent": "g1.num.counting-to-9", "title": "Still the Same Number: Count in Any Order", "description": "Discovering that a group keeps its number when the objects are moved, spread out or counted in a different order. Rearranging changes how it looks, not how many.", "outcomes": ["Can predict that a rearranged group still has the same count", "Can count the same group starting from different objects and get the same answer"], "prereqs": ["g1.num.counting-to-9.cardinality-last-number"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g1.num.counting-to-9.comparing-groups", "parent": "g1.num.counting-to-9", "title": "More, Fewer or the Same", "description": "Comparing two small groups by matching objects one-to-one or by counting both, and saying which group has more, which has fewer, or that they are the same.", "outcomes": ["Can match two groups object-to-object to see which has more", "Can use the words more, fewer and same correctly for groups up to 9"], "prereqs": ["g1.num.counting-to-9.cardinality-last-number"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g1.num.counting-to-9.writing-numerals", "parent": "g1.num.counting-to-9", "title": "Reading and Writing 1 to 9", "description": "Recognising the numerals 1 to 9, matching each numeral to a group of that many objects, and writing the numerals with correct strokes.", "outcomes": ["Can point to the right numeral for a counted group", "Can write the numerals 1 to 9 legibly", "Can count out a requested number of objects from a bigger pile"], "prereqs": ["g1.num.counting-to-9.cardinality-last-number"], "est_minutes": 20, "difficulty": 1, "question": false}]}, {"id": "g1.num.zero", "title": "Zero and Its Meaning", "grade": 1, "strand": "num", "description": "Zero is the number that tells us there is nothing to count. It is a real number with its own symbol, 0, and its own place on the number line just before 1. Understanding zero prepares us for place value and for adding and subtracting.", "prereqs": ["g1.num.counting-to-9"], "outcomes": ["Can say that zero means 'none' and write the numeral 0", "Can place 0 correctly before 1 when ordering numbers", "Can answer 'how many' questions where the answer is zero", "Can add and take away zero from a small number correctly"], "difficulty": 1, "est_minutes": 15, "stub": false, "micros": [{"id": "g1.num.zero.zero-means-none", "parent": "g1.num.zero", "title": "Zero Means None", "description": "Meeting zero as the number for 'nothing there': an empty plate, an empty nest. Zero is a real number and a perfectly good answer to 'how many?'.", "outcomes": ["Can answer 'how many?' with zero when a group is empty", "Can say that zero means 'none' or 'nothing to count'"], "prereqs": ["g1.num.counting-to-9.cardinality-last-number"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g1.num.zero.writing-zero", "parent": "g1.num.zero", "title": "Writing the Numeral 0", "description": "Writing the symbol 0 and using it as an answer: whenever a count comes out empty, we write 0 just like any other number.", "outcomes": ["Can write the numeral 0", "Can write 0 as the answer when a group is empty"], "prereqs": ["g1.num.zero.zero-means-none", "g1.num.counting-to-9.writing-numerals"], "est_minutes": 10, "difficulty": 1, "question": false}, {"id": "g1.num.zero.zero-before-one", "parent": "g1.num.zero", "title": "Zero's Home: Just Before 1", "description": "Placing zero in the number order — counting down 3, 2, 1, 0 and starting the number line at 0, just before 1.", "outcomes": ["Can count down to zero (3, 2, 1, 0)", "Can place 0 before 1 when ordering number cards"], "prereqs": ["g1.num.zero.zero-means-none"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g1.num.zero.adding-taking-away-zero", "parent": "g1.num.zero", "title": "Adding and Taking Away Zero", "description": "Seeing with objects that adding zero or taking away zero changes nothing: 6 + 0 = 6 and 6 − 0 = 6. An empty plate joined to your plate adds no biscuits.", "outcomes": ["Can answer n + 0 and n − 0 correctly for small numbers", "Can explain with objects why adding zero changes nothing"], "prereqs": ["g1.num.zero.zero-means-none"], "est_minutes": 10, "difficulty": 1, "question": true}]}, {"id": "g1.num.numbers-to-20", "title": "Numbers up to 20", "grade": 1, "strand": "num", "description": "The numbers 10 to 20 are our first step beyond one hand and one foot of counting! Each 'teen' number is really a ten and some more — 14 is 10 and 4. Seeing this hidden ten is the first big idea of place value.", "prereqs": ["g1.num.counting-to-9", "g1.num.zero"], "outcomes": ["Can count objects up to 20 accurately", "Can read and write numerals 10 to 20 and say them in order", "Can show a teen number as one group of ten and some ones", "Can say which of two numbers up to 20 is more"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": [{"id": "g1.num.numbers-to-20.counting-objects-to-20", "parent": "g1.num.numbers-to-20", "title": "Counting On Up to 20", "description": "Saying the counting sequence from 1 to 20 without gaps and counting up to 20 objects accurately, with extra care on the tricky teen words.", "outcomes": ["Can say the numbers 1 to 20 in order with no skips", "Can count up to 20 objects accurately"], "prereqs": ["g1.num.counting-to-9.one-to-one-counting", "g1.num.counting-to-9.cardinality-last-number"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.num.numbers-to-20.teen-numbers-ten-and-more", "parent": "g1.num.numbers-to-20", "title": "Teen Numbers: A Ten and Some More", "description": "Building every teen number as one full group of ten plus loose ones — 14 is 10 and 4. Ten-frames and bundles make the hidden ten visible.", "outcomes": ["Can show a teen number as one bundle of ten and loose ones", "Can say how many tens and how many ones are in a teen number"], "prereqs": ["g1.num.numbers-to-20.counting-objects-to-20"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g1.num.numbers-to-20.reading-writing-teens", "parent": "g1.num.numbers-to-20", "title": "Reading and Writing 10 to 20", "description": "Reading and writing the numerals 10 to 20, writing the ten FIRST even though English says the ones first ('four-teen' is written 14, not 41).", "outcomes": ["Can write the numeral for any spoken teen number", "Can read 10 to 20 correctly without reversing digits"], "prereqs": ["g1.num.numbers-to-20.teen-numbers-ten-and-more", "g1.num.counting-to-9.writing-numerals"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.num.numbers-to-20.ordering-to-20", "parent": "g1.num.numbers-to-20", "title": "Before, After and Between up to 20", "description": "Saying which number comes just before, just after or between given numbers up to 20, and arranging shuffled number cards in order starting from 0.", "outcomes": ["Can say the number just before and just after any number up to 20", "Can arrange number cards 0 to 20 in order"], "prereqs": ["g1.num.numbers-to-20.counting-objects-to-20", "g1.num.zero.zero-before-one"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g1.num.numbers-to-20.comparing-to-20", "parent": "g1.num.numbers-to-20", "title": "Which Number Is More?", "description": "Comparing two numbers up to 20 using counting order and ten-frames: the number that comes later in counting is more.", "outcomes": ["Can say which of two numbers up to 20 is more and which is less", "Can explain the answer using counting order or ten-frames"], "prereqs": ["g1.num.numbers-to-20.ordering-to-20", "g1.num.counting-to-9.comparing-groups"], "est_minutes": 10, "difficulty": 1, "question": false}]}, {"id": "g1.num.add-sub-within-20", "title": "Addition and Subtraction within 20", "grade": 1, "strand": "num", "description": "Adding means putting groups together; subtracting means taking away or finding how many more. With numbers up to 20 we learn smart moves like counting on from the bigger number and making a ten. These small facts become the building blocks for all bigger sums.", "prereqs": ["g1.num.numbers-to-20"], "outcomes": ["Can add two numbers with a total up to 20 using objects, fingers or counting on", "Can subtract within 20 by taking away or counting back", "Can solve simple story problems about joining and taking away", "Can find the missing number in facts like 9 + __ = 15"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g1.num.add-sub-within-20.addition-as-joining", "parent": "g1.num.add-sub-within-20", "title": "Adding Is Putting Together", "description": "Joining two small groups of objects and counting all of them to find the total. Meeting the plus sign and writing simple addition sentences like 3 + 2 = 5.", "outcomes": ["Can join two groups of objects and count the total", "Can write a matching addition sentence with + and =", "Can act out simple joining stories"], "prereqs": ["g1.num.counting-to-9.cardinality-last-number", "g1.num.numbers-to-20.counting-objects-to-20"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g1.num.add-sub-within-20.counting-on-to-add", "parent": "g1.num.add-sub-within-20", "title": "Counting On from the Bigger Number", "description": "Adding by putting the bigger number 'in your head' and counting on only the new jumps: for 9 + 4, say 9... then 10, 11, 12, 13. The start number is already done.", "outcomes": ["Can add within 20 by counting on from the bigger number", "Can show the jumps on fingers without counting the start number"], "prereqs": ["g1.num.add-sub-within-20.addition-as-joining", "g1.num.numbers-to-20.ordering-to-20"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.num.add-sub-within-20.subtraction-as-taking-away", "parent": "g1.num.add-sub-within-20", "title": "Subtracting Is Taking Away", "description": "Taking objects away from a group and counting what is left. Meeting the minus sign and discovering that order matters — you cannot take away more than you have.", "outcomes": ["Can act out take-away stories and count what is left", "Can write a matching subtraction sentence with − and =", "Can explain why 4 − 9 cannot be acted out with real objects"], "prereqs": ["g1.num.add-sub-within-20.addition-as-joining", "g1.num.zero.zero-means-none"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.num.add-sub-within-20.counting-back-to-subtract", "parent": "g1.num.add-sub-within-20", "title": "Counting Back to Subtract", "description": "Subtracting a small number by counting backwards from the start: for 11 − 2, say 11... then 10, 9. Count the jumps back, not the starting number.", "outcomes": ["Can subtract within 20 by counting back", "Can count the jumps back without counting the start number as a jump"], "prereqs": ["g1.num.add-sub-within-20.subtraction-as-taking-away", "g1.num.zero.zero-before-one"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.num.add-sub-within-20.make-a-ten", "parent": "g1.num.add-sub-within-20", "title": "The Make-a-Ten Trick", "description": "Adding across ten by filling the ten first: for 8 + 5, give 2 to the 8 to make 10, then add the 3 that is left — 13. Ten-frames make the move visible.", "outcomes": ["Can break the smaller number to make a ten and then add the rest", "Can show the make-a-ten move on a ten-frame"], "prereqs": ["g1.num.add-sub-within-20.counting-on-to-add", "g1.num.numbers-to-20.teen-numbers-ten-and-more"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g1.num.add-sub-within-20.missing-number-facts", "parent": "g1.num.add-sub-within-20", "title": "Missing Number Facts and the Balance Meaning of =", "description": "Finding the missing number in facts like 5 + __ = 9, reading '=' as 'is the same as' — both sides of the equals sign must balance like a seesaw.", "outcomes": ["Can find the missing number in facts like 9 + __ = 15", "Can say whether number sentences like 6 + 1 = 5 + 2 are true or false"], "prereqs": ["g1.num.add-sub-within-20.counting-on-to-add", "g1.num.add-sub-within-20.subtraction-as-taking-away"], "est_minutes": 20, "difficulty": 2, "question": true}]}, {"id": "g1.num.numbers-to-99", "title": "Numbers up to 99: Tens and Ones", "grade": 1, "strand": "num", "description": "Big numbers are built from groups of ten. In the number 47, the 4 stands for 4 tens (forty) and the 7 stands for 7 ones. Once you can see tens and ones inside a number, you can read, write and compare any number up to 99.", "prereqs": ["g1.num.numbers-to-20"], "outcomes": ["Can count to 99 including across decade numbers (39 to 40, 59 to 60)", "Can say how many tens and ones are in any 2-digit number", "Can read and write 2-digit numbers from words and bundles", "Can skip count by tens (10, 20, 30, ...)"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g1.num.numbers-to-99.bundles-of-ten", "parent": "g1.num.numbers-to-99", "title": "Making Bundles of Ten", "description": "Grouping loose sticks into bundles of ten and counting bundles by tens: 3 bundles means 10, 20, 30. Groups of ten are the building blocks of big numbers.", "outcomes": ["Can bundle loose objects into groups of ten", "Can count bundles by tens: 10, 20, 30, ..."], "prereqs": ["g1.num.numbers-to-20.teen-numbers-ten-and-more"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g1.num.numbers-to-99.tens-and-ones", "parent": "g1.num.numbers-to-99", "title": "Tens and Ones Inside a Number", "description": "Seeing that a 2-digit number is made of tens and ones: 47 is 4 bundles of ten (forty) and 7 loose ones. The place of a digit tells what it is worth.", "outcomes": ["Can say how many tens and ones are in any 2-digit number", "Can build a given 2-digit number from bundles and loose sticks"], "prereqs": ["g1.num.numbers-to-99.bundles-of-ten"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g1.num.numbers-to-99.reading-writing-2-digit", "parent": "g1.num.numbers-to-99", "title": "Reading and Writing 2-digit Numbers", "description": "Writing 2-digit numbers from their names using place-value cards: 'sixty-three' is the 60 card with the 3 sliding over the 0 — two digits, 63, never 603.", "outcomes": ["Can write the numeral for a spoken 2-digit number", "Can read any 2-digit number aloud correctly"], "prereqs": ["g1.num.numbers-to-99.tens-and-ones", "g1.num.numbers-to-20.reading-writing-teens"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.num.numbers-to-99.crossing-decades", "parent": "g1.num.numbers-to-99", "title": "Counting Past 39, 49, 59...", "description": "Counting smoothly across decade numbers: after 49 the ten ones bundle into a new ten, making 50. The 100-chart shows the same jump at the end of every row.", "outcomes": ["Can count on across any decade (39 to 40, 59 to 60) without stalling", "Can explain with bundles why 49 + 1 makes 50"], "prereqs": ["g1.num.numbers-to-99.tens-and-ones", "g1.num.numbers-to-20.counting-objects-to-20"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.num.numbers-to-99.skip-counting-by-tens", "parent": "g1.num.numbers-to-99", "title": "Skip Counting by Tens", "description": "Counting by tens from 10 to 90 — forwards and backwards — and noticing that the ones digit stays 0 while the tens digit climbs.", "outcomes": ["Can skip count by tens: 10, 20, 30, ... 90", "Can continue a tens count from any decade number"], "prereqs": ["g1.num.numbers-to-99.bundles-of-ten"], "est_minutes": 10, "difficulty": 1, "question": false}]}, {"id": "g1.num.money-intro", "title": "Money: Recognising Coins and Notes", "grade": 1, "strand": "num", "description": "Money comes as coins and notes, and each one has a value printed on it — ₹1, ₹2, ₹5, ₹10 and more. The value is what matters, not the size or the number of pieces. Knowing coins and notes lets us buy things and count small amounts.", "prereqs": ["g1.num.numbers-to-20"], "outcomes": ["Can name the common coins (₹1, ₹2, ₹5, ₹10) and notes (₹10, ₹20, ₹50)", "Can compare two coins or notes by value using the printed number", "Can find the total of two or three small coins and notes", "Can show the same amount using different coins"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": [{"id": "g1.num.money-intro.naming-coins-notes", "parent": "g1.num.money-intro", "title": "Naming Coins and Notes", "description": "Recognising and naming the common coins (₹1, ₹2, ₹5, ₹10) and notes (₹10, ₹20, ₹50) by reading the value printed on each one.", "outcomes": ["Can name the common coins and notes", "Can find and read the printed value on any coin or note"], "prereqs": ["g1.num.numbers-to-20.reading-writing-teens"], "est_minutes": 10, "difficulty": 1, "question": false}, {"id": "g1.num.money-intro.comparing-coin-values", "parent": "g1.num.money-intro", "title": "Which Is Worth More?", "description": "Comparing coins and notes by the printed number, not by size or shininess. A small ₹2 coin beats a big old ₹1 coin.", "outcomes": ["Can compare two coins or notes by their printed values", "Can explain that a coin's size does not decide its value"], "prereqs": ["g1.num.money-intro.naming-coins-notes", "g1.num.numbers-to-20.comparing-to-20"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g1.num.money-intro.totalling-small-amounts", "parent": "g1.num.money-intro", "title": "Adding Up Coins and Notes", "description": "Finding the total of two or three small coins and notes by counting on from the biggest value: a ₹10 note and a ₹2 coin make 10... 11, 12.", "outcomes": ["Can find the total of two or three coins and notes", "Can count on by each piece's value, not by pieces"], "prereqs": ["g1.num.money-intro.naming-coins-notes", "g1.num.add-sub-within-20.counting-on-to-add"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.num.money-intro.same-amount-different-coins", "parent": "g1.num.money-intro", "title": "Same Money, Different Coins", "description": "Showing one amount in different ways — two ₹5 coins are worth the same as one ₹10 coin. Fewer pieces can still be more money.", "outcomes": ["Can show a small amount using different sets of coins", "Can check whether two sets of coins are worth the same by adding values"], "prereqs": ["g1.num.money-intro.totalling-small-amounts"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g1.geo.shapes-around-us", "title": "Shapes Around Us: Solids and Flat Shapes", "grade": 1, "strand": "geo", "description": "Everything around us has a shape. Solid objects like balls, boxes and cans can roll, slide or stack, while flat shapes like circles, triangles, squares and rectangles live on paper and on the faces of solids. Naming and sorting shapes trains us to see the world like a mathematician.", "prereqs": [], "outcomes": ["Can name circle, triangle, square and rectangle in any size or turn", "Can sort everyday objects by whether they roll, slide or stack", "Can tell a flat (2D) shape from a solid (3D) object", "Can find shapes hiding in everyday things (a roti is round, a door is a rectangle)"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": [{"id": "g1.geo.shapes-around-us.naming-flat-shapes", "parent": "g1.geo.shapes-around-us", "title": "Circle, Triangle, Square, Rectangle", "description": "Naming the four basic flat shapes and telling them apart by counting sides and corners: a triangle has 3, a square and rectangle have 4, a circle has none.", "outcomes": ["Can name circle, triangle, square and rectangle", "Can count the sides and corners of a flat shape"], "prereqs": [], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.geo.shapes-around-us.shapes-any-size-or-turn", "parent": "g1.geo.shapes-around-us", "title": "Still the Same Shape: Any Size, Any Turn", "description": "Recognising shapes even when they are turned, tilted, skinny or huge. A tilted square is still a square; a long thin triangle is still a triangle — check the sides and corners, not the pose.", "outcomes": ["Can recognise a square, triangle or rectangle in any turn or size", "Can decide 'triangle or not' by counting 3 straight sides and 3 corners"], "prereqs": ["g1.geo.shapes-around-us.naming-flat-shapes"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.geo.shapes-around-us.roll-slide-stack", "parent": "g1.geo.shapes-around-us", "title": "Roll, Slide or Stack?", "description": "Exploring solid objects with hands: round things like balls roll, flat-faced things like boxes slide and stack, and a can does both. Sorting solids by what they can do.", "outcomes": ["Can sort everyday solids by whether they roll, slide or stack", "Can explain that round parts roll and flat parts slide or stack"], "prereqs": [], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g1.geo.shapes-around-us.flat-vs-solid", "parent": "g1.geo.shapes-around-us", "title": "Flat Shapes and Solid Objects", "description": "Telling a flat (2D) shape from a solid (3D) object: a ball is a solid, not a 'circle' — the circle is what you see when you trace or stamp a solid's face on paper.", "outcomes": ["Can tell whether something is a flat shape or a solid object", "Can predict what flat shape a solid's face will print or trace"], "prereqs": ["g1.geo.shapes-around-us.naming-flat-shapes", "g1.geo.shapes-around-us.roll-slide-stack"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.geo.shapes-around-us.shapes-in-everyday-things", "parent": "g1.geo.shapes-around-us", "title": "Shape Hunt: Shapes Hiding Around Us", "description": "Finding shapes in everyday things on a shape hunt — a roti is round like a circle, a door is a rectangle, a samosa face is a triangle — and saying which shape is seen.", "outcomes": ["Can find and name shapes in everyday objects", "Can collect and share examples of each shape from home or class"], "prereqs": ["g1.geo.shapes-around-us.flat-vs-solid"], "est_minutes": 15, "difficulty": 1, "question": false}]}, {"id": "g1.mea.compare-lengths", "title": "Comparing Length, Weight and Capacity", "grade": 1, "strand": "mea", "description": "We compare things all the time: which pencil is longer, which bag is heavier, which glass holds more. To compare fairly we must line things up from the same end, feel or balance their weight, and pour to check what holds more. Careful comparing is the first step of all measurement.", "prereqs": [], "outcomes": ["Can use the words longer/shorter, taller/shorter, heavier/lighter, holds more/holds less correctly", "Can compare two lengths by lining objects up from the same end", "Can guess and then check which of two objects is heavier", "Can order three objects by length"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": [{"id": "g1.mea.compare-lengths.comparing-words", "parent": "g1.mea.compare-lengths", "title": "The Right Comparing Words", "description": "Using the precise words of comparing: longer/shorter, taller/shorter, heavier/lighter, holds more/holds less — instead of saying 'big' for everything.", "outcomes": ["Can pick the right comparing word for a situation", "Can say the opposite of each comparing word"], "prereqs": [], "est_minutes": 10, "difficulty": 1, "question": false}, {"id": "g1.mea.compare-lengths.lining-up-ends", "parent": "g1.mea.compare-lengths", "title": "Fair Length Tests: Same Starting Line", "description": "Comparing two lengths fairly by putting both objects' starting ends on the same line before looking at which reaches farther. Catching the trick when one object is pushed ahead.", "outcomes": ["Can line up two objects from the same end before comparing", "Can spot an unfair comparison where the starting ends are offset"], "prereqs": ["g1.mea.compare-lengths.comparing-words"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.mea.compare-lengths.ordering-three-lengths", "parent": "g1.mea.compare-lengths", "title": "Shortest to Longest", "description": "Ordering three objects by length from shortest to longest using the same-starting-line rule, and using words like 'the longest' and 'the shortest'.", "outcomes": ["Can order three objects from shortest to longest", "Can point out the longest and the shortest of three objects"], "prereqs": ["g1.mea.compare-lengths.lining-up-ends"], "est_minutes": 10, "difficulty": 1, "question": false}, {"id": "g1.mea.compare-lengths.heavier-lighter", "parent": "g1.mea.compare-lengths", "title": "Heavier or Lighter?", "description": "Comparing weights by holding one object in each hand or using a simple pan balance — and discovering that bigger does NOT always mean heavier.", "outcomes": ["Can guess and then check which of two objects is heavier", "Can give an example where the smaller object is heavier"], "prereqs": ["g1.mea.compare-lengths.comparing-words"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.mea.compare-lengths.holds-more-less", "parent": "g1.mea.compare-lengths", "title": "Which Holds More?", "description": "Comparing how much two containers hold by pouring with a small cup and counting cupfuls. A tall thin bottle can hold less than a short wide pot — pouring tells the truth.", "outcomes": ["Can compare two containers by pouring and counting cupfuls", "Can explain that taller does not always mean holds more"], "prereqs": ["g1.mea.compare-lengths.comparing-words"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g1.mea.time-day-events", "title": "Time: Day, Night and Ordering Events", "grade": 1, "strand": "mea", "description": "Our day has a rhythm: morning, afternoon, evening and night, and things happen in an order — we wake up before we go to school. Talking about before, after, day and night, and which activity takes longer is how we begin to understand time.", "prereqs": [], "outcomes": ["Can name the parts of the day (morning, afternoon, evening, night) and match activities to them", "Can put 3-4 daily events in the right order using before and after", "Can use yesterday, today and tomorrow correctly in conversation", "Can say which of two activities takes longer"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": [{"id": "g1.mea.time-day-events.day-and-night", "parent": "g1.mea.time-day-events", "title": "Day and Night", "description": "Telling day from night by looking at the sky — sun means day, moon and stars mean night — not by what we happen to be doing. A nap in the afternoon still happens in the day.", "outcomes": ["Can tell whether it is day or night from the sky", "Can name things that happen in the day and at night"], "prereqs": [], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g1.mea.time-day-events.parts-of-the-day", "parent": "g1.mea.time-day-events", "title": "Morning, Afternoon, Evening, Night", "description": "Naming the four parts of the day in order and matching everyday activities to them: breakfast in the morning, play in the evening, sleep at night.", "outcomes": ["Can say the parts of the day in order", "Can match common activities to the right part of the day"], "prereqs": ["g1.mea.time-day-events.day-and-night"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g1.mea.time-day-events.ordering-events", "parent": "g1.mea.time-day-events", "title": "First, Next, Last: Before and After", "description": "Putting 3-4 daily events in order and using before, after, yesterday, today and tomorrow correctly, anchored to real remembered events.", "outcomes": ["Can put 3-4 picture cards of daily events in the right order", "Can use before/after and yesterday/today/tomorrow correctly"], "prereqs": ["g1.mea.time-day-events.parts-of-the-day"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.mea.time-day-events.which-takes-longer", "parent": "g1.mea.time-day-events", "title": "Which Takes Longer?", "description": "Comparing how long two activities take using a fair measure — claps, steps or a sand timer — because boring things only FEEL long. Feelings are not clocks.", "outcomes": ["Can say which of two activities takes longer", "Can time short activities by counting claps or using a sand timer"], "prereqs": ["g1.mea.time-day-events.ordering-events", "g1.num.counting-to-9.one-to-one-counting"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g1.alg.patterns-repeat", "title": "Repeating Patterns", "grade": 1, "strand": "alg", "description": "A repeating pattern is made of a small unit that comes again and again, like red-blue, red-blue. If you can find the unit, you can say exactly what comes next — that is the power of a pattern. Spotting and extending patterns is the very beginning of algebraic thinking.", "prereqs": [], "outcomes": ["Can copy and extend a repeating pattern of colours, shapes, sounds or actions", "Can point out the unit that repeats in a pattern", "Can create an own repeating pattern and explain its rule", "Can tell a real pattern from a random arrangement"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": [{"id": "g1.alg.patterns-repeat.copy-extend-patterns", "parent": "g1.alg.patterns-repeat", "title": "Copy It, Continue It", "description": "Copying a simple repeating pattern (red-blue, red-blue) with beads, claps or drawings, and continuing it correctly by following the repeat — not by copying the last item.", "outcomes": ["Can copy a simple AB pattern of colours, shapes, sounds or actions", "Can say and place what comes next in an AB pattern"], "prereqs": [], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.alg.patterns-repeat.find-the-unit", "parent": "g1.alg.patterns-repeat", "title": "Find the Chunk That Repeats", "description": "Circling the whole unit that repeats in a pattern — including trickier units like clap-stomp-stomp, where the doubled element must be counted twice.", "outcomes": ["Can point out or circle the repeating unit of a pattern", "Can extend ABB and AAB patterns one whole unit at a time"], "prereqs": ["g1.alg.patterns-repeat.copy-extend-patterns"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.alg.patterns-repeat.pattern-or-not", "parent": "g1.alg.patterns-repeat", "title": "Pattern or Not?", "description": "Telling a true pattern from a random arrangement with one test: can you say for sure what comes next? If yes, it is a pattern; if not, it is just decoration.", "outcomes": ["Can decide whether an arrangement is a pattern or random", "Can use the 'what comes next?' test and explain the answer"], "prereqs": ["g1.alg.patterns-repeat.find-the-unit"], "est_minutes": 10, "difficulty": 2, "question": true}, {"id": "g1.alg.patterns-repeat.make-your-own-pattern", "parent": "g1.alg.patterns-repeat", "title": "Make Your Own Pattern", "description": "Creating an own repeating pattern with beads, stamps, sounds or body moves, saying its rule aloud, and challenging a friend to continue it.", "outcomes": ["Can create a repeating pattern and say its unit aloud", "Can check whether a friend continued the pattern correctly"], "prereqs": ["g1.alg.patterns-repeat.find-the-unit"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g1.dat.sort-classify", "title": "Sorting and Classifying Objects", "grade": 1, "strand": "dat", "description": "Sorting means putting things into groups by a rule — by colour, by shape, by size, or by what they are used for. The same objects can be sorted in different ways, but within one sort the rule must stay the same. Sorting is how we begin to organise information, the first step towards handling data.", "prereqs": [], "outcomes": ["Can sort a set of objects by a given rule (colour, shape, size, use)", "Can state the rule used to sort a given group of objects", "Can re-sort the same objects using a different rule", "Can say which group has more or fewer objects after sorting"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": [{"id": "g1.dat.sort-classify.sort-by-one-rule", "parent": "g1.dat.sort-classify", "title": "Sort by One Rule", "description": "Sorting objects into groups by one spoken rule (colour, shape, size or use) and sticking to that rule for every single object — no switching midway.", "outcomes": ["Can sort a set of objects by a given rule", "Can check each object against the rule card before placing it"], "prereqs": [], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g1.dat.sort-classify.name-the-rule", "parent": "g1.dat.sort-classify", "title": "Guess My Rule", "description": "Looking at an already-sorted group and working out the rule: asking 'what is the SAME about everything in this pile?' — a shared attribute, not a story or a favourite.", "outcomes": ["Can state the rule used to sort a given group", "Can say what is the same about all objects in a pile"], "prereqs": ["g1.dat.sort-classify.sort-by-one-rule"], "est_minutes": 10, "difficulty": 2, "question": true}, {"id": "g1.dat.sort-classify.every-object-a-home", "parent": "g1.dat.sort-classify", "title": "Every Object Gets a Home", "description": "Finishing a sort completely: a good rule splits ALL the objects, so nothing is left over. Using an 'others' or 'not-red' group for things that don't fit the first pile.", "outcomes": ["Can sort every object, using a 'not-...' group when needed", "Can re-sort the same objects with a different rule"], "prereqs": ["g1.dat.sort-classify.sort-by-one-rule"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g1.dat.sort-classify.count-compare-groups", "parent": "g1.dat.sort-classify", "title": "Count the Groups: More or Fewer?", "description": "After sorting, counting how many objects landed in each group and saying which group has more, which has fewer — our very first step of reading data.", "outcomes": ["Can count the objects in each sorted group", "Can say which group has more and which has fewer"], "prereqs": ["g1.dat.sort-classify.sort-by-one-rule", "g1.num.counting-to-9.comparing-groups"], "est_minutes": 10, "difficulty": 1, "question": false}]}, {"id": "g2.num.place-value-2digit", "title": "Place Value: Comparing and Ordering to 99", "grade": 2, "strand": "num", "description": "A digit's value depends on WHERE it sits: in 47, the 4 means forty. To compare two numbers we look at the tens first, and only if the tens match do we check the ones. This lets us order any set of numbers up to 99 with certainty.", "prereqs": ["g1.num.numbers-to-99"], "outcomes": ["Can write any 2-digit number in expanded form (47 = 40 + 7)", "Can compare two 2-digit numbers by checking tens first, then ones", "Can order three or more numbers from smallest to greatest and greatest to smallest", "Can find the number that is 1 more, 1 less, 10 more or 10 less than a given number"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": [{"id": "g2.num.place-value-2digit.expanded-form", "parent": "g2.num.place-value-2digit", "title": "Pulling Numbers Apart: Tens and Ones", "description": "See any 2-digit number as tens plus ones: 47 is 4 tens and 7 ones, so 47 = 40 + 7. Compose numbers from 'so many tens and so many ones' and decompose them back.", "outcomes": ["Can write any 2-digit number in expanded form (47 = 40 + 7)", "Can write the number for a given count of tens and ones (6 tens 2 ones = 62)"], "prereqs": ["g1.num.numbers-to-99"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.num.place-value-2digit.compare-two-numbers", "parent": "g2.num.place-value-2digit", "title": "Which Number Is Bigger? Tens First", "description": "Compare two 2-digit numbers by checking the tens digit first; only if the tens match do we look at the ones. Same digits in different places make different numbers.", "outcomes": ["Can compare two 2-digit numbers by checking tens first, then ones", "Can explain why 47 and 74 are different numbers"], "prereqs": ["g2.num.place-value-2digit.expanded-form"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.num.place-value-2digit.order-numbers", "parent": "g2.num.place-value-2digit", "title": "Lining Numbers Up in Order", "description": "Order three or more 2-digit numbers from smallest to greatest and greatest to smallest by comparing tens first, then ones, and reading the asked direction carefully.", "outcomes": ["Can order three or more numbers from smallest to greatest and greatest to smallest", "Can place a given number between its neighbours on a number line or 100-chart"], "prereqs": ["g2.num.place-value-2digit.compare-two-numbers"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.num.place-value-2digit.ten-more-ten-less", "parent": "g2.num.place-value-2digit", "title": "1 More, 1 Less, 10 More, 10 Less", "description": "Jump around the 100-chart: adding or taking 1 changes the ones digit, while adding or taking 10 changes only the tens digit. This builds fast mental moves for later addition.", "outcomes": ["Can say the number that is 1 more, 1 less, 10 more or 10 less than any 2-digit number", "Can explain which digit changes when we add ten and why"], "prereqs": ["g2.num.place-value-2digit.expanded-form"], "est_minutes": 15, "difficulty": 1, "question": true}]}, {"id": "g2.num.numbers-to-999", "title": "Numbers up to 999: Hundreds", "grade": 2, "strand": "num", "description": "After tens come hundreds: ten tens bundle into one hundred. A 3-digit number like 407 has hundreds, tens and ones — and a zero can hold a place to show 'no tens'. With hundreds we can count, read and compare numbers all the way to 999.", "prereqs": ["g2.num.place-value-2digit"], "outcomes": ["Can explain that 10 tens make 1 hundred", "Can read and write 3-digit numbers from words and from hundreds-tens-ones", "Can write a 3-digit number in expanded form (263 = 200 + 60 + 3)", "Can compare and order 3-digit numbers by checking hundreds first"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g2.num.numbers-to-999.ten-tens-make-hundred", "parent": "g2.num.numbers-to-999", "title": "Ten Tens Make One Hundred", "description": "Bundle ten tens-rods into one hundred-square and count in hundreds: 100, 200, 300 ... 900. The hundred is a new, bigger bundle that sits to the left of the tens.", "outcomes": ["Can explain that 10 tens make 1 hundred", "Can count forwards and backwards in hundreds up to 900"], "prereqs": ["g2.num.place-value-2digit.expanded-form"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g2.num.numbers-to-999.read-write-3digit", "parent": "g2.num.numbers-to-999", "title": "Reading and Writing 3-digit Numbers", "description": "Turn number words like 'two hundred sixty-three' into figures and back, using a hundreds-tens-ones mat. Three places means exactly three digits — never more.", "outcomes": ["Can read and write 3-digit numbers from words and from hundreds-tens-ones", "Can build a 3-digit number on a place-value mat with arrow cards"], "prereqs": ["g2.num.numbers-to-999.ten-tens-make-hundred"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g2.num.numbers-to-999.zero-placeholder", "parent": "g2.num.numbers-to-999", "title": "Zero Holds the Place", "description": "Numbers like 407 or 630 have an empty place — no tens, or no ones. The zero sits in that place to hold it, so the other digits keep their true values.", "outcomes": ["Can write numbers with an empty tens or ones place using a placeholder zero", "Can read numbers like 407 and 630 correctly aloud"], "prereqs": ["g2.num.numbers-to-999.read-write-3digit", "g1.num.zero"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.num.numbers-to-999.expanded-form-3digit", "parent": "g2.num.numbers-to-999", "title": "Expanded Form with Hundreds", "description": "Stretch a 3-digit number into hundreds, tens and ones: 263 = 200 + 60 + 3. Snap the parts back together to rebuild the number.", "outcomes": ["Can write a 3-digit number in expanded form (263 = 200 + 60 + 3)", "Can rebuild a number from its expanded parts"], "prereqs": ["g2.num.numbers-to-999.read-write-3digit", "g2.num.place-value-2digit.expanded-form"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g2.num.numbers-to-999.compare-order-3digit", "parent": "g2.num.numbers-to-999", "title": "Comparing 3-digit Numbers: Hundreds First", "description": "Compare and order numbers up to 999 by checking hundreds first, then tens, then ones. Four flat hundreds beat three flat hundreds no matter what loose pieces come after.", "outcomes": ["Can compare and order 3-digit numbers by checking hundreds first", "Can explain why 400 is greater than 389 even though 8 and 9 look big"], "prereqs": ["g2.num.numbers-to-999.expanded-form-3digit", "g2.num.place-value-2digit.compare-two-numbers"], "est_minutes": 20, "difficulty": 2, "question": true}]}, {"id": "g2.num.add-sub-2digit", "title": "2-digit Addition and Subtraction with Regrouping", "grade": 2, "strand": "num", "description": "When we add and the ones spill over ten, we bundle them into a new ten — that is carrying. When we subtract and the ones are not enough, we open up a ten — that is borrowing. Regrouping lets us add and subtract any numbers up to 99 quickly and correctly.", "prereqs": ["g1.num.add-sub-within-20", "g2.num.place-value-2digit"], "outcomes": ["Can add two 2-digit numbers with and without carrying", "Can subtract 2-digit numbers with and without borrowing", "Can explain regrouping using bundles of tens and ones", "Can check an answer using estimation or the opposite operation", "Can solve one-step story problems involving 2-digit addition and subtraction"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g2.num.add-sub-2digit.add-no-regroup", "parent": "g2.num.add-sub-2digit", "title": "Adding 2-digit Numbers without Carrying", "description": "Add numbers like 23 + 45 by adding ones with ones and tens with tens, when the ones do not spill over ten. Line the columns up and add each place.", "outcomes": ["Can add two 2-digit numbers when no carrying is needed", "Can explain that ones add with ones and tens add with tens"], "prereqs": ["g1.num.add-sub-within-20", "g2.num.place-value-2digit.expanded-form"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g2.num.add-sub-2digit.add-with-carry", "parent": "g2.num.add-sub-2digit", "title": "Adding with Carrying", "description": "When the ones add up to ten or more, bundle ten of them into a new ten and carry it to the tens column. Ten ones can never stay in the ones place.", "outcomes": ["Can add two 2-digit numbers that need carrying", "Can show the carry with base-ten blocks: ten ones swap for one ten-rod"], "prereqs": ["g2.num.add-sub-2digit.add-no-regroup"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g2.num.add-sub-2digit.sub-no-regroup", "parent": "g2.num.add-sub-2digit", "title": "Subtracting without Borrowing", "description": "Subtract numbers like 57 - 24 by taking ones from ones and tens from tens, when the top ones digit is big enough. Always start from the ones column.", "outcomes": ["Can subtract 2-digit numbers when no borrowing is needed", "Can check a subtraction by adding the answer back"], "prereqs": ["g2.num.add-sub-2digit.add-no-regroup"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g2.num.add-sub-2digit.sub-with-borrow", "parent": "g2.num.add-sub-2digit", "title": "Subtracting with Borrowing", "description": "When the ones are not enough, open up a ten: one ten-rod breaks into ten ones, the tens go down by one, and now we can subtract. Estimation helps check the answer makes sense.", "outcomes": ["Can subtract 2-digit numbers that need borrowing", "Can show borrowing with blocks: break one ten into ten ones", "Can use estimation to spot an impossible answer"], "prereqs": ["g2.num.add-sub-2digit.sub-no-regroup", "g2.num.add-sub-2digit.add-with-carry"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g2.num.add-sub-2digit.word-problems-choose-operation", "parent": "g2.num.add-sub-2digit", "title": "Story Problems: Add or Subtract?", "description": "Read a one-step story, decide whether it asks for joining (add) or taking away or comparing (subtract), then solve and check that the answer fits the story.", "outcomes": ["Can choose the right operation for a one-step story problem", "Can solve 2-digit story problems and check the answer against the story"], "prereqs": ["g2.num.add-sub-2digit.add-with-carry", "g2.num.add-sub-2digit.sub-with-borrow"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g2.num.mult-intro", "title": "Multiplication as Equal Groups and Repeated Addition", "grade": 2, "strand": "num", "description": "Multiplication is a shortcut for adding the same number again and again. '3 × 4' means 3 equal groups of 4 — like 3 plates with 4 laddoos each — and equals 4 + 4 + 4. Arrays of rows and columns show why 3 × 4 and 4 × 3 give the same total.", "prereqs": ["g1.num.add-sub-within-20"], "outcomes": ["Can describe a multiplication like 3 × 4 as '3 groups of 4'", "Can write repeated addition (5 + 5 + 5) as multiplication (3 × 5) and back", "Can find totals of equal groups by skip counting", "Can arrange objects in rows and columns (arrays) and count them two ways"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": [{"id": "g2.num.mult-intro.equal-groups", "parent": "g2.num.mult-intro", "title": "Equal Groups: 3 Plates of 4", "description": "Multiplication starts with groups that are all the SAME size: 3 plates with 4 laddoos each is '3 groups of 4', written 3 × 4. Unequal groups cannot be multiplied.", "outcomes": ["Can describe a multiplication like 3 × 4 as '3 groups of 4'", "Can spot whether groups are equal and so can be multiplied"], "prereqs": ["g1.num.add-sub-within-20"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.num.mult-intro.repeated-addition", "parent": "g2.num.mult-intro", "title": "Multiplication as Repeated Addition", "description": "3 × 5 is a shortcut for 5 + 5 + 5. Turn repeated additions into multiplications and back, and find the totals by adding.", "outcomes": ["Can write repeated addition (5 + 5 + 5) as multiplication (3 × 5) and back", "Can find the total of a small multiplication by repeated adding"], "prereqs": ["g2.num.mult-intro.equal-groups"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.num.mult-intro.skip-counting", "parent": "g2.num.mult-intro", "title": "Skip Counting to Find Totals", "description": "Count equal groups the fast way by skipping: 2, 4, 6, 8 or 5, 10, 15, 20. Each skip lands on the total of one more group.", "outcomes": ["Can skip count in 2s, 5s and 10s to find totals of equal groups", "Can match each skip to one more group added"], "prereqs": ["g2.num.mult-intro.repeated-addition"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g2.num.mult-intro.arrays-two-ways", "parent": "g2.num.mult-intro", "title": "Arrays: Rows and Columns, Two Ways", "description": "Arrange objects in neat rows and columns and count them two ways: 3 rows of 4 or 4 columns of 3. The same array shows why 3 × 4 and 4 × 3 give the same total.", "outcomes": ["Can arrange objects in rows and columns (arrays) and count them two ways", "Can explain with an array why 3 × 4 = 4 × 3"], "prereqs": ["g2.num.mult-intro.skip-counting"], "est_minutes": 20, "difficulty": 2, "question": true}]}, {"id": "g2.num.money-transactions", "title": "Money: Simple Totals and Change", "grade": 2, "strand": "num", "description": "Shopping is maths in action: we add prices to find the total, and when we pay with a bigger note, we get change — the difference between what we gave and what it cost. We can also make the same amount in many ways using different coins and notes.", "prereqs": ["g1.num.money-intro", "g2.num.add-sub-2digit"], "outcomes": ["Can add two or three prices to find a total up to ₹99", "Can work out the change from ₹10, ₹20 or ₹50", "Can make a given amount using different combinations of coins and notes", "Can check whether the money offered is enough to buy something"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": [{"id": "g2.num.money-transactions.count-coin-values", "parent": "g2.num.money-transactions", "title": "Counting Money by Value, Not Pieces", "description": "Three ten-rupee notes are thirty rupees, not three. Count money by adding the VALUE printed on each coin or note, skip counting in 10s and 5s where it helps.", "outcomes": ["Can find the total value of a handful of coins and notes", "Can explain why 3 notes is not the same as ₹3"], "prereqs": ["g1.num.money-intro", "g2.num.place-value-2digit.ten-more-ten-less"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.num.money-transactions.make-amounts-many-ways", "parent": "g2.num.money-transactions", "title": "Making the Same Amount in Different Ways", "description": "₹20 can be one ₹20 note, two ₹10 notes, or four ₹5 coins. Build a given amount in several ways and check each way really adds to the same total.", "outcomes": ["Can make a given amount using different combinations of coins and notes", "Can check that two different combinations are worth the same amount"], "prereqs": ["g2.num.money-transactions.count-coin-values"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.num.money-transactions.add-prices-total", "parent": "g2.num.money-transactions", "title": "Adding Prices to Find the Total", "description": "Add two or three prices to find what the shopping costs altogether, up to ₹99, and check whether the money in hand is enough to pay.", "outcomes": ["Can add two or three prices to find a total up to ₹99", "Can check whether the money offered is enough to buy something"], "prereqs": ["g2.num.money-transactions.count-coin-values", "g2.num.add-sub-2digit.add-with-carry"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.num.money-transactions.change-by-subtracting", "parent": "g2.num.money-transactions", "title": "Working Out the Change", "description": "When you pay with a bigger note, the change is the DIFFERENCE: what you gave minus what it cost. Find change from ₹10, ₹20 and ₹50 by subtracting or counting up.", "outcomes": ["Can work out the change from ₹10, ₹20 or ₹50", "Can find change by counting up from the price to the payment"], "prereqs": ["g2.num.money-transactions.add-prices-total", "g2.num.add-sub-2digit.sub-with-borrow"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g2.geo.2d-3d-shapes", "title": "2D and 3D Shapes: Faces, Edges, Lines", "grade": 2, "strand": "geo", "description": "Solid shapes like cubes, cuboids, cylinders and spheres have faces you can touch, edges you can run a finger along, and corners that poke. Flat shapes live on the faces of solids. Learning to count faces, edges and corners — and to tell straight lines from curves — makes us precise about shapes.", "prereqs": ["g1.geo.shapes-around-us"], "outcomes": ["Can name cube, cuboid, cylinder, cone and sphere from real objects", "Can count the faces, edges and corners of a cube or cuboid", "Can predict the flat shape a solid's face will print or trace", "Can tell straight lines from curved lines and draw both"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g2.geo.2d-3d-shapes.name-solids", "parent": "g2.geo.2d-3d-shapes", "title": "Naming Solid Shapes Around Us", "description": "Spot cubes, cuboids, cylinders, cones and spheres in real objects — dice, bricks, tins, ice-cream cones and balls. Solids are the shapes you can hold; flat shapes live on their faces.", "outcomes": ["Can name cube, cuboid, cylinder, cone and sphere from real objects", "Can tell a solid shape's name apart from the flat shape on its face"], "prereqs": ["g1.geo.shapes-around-us"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.geo.2d-3d-shapes.faces-edges-corners", "parent": "g2.geo.2d-3d-shapes", "title": "Counting Faces, Edges and Corners", "description": "Touch a face, run a finger along an edge, feel a corner poke. Count all of them on a cube and cuboid — including the hidden ones a picture does not show.", "outcomes": ["Can count the faces, edges and corners of a cube or cuboid", "Can point to and tell apart a face, an edge and a corner"], "prereqs": ["g2.geo.2d-3d-shapes.name-solids"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g2.geo.2d-3d-shapes.face-prints", "parent": "g2.geo.2d-3d-shapes", "title": "What Shape Does a Face Print?", "description": "Dip a solid's face in paint and press it on paper: a cube prints squares, a cylinder's end prints a circle. Predicting the print connects solids to the flat shapes on their faces.", "outcomes": ["Can predict the flat shape a solid's face will print or trace", "Can match solids to the flat shapes found on their faces"], "prereqs": ["g2.geo.2d-3d-shapes.faces-edges-corners"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.geo.2d-3d-shapes.straight-curved-lines", "parent": "g2.geo.2d-3d-shapes", "title": "Straight Lines and Curved Lines", "description": "Tell straight lines from curves, find both on shapes and objects, and draw them — straight lines with a ruler's edge, curves freehand.", "outcomes": ["Can tell straight lines from curved lines and draw both", "Can count the straight sides and curved sides of a flat shape"], "prereqs": ["g2.geo.2d-3d-shapes.name-solids"], "est_minutes": 15, "difficulty": 1, "question": false}]}, {"id": "g2.mea.length-units-intro", "title": "Measuring Length: Non-standard to Standard Units", "grade": 2, "strand": "mea", "description": "We can measure length with handspans, footsteps or pencils — but everyone's hands and feet are different, so the counts don't match. That is why the world agreed on standard units like the centimetre and metre. Measuring means laying units end to end with no gaps and no overlaps, then counting them.", "prereqs": ["g1.mea.compare-lengths"], "outcomes": ["Can measure a length by repeating a unit end to end with no gaps or overlaps", "Can explain why different people get different handspan counts for the same object", "Can say why standard units like centimetre and metre are needed", "Can measure short lengths in centimetres with a ruler"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g2.mea.length-units-intro.repeat-units-no-gaps", "parent": "g2.mea.length-units-intro", "title": "Measuring by Repeating a Unit", "description": "Measure a length by laying one unit — a pencil, a handspan — end to end again and again, with no gaps and no overlaps, then counting the units.", "outcomes": ["Can measure a length by repeating a unit end to end with no gaps or overlaps", "Can explain why gaps or overlaps spoil the count"], "prereqs": ["g1.mea.compare-lengths"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.mea.length-units-intro.why-standard-units", "parent": "g2.mea.length-units-intro", "title": "Why the World Needs Standard Units", "description": "Different people get different handspan counts for the same table because their hands differ — the table never changes. Smaller units give bigger counts. That is why everyone agreed on the centimetre and metre.", "outcomes": ["Can explain why different people get different handspan counts for the same object", "Can say why standard units like centimetre and metre are needed", "Can predict that a smaller unit gives a bigger count for the same length"], "prereqs": ["g2.mea.length-units-intro.repeat-units-no-gaps"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.mea.length-units-intro.ruler-centimetres", "parent": "g2.mea.length-units-intro", "title": "Measuring in Centimetres with a Ruler", "description": "A ruler is centimetres already laid end to end for us. Line the object's end up with the 0 mark and read the number at the other end.", "outcomes": ["Can measure short lengths in centimetres with a ruler", "Can start measuring from the 0 mark, not the ruler's edge"], "prereqs": ["g2.mea.length-units-intro.why-standard-units"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g2.mea.length-units-intro.choose-cm-or-m", "parent": "g2.mea.length-units-intro", "title": "Centimetre or Metre? Choosing the Unit", "description": "Small things like a crayon are measured in centimetres; big things like a door or the classroom are measured in metres. Choose the unit that fits the job.", "outcomes": ["Can choose centimetres or metres as the sensible unit for an object", "Can name objects around them that are about 1 cm and about 1 m"], "prereqs": ["g2.mea.length-units-intro.ruler-centimetres"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g2.mea.weight-capacity-intro", "title": "Weight and Capacity: Comparing and Measuring", "grade": 2, "strand": "mea", "description": "Weight tells how heavy something is; capacity tells how much a container can hold. A balance shows which of two things is heavier — the heavier side goes down. To compare containers fairly, we fill them using the same cup and count. Looks can trick us: big things can be light, and tall containers can hold less.", "prereqs": ["g1.mea.compare-lengths"], "outcomes": ["Can compare two objects' weights using hands or a simple balance", "Can read a pan balance: the heavier side goes down", "Can compare two containers' capacities by filling with a common cup and counting", "Can order three objects by weight or three containers by capacity"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": [{"id": "g2.mea.weight-capacity-intro.compare-weights-hands", "parent": "g2.mea.weight-capacity-intro", "title": "Heavier or Lighter? Hands First", "description": "Hold one object in each hand and feel which pulls down more. Discover that looks can trick us: a big balloon is lighter than a small stone.", "outcomes": ["Can compare two objects' weights using hands", "Can give an example where the bigger-looking object is lighter"], "prereqs": ["g1.mea.compare-lengths"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.mea.weight-capacity-intro.read-pan-balance", "parent": "g2.mea.weight-capacity-intro", "title": "Reading a Pan Balance", "description": "On a balance, the heavier side goes DOWN and the lighter side goes up; level pans mean equal weights. Use the balance to settle comparisons hands cannot feel.", "outcomes": ["Can read a pan balance: the heavier side goes down", "Can use a balance to compare two objects whose weights feel similar"], "prereqs": ["g2.mea.weight-capacity-intro.compare-weights-hands"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.mea.weight-capacity-intro.compare-capacity-cups", "parent": "g2.mea.weight-capacity-intro", "title": "Which Holds More? Filling with Cups", "description": "Compare containers fairly by filling each with the SAME cup and counting the cupfuls. Tall thin containers can hold less than short wide ones.", "outcomes": ["Can compare two containers' capacities by filling with a common cup and counting", "Can explain why a taller container does not always hold more"], "prereqs": ["g2.mea.weight-capacity-intro.compare-weights-hands"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.mea.weight-capacity-intro.order-three-things", "parent": "g2.mea.weight-capacity-intro", "title": "Ordering by Weight and by Capacity", "description": "Put three objects in order from lightest to heaviest using pairwise balance checks, and three containers in order by counting cupfuls of each.", "outcomes": ["Can order three objects by weight or three containers by capacity", "Can use two comparisons to work out the order of three things"], "prereqs": ["g2.mea.weight-capacity-intro.read-pan-balance", "g2.mea.weight-capacity-intro.compare-capacity-cups"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g2.mea.time-days-calendar", "title": "Time: Days, Months, Calendar and O'Clock", "grade": 2, "strand": "mea", "description": "The 7 days of the week go round and round like a wheel, and the 12 months fill a year on the calendar. A clock has two hands: the short hand tells the hour, and when the long hand points to 12, it is exactly o'clock. Reading calendars and clocks helps us plan our days.", "prereqs": ["g1.mea.time-day-events"], "outcomes": ["Can say the days of the week in order and name yesterday/tomorrow for any day", "Can name the 12 months in order and find dates on a calendar", "Can read o'clock times on a clock with hands", "Can tell which hand of a clock shows hours and which shows minutes"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g2.mea.time-days-calendar.days-of-week", "parent": "g2.mea.time-days-calendar", "title": "The Wheel of Seven Days", "description": "Say the 7 days in order and see that they go round like a wheel: after Sunday comes Monday again. Name yesterday and tomorrow for any day.", "outcomes": ["Can say the days of the week in order and name yesterday/tomorrow for any day", "Can explain that the week loops — it never runs out of days"], "prereqs": ["g1.mea.time-day-events"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.mea.time-days-calendar.months-and-calendar", "parent": "g2.mea.time-days-calendar", "title": "Twelve Months and the Calendar", "description": "Name the 12 months in order, find today's date on a calendar page, and keep weeks, months and years apart: 7 days make a week, and about 30 days make a month.", "outcomes": ["Can name the 12 months in order and find dates on a calendar", "Can say how many days are in a week and how many months in a year"], "prereqs": ["g2.mea.time-days-calendar.days-of-week"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g2.mea.time-days-calendar.clock-two-hands", "parent": "g2.mea.time-days-calendar", "title": "The Clock's Two Hands", "description": "A clock has a SHORT hand for hours and a LONG hand for minutes. Watch how the short hand creeps from number to number while the long hand races around.", "outcomes": ["Can tell which hand of a clock shows hours and which shows minutes", "Can point to the hour hand and minute hand on any clock face"], "prereqs": ["g2.mea.time-days-calendar.days-of-week"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g2.mea.time-days-calendar.read-oclock", "parent": "g2.mea.time-days-calendar", "title": "Reading O'Clock Times", "description": "When the long hand points straight up at 12, it is exactly o'clock — and the short hand tells WHICH o'clock. Read and set o'clock times on a clock with hands.", "outcomes": ["Can read o'clock times on a clock with hands", "Can set a toy clock to a given o'clock time"], "prereqs": ["g2.mea.time-days-calendar.clock-two-hands"], "est_minutes": 20, "difficulty": 2, "question": true}]}, {"id": "g2.alg.patterns-grow", "title": "Growing Patterns in Numbers and Shapes", "grade": 2, "strand": "alg", "description": "Some patterns don't repeat — they GROW. A staircase gains a step each time; the numbers 2, 4, 6, 8 climb by 2 at every jump. To continue a growing pattern you must find its rule: what changes from one step to the next, and by how much?", "prereqs": ["g1.alg.patterns-repeat", "g1.num.add-sub-within-20"], "outcomes": ["Can continue a number pattern that grows by the same amount each time", "Can build and extend growing shape patterns (staircases, triangles of dots)", "Can state the rule of a growing pattern in words ('add 5 each time')", "Can check whether a claimed rule works for EVERY step of a pattern"], "difficulty": 2, "est_minutes": 25, "stub": false, "micros": [{"id": "g2.alg.patterns-grow.spot-growing-patterns", "parent": "g2.alg.patterns-grow", "title": "Repeating or Growing?", "description": "Some patterns repeat the same chunk (red, blue, red, blue) and some GROW (2, 4, 6, 8). Sort patterns into repeating and growing, and say what a growing pattern does at each step.", "outcomes": ["Can tell a growing pattern apart from a repeating one", "Can say what changes at each step of a growing pattern"], "prereqs": ["g1.alg.patterns-repeat", "g1.num.add-sub-within-20"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.alg.patterns-grow.continue-number-patterns", "parent": "g2.alg.patterns-grow", "title": "Continuing Number Patterns", "description": "Find the constant jump in a number pattern by checking the gap between neighbours, then use it to write the next few terms.", "outcomes": ["Can continue a number pattern that grows by the same amount each time", "Can find the jump by subtracting a term from the next one"], "prereqs": ["g2.alg.patterns-grow.spot-growing-patterns"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.alg.patterns-grow.build-shape-staircases", "parent": "g2.alg.patterns-grow", "title": "Building Staircases and Dot Triangles", "description": "Build growing shape patterns with blocks or dots — a staircase that gains a step each time — and count how many pieces each new step needs.", "outcomes": ["Can build and extend growing shape patterns (staircases, triangles of dots)", "Can count and record how many pieces each stage of the pattern uses"], "prereqs": ["g2.alg.patterns-grow.spot-growing-patterns"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g2.alg.patterns-grow.state-and-check-rule", "parent": "g2.alg.patterns-grow", "title": "Saying the Rule and Checking Every Step", "description": "Put a growing pattern's rule into words — 'add 3 each time' — and test it on EVERY step. A real rule never changes halfway through.", "outcomes": ["Can state the rule of a growing pattern in words ('add 5 each time')", "Can check whether a claimed rule works for EVERY step of a pattern"], "prereqs": ["g2.alg.patterns-grow.continue-number-patterns", "g2.alg.patterns-grow.build-shape-staircases"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g2.dat.pictographs-intro", "title": "Pictographs: Recording and Reading Data", "grade": 2, "strand": "dat", "description": "A pictograph shows information using little pictures — one picture for each thing counted (or sometimes for two or more). Lining the pictures up in neat rows lets us see at a glance which group has most and how many more. Pictographs turn messy counts into a story our eyes can read.", "prereqs": ["g1.dat.sort-classify", "g1.num.numbers-to-20"], "outcomes": ["Can collect simple data by counting and record it with tally marks or pictures", "Can read how many each row of a pictograph shows", "Can answer most/least and how-many-more questions from a pictograph", "Can use a key where one symbol stands for more than one object"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": [{"id": "g2.dat.pictographs-intro.collect-and-tally", "parent": "g2.dat.pictographs-intro", "title": "Collecting Data with Tallies and Pictures", "description": "Count things around us — favourite fruits, birds spotted — and record each one with a tally mark or a small picture so nothing gets counted twice or missed.", "outcomes": ["Can collect simple data by counting and record it with tally marks or pictures", "Can turn a tally count into a neat row of pictures"], "prereqs": ["g1.dat.sort-classify", "g1.num.numbers-to-20"], "est_minutes": 20, "difficulty": 1, "question": false}, {"id": "g2.dat.pictographs-intro.read-counts", "parent": "g2.dat.pictographs-intro", "title": "Reading How Many from a Pictograph", "description": "Read a simple pictograph where one picture means one thing: count the symbols in a row to answer 'how many?'. The chart — not our memory or taste — gives the answer.", "outcomes": ["Can read how many each row of a pictograph shows", "Can answer questions from the chart rather than from personal preference"], "prereqs": ["g2.dat.pictographs-intro.collect-and-tally"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g2.dat.pictographs-intro.compare-most-least", "parent": "g2.dat.pictographs-intro", "title": "Most, Least and How Many More", "description": "Compare rows of a pictograph by COUNTING symbols, not by how long a row looks — big pictures can make a short count look long. Answer most/least and how-many-more questions.", "outcomes": ["Can answer most/least and how-many-more questions from a pictograph", "Can explain why rows are compared by counting symbols, not by their length"], "prereqs": ["g2.dat.pictographs-intro.read-counts", "g2.num.add-sub-2digit.sub-no-regroup"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g2.dat.pictographs-intro.use-a-key", "parent": "g2.dat.pictographs-intro", "title": "When One Picture Means More Than One", "description": "Sometimes a key says one symbol stands for 2 or 5 things. Read the key first, then skip count the symbols to find the real total.", "outcomes": ["Can use a key where one symbol stands for more than one object", "Can skip count symbols using the key to find totals"], "prereqs": ["g2.dat.pictographs-intro.compare-most-least", "g2.num.mult-intro.skip-counting"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g3.num.numbers-to-9999", "title": "4-digit Numbers and Place Value", "grade": 3, "strand": "num", "description": "With four places — thousands, hundreds, tens and ones — we can name every number up to 9999. Each step left multiplies a digit's value by ten, and a zero holds any empty place. Reading, writing, expanding and comparing 4-digit numbers makes big numbers as friendly as small ones.", "prereqs": ["g2.num.numbers-to-999"], "outcomes": ["Can read and write 4-digit numbers from words and figures", "Can give the place value of any digit in a 4-digit number", "Can write a 4-digit number in expanded form (3206 = 3000 + 200 + 6)", "Can compare and order 4-digit numbers", "Can find 1, 10, 100 or 1000 more or less than a given number"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g3.num.numbers-to-9999.build-thousands", "parent": "g3.num.numbers-to-9999", "title": "Making a Thousand", "description": "Bundle 10 hundreds into 1 thousand and count in thousands: 1000, 2000, ... 9000. The thousands place is the new fourth seat on the place-value mat.", "outcomes": ["Can explain that 10 hundreds make 1 thousand", "Can count in thousands from 1000 to 9000"], "prereqs": ["g2.num.numbers-to-999"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g3.num.numbers-to-9999.read-write-4digit", "parent": "g3.num.numbers-to-9999", "title": "Reading and Writing 4-digit Numbers", "description": "Turn number words into figures and back, using a Th | H | T | O mat. A zero must hold any empty place so the other digits stay in their seats.", "outcomes": ["Can write a 4-digit number from its number name, including zero-rich ones like 4056", "Can read any 4-digit number aloud correctly"], "prereqs": ["g3.num.numbers-to-9999.build-thousands"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.numbers-to-9999.place-value-expanded", "parent": "g3.num.numbers-to-9999", "title": "Place Value and Expanded Form", "description": "Every digit has a face and a value: the 5 in 2593 is worth 500 because it sits in the hundreds seat. Writing 2593 = 2000 + 500 + 90 + 3 shows each digit's true worth.", "outcomes": ["Can state the place value of any digit in a 4-digit number", "Can write a 4-digit number in expanded form and put expanded parts back together"], "prereqs": ["g3.num.numbers-to-9999.read-write-4digit"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.numbers-to-9999.compare-order", "parent": "g3.num.numbers-to-9999", "title": "Comparing and Ordering 4-digit Numbers", "description": "Compare from the LEFT: thousands first, then hundreds, tens, ones. Shiny big digits on the right cannot beat one extra thousand on the left.", "outcomes": ["Can compare two 4-digit numbers using > and <", "Can put three or four 4-digit numbers in order"], "prereqs": ["g3.num.numbers-to-9999.place-value-expanded"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.numbers-to-9999.more-less-jumps", "parent": "g3.num.numbers-to-9999", "title": "1, 10, 100 or 1000 More or Less", "description": "Jump up or down by 1, 10, 100 or 1000 from any 4-digit number — only one place changes, unless the jump rolls over into the next place.", "outcomes": ["Can find 1, 10, 100 or 1000 more or less than a given number", "Can handle jumps that cross over, like 100 more than 3950"], "prereqs": ["g3.num.numbers-to-9999.place-value-expanded"], "est_minutes": 10, "difficulty": 2, "question": true}]}, {"id": "g3.num.add-sub-3digit", "title": "3-digit Addition and Subtraction", "grade": 3, "strand": "num", "description": "Adding and subtracting 3-digit numbers uses the same regrouping ideas as 2-digit work — just with a hundreds column too. Carries can travel from ones to tens to hundreds, and borrowing can even cross a zero. Estimating first tells us roughly what to expect, so wild answers get caught.", "prereqs": ["g2.num.add-sub-2digit", "g2.num.numbers-to-999"], "outcomes": ["Can add two 3-digit numbers with one or more carries", "Can subtract 3-digit numbers with borrowing, including across a zero", "Can estimate a sum or difference to the nearest hundred before computing", "Can check subtraction by adding back", "Can solve story problems needing 3-digit addition or subtraction"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g3.num.add-sub-3digit.line-up-columns", "parent": "g3.num.add-sub-3digit", "title": "Lining Up the Columns", "description": "Numbers of different lengths must be lined up from the RIGHT, ones under ones — like books pushed to the right end of a shelf. Then add column by column without regrouping.", "outcomes": ["Can set out a 3-digit and a 2-digit number with the ones aligned", "Can add 3-digit numbers column by column when no carrying is needed"], "prereqs": ["g2.num.add-sub-2digit", "g3.num.numbers-to-9999.place-value-expanded"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.add-sub-3digit.add-with-carrying", "parent": "g3.num.add-sub-3digit", "title": "Adding with Carrying", "description": "When a column's total reaches 10, bundle it and carry into the next column. Carries can travel from ones to tens and from tens to hundreds in the same sum.", "outcomes": ["Can add two 3-digit numbers with one or two carries", "Can say aloud what each carry stands for"], "prereqs": ["g3.num.add-sub-3digit.line-up-columns"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g3.num.add-sub-3digit.subtract-borrowing", "parent": "g3.num.add-sub-3digit", "title": "Subtracting with Borrowing", "description": "When a column's top digit is too small, open a bundle from the next column: one ten becomes ten ones. The top number is the starting amount — order matters, so never just flip the digits.", "outcomes": ["Can subtract 3-digit numbers borrowing from tens and hundreds", "Can explain a borrow as opening a ten or a hundred"], "prereqs": ["g3.num.add-sub-3digit.line-up-columns"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g3.num.add-sub-3digit.borrow-across-zero", "parent": "g3.num.add-sub-3digit", "title": "Borrowing Across a Zero", "description": "When the top number has a 0 in the middle, rename before subtracting: 403 becomes 3 hundreds + 9 tens + 13 ones. Write the renamed number fully, THEN subtract column by column.", "outcomes": ["Can subtract when the top number has a zero in the tens or ones place", "Can rename a number like 403 or 500 before subtracting"], "prereqs": ["g3.num.add-sub-3digit.subtract-borrowing"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g3.num.add-sub-3digit.estimate-and-check", "parent": "g3.num.add-sub-3digit", "title": "Estimating First and Checking Back", "description": "Round each number to the nearest hundred and add or subtract in your head to know roughly what to expect — wild answers get caught. Check any subtraction by adding back.", "outcomes": ["Can estimate a sum or difference to the nearest hundred before computing", "Can check a subtraction by adding the answer to the number taken away"], "prereqs": ["g3.num.add-sub-3digit.add-with-carrying", "g3.num.add-sub-3digit.subtract-borrowing"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.add-sub-3digit.story-problems", "parent": "g3.num.add-sub-3digit", "title": "Story Problems with 3-digit Numbers", "description": "Read the story, decide whether the pile grows (add) or shrinks (subtract), estimate, then compute. Words like 'sold', 'left' and 'in all' are the clues.", "outcomes": ["Can choose the right operation from a story", "Can solve add and subtract stories with 3-digit numbers and check the answer is sensible"], "prereqs": ["g3.num.add-sub-3digit.borrow-across-zero", "g3.num.add-sub-3digit.estimate-and-check"], "est_minutes": 20, "difficulty": 3, "question": false}]}, {"id": "g3.num.mult-tables", "title": "Multiplication Tables and Facts (2–10)", "grade": 3, "strand": "num", "description": "The multiplication tables from 2 to 10 are the fact family of arithmetic — knowing them by heart makes every later calculation faster. But tables are more than a chant: each fact is an array you can picture, facts connect (7 × 6 is 7 × 5 and 7 more), and order never matters. Special rules for 0 and 1 complete the set.", "prereqs": ["g2.num.mult-intro"], "outcomes": ["Can recall multiplication facts for tables 2 to 10", "Can use a known fact to derive a nearby one (7 × 6 = 7 × 5 + 7)", "Can explain why n × 0 = 0 and n × 1 = n", "Can use the turn-around rule: a × b = b × a", "Can find the missing factor in facts like 6 × __ = 42"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g3.num.mult-tables.equal-groups-to-tables", "parent": "g3.num.mult-tables", "title": "From Equal Groups to Table Facts", "description": "Every table fact is an equal-groups story and an array picture: 3 × 4 is 3 plates of 4 laddoos. Group stories also settle the special cases — any number of empty plates gives 0, and plates of 1 give exactly the number of plates.", "outcomes": ["Can turn an equal-groups picture or story into a multiplication fact", "Can explain why n × 0 = 0 and n × 1 = n with a group story"], "prereqs": ["g2.num.mult-intro"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g3.num.mult-tables.tables-2-5-10", "parent": "g3.num.mult-tables", "title": "Tables of 2, 5 and 10", "description": "The friendliest tables first: 2s are doubles, 5s end in 5 or 0, 10s just gain a zero. Skip counting and quick-fire recall make these facts automatic.", "outcomes": ["Can recall the 2, 5 and 10 times tables in and out of order", "Can spot the ending-digit patterns of the 5s and 10s"], "prereqs": ["g3.num.mult-tables.equal-groups-to-tables"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g3.num.mult-tables.tables-3-4-6", "parent": "g3.num.mult-tables", "title": "Tables of 3, 4 and 6", "description": "Build the 3s by adding a group to the 2s, the 4s by doubling the 2s, and the 6s by doubling the 3s. Deriving from a known fact beats guessing.", "outcomes": ["Can recall the 3, 4 and 6 times tables", "Can derive a 4s or 6s fact by doubling a known fact"], "prereqs": ["g3.num.mult-tables.tables-2-5-10"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g3.num.mult-tables.tables-7-8-9", "parent": "g3.num.mult-tables", "title": "Tables of 7, 8 and 9", "description": "The trickiest facts live here. Anchor and derive: from 7 × 7 = 49 get 7 × 8 = 56; get the 9s from the 10s by taking one group away. Drill the few slippery facts separately.", "outcomes": ["Can recall the 7, 8 and 9 times tables", "Can derive a hard fact from a nearby anchor fact"], "prereqs": ["g3.num.mult-tables.tables-3-4-6"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g3.num.mult-tables.fact-families-commutativity", "parent": "g3.num.mult-tables", "title": "Turn-around Facts and Missing Factors", "description": "Rotating an array a quarter turn shows a × b = b × a — every fact you learn gives its twin for free. Fact families also answer missing-factor puzzles like 6 × __ = 42.", "outcomes": ["Can use the turn-around rule a × b = b × a", "Can find the missing factor in facts like 6 × __ = 42"], "prereqs": ["g3.num.mult-tables.tables-2-5-10"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g3.num.mult-2digit-by-1digit", "title": "Multiplying 2-digit by 1-digit Numbers", "grade": 3, "strand": "num", "description": "To multiply a number like 47 by 3, we split it by place value: 3 × 40 and 3 × 7, then add the parts. Written short, this becomes the column method with carrying. BOTH parts of the number must be multiplied — that is the heart of the method.", "prereqs": ["g3.num.mult-tables", "g2.num.place-value-2digit"], "outcomes": ["Can multiply a 2-digit number by a 1-digit number using expanded form (area model)", "Can use the column method with carrying", "Can estimate the product first (47 × 3 is about 50 × 3 = 150)", "Can solve story problems involving equal groups of 2-digit amounts"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g3.num.mult-2digit-by-1digit.split-tens-ones", "parent": "g3.num.mult-2digit-by-1digit", "title": "Splitting into Tens and Ones", "description": "To multiply 14 × 2, split 14 into 10 and 4 and multiply BOTH parts: (10 × 2) + (4 × 2). Both parts get the same operation — times, never add.", "outcomes": ["Can split a 2-digit number into tens and ones for multiplying", "Can multiply both parts and add them, without mixing in addition"], "prereqs": ["g3.num.mult-tables.tables-2-5-10", "g2.num.place-value-2digit"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.mult-2digit-by-1digit.area-model-partials", "parent": "g3.num.mult-2digit-by-1digit", "title": "Area Model: Add the Partial Products", "description": "Draw the number as a rectangle cut into a tens box and a ones box, work out each box, then ADD the parts. The parts combine by addition — never by sitting side by side.", "outcomes": ["Can find both partial products with an area model", "Can combine partial products by adding, not gluing digits together"], "prereqs": ["g3.num.mult-2digit-by-1digit.split-tens-ones", "g3.num.mult-tables.tables-7-8-9"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g3.num.mult-2digit-by-1digit.column-method-carry", "parent": "g3.num.mult-2digit-by-1digit", "title": "Column Method with Carrying", "description": "The short written form of the area model: multiply the ones, carry the extra tens, multiply the tens, THEN add the carry. Say it aloud and cross out each carry once it is used.", "outcomes": ["Can multiply a 2-digit number by a 1-digit number in columns with carrying", "Can say the multiply-then-add-the-carry ritual aloud"], "prereqs": ["g3.num.mult-2digit-by-1digit.area-model-partials", "g3.num.add-sub-3digit.add-with-carrying"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g3.num.mult-2digit-by-1digit.estimate-products", "parent": "g3.num.mult-2digit-by-1digit", "title": "Estimating Products", "description": "Round the 2-digit number to the nearest ten and multiply in your head: 62 × 4 is about 60 × 4 = 240. The estimate flags answers that are far too big or too small.", "outcomes": ["Can estimate a product by rounding to the nearest ten", "Can use the estimate to judge whether a computed answer is sensible"], "prereqs": ["g3.num.mult-2digit-by-1digit.split-tens-ones"], "est_minutes": 10, "difficulty": 2, "question": true}, {"id": "g3.num.mult-2digit-by-1digit.story-problems", "parent": "g3.num.mult-2digit-by-1digit", "title": "Equal-groups Story Problems", "description": "Spot the equal groups in a story — boxes of pencils, tickets at the same price — write the multiplication, estimate, then compute.", "outcomes": ["Can turn an equal-groups story into a 2-digit by 1-digit multiplication", "Can solve and check the answer against an estimate"], "prereqs": ["g3.num.mult-2digit-by-1digit.column-method-carry", "g3.num.mult-2digit-by-1digit.estimate-products"], "est_minutes": 15, "difficulty": 3, "question": true}]}, {"id": "g3.num.division-intro", "title": "Division: Sharing, Grouping and Inverse of Multiplication", "grade": 3, "strand": "num", "description": "Division answers two kinds of questions: sharing (12 laddoos among 3 children — how many each?) and grouping (12 laddoos, 3 per bag — how many bags?). It is multiplication run backwards: 12 ÷ 3 = 4 because 3 × 4 = 12. Sometimes things don't share out evenly, and what's left over is the remainder.", "prereqs": ["g3.num.mult-tables"], "outcomes": ["Can solve sharing and grouping problems by acting them out or drawing", "Can write and read division sentences (12 ÷ 3 = 4)", "Can use a multiplication fact to solve a division (12 ÷ 3 via 3 × ? = 12)", "Can handle simple leftovers (remainders) in sharing stories"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g3.num.division-intro.sharing-equally", "parent": "g3.num.division-intro", "title": "Division as Sharing", "description": "Share 15 mangoes among 3 friends by dealing them out one round at a time like playing cards, then count ONE friend's pile. The answer is how many EACH gets, with its unit.", "outcomes": ["Can solve sharing problems by dealing out objects or drawing", "Can state the answer with its unit: '5 mangoes EACH'"], "prereqs": ["g2.num.mult-intro"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g3.num.division-intro.grouping-how-many", "parent": "g3.num.division-intro", "title": "Division as Grouping", "description": "The other division question: 20 rotis, 5 per box — how many BOXES? Make groups of the given size and count the groups, or subtract 5 again and again.", "outcomes": ["Can solve grouping problems by making groups of a given size", "Can tell a sharing question from a grouping question"], "prereqs": ["g3.num.division-intro.sharing-equally"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g3.num.division-intro.division-sentences", "parent": "g3.num.division-intro", "title": "Writing Division Sentences", "description": "Write and read sentences like 15 ÷ 3 = 5. The order tells the story: the first number is what gets shared, the second is how it is shared — swapping them changes everything.", "outcomes": ["Can write a division sentence for a sharing or grouping story", "Can explain why 12 ÷ 3 and 3 ÷ 12 are different"], "prereqs": ["g3.num.division-intro.sharing-equally", "g3.num.division-intro.grouping-how-many"], "est_minutes": 10, "difficulty": 2, "question": true}, {"id": "g3.num.division-intro.mult-div-fact-link", "parent": "g3.num.division-intro", "title": "Division from Multiplication Facts", "description": "Division is multiplication run backwards: to find 42 ÷ 6, ask '6 times WHAT makes 42?'. Every table fact gives two divisions for free.", "outcomes": ["Can solve a division using a known multiplication fact", "Can write the fact family for a triple like 6, 7, 42"], "prereqs": ["g3.num.division-intro.division-sentences", "g3.num.mult-tables.fact-families-commutativity"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.division-intro.remainders-leftovers", "parent": "g3.num.division-intro", "title": "Leftovers: Simple Remainders", "description": "Sometimes things do not share out evenly — what is left goes in the 'remainder dish' and must ALWAYS be reported: 17 ÷ 5 = 3 remainder 2.", "outcomes": ["Can share with a leftover and report both parts of the answer", "Can say what could happen to the leftover in a story"], "prereqs": ["g3.num.division-intro.mult-div-fact-link"], "est_minutes": 15, "difficulty": 3, "question": true}]}, {"id": "g3.num.fractions-intro", "title": "Fractions: Half, Quarter, Third", "grade": 3, "strand": "num", "description": "A fraction names a fair share: a half is one of 2 EQUAL parts, a third is one of 3, a quarter is one of 4. The parts must be equal — a big piece and a small piece are not halves! Because quarters are smaller than halves, the more parts we cut, the smaller each part becomes.", "prereqs": ["g3.num.division-intro"], "outcomes": ["Can fold or cut a shape into halves, thirds and quarters — with EQUAL parts", "Can name and write 1/2, 1/3, 1/4 for one part of an equally divided whole", "Can explain that 1/2 of the same whole is bigger than 1/4", "Can find half or a quarter of a small collection (half of 8 mangoes)"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g3.num.fractions-intro.equal-parts-fairness", "parent": "g3.num.fractions-intro", "title": "Equal Parts: The Fairness Test", "description": "Fraction parts must be EQUAL — a big piece and a small piece are not halves. Test with fairness: would both children happily take either piece? Fold and stack paper shapes to check parts match.", "outcomes": ["Can fold or cut a shape into equal parts and check by stacking", "Can reject unequal cuts as 'not halves / not thirds'"], "prereqs": ["g3.num.division-intro.sharing-equally"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g3.num.fractions-intro.halves-quarters", "parent": "g3.num.fractions-intro", "title": "Naming Halves and Quarters", "description": "A half is ONE out of 2 equal parts, a quarter is ONE out of 4. Say 'one out of 4 equal parts' while pointing at a real cut shape, then write it as 1/2 or 1/4.", "outcomes": ["Can name and write 1/2 and 1/4 for one part of an equally divided whole", "Can read 1/4 as 'one out of 4 equal parts', not as two separate numbers"], "prereqs": ["g3.num.fractions-intro.equal-parts-fairness"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.fractions-intro.thirds", "parent": "g3.num.fractions-intro", "title": "Thirds", "description": "Cut or fold a whole into 3 equal parts: each part is one third, written 1/3. Folding into three takes more care than halving — fold, check, adjust.", "outcomes": ["Can fold or mark a shape into 3 equal parts", "Can name and write 1/3 for one of 3 equal parts"], "prereqs": ["g3.num.fractions-intro.halves-quarters"], "est_minutes": 10, "difficulty": 2, "question": false}, {"id": "g3.num.fractions-intro.compare-simple-fractions", "parent": "g3.num.fractions-intro", "title": "Comparing Halves, Thirds and Quarters", "description": "Of the SAME whole, 1/2 beats 1/3, and 1/3 beats 1/4 — more cuts mean smaller pieces. Lay folded pieces on top of each other to see it.", "outcomes": ["Can explain why 1/2 of a whole is bigger than 1/3 or 1/4 of the same whole", "Can order 1/2, 1/3, 1/4 by size"], "prereqs": ["g3.num.fractions-intro.halves-quarters", "g3.num.fractions-intro.thirds"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.fractions-intro.fraction-of-collection", "parent": "g3.num.fractions-intro", "title": "Half or Quarter of a Collection", "description": "Fractions work on groups too: half of 8 mangoes means splitting the 8 into 2 equal piles — 4 each. A quarter means 4 equal piles.", "outcomes": ["Can find half of a small even collection", "Can find a quarter of a collection that splits into 4 equal piles"], "prereqs": ["g3.num.fractions-intro.halves-quarters", "g3.num.division-intro.sharing-equally"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g3.num.money-add-sub", "title": "Money: Making Bills, Adding and Subtracting Amounts", "grade": 3, "strand": "num", "description": "Real shopping needs real arithmetic: adding up a bill with several items, multiplying when we buy more than one of something, and working out change from ₹50 or ₹100. Remember that 100 paise make ₹1, and always check: change must be less than what you handed over!", "prereqs": ["g2.num.money-transactions", "g3.num.add-sub-3digit"], "outcomes": ["Can add amounts of money to make a simple bill", "Can find the change from ₹50 or ₹100", "Can multiply a price by a small quantity within a bill", "Can convert between rupees and paise (₹1 = 100 paise)", "Can judge whether a total or change is reasonable"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g3.num.money-add-sub.rupees-paise", "parent": "g3.num.money-add-sub", "title": "Rupees and Paise", "description": "100 paise make ₹1 — paise are not rupees! Write mixed amounts with a dot, like ₹7.50, and keep rupees and paise in their own columns on a money mat.", "outcomes": ["Can state that ₹1 = 100 paise", "Can write an amount like 7 rupees 50 paise as ₹7.50"], "prereqs": ["g2.num.money-transactions"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.money-add-sub.add-amounts", "parent": "g3.num.money-add-sub", "title": "Adding Amounts of Money", "description": "Add prices the same way as 3-digit numbers — line up, add, carry — and write the ₹ sign on the answer. This is how a shop bill total is made.", "outcomes": ["Can add two or three money amounts in rupees", "Can total a simple bill"], "prereqs": ["g3.num.money-add-sub.rupees-paise", "g3.num.add-sub-3digit.add-with-carrying"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.money-add-sub.change-count-up", "parent": "g3.num.money-add-sub", "title": "Finding Change by Counting Up", "description": "Change is what comes BACK: count up from the price to the note on a number line — 42 → 50 is 8, then 50 → 100 is 50 more. Change is always found by subtracting, never adding.", "outcomes": ["Can find change from ₹50 or ₹100 by counting up", "Can check change by adding it back to the price"], "prereqs": ["g3.num.money-add-sub.add-amounts", "g3.num.add-sub-3digit.subtract-borrowing"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.num.money-add-sub.bills-multiply", "parent": "g3.num.money-add-sub", "title": "Bills with Quantities: Multiply, Don't Add", "description": "When a bill line says 3 pencils at ₹12 each, the quantity MULTIPLIES the price: 3 × 12 = 36. Write the line as repeated addition first, then compress it to a multiplication.", "outcomes": ["Can compute a bill line as quantity × price", "Can total a bill with one multiplied line and one single item"], "prereqs": ["g3.num.money-add-sub.add-amounts", "g3.num.mult-2digit-by-1digit.split-tens-ones"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g3.num.money-add-sub.sensible-answers", "parent": "g3.num.money-add-sub", "title": "Is the Answer Sensible?", "description": "Install the sanity checks: change must be LESS than what you handed over, and a bill total should match a quick estimate. Catch silly answers before the shopkeeper does.", "outcomes": ["Can judge whether a total or change is reasonable without full computing", "Can state the rule: change is always smaller than the payment"], "prereqs": ["g3.num.money-add-sub.change-count-up", "g3.num.money-add-sub.bills-multiply"], "est_minutes": 10, "difficulty": 2, "question": true}]}, {"id": "g3.geo.lines-shapes", "title": "Lines, Corners and Shape Composition", "grade": 3, "strand": "geo", "description": "Shapes are built from lines and corners: straight lines, curved lines, sides that meet at corners. A shape keeps its name however it is turned — a tilted square is still a square. And shapes combine: two equal triangles can join to make a square, tangram pieces build pictures. Composing and decomposing shapes is geometry's version of adding and subtracting.", "prereqs": ["g2.geo.2d-3d-shapes"], "outcomes": ["Can identify straight and curved lines in drawings and objects, in any direction", "Can count sides and corners of polygons and use them to name shapes", "Can recognise a shape in any orientation", "Can compose new shapes from tangram-style pieces and predict what two shapes will make"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g3.geo.lines-shapes.straight-curved-lines", "parent": "g3.geo.lines-shapes", "title": "Straight and Curved Lines", "description": "Straight means 'does not bend' — direction does not matter, so slanted and standing lines are just as straight as lying ones. Test with a taut string or a ruler's edge.", "outcomes": ["Can sort lines and edges into straight and curved", "Can accept slanted and vertical lines as straight"], "prereqs": ["g2.geo.2d-3d-shapes"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g3.geo.lines-shapes.sides-corners", "parent": "g3.geo.lines-shapes", "title": "Counting Sides and Corners", "description": "A polygon's sides are its straight edges and its corners are where two sides meet. Counting sides and corners — not squinting at the look — is how shapes get their names.", "outcomes": ["Can count the sides and corners of triangles, rectangles and other polygons", "Can name a shape from its side and corner count"], "prereqs": ["g3.geo.lines-shapes.straight-curved-lines"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g3.geo.lines-shapes.shapes-any-turn", "parent": "g3.geo.lines-shapes", "title": "A Shape Keeps Its Name When Turned", "description": "Rotate a cut-out slowly and recount: 4 equal sides and 4 square corners is a square in ANY position. Turning a shape never changes what it is.", "outcomes": ["Can recognise squares, triangles and rectangles in any orientation", "Can justify a shape's name by counting, not by how it sits"], "prereqs": ["g3.geo.lines-shapes.sides-corners"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g3.geo.lines-shapes.compose-decompose", "parent": "g3.geo.lines-shapes", "title": "Composing Shapes: Tangram Play", "description": "The same pieces can build different shapes depending on which edges meet. Predict first, then test: two equal triangles can make a square, a rectangle or a bigger triangle.", "outcomes": ["Can compose new shapes from tangram-style pieces", "Can predict what two given shapes will make before joining them"], "prereqs": ["g3.geo.lines-shapes.shapes-any-turn"], "est_minutes": 20, "difficulty": 2, "question": true}]}, {"id": "g3.mea.length-std-units", "title": "Length in Centimetres and Metres; Estimation", "grade": 3, "strand": "mea", "description": "Centimetres measure small things (your finger is about 1 cm wide) and metres measure big things (a big step is about 1 m). There are 100 centimetres in 1 metre. Reading a ruler from the 0 mark, choosing the right unit and estimating before measuring make us smart measurers.", "prereqs": ["g2.mea.length-units-intro"], "outcomes": ["Can measure lengths in cm with a ruler, starting from the 0 mark", "Can state that 1 m = 100 cm and pick cm or m sensibly for an object", "Can estimate lengths using body benchmarks before measuring", "Can measure correctly even when the object doesn't start at 0 (broken-ruler problems)"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": [{"id": "g3.mea.length-std-units.measure-from-zero", "parent": "g3.mea.length-std-units", "title": "Measuring with a Ruler from 0", "description": "Line the object's end up with the 0 mark — not the ruler's edge — and read where the other end lands. Length counts the SPACES between marks, not the marks themselves.", "outcomes": ["Can measure an object in cm starting from the 0 mark", "Can explain that length counts gaps, not marks"], "prereqs": ["g2.mea.length-units-intro"], "est_minutes": 10, "difficulty": 1, "question": false}, {"id": "g3.mea.length-std-units.broken-ruler", "parent": "g3.mea.length-std-units", "title": "Broken-Ruler Measuring", "description": "When an object does not start at 0, subtract: length = end mark − start mark. Measure the same pencil from 0 and from 1 and see why both readings agree.", "outcomes": ["Can measure correctly when the object starts at any mark", "Can find a length by subtracting the start mark from the end mark"], "prereqs": ["g3.mea.length-std-units.measure-from-zero"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.mea.length-std-units.metres-centimetres", "parent": "g3.mea.length-std-units", "title": "Metres and Centimetres: 1 m = 100 cm", "description": "Unroll a metre tape and count the centimetres in tens: 10, 20, ... 100. Exactly 100 cm make 1 m, so 2 m = 200 cm — always two zeros, never one.", "outcomes": ["Can state that 1 m = 100 cm", "Can convert whole metres to centimetres"], "prereqs": ["g3.mea.length-std-units.measure-from-zero"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.mea.length-std-units.estimate-choose-unit", "parent": "g3.mea.length-std-units", "title": "Estimating and Choosing cm or m", "description": "Build body benchmarks — a fingernail is about 1 cm, a giant step about 1 m — then estimate before measuring and pick the sensible unit. Always say the unit with the number.", "outcomes": ["Can pick cm or m sensibly for an object", "Can estimate a length using body benchmarks before measuring"], "prereqs": ["g3.mea.length-std-units.metres-centimetres"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g3.mea.weight-capacity", "title": "Weight (g, kg) and Capacity (mL, L)", "grade": 3, "strand": "mea", "description": "We weigh things in grams and kilograms (1 kg = 1000 g) and measure liquids in millilitres and litres (1 L = 1000 mL). Choosing the right unit matters: a pencil in grams, a rice sack in kilograms; a spoon of medicine in mL, a bucket in litres. Balances and measuring jars turn 'heavier' and 'holds more' into exact numbers.", "prereqs": ["g2.mea.weight-capacity-intro"], "outcomes": ["Can state 1 kg = 1000 g and 1 L = 1000 mL", "Can choose sensible units (g/kg, mL/L) for everyday objects and containers", "Can read simple weights and volumes from balances and measuring jars", "Can compare and add simple weights and capacities in the same unit"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": [{"id": "g3.mea.weight-capacity.heavier-lighter-balance", "parent": "g3.mea.weight-capacity", "title": "Heavier or Lighter: Trust the Balance", "description": "Big does not mean heavy and tall does not mean holds-more. Predict, then test on a balance or by pouring — let the measurement, not the look, give the answer.", "outcomes": ["Can compare weights with a balance and capacities by pouring", "Can give examples where the bigger-looking thing is lighter"], "prereqs": ["g2.mea.weight-capacity-intro"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g3.mea.weight-capacity.grams-kilograms", "parent": "g3.mea.weight-capacity", "title": "Grams and Kilograms: 1 kg = 1000 g", "description": "Kilo means one thousand: stack ten 100 g packets and you have exactly 1 kg. Converting kg to g always uses 1000, never 100.", "outcomes": ["Can state that 1 kg = 1000 g", "Can convert whole kilograms to grams"], "prereqs": ["g3.mea.weight-capacity.heavier-lighter-balance"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.mea.weight-capacity.millilitres-litres", "parent": "g3.mea.weight-capacity", "title": "Millilitres and Litres: 1 L = 1000 mL", "description": "Liquids are measured in millilitres and litres: five 200 mL cups fill a 1 L bottle. Convert to the SAME unit before comparing any two amounts.", "outcomes": ["Can state that 1 L = 1000 mL", "Can compare two amounts by converting to the same unit first"], "prereqs": ["g3.mea.weight-capacity.heavier-lighter-balance"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.mea.weight-capacity.choose-sensible-units", "parent": "g3.mea.weight-capacity", "title": "Choosing Sensible Units", "description": "Pick g for light things and kg for heavy ones, mL for spoonfuls and L for buckets — but remember the unit measures the AMOUNT, not the material: 1 kg of cotton equals 1 kg of iron.", "outcomes": ["Can choose g/kg and mL/L sensibly for everyday things", "Can explain that same number + same unit = same amount, whatever the stuff"], "prereqs": ["g3.mea.weight-capacity.grams-kilograms", "g3.mea.weight-capacity.millilitres-litres"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.mea.weight-capacity.compare-add-amounts", "parent": "g3.mea.weight-capacity", "title": "Comparing and Adding Weights and Capacities", "description": "Add and compare weights or capacities once they are in the same unit: 500 g + 250 g = 750 g; a 500 mL bottle and a 500 mL mug together fill a 1 L jug.", "outcomes": ["Can add simple weights or capacities given in the same unit", "Can solve simple shopping and pouring comparisons"], "prereqs": ["g3.mea.weight-capacity.grams-kilograms", "g3.mea.weight-capacity.millilitres-litres"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g3.mea.time-clock", "title": "Reading the Clock and Calendar", "grade": 3, "strand": "mea", "description": "The clock's long hand counts minutes in fives — pointing at 3 means 15 minutes past. The short hour hand creeps between numbers: at half past 4 it sits halfway from 4 to 5, but the hour is still 4. Together with the calendar's dates, days and months, clocks let us plan and keep our promises on time.", "prereqs": ["g2.mea.time-days-calendar"], "outcomes": ["Can read times to the half and quarter hour, and to 5 minutes", "Can explain what each hand shows, including the hour hand between numbers", "Can count minutes in fives around the clock face", "Can find how many days between two dates on a calendar"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g3.mea.time-clock.hour-minute-hands", "parent": "g3.mea.time-clock", "title": "The Jobs of the Two Hands", "description": "Sort the hands' jobs aloud before every read: SHORT hand tells the hour, LONG hand tells the minutes. Start with o'clock times where the long hand rests on 12.", "outcomes": ["Can identify the hour hand and minute hand", "Can read o'clock times correctly"], "prereqs": ["g2.mea.time-days-calendar"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g3.mea.time-clock.count-by-fives-clock", "parent": "g3.mea.time-clock", "title": "Counting Minutes in Fives", "description": "For the long hand, each clock number is worth 5 minutes: chant round from 12 — 5, 10, 15 ... 55. The number the long hand touches is NOT its face value.", "outcomes": ["Can count minutes in fives around the clock face", "Can say how many minutes past when the long hand is on any number"], "prereqs": ["g3.mea.time-clock.hour-minute-hands", "g2.alg.patterns-grow"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.mea.time-clock.half-quarter-past", "parent": "g3.mea.time-clock", "title": "Half Past and Quarter Past", "description": "Half past means the long hand on 6 (30 minutes); quarter past means it on 3 (15 minutes). Meanwhile the hour hand creeps: at half past 7 it floats between 7 and 8 — but the hour is still 7.", "outcomes": ["Can read times to the half and quarter hour", "Can name the hour from a hand sitting between two numbers"], "prereqs": ["g3.mea.time-clock.count-by-fives-clock"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.mea.time-clock.read-to-5-minutes", "parent": "g3.mea.time-clock", "title": "Reading Time to 5 Minutes", "description": "Put it all together: hour from the short hand's last-passed number, minutes by counting the long hand's fives — 11:20, 3:45, 6:05.", "outcomes": ["Can read any time to the nearest 5 minutes", "Can write clock times in hh:mm form"], "prereqs": ["g3.mea.time-clock.half-quarter-past"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g3.mea.time-clock.calendar-days-between", "parent": "g3.mea.time-clock", "title": "Calendar: Days Between Dates", "description": "Use the calendar to count days between two dates in the same month: count from tomorrow up to the target day, or subtract the dates.", "outcomes": ["Can find how many days between two dates in a month", "Can read dates, days and months from a calendar page"], "prereqs": ["g2.mea.time-days-calendar"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g3.alg.patterns-number", "title": "Number Patterns: Skip Counting, Even and Odd", "grade": 3, "strand": "alg", "description": "Numbers make patterns of their own: skip counting by 2s, 5s and 10s from any starting point, and the even-odd rhythm that alternates forever. A number is even if it splits into pairs with none left over — and you can tell just by looking at its ones digit. Spotting these patterns builds the number sense that powers multiplication and algebra.", "prereqs": ["g2.alg.patterns-grow", "g2.num.mult-intro"], "outcomes": ["Can skip count by 2s, 5s and 10s starting from any number", "Can say whether a number is even or odd using the ones digit", "Can explain even numbers as 'splits into pairs with none left over'", "Can describe and extend a number pattern by stating its rule"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": [{"id": "g3.alg.patterns-number.skip-count-2-5-10", "parent": "g3.alg.patterns-number", "title": "Skip Counting by 2s, 5s and 10s", "description": "Make equal jumps on the number line starting from the jump number: 2, 4, 6...; 5, 10, 15...; 10, 20, 30... Spot the ending-digit patterns each family makes.", "outcomes": ["Can skip count by 2s, 5s and 10s from their own multiples", "Can describe the ending-digit pattern of each count"], "prereqs": ["g2.alg.patterns-grow", "g2.num.mult-intro"], "est_minutes": 10, "difficulty": 1, "question": false}, {"id": "g3.alg.patterns-number.skip-any-start", "parent": "g3.alg.patterns-number", "title": "Skip Counting from Any Start", "description": "The rule of a skip pattern is the JUMP SIZE — the starting stone is free. Jumping +5 from 3 lands on 3, 8, 13, 18, and that is a perfectly good pattern.", "outcomes": ["Can continue a skip pattern that starts away from the skip number", "Can state a pattern's jump size from its first few terms"], "prereqs": ["g3.alg.patterns-number.skip-count-2-5-10"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.alg.patterns-number.even-odd-pairs", "parent": "g3.alg.patterns-number", "title": "Even and Odd by Pairing", "description": "A number is even if its counters all pair up with none left over, and odd if one is left alone. Numbers ending in 0 pair up perfectly too — they are even.", "outcomes": ["Can decide even or odd by pairing up counters", "Can show that numbers like 30 are even because nothing is left over"], "prereqs": ["g2.num.mult-intro"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g3.alg.patterns-number.even-odd-ones-digit", "parent": "g3.alg.patterns-number", "title": "The Ones-Digit Shortcut", "description": "Only the ONES digit decides even or odd, because tens and hundreds always split into pairs. 21 is odd since 1 is odd — the 2 in front has no say.", "outcomes": ["Can decide even or odd for any 2- or 3-digit number using the ones digit", "Can explain why the other digits do not matter"], "prereqs": ["g3.alg.patterns-number.even-odd-pairs", "g3.num.numbers-to-9999.place-value-expanded"], "est_minutes": 10, "difficulty": 2, "question": true}, {"id": "g3.alg.patterns-number.describe-extend-rules", "parent": "g3.alg.patterns-number", "title": "Describing and Extending Pattern Rules", "description": "Say the rule out loud — 'add 10 each time', 'the numbers go even, odd, even, odd' — then use it to extend the pattern and to invent new patterns of your own.", "outcomes": ["Can state the rule of a number pattern in words", "Can extend a pattern by its rule and make up a new pattern from a given rule"], "prereqs": ["g3.alg.patterns-number.skip-any-start", "g3.alg.patterns-number.even-odd-ones-digit"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g3.dat.tables-bar-charts-intro", "title": "Tables and Simple Bar Charts", "grade": 3, "strand": "dat", "description": "A table lines data up in rows and columns; a bar chart turns those numbers into bars whose heights we can compare at a glance. To read a bar we follow its top across to the scale — and when one step of the scale stands for 2 or more, we must multiply, not just count steps. Charts help us answer questions with evidence.", "prereqs": ["g2.dat.pictographs-intro"], "outcomes": ["Can record counts in a table using tally marks", "Can read values from a simple bar chart using its scale", "Can answer most/least and how-many-more questions from a chart", "Can draw a bar chart from a small table of data"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": [{"id": "g3.dat.tables-bar-charts-intro.tally-marks-tables", "parent": "g3.dat.tables-bar-charts-intro", "title": "Tally Marks and Tables", "description": "Record counts as tally marks in bundles of five — four sticks and a gate — and line the totals up in a neat table of rows and columns.", "outcomes": ["Can record a count with tally marks in fives", "Can fill and read a simple data table"], "prereqs": ["g2.dat.pictographs-intro"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g3.dat.tables-bar-charts-intro.read-bar-charts", "parent": "g3.dat.tables-bar-charts-intro", "title": "Reading a Bar Chart", "description": "Follow a bar's top across to the scale to read its value, and answer questions from what the CHART says — point to the bar that proves your answer, not to your favourite.", "outcomes": ["Can read values from a simple bar chart", "Can answer most/least questions using the chart as evidence"], "prereqs": ["g3.dat.tables-bar-charts-intro.tally-marks-tables"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g3.dat.tables-bar-charts-intro.scaled-bars", "parent": "g3.dat.tables-bar-charts-intro", "title": "When One Step Stands for 2", "description": "Check the scale BEFORE reading any bar: when one step stands for 2 or more, multiply the steps by the scale — never just count steps as ones.", "outcomes": ["Can read a bar chart whose scale is 2 or more per step", "Can explain why the scale must be read first"], "prereqs": ["g3.dat.tables-bar-charts-intro.read-bar-charts", "g3.num.mult-tables.tables-2-5-10"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.dat.tables-bar-charts-intro.compare-difference-questions", "parent": "g3.dat.tables-bar-charts-intro", "title": "How Many More? Comparing Bars", "description": "'How many more' asks for a NUMBER, not a name: put a finger on the shorter bar's top and count the climb to the taller bar's top — that climb is the difference.", "outcomes": ["Can answer how-many-more questions with a number found by subtracting", "Can compare two categories from a chart or table"], "prereqs": ["g3.dat.tables-bar-charts-intro.read-bar-charts"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g3.dat.tables-bar-charts-intro.draw-bar-chart", "parent": "g3.dat.tables-bar-charts-intro", "title": "Drawing a Bar Chart", "description": "Turn a small table into a bar chart: label the categories, choose a scale, draw each bar to the right height with equal widths and equal gaps, and give the chart a title.", "outcomes": ["Can draw a bar chart from a small table of data", "Can choose and label a sensible scale"], "prereqs": ["g3.dat.tables-bar-charts-intro.scaled-bars", "g3.dat.tables-bar-charts-intro.compare-difference-questions"], "est_minutes": 20, "difficulty": 2, "question": false}]}, {"id": "g4.num.numbers-to-100000", "title": "5-digit Numbers: Place Value and the Indian System", "grade": 4, "strand": "num", "description": "Numbers up to 1,00,000 open the door to real-world quantities like town populations, distances between cities and prices of scooters. You will read, write, compare and order 5-digit numbers, and use the Indian system of commas (ones, tens, hundreds, thousands, ten thousands). Knowing what each digit is worth is the key skill that all later arithmetic is built on.", "prereqs": ["g3.num.numbers-to-9999"], "outcomes": ["Can read and write 5-digit numbers in figures and words using Indian-system commas", "Can state the place value and face value of any digit in a 5-digit number", "Can compare and order 5-digit numbers by first counting digits, then comparing place by place", "Can expand a number as ten thousands + thousands + hundreds + tens + ones and rebuild it"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": [{"id": "g4.num.numbers-to-100000.ten-thousands-place", "parent": "g4.num.numbers-to-100000", "title": "The Ten-Thousands Place: Crossing 9,999", "description": "What happens one step after 9,999: a new column opens up. Build 10,000 from ten thousands and meet the five-column place-value frame (TTh Th H T O).", "outcomes": ["Can say what number comes after 9,999 and explain why a new column is needed", "Can place the digits of a 5-digit number into a TTh Th H T O frame"], "prereqs": ["g3.num.numbers-to-9999"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g4.num.numbers-to-100000.read-write-figures", "parent": "g4.num.numbers-to-100000", "title": "Reading and Writing 5-digit Numbers", "description": "Read 5-digit numbers aloud, write them from words, and place Indian-system commas (last three digits, then pairs). Zeros hold empty places and must be written.", "outcomes": ["Can write a spoken or worded number in figures using a place-value frame", "Can read a 5-digit numeral aloud correctly, including ones with middle zeros", "Can place Indian-system commas correctly in a 5-digit number"], "prereqs": ["g4.num.numbers-to-100000.ten-thousands-place"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.num.numbers-to-100000.place-face-value", "parent": "g4.num.numbers-to-100000", "title": "Place Value and Face Value", "description": "A digit's face value is the digit itself; its place value is digit × the worth of its column. The same digit is worth different amounts in different positions.", "outcomes": ["Can state the place value and the face value of any digit in a 5-digit number", "Can explain why the two 5s in 55,000 are worth different amounts"], "prereqs": ["g4.num.numbers-to-100000.read-write-figures"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.num.numbers-to-100000.expanded-form", "parent": "g4.num.numbers-to-100000", "title": "Expanded Form: Breaking and Rebuilding Numbers", "description": "Write a 5-digit number as ten-thousands + thousands + hundreds + tens + ones, and rebuild the numeral from an expansion — even a jumbled one.", "outcomes": ["Can expand a 5-digit number as a sum of place values", "Can rebuild the numeral from an expansion given in any order", "Can spot a wrong expansion such as 7 + 4 + 5 + 6 + 8 for 74,568"], "prereqs": ["g4.num.numbers-to-100000.place-face-value"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g4.num.numbers-to-100000.compare-order", "parent": "g4.num.numbers-to-100000", "title": "Comparing and Ordering 5-digit Numbers", "description": "Compare numbers by first counting digits — more digits means a bigger number — and only then comparing place by place from the left. Order sets of numbers ascending and descending.", "outcomes": ["Can compare two numbers by counting digits first, then comparing from the leftmost place", "Can order four or five large numbers from smallest to greatest"], "prereqs": ["g4.num.numbers-to-100000.place-face-value"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.num.numbers-to-100000.make-largest-smallest", "parent": "g4.num.numbers-to-100000", "title": "Making the Largest and Smallest Numbers from Digits", "description": "Given a set of digits, arrange them to build the largest and the smallest possible 5-digit number — including the trick that 0 cannot lead.", "outcomes": ["Can build the largest number by placing the biggest digit in the highest place", "Can build the smallest number, moving a 0 to second place instead of first"], "prereqs": ["g4.num.numbers-to-100000.compare-order"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g4.num.add-sub-large", "title": "Addition and Subtraction of Larger Numbers", "grade": 4, "strand": "num", "description": "Adding and subtracting 4- and 5-digit numbers lets you handle real quantities — ticket sales, populations, bank balances. The column method works exactly as it did for small numbers; the new challenges are carrying and borrowing across several places, especially across zeros. Estimation first tells you whether your exact answer is sensible.", "prereqs": ["g4.num.numbers-to-100000", "g3.num.add-sub-3digit"], "outcomes": ["Can add two numbers up to 5 digits with regrouping in any column", "Can subtract with borrowing, including across one or more zeros", "Can solve two-step word problems involving addition and subtraction", "Can estimate a sum or difference to check whether an exact answer is reasonable"], "difficulty": 1, "est_minutes": 40, "stub": false, "micros": [{"id": "g4.num.add-sub-large.estimate-first", "parent": "g4.num.add-sub-large", "title": "Estimate Before You Calculate", "description": "Round each number to a friendly nearby thousand or hundred and add or subtract in your head, so you know roughly what the exact answer must be before you start.", "outcomes": ["Can give a rough estimate for a sum or difference of 4- and 5-digit numbers", "Can use the estimate to reject an answer that is clearly too big or too small"], "prereqs": ["g3.num.add-sub-3digit", "g4.num.numbers-to-100000.compare-order"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g4.num.add-sub-large.add-with-regrouping", "parent": "g4.num.add-sub-large", "title": "Column Addition with Carrying", "description": "Add 4- and 5-digit numbers in columns, carrying into the next place whenever a column sum reaches 10 — sometimes in several columns of the same sum.", "outcomes": ["Can add two numbers up to 5 digits with carrying in any or all columns", "Can explain what the small carry mark records (ten ones traded for one ten)"], "prereqs": ["g3.num.add-sub-3digit", "g4.num.numbers-to-100000.place-face-value"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g4.num.add-sub-large.subtract-with-borrowing", "parent": "g4.num.add-sub-large", "title": "Column Subtraction with Borrowing", "description": "Subtract large numbers in columns. When the top digit is smaller, break one from the next place into ten — never just flip the digits around.", "outcomes": ["Can subtract numbers up to 5 digits with borrowing in one or more columns", "Can explain why 52 − 38 is not 26: you must borrow, not take smaller from larger"], "prereqs": ["g4.num.add-sub-large.add-with-regrouping"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g4.num.add-sub-large.borrow-across-zeros", "parent": "g4.num.add-sub-large", "title": "Borrowing Across Zeros", "description": "Subtracting from numbers like 7,000 means borrowing across several zeros. Rename the whole block first (7,000 = 6 thousands, 9 hundreds, 9 tens, 10 ones), then subtract place by place.", "outcomes": ["Can subtract from a number with one or more zeros in the top row", "Can rename a round number as thousands-hundreds-tens-ones before subtracting"], "prereqs": ["g4.num.add-sub-large.subtract-with-borrowing"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g4.num.add-sub-large.check-by-adding-back", "parent": "g4.num.add-sub-large", "title": "Checking Answers by Adding Back", "description": "Every subtraction can be checked: answer + number subtracted must give the starting number. Make the add-back check a habit that catches borrowing mistakes.", "outcomes": ["Can check a subtraction with the add-back rule and say whether the answer stands", "Can find which column went wrong when the check fails"], "prereqs": ["g4.num.add-sub-large.subtract-with-borrowing"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g4.num.add-sub-large.two-step-word-problems", "parent": "g4.num.add-sub-large", "title": "Two-step Word Problems", "description": "Real problems often need two moves — add first, then subtract, or the other way round. Plan the steps, estimate the answer, compute, and check it makes sense in the story.", "outcomes": ["Can plan and solve a word problem that needs both an addition and a subtraction", "Can state the answer in a sentence with the right unit and sense-check it"], "prereqs": ["g4.num.add-sub-large.add-with-regrouping", "g4.num.add-sub-large.borrow-across-zeros", "g4.num.add-sub-large.estimate-first"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g4.num.mult-multi-digit", "title": "Multi-digit Multiplication", "grade": 4, "strand": "num", "description": "Multiplying 2- and 3-digit numbers lets you scale things up fast: chairs in a hall, sticks of chalk in a delivery, rupees earned per day over a month. The big idea is breaking a number into tens and ones, multiplying each part, and adding the partial products — the written algorithm is just a tidy record of that.", "prereqs": ["g3.num.mult-tables", "g3.num.mult-2digit-by-1digit"], "outcomes": ["Can multiply a 2- or 3-digit number by a 1-digit number with carrying", "Can multiply two 2-digit numbers using partial products or the column method", "Can explain why a zero placeholder appears when multiplying by the tens digit", "Can solve multiplication word problems and check answers by estimating"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g4.num.mult-multi-digit.mult-by-10-100", "parent": "g4.num.mult-multi-digit", "title": "Multiplying by 10, 100 and Tens", "description": "Multiplying by 10 shifts every digit one place up, leaving a zero in the ones. Use this to compute 27 × 30 as 27 × 3 × 10 — the key fact behind the long multiplication algorithm.", "outcomes": ["Can multiply any number by 10 or 100 and explain the zero pattern by place value", "Can multiply by a multiple of ten, e.g. 27 × 30 = 810"], "prereqs": ["g3.num.mult-tables"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g4.num.mult-multi-digit.mult-2digit-by-1digit", "parent": "g4.num.mult-multi-digit", "title": "2-digit × 1-digit with Carrying", "description": "Multiply a 2-digit number by a 1-digit number in columns. The rule to say aloud every time: multiply first, THEN add the carry.", "outcomes": ["Can multiply a 2-digit number by a 1-digit number with a carry", "Can verbalise the order: times fact first, carry added after"], "prereqs": ["g3.num.mult-2digit-by-1digit"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.num.mult-multi-digit.mult-3digit-by-1digit", "parent": "g4.num.mult-multi-digit", "title": "3-digit × 1-digit Numbers", "description": "Extend column multiplication to 3-digit numbers, handling carries in more than one column and zeros inside the number (e.g. 305 × 7).", "outcomes": ["Can multiply a 3-digit number by a 1-digit number with carries in several columns", "Can handle a zero inside the 3-digit number correctly"], "prereqs": ["g4.num.mult-multi-digit.mult-2digit-by-1digit"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g4.num.mult-multi-digit.area-model-partials", "parent": "g4.num.mult-multi-digit", "title": "The Area (Box) Model and Partial Products", "description": "Split each factor into tens and ones and draw a box: 23 × 45 becomes four small products (20×40, 20×5, 3×40, 3×5) that add to the answer. This is what the written algorithm secretly records.", "outcomes": ["Can draw the box model for a 2-digit × 2-digit product and find all four partial products", "Can explain why multiplying digit-under-digit misses two of the four boxes"], "prereqs": ["g4.num.mult-multi-digit.mult-by-10-100", "g4.num.mult-multi-digit.mult-2digit-by-1digit"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g4.num.mult-multi-digit.mult-2digit-by-2digit", "parent": "g4.num.mult-multi-digit", "title": "2-digit × 2-digit Column Method", "description": "The compact written method: one row for the ones digit, one row for the tens digit ending in a placeholder zero because you are really multiplying by tens. Add the two partial products.", "outcomes": ["Can multiply two 2-digit numbers with the column method, writing the placeholder zero", "Can explain that the second row is 'times thirty', not 'times three'"], "prereqs": ["g4.num.mult-multi-digit.area-model-partials"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g4.num.mult-multi-digit.estimate-word-problems", "parent": "g4.num.mult-multi-digit", "title": "Estimating and Multiplication Word Problems", "description": "Round the factors to estimate the product first, then solve rows-and-columns, price and earnings problems, using the estimate to spot answers that are far too small or big.", "outcomes": ["Can estimate a product by rounding both factors to friendly numbers", "Can solve a multiplication word problem and check the answer against the estimate"], "prereqs": ["g4.num.mult-multi-digit.mult-2digit-by-2digit"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g4.num.division-long-intro", "title": "Long Division with 1-digit Divisors and Remainders", "grade": 4, "strand": "num", "description": "Long division shares a big number into equal groups place by place: divide, multiply, subtract, bring down. The remainder tells you what is left over when the sharing cannot be completed — and in real problems, deciding what to do with that remainder is as important as the division itself.", "prereqs": ["g3.num.division-intro", "g3.num.mult-tables"], "outcomes": ["Can divide a 2- or 3-digit number by a 1-digit number using long division", "Can express and check an answer as quotient × divisor + remainder = dividend", "Can explain why a remainder must be smaller than the divisor", "Can interpret the remainder sensibly in word problems (round up, drop, or report it)"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g4.num.division-long-intro.division-as-sharing-recap", "parent": "g4.num.division-long-intro", "title": "Division as Sharing and Grouping: Recap", "description": "Warm up the two meanings of division — sharing equally among plates and making groups of a fixed size — and its link to multiplication facts (24 ÷ 6 asks '6 times what is 24?').", "outcomes": ["Can model a division fact as sharing and as grouping with counters", "Can find a division answer from the matching multiplication table fact"], "prereqs": ["g3.num.division-intro", "g3.num.mult-tables"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g4.num.division-long-intro.divide-tens-then-ones", "parent": "g4.num.division-long-intro", "title": "Divide the Tens, Then the Ones", "description": "Share a 2-digit number place by place: split 84 into 8 tens and 4 ones, share the tens first, then the ones. This place-by-place sharing is what long division writes down.", "outcomes": ["Can divide a 2-digit number by a 1-digit number by sharing tens first, then ones", "Can exchange leftover tens into ones and keep sharing"], "prereqs": ["g4.num.division-long-intro.division-as-sharing-recap"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g4.num.division-long-intro.remainder-meaning", "parent": "g4.num.division-long-intro", "title": "What the Remainder Means", "description": "Sometimes sharing does not come out even — the remainder is what is left. The golden rule: a remainder must always be SMALLER than the divisor, or one more group could still be made.", "outcomes": ["Can find a quotient and remainder for a small division and say what each means", "Can explain why a remainder equal to or bigger than the divisor signals an unfinished division"], "prereqs": ["g4.num.division-long-intro.divide-tens-then-ones"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.num.division-long-intro.long-division-algorithm", "parent": "g4.num.division-long-intro", "title": "The Long Division Algorithm", "description": "Divide, multiply, subtract, bring down — repeated for each digit of the dividend. Every digit of the dividend gets a digit written above it, even when that digit is 0.", "outcomes": ["Can divide a 2- or 3-digit number by a 1-digit number using the written algorithm", "Can place a 0 in the quotient when a digit is too small to divide", "Can estimate the quotient first to catch missing-zero answers"], "prereqs": ["g4.num.division-long-intro.remainder-meaning"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g4.num.division-long-intro.check-by-multiplying", "parent": "g4.num.division-long-intro", "title": "Checking Division by Multiplying Back", "description": "Every division can be verified: quotient × divisor + remainder must rebuild the dividend exactly. Use the check to catch remainder and missing-zero slips.", "outcomes": ["Can check a division answer with quotient × divisor + remainder = dividend", "Can use a failed check to find and fix the error"], "prereqs": ["g4.num.division-long-intro.long-division-algorithm"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.num.division-long-intro.word-problems-interpret-remainder", "parent": "g4.num.division-long-intro", "title": "Word Problems: What to Do with the Remainder", "description": "In real problems the remainder must be interpreted: round up (everyone needs a seat), drop it (only full boxes count), or report it (sweets left over). The story decides.", "outcomes": ["Can decide whether a problem needs rounding up, dropping, or reporting the remainder", "Can state the final answer as a sensible sentence, not a bare 'q r n'"], "prereqs": ["g4.num.division-long-intro.long-division-algorithm", "g4.num.division-long-intro.check-by-multiplying"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g4.num.fractions-equal-parts", "title": "Fractions: Equal Parts, Comparing and Equivalence Intro", "grade": 4, "strand": "num", "description": "A fraction names equal parts of a whole: the bottom number tells how many equal parts the whole is cut into, and the top number tells how many of them we take. You will name fractions from pictures, compare simple fractions of the same whole, and meet the surprising idea that different-looking fractions like 1/2 and 3/6 can name the same amount.", "prereqs": ["g3.num.fractions-intro"], "outcomes": ["Can explain why fraction parts must be equal, and reject unequal-part 'fractions'", "Can name the fraction shown by a shaded region or a shared collection", "Can compare unit fractions of the same whole (1/4 vs 1/6) with a reason", "Can find a simple equivalent fraction using a picture or by doubling both numbers"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g4.num.fractions-equal-parts.equal-parts-idea", "parent": "g4.num.fractions-equal-parts", "title": "Fractions Need EQUAL Parts", "description": "A fraction only makes sense when the whole is cut into equal parts. Test cuttings of rotis, cakes and rectangles: equal parts earn fraction names, unequal parts do not.", "outcomes": ["Can say whether a picture shows real fractions by checking the parts are equal", "Can reject 'one of three pieces = one third' when the pieces differ in size"], "prereqs": ["g3.num.fractions-intro"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g4.num.fractions-equal-parts.name-shaded-fractions", "parent": "g4.num.fractions-equal-parts", "title": "Naming Fractions from Pictures", "description": "Read a fraction off a picture: the bottom number counts the equal parts the whole is cut into, the top number counts the parts taken. Say it aloud: 'cut into __ equal parts, take __'.", "outcomes": ["Can write the fraction for a shaded region or a shared collection", "Can say which number is the denominator and what job it does"], "prereqs": ["g4.num.fractions-equal-parts.equal-parts-idea"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.num.fractions-equal-parts.fraction-of-collection", "parent": "g4.num.fractions-equal-parts", "title": "Fractions of a Collection", "description": "A fraction can also name part of a group: 1/4 of 12 marbles means sharing 12 into 4 equal groups and taking one group. Connect the denominator to dividing.", "outcomes": ["Can find a unit fraction of a small collection by equal sharing", "Can explain why 1/4 of 12 is found by dividing 12 by 4"], "prereqs": ["g4.num.fractions-equal-parts.name-shaded-fractions", "g3.num.division-intro"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g4.num.fractions-equal-parts.compare-unit-fractions", "parent": "g4.num.fractions-equal-parts", "title": "Comparing Unit Fractions of the Same Whole", "description": "For the same whole, more parts means smaller parts: 1/4 of a chapati is bigger than 1/6 of it. Fold paper strips to see why the whole-number order flips for unit fractions.", "outcomes": ["Can compare two unit fractions of the same whole and give the more-parts-smaller-parts reason", "Can order three unit fractions such as 1/2, 1/5, 1/8"], "prereqs": ["g4.num.fractions-equal-parts.name-shaded-fractions"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.num.fractions-equal-parts.equivalent-fractions-intro", "parent": "g4.num.fractions-equal-parts", "title": "Equivalent Fractions: Different Names, Same Amount", "description": "Cutting every part in half doubles both numbers of a fraction but leaves the amount unchanged: 1/2 = 2/4 = 3/6. Meet equivalence with pictures and the fraction wall.", "outcomes": ["Can find an equivalent fraction by doubling (or tripling) both top and bottom", "Can use a picture to explain why 1/2 and 3/6 name the same amount", "Can spot false equivalents made by changing only one number"], "prereqs": ["g4.num.fractions-equal-parts.compare-unit-fractions"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g4.geo.circle-intro", "title": "The Circle: Centre and Radius", "grade": 4, "strand": "geo", "description": "A circle is the set of all points at the same distance from one special point, the centre. That fixed distance is the radius, and a line through the centre from edge to edge is the diameter — always twice the radius. This 'same distance all around' idea explains why wheels roll smoothly and why a compass draws a perfect circle.", "prereqs": ["g3.geo.lines-shapes", "g3.mea.length-std-units"], "outcomes": ["Can identify and label the centre, radius and diameter of a circle", "Can explain that all radii of a circle are equal, and use diameter = 2 × radius", "Can draw a circle of a given radius with a compass", "Can explain why wheels are circles using the equal-radius property"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g4.geo.circle-intro.parts-of-circle", "parent": "g4.geo.circle-intro", "title": "Centre, Radius, Diameter: Naming the Parts", "description": "Meet the circle's special point (centre), the centre-to-edge distance (radius), the edge-to-edge line through the centre (diameter), and the boundary itself. Label them on drawings and real wheels.", "outcomes": ["Can point out and label centre, radius and diameter on a circle", "Can describe a circle as all points the same distance from the centre"], "prereqs": ["g3.geo.lines-shapes"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g4.geo.circle-intro.all-radii-equal", "parent": "g4.geo.circle-intro", "title": "All Radii of a Circle Are Equal", "description": "Draw a circle with string and chalk: the string cannot stretch, so every point of the curve is exactly one string-length from the centre. Equal radii are what MAKE a circle.", "outcomes": ["Can state that all radii of one circle are equal, without measuring each one", "Can use the string-and-chalk construction to justify the equal-radius property"], "prereqs": ["g4.geo.circle-intro.parts-of-circle"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.geo.circle-intro.diameter-double-radius", "parent": "g4.geo.circle-intro", "title": "Diameter = 2 × Radius", "description": "Fold a paper circle in half: the crease is a diameter, made of two radii laid end to end. Convert between radius and diameter in both directions.", "outcomes": ["Can find the diameter from the radius and the radius from the diameter", "Can show with a folded circle why the diameter is twice the radius"], "prereqs": ["g4.geo.circle-intro.all-radii-equal"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.geo.circle-intro.diameter-vs-chord", "parent": "g4.geo.circle-intro", "title": "No Centre, No Diameter", "description": "Many lines can join two points on a circle (chords), but only the ones through the centre are diameters — and they are the longest. Test lines with the centre rule, not by eye.", "outcomes": ["Can decide whether a line across a circle is a diameter by checking it passes through the centre", "Can explain why the diameter is the longest chord"], "prereqs": ["g4.geo.circle-intro.diameter-double-radius"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.geo.circle-intro.compass-drawing", "parent": "g4.geo.circle-intro", "title": "Drawing Circles with a Compass", "description": "Set the compass opening to the RADIUS, plant the point at the centre, and sweep. Draw circles of a given radius — and of a given diameter, halving first.", "outcomes": ["Can draw a neat circle of a given radius with a compass", "Can set the compass correctly when the DIAMETER is given, by halving it first"], "prereqs": ["g4.geo.circle-intro.diameter-double-radius", "g3.mea.length-std-units"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.geo.circle-intro.why-wheels-round", "parent": "g4.geo.circle-intro", "title": "Why Wheels Are Round", "description": "Because all radii are equal, a rolling wheel keeps its axle at a constant height — that is why carts do not bump up and down. Connect the equal-radius property to wheels, bangles and manhole covers.", "outcomes": ["Can explain a smooth wheel ride using the equal-radius property", "Can predict what would happen with a square or oval wheel"], "prereqs": ["g4.geo.circle-intro.all-radii-equal"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g4.geo.symmetry-reflection", "title": "Symmetry and Reflection", "grade": 4, "strand": "geo", "description": "A shape has line symmetry when one half folds exactly onto the other — the fold line is the line of symmetry, and it acts like a mirror. You will find symmetry lines by folding and with mirrors, count them for common shapes and letters, and draw the mirror image of a simple figure.", "prereqs": ["g3.geo.lines-shapes"], "outcomes": ["Can test a proposed line of symmetry by folding or with a mirror", "Can find all lines of symmetry of squares, rectangles, triangles and letters", "Can draw the reflection of a simple shape across a mirror line", "Can explain why equal halves are not always mirror halves (e.g. a rectangle's diagonal)"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g4.geo.symmetry-reflection.fold-test", "parent": "g4.geo.symmetry-reflection", "title": "The Fold Test for Symmetry", "description": "A line of symmetry is a fold along which the two halves land EXACTLY on each other. Equal-sized halves are not enough — they must match point for point when folded.", "outcomes": ["Can test a proposed line of symmetry by folding a cut-out or using a mirror", "Can explain why a rectangle's diagonal cuts equal halves but is not a symmetry line"], "prereqs": ["g3.geo.lines-shapes"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g4.geo.symmetry-reflection.find-all-lines", "parent": "g4.geo.symmetry-reflection", "title": "Finding ALL the Lines of Symmetry", "description": "Hunt for every fold line of squares, rectangles, triangles and circles — vertical, horizontal and slanted. Rotate the cut-out so tilted lines are not missed.", "outcomes": ["Can find all lines of symmetry of common shapes (square 4, rectangle 2, equilateral triangle 3)", "Can keep hunting after the first line is found, in every direction"], "prereqs": ["g4.geo.symmetry-reflection.fold-test"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.geo.symmetry-reflection.letters-numbers", "parent": "g4.geo.symmetry-reflection", "title": "Symmetry in Letters and Numbers", "description": "Sort the alphabet by symmetry: A has a vertical line, E has a horizontal one, H and O have both, F has none. A small mirror makes the hunt a game.", "outcomes": ["Can find vertical and horizontal symmetry lines in capital letters and digits", "Can name letters with no line of symmetry"], "prereqs": ["g4.geo.symmetry-reflection.find-all-lines"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.geo.symmetry-reflection.draw-reflection", "parent": "g4.geo.symmetry-reflection", "title": "Drawing Mirror Images", "description": "A reflection FLIPS a shape: each point moves to the same distance on the other side of the mirror line, and left-right (or top-bottom) reverses. Copying without flipping is a slide, not a reflection.", "outcomes": ["Can draw the reflection of a simple shape or letter across a mirror line", "Can check a reflection by matching point distances and reversed orientation"], "prereqs": ["g4.geo.symmetry-reflection.fold-test"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.geo.symmetry-reflection.complete-figures", "parent": "g4.geo.symmetry-reflection", "title": "Completing Symmetric Figures on a Grid", "description": "Given half a figure and its mirror line on squared paper, draw the missing half: count each point's squares to the line and match them on the other side.", "outcomes": ["Can complete a symmetric figure across a vertical or horizontal mirror line on a grid", "Can verify the finished figure with the fold test or a mirror"], "prereqs": ["g4.geo.symmetry-reflection.draw-reflection"], "est_minutes": 20, "difficulty": 2, "question": false}]}, {"id": "g4.mea.perimeter-intro", "title": "Perimeter as Boundary Length", "grade": 4, "strand": "mea", "description": "Perimeter is the total length of the boundary of a shape — the distance you would walk going once around it. You find it by adding all the side lengths. It answers real questions like how much fencing a field needs or how much lace goes around a tablecloth, and it is measured in units of length (cm, m).", "prereqs": ["g3.mea.length-std-units", "g3.num.add-sub-3digit"], "outcomes": ["Can find the perimeter of any straight-sided shape by adding all its side lengths", "Can find the perimeter of rectangles and squares, using the repeated sides", "Can solve fencing/border word problems, including finding a missing side from the perimeter", "Can explain that shapes with the same area can have different perimeters"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": [{"id": "g4.mea.perimeter-intro.boundary-idea", "parent": "g4.mea.perimeter-intro", "title": "Perimeter Is the Walk Around the Boundary", "description": "Perimeter is the total distance once around a shape — the length of fence, lace or one lap. It is measured in length units (cm, m). First question for any problem: fence or paint?", "outcomes": ["Can explain perimeter as boundary length and give real examples (fencing, lace, laps)", "Can say that perimeter is measured in cm or m, not square units"], "prereqs": ["g3.mea.length-std-units"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g4.mea.perimeter-intro.add-all-sides", "parent": "g4.mea.perimeter-intro", "title": "Adding All the Sides", "description": "For any straight-sided shape, trace the whole trip around it and add EVERY side length — triangles, quadrilaterals and odd shapes, including ones with an unlabelled repeated side.", "outcomes": ["Can find the perimeter of a triangle or irregular shape by adding all side lengths", "Can keep track of sides so none is missed or counted twice"], "prereqs": ["g4.mea.perimeter-intro.boundary-idea", "g3.num.add-sub-3digit"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.mea.perimeter-intro.rectangle-perimeter", "parent": "g4.mea.perimeter-intro", "title": "Perimeter of a Rectangle", "description": "A rectangle's trip goes long-short-long-short: each labelled side appears TWICE. Add all four sides, then meet the shortcut 2 × (length + width).", "outcomes": ["Can find a rectangle's perimeter using all four sides", "Can use and explain the shortcut 2 × (length + width)"], "prereqs": ["g4.mea.perimeter-intro.add-all-sides"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.mea.perimeter-intro.square-perimeter", "parent": "g4.mea.perimeter-intro", "title": "Perimeter of a Square", "description": "A square's four sides are equal, so its perimeter is 4 × side. Solve fencing problems and reverse ones: given the perimeter, find the side.", "outcomes": ["Can find a square's perimeter with 4 × side", "Can find the side of a square from its perimeter by dividing by 4"], "prereqs": ["g4.mea.perimeter-intro.rectangle-perimeter"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.mea.perimeter-intro.missing-side", "parent": "g4.mea.perimeter-intro", "title": "Finding a Missing Side from the Perimeter", "description": "Work backwards: if the perimeter and some sides are known, subtract to find the missing side. For rectangles, remember the missing width appears twice in the total.", "outcomes": ["Can find a missing side of a shape when the perimeter and other sides are given", "Can solve rectangle problems where the unknown side occurs twice"], "prereqs": ["g4.mea.perimeter-intro.rectangle-perimeter"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g4.mea.perimeter-intro.same-tiles-different-boundary", "parent": "g4.mea.perimeter-intro", "title": "Same Tiles, Different Boundary", "description": "Build different shapes from the same square tiles and count their boundary units: a stretched-out row has a longer boundary than a compact block. Same covering does not mean same perimeter.", "outcomes": ["Can count boundary units of tile shapes on a grid", "Can show with an example that equal tile counts can give different perimeters"], "prereqs": ["g4.mea.perimeter-intro.rectangle-perimeter"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g4.mea.area-intro", "title": "Area by Counting Squares", "grade": 4, "strand": "mea", "description": "Area measures how much surface a shape covers, and we measure it by counting unit squares that tile the shape. Full squares count as 1, two half squares make 1, and rows of squares can be counted quickly with multiplication. Area answers 'how much carpet, paint or land?' — a different question from how long the boundary is.", "prereqs": ["g3.geo.lines-shapes", "g3.num.mult-tables"], "outcomes": ["Can find the area of a shape on squared paper by counting unit squares, combining half squares", "Can use rows × columns to count squares in a rectangle quickly", "Can compare areas of different shapes drawn on the same grid", "Can explain the difference between area (covering) and perimeter (boundary)"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": [{"id": "g4.mea.area-intro.covering-idea", "parent": "g4.mea.area-intro", "title": "Area Is How Much a Shape Covers", "description": "Area answers 'how much carpet, paint or land?' and is measured in square units by covering the shape with unit squares — a different question from the boundary walk.", "outcomes": ["Can tell an area question (covering) from a perimeter question (boundary)", "Can say that area is measured in square units"], "prereqs": ["g4.mea.perimeter-intro.boundary-idea"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g4.mea.area-intro.count-unit-squares", "parent": "g4.mea.area-intro", "title": "Counting Unit Squares", "description": "Find the area of grid shapes by counting the unit squares they cover, marking each counted square so none is missed or double-counted — including L-shapes and staircases.", "outcomes": ["Can find the area of a grid shape by counting full unit squares", "Can compare two shapes on the same grid by their square counts"], "prereqs": ["g4.mea.area-intro.covering-idea"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g4.mea.area-intro.half-squares", "parent": "g4.mea.area-intro", "title": "Handling Half Squares", "description": "Slanted and curved shapes cover partial squares. Rule set: full square = 1, two halves = 1; for estimates, more than half ≈ 1 and less than half ≈ 0.", "outcomes": ["Can find the area of a shape with half squares by pairing them up", "Can estimate the area of a curved shape (like a leaf) on squared paper"], "prereqs": ["g4.mea.area-intro.count-unit-squares"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.mea.area-intro.rows-times-columns", "parent": "g4.mea.area-intro", "title": "Counting Squares Fast: Rows × Columns", "description": "In a rectangle the squares sit in equal rows, so multiply rows by columns instead of counting one by one. This shortcut is the seed of the area formula met in Class 5.", "outcomes": ["Can find a grid rectangle's area with rows × columns", "Can explain why multiplying counts exactly the same squares as counting one by one"], "prereqs": ["g4.mea.area-intro.count-unit-squares", "g3.num.mult-tables"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.mea.area-intro.same-perimeter-different-area", "parent": "g4.mea.area-intro", "title": "Same Boundary, Different Area", "description": "Bend one loop of string into different rectangles and count the enclosed squares: the boundary stays the same but the area changes. Equal perimeter does NOT mean equal area.", "outcomes": ["Can show with one string loop that equal perimeters can enclose different areas", "Can explain why compact shapes enclose more than stretched ones"], "prereqs": ["g4.mea.area-intro.rows-times-columns", "g4.mea.perimeter-intro.rectangle-perimeter"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g4.mea.time-duration", "title": "Elapsed Time and the 24-hour Clock", "grade": 4, "strand": "mea", "description": "Elapsed time is how long something lasts — from a movie's start to its end, or a train's departure to its arrival. Because an hour has 60 minutes (not 100), adding and subtracting times needs care at the hour boundary. The 24-hour clock, used in railway timetables, removes the confusion between morning and evening times.", "prereqs": ["g3.mea.time-clock"], "outcomes": ["Can convert between 12-hour (am/pm) and 24-hour clock times", "Can add a duration to a start time, regrouping 60 minutes into 1 hour", "Can find the elapsed time between two clock times, including across noon", "Can read a railway timetable and answer duration questions from it"], "difficulty": 1, "est_minutes": 40, "stub": false, "micros": [{"id": "g4.mea.time-duration.clock-24-hour", "parent": "g4.mea.time-duration", "title": "The 24-hour Clock", "description": "After noon the railway clock keeps counting: 13:00, 14:00, ... 23:59. Convert both ways between am/pm times and 24-hour times using the anchor noon = 12:00.", "outcomes": ["Can convert a 24-hour time to am/pm by subtracting 12 after noon", "Can convert an afternoon or evening time to 24-hour form by adding 12"], "prereqs": ["g3.mea.time-clock"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.mea.time-duration.add-minutes-within-hour", "parent": "g4.mea.time-duration", "title": "Adding Minutes Inside One Hour", "description": "Add a duration to a start time when the sum of minutes stays under 60 — 3:10 + 25 minutes = 3:35. Reading durations in minutes and relating them to quarter and half hours.", "outcomes": ["Can add minutes to a time when no hour boundary is crossed", "Can use quarter-hour landmarks (15, 30, 45 minutes) fluently"], "prereqs": ["g3.mea.time-clock"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g4.mea.time-duration.cross-hour-boundary", "parent": "g4.mea.time-duration", "title": "Crossing the Hour: 60 Minutes, Not 100", "description": "When minutes pass 60 they roll into a new hour — there is no such time as 4:75. Split the added minutes at the next o'clock on a number line of minutes.", "outcomes": ["Can add a duration that crosses an hour boundary by splitting at the next o'clock", "Can explain why times like 4:75 are impossible"], "prereqs": ["g4.mea.time-duration.add-minutes-within-hour"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.mea.time-duration.elapsed-time-number-line", "parent": "g4.mea.time-duration", "title": "Elapsed Time on an Empty Number Line", "description": "Find how long something lasts by hopping on a time line: jump to the next o'clock, hop whole hours, then the final minutes. Works for any two times on the same side of noon.", "outcomes": ["Can find the duration between two times using jumps on an empty time line", "Can add the hour and minute jumps into a total like 2 h 30 min"], "prereqs": ["g4.mea.time-duration.cross-hour-boundary"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g4.mea.time-duration.elapsed-across-noon", "parent": "g4.mea.time-duration", "title": "Elapsed Time Across Noon", "description": "Durations that cross 12 o'clock cannot be found by subtracting clock numbers. Bridge at noon: start → 12:00, then 12:00 → finish, and add the two jumps.", "outcomes": ["Can find a duration from a morning time to an afternoon time with the noon bridge", "Can explain why subtracting the clock numbers directly gives nonsense"], "prereqs": ["g4.mea.time-duration.elapsed-time-number-line", "g4.mea.time-duration.clock-24-hour"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g4.mea.time-duration.railway-timetables", "parent": "g4.mea.time-duration", "title": "Reading Railway Timetables", "description": "Use real timetables in 24-hour time: find departures and arrivals, compute journey lengths, and compare trains. All the elapsed-time skills come together here.", "outcomes": ["Can read departure and arrival times from a 24-hour timetable", "Can compute a journey's duration from timetable times", "Can answer comparison questions (which train is faster, which reaches first)"], "prereqs": ["g4.mea.time-duration.elapsed-across-noon"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g4.mea.unit-conversions", "title": "Unit Conversions: Length, Weight, Capacity", "grade": 4, "strand": "mea", "description": "Metres and centimetres, kilograms and grams, litres and millilitres — the metric system connects big and small units by factors of 100 and 1000. Converting between them means multiplying when going to smaller units and dividing when going to bigger ones. Mixed measures like 3 m 5 cm must be handled place by place, not glued together.", "prereqs": ["g3.mea.length-std-units", "g3.mea.weight-capacity", "g3.num.mult-tables"], "outcomes": ["Can state the key metric relations: 1 m = 100 cm, 1 km = 1000 m, 1 kg = 1000 g, 1 L = 1000 mL", "Can convert a measure to a smaller unit by multiplying, and to a larger unit by dividing", "Can express mixed measures (3 m 5 cm) as a single unit correctly", "Can choose sensible units and estimate everyday lengths, weights and capacities"], "difficulty": 1, "est_minutes": 40, "stub": false, "micros": [{"id": "g4.mea.unit-conversions.metric-fact-family", "parent": "g4.mea.unit-conversions", "title": "The Metric Fact Family", "description": "Fix the four key relations with real objects: 1 m = 100 cm (metre stick), 1 km = 1000 m (distance boards), 1 kg = 1000 g (sugar pack), 1 L = 1000 mL (water bottle).", "outcomes": ["Can state the four key metric relations from memory", "Can name a real object that proves each relation"], "prereqs": ["g3.mea.length-std-units", "g3.mea.weight-capacity"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g4.mea.unit-conversions.to-smaller-multiply", "parent": "g4.mea.unit-conversions", "title": "Converting to a Smaller Unit: Multiply", "description": "A smaller unit needs MORE of them, so multiply by the factor: 7 m = 700 cm, 4 kg = 4000 g. Say the sense-check sentence aloud before computing.", "outcomes": ["Can convert m→cm, km→m, kg→g and L→mL by multiplying by the right factor", "Can justify the direction: smaller units means a bigger count"], "prereqs": ["g4.mea.unit-conversions.metric-fact-family", "g3.num.mult-tables"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.mea.unit-conversions.to-bigger-divide", "parent": "g4.mea.unit-conversions", "title": "Converting to a Bigger Unit: Divide", "description": "A bigger unit needs FEWER of them, so divide by the factor: 5000 m = 5 km, 300 cm = 3 m. An absurd-looking answer (a 25,000 m table!) means the direction was wrong.", "outcomes": ["Can convert cm→m, m→km, g→kg and mL→L by dividing by the right factor", "Can catch a wrong-direction conversion by sense-checking the answer's size"], "prereqs": ["g4.mea.unit-conversions.to-smaller-multiply"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.mea.unit-conversions.mixed-measures", "parent": "g4.mea.unit-conversions", "title": "Mixed Measures: 2 kg 50 g Is Not 250 g", "description": "Convert mixed measures like 3 m 5 cm or 2 kg 50 g to a single unit: convert the big-unit part first, THEN add the small part. Never glue the digits together.", "outcomes": ["Can express a mixed measure in the smaller unit by converting then adding", "Can explain the zero that holds the empty place (3 m 5 cm = 305 cm, not 35 or 350)"], "prereqs": ["g4.mea.unit-conversions.to-smaller-multiply"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g4.mea.unit-conversions.choose-sensible-units", "parent": "g4.mea.unit-conversions", "title": "Choosing Sensible Units and Estimating", "description": "Pick the right unit for the job — km for city distances, g for a pencil — and estimate everyday measures: a door is about 2 m, an apple about 150 g, a bucket about 10 L.", "outcomes": ["Can choose the sensible unit for a given object or distance", "Can give a reasonable estimate for everyday lengths, weights and capacities"], "prereqs": ["g4.mea.unit-conversions.metric-fact-family"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g4.mea.unit-conversions.conversion-word-problems", "parent": "g4.mea.unit-conversions", "title": "Word Problems with Unit Conversions", "description": "Solve shopping and measuring problems where quantities come in mixed units: total cloth bought in m and cm, milk in L and mL. Convert to one unit before adding or comparing.", "outcomes": ["Can bring all quantities to one unit before adding or comparing", "Can answer with the sensible unit and sense-check the size of the result"], "prereqs": ["g4.mea.unit-conversions.to-bigger-divide", "g4.mea.unit-conversions.mixed-measures"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g4.alg.patterns-rules", "title": "Patterns and Rules", "grade": 4, "strand": "alg", "description": "A pattern is a sequence built by a rule — add the same number, double, or repeat a block of shapes. The mathematician's job is to find the rule, check it against EVERY step given, and then use it to predict what comes next (or far ahead) without drawing everything. This is the first step toward algebra.", "prereqs": ["g3.alg.patterns-number"], "outcomes": ["Can find and state the rule of a number pattern and extend it", "Can check a proposed rule against every given term, not just the first pair", "Can identify the repeating unit of a shape pattern and predict a far-away term (e.g. the 20th shape)", "Can create a pattern from a given rule and describe features of it"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": [{"id": "g4.alg.patterns-rules.repeating-unit", "parent": "g4.alg.patterns-rules", "title": "Finding the Repeating Unit", "description": "In a repeating pattern, first bracket the block that repeats — [red red blue] — and then continue by restarting the block, not by copying the last item.", "outcomes": ["Can circle the repeating block of a shape or colour pattern", "Can extend a repeating pattern by restarting its block"], "prereqs": ["g3.alg.patterns-number"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g4.alg.patterns-rules.predict-far-term", "parent": "g4.alg.patterns-rules", "title": "Predicting a Far-away Term", "description": "Use the block length to leap ahead: for a block of 3, the 20th item is found from 20 = 6 blocks + 2, so it matches position 2 — no drawing twenty items.", "outcomes": ["Can find a far-away term of a repeating pattern using full blocks and leftovers", "Can explain the method as division with remainder in disguise"], "prereqs": ["g4.alg.patterns-rules.repeating-unit"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g4.alg.patterns-rules.find-number-rule", "parent": "g4.alg.patterns-rules", "title": "Finding the Rule of a Number Pattern", "description": "Ask 'what is DONE to each term to get the next?' — add the same number, or multiply. Find the rule and use it to extend the pattern.", "outcomes": ["Can state the rule of an adding or doubling pattern", "Can extend a number pattern two or three terms using its rule"], "prereqs": ["g3.alg.patterns-number", "g3.num.mult-tables"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.alg.patterns-rules.check-rule-every-step", "parent": "g4.alg.patterns-rules", "title": "A Rule Must Work at EVERY Step", "description": "A candidate rule earns the right to predict only after it explains every given step. Write the rule over each gap and tick it — one failure and the rule is out.", "outcomes": ["Can test a proposed rule against all the given terms, not just the first pair", "Can reject a rule with a counterexample step"], "prereqs": ["g4.alg.patterns-rules.find-number-rule"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.alg.patterns-rules.decreasing-patterns", "parent": "g4.alg.patterns-rules", "title": "Patterns Can Shrink Too", "description": "Rules can subtract as well as add: 50, 45, 40 keeps dropping by 5. Practise decreasing patterns beside growing ones so 'pattern' does not mean 'goes up'.", "outcomes": ["Can find and continue a decreasing number pattern", "Can describe a rule neutrally, e.g. 'subtract 5 each time'"], "prereqs": ["g4.alg.patterns-rules.find-number-rule"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g4.alg.patterns-rules.create-own-patterns", "parent": "g4.alg.patterns-rules", "title": "Creating Patterns from a Rule", "description": "Turn a given rule into a pattern of your own — 'start at 7, add 6' or a repeating block you design — and describe its features (all odd? every third term?).", "outcomes": ["Can generate a pattern from a stated starting number and rule", "Can notice and describe a feature of the pattern that the rule creates"], "prereqs": ["g4.alg.patterns-rules.check-rule-every-step", "g4.alg.patterns-rules.repeating-unit"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g4.dat.bar-charts", "title": "Reading and Drawing Bar Charts", "grade": 4, "strand": "dat", "description": "A bar chart shows data as bars whose heights stand for amounts, read off a scaled axis. The crucial skill is using the scale: when one division stands for 5 or 10, you multiply divisions by the scale instead of counting lines. You will read values, compare categories, answer 'how many more' questions and draw your own charts from a table.", "prereqs": ["g3.dat.tables-bar-charts-intro", "g3.num.mult-tables"], "outcomes": ["Can read a value from a bar chart whose scale is 2, 5 or 10 per division", "Can compare two bars and find 'how many more/less' as a difference of values", "Can draw a bar chart from a data table, choosing a sensible scale", "Can answer multi-step questions (totals, differences) from one chart"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": [{"id": "g4.dat.bar-charts.read-one-unit-bars", "parent": "g4.dat.bar-charts", "title": "Reading Bars When One Division = 1", "description": "Recap bar charts where each gridline step stands for exactly 1: read values, find the tallest and shortest bars, and connect each bar to its label.", "outcomes": ["Can read values from a bar chart with a 1-per-division scale", "Can identify the largest and smallest categories from bar heights"], "prereqs": ["g3.dat.tables-bar-charts-intro"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g4.dat.bar-charts.read-scaled-bars", "parent": "g4.dat.bar-charts", "title": "Reading Scaled Bar Charts", "description": "When one division stands for 2, 5 or 10, a bar's value is divisions × scale. Start every reading with the scale-check ritual: touch the axis, say '1 division = __'.", "outcomes": ["Can read a value from a chart whose scale is 2, 5 or 10 per division", "Can perform the scale check before answering any question"], "prereqs": ["g4.dat.bar-charts.read-one-unit-bars", "g3.num.mult-tables"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.dat.bar-charts.category-and-value", "parent": "g4.dat.bar-charts", "title": "Category or Value: Answering What Is Asked", "description": "Every bar carries two facts: its label (category) and its height (value). 'Which fruit?' wants the label; 'how many?' wants the number. Practise the two-part sentence 'mango has 40 votes'.", "outcomes": ["Can answer 'which' questions with the category and 'how many' questions with the value", "Can state any bar as a full sentence linking label and value"], "prereqs": ["g4.dat.bar-charts.read-one-unit-bars"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g4.dat.bar-charts.compare-bars-difference", "parent": "g4.dat.bar-charts", "title": "How Many More? Comparing Two Bars", "description": "'How many more A than B?' asks for the difference A − B — the stub of the taller bar poking above the shorter one — not A's value. Read both bars, then subtract.", "outcomes": ["Can answer 'how many more/fewer' questions by subtracting two bar values", "Can point to the difference as the part of the taller bar above the shorter one"], "prereqs": ["g4.dat.bar-charts.read-scaled-bars"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g4.dat.bar-charts.draw-bar-chart", "parent": "g4.dat.bar-charts", "title": "Drawing a Bar Chart from a Table", "description": "Turn a data table into a chart: choose a sensible scale, label the axes, and draw each bar to exactly the right height — including half divisions when the data demands them.", "outcomes": ["Can choose a sensible scale for the given data", "Can draw bars of exactly the right height, using part divisions where needed"], "prereqs": ["g4.dat.bar-charts.read-scaled-bars"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g4.dat.bar-charts.multi-step-questions", "parent": "g4.dat.bar-charts", "title": "Totals and Multi-step Chart Questions", "description": "Combine readings: totals across all bars, differences chained with sums ('how many children in all?', 'how many more on the two busiest days?'). Read each bar with the scale first, then compute.", "outcomes": ["Can find a total across several bars of a scaled chart", "Can solve a two-step question mixing addition and subtraction of bar values"], "prereqs": ["g4.dat.bar-charts.compare-bars-difference", "g4.dat.bar-charts.draw-bar-chart"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g5.num.large-numbers", "title": "Large Numbers: Lakhs, Comparing, Rounding", "grade": 5, "strand": "num", "description": "Beyond ten thousand come lakhs (1,00,000) and ten lakhs — the numbers of city populations, fish-catch tonnages and film box-office collections. You will read and write 6- and 7-digit numbers in the Indian system, compare and order them, and round them to the nearest ten, hundred or thousand to make them easy to talk about.", "prereqs": ["g4.num.numbers-to-100000"], "outcomes": ["Can read and write numbers up to ten lakh using Indian-system commas", "Can compare and order large numbers by digit count, then place-by-place", "Can round a number to the nearest ten, hundred or thousand using the digit to the right", "Can use rounded numbers to estimate sums and to sense-check calculations"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g5.num.large-numbers.lakh-landmark", "parent": "g5.num.large-numbers", "title": "The Lakh Landmark", "description": "Meet 1,00,000 as one lakh: how many zeros it has, where it sits on the number ladder, and where the Indian-system commas go (three digits from the right, then pairs).", "outcomes": ["Can write 1 lakh and 10 lakh in figures with correct Indian-system commas", "Can recite the landmark ladder: 1,000 -> 10,000 -> 1,00,000 -> 10,00,000"], "prereqs": ["g4.num.numbers-to-100000"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.num.large-numbers.read-write-6-7-digit", "parent": "g5.num.large-numbers", "title": "Reading and Writing 6- and 7-digit Numbers", "description": "Read and write numbers up to ten lakh in figures and in words, using a place-value frame (TL L TTh Th H T O) and filling untouched columns with zeros.", "outcomes": ["Can write a spoken 6- or 7-digit number in figures with every zero in place", "Can read a 6- or 7-digit numeral aloud in words using lakhs and thousands"], "prereqs": ["g5.num.large-numbers.lakh-landmark"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.large-numbers.compare-order", "parent": "g5.num.large-numbers", "title": "Comparing and Ordering Large Numbers", "description": "Compare and order numbers up to ten lakh: count digits first, and only when the digit counts match, compare place by place from the left.", "outcomes": ["Can state which of two large numbers is greater, giving digit count as the first reason", "Can order four or five large numbers from smallest to greatest"], "prereqs": ["g5.num.large-numbers.read-write-6-7-digit"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.num.large-numbers.round-nearest", "parent": "g5.num.large-numbers", "title": "Rounding to the Nearest Ten, Hundred and Thousand", "description": "Round a number by finding its two neighbours at the rounding place and choosing the closer one, using the digit to the right to decide. Rounding is about closeness, not chopping.", "outcomes": ["Can round any number to the nearest ten, hundred or thousand", "Can show a rounding decision on an empty number line between the two neighbours"], "prereqs": ["g5.num.large-numbers.read-write-6-7-digit"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.large-numbers.estimate-check", "parent": "g5.num.large-numbers", "title": "Estimating with Rounded Numbers", "description": "Use rounded numbers to estimate sums and differences before calculating exactly, and use the estimate to sense-check the exact answer.", "outcomes": ["Can estimate a sum or difference by rounding each number first", "Can spot an unreasonable exact answer by comparing it with an estimate"], "prereqs": ["g5.num.large-numbers.round-nearest", "g4.num.add-sub-large"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g5.num.mult-div-large", "title": "Multiplication and Division with Larger Numbers", "grade": 5, "strand": "num", "description": "Now the numbers grow: multiplying 3-digit numbers by 2-digit numbers, multiplying by tens and hundreds using zero patterns, and dividing by 2-digit numbers. The methods are the same ones you know — partial products and divide-multiply-subtract-bring-down — applied with more care, and always sanity-checked with estimation.", "prereqs": ["g4.num.mult-multi-digit", "g4.num.division-long-intro"], "outcomes": ["Can multiply by 10, 100 and their multiples using zero patterns correctly", "Can multiply a 3-digit number by a 2-digit number using partial products", "Can divide by a 2-digit divisor, with the remainder smaller than the divisor", "Can estimate products and quotients first, and verify division by multiplying back"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g5.num.mult-div-large.multiply-tens-hundreds", "parent": "g5.num.mult-div-large", "title": "Multiplying by Tens and Hundreds (Zero Patterns)", "description": "Multiply numbers like 60 x 400 by separating the basic fact from the zeros: do 6 x 4, then attach exactly the zeros that came from each factor.", "outcomes": ["Can multiply by 10, 100 and their multiples using counted zeros", "Can explain where each zero in the answer came from"], "prereqs": ["g4.num.mult-multi-digit"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.num.mult-div-large.estimate-products-quotients", "parent": "g5.num.mult-div-large", "title": "Estimating Products and Quotients", "description": "Round the numbers to friendly tens and hundreds to estimate a product or quotient before computing, so a wildly wrong exact answer is caught immediately.", "outcomes": ["Can estimate a product like 245 x 32 as about 250 x 30", "Can use an estimate to reject an answer that is far too big or too small"], "prereqs": ["g5.num.mult-div-large.multiply-tens-hundreds", "g5.num.large-numbers.round-nearest"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g5.num.mult-div-large.mult-3digit-by-2digit", "parent": "g5.num.mult-div-large", "title": "Multiplying 3-digit by 2-digit Numbers", "description": "Multiply a 3-digit number by a 2-digit number using partial products, writing the second row as a multiplication by tens — with its placeholder zero written first.", "outcomes": ["Can compute a 3-digit x 2-digit product with both partial products", "Can explain why the second partial-product row must end in zero"], "prereqs": ["g5.num.mult-div-large.estimate-products-quotients"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g5.num.mult-div-large.divide-2digit-divisor", "parent": "g5.num.mult-div-large", "title": "Dividing by a 2-digit Divisor", "description": "Run long division with 2-digit divisors like 21 and 24: estimate each quotient digit by trying multiples of the divisor, then divide-multiply-subtract-bring-down as usual.", "outcomes": ["Can divide a 3-digit number by a 2-digit divisor", "Can choose a sensible first quotient digit by trying multiples of the divisor"], "prereqs": ["g5.num.mult-div-large.estimate-products-quotients", "g4.num.division-long-intro"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g5.num.mult-div-large.check-division", "parent": "g5.num.mult-div-large", "title": "Checking Division: Remainder Rule and Multiply-back", "description": "Finish every division with two checks: the remainder must be smaller than the divisor, and quotient x divisor + remainder must rebuild the dividend.", "outcomes": ["Can verify a division answer using quotient x divisor + remainder = dividend", "Can spot and fix a division that stopped with a remainder as big as the divisor"], "prereqs": ["g5.num.mult-div-large.divide-2digit-divisor"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g5.num.factors-multiples", "title": "Factors, Multiples and Prime Numbers Intro", "grade": 5, "strand": "num", "description": "A factor of a number divides it exactly; a multiple is what you get by multiplying it. Factors come in pairs and stop at the number itself, while multiples go on forever. Numbers with exactly two factors — 1 and themselves — are the primes, the building blocks of all whole numbers.", "prereqs": ["g3.num.mult-tables", "g3.num.division-intro"], "outcomes": ["Can list all factors of a number systematically using factor pairs", "Can list multiples of a number and decide whether one number is a multiple of another", "Can explain the difference between a factor and a multiple of a number", "Can identify prime and composite numbers up to 100 by testing small divisors"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g5.num.factors-multiples.factor-pairs", "parent": "g5.num.factors-multiples", "title": "Finding Factors with Factor Pairs", "description": "List all factors of a number systematically by finding pairs that multiply to it (1 x 12, 2 x 6, 3 x 4), using rectangle arrays of counters as the picture.", "outcomes": ["Can list all factors of a number up to 50 using factor pairs", "Can show a factor pair as a rectangle arrangement of counters"], "prereqs": ["g3.num.mult-tables", "g3.num.division-intro"], "est_minutes": 20, "difficulty": 1, "question": true}, {"id": "g5.num.factors-multiples.multiples-listing", "parent": "g5.num.factors-multiples", "title": "Multiples: The Never-ending Times Table", "description": "List multiples of a number by skip counting, and decide whether a given number is a multiple of another by testing exact division. Multiples go on forever; factors stop at the number.", "outcomes": ["Can list the first several multiples of any number up to 12", "Can decide whether one number is a multiple of another and justify it"], "prereqs": ["g5.num.factors-multiples.factor-pairs"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.num.factors-multiples.factor-vs-multiple", "parent": "g5.num.factors-multiples", "title": "Factor or Multiple? Keeping Them Apart", "description": "Contrast the two ideas with the size rule: factors of a number fit inside it (never bigger), multiples are its times table (never smaller). Sort numbers into 'factors of n' and 'multiples of n' bins.", "outcomes": ["Can classify given numbers as factors of n, multiples of n, or neither", "Can state that n itself is both a factor and a multiple of n"], "prereqs": ["g5.num.factors-multiples.factor-pairs", "g5.num.factors-multiples.multiples-listing"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.num.factors-multiples.prime-composite", "parent": "g5.num.factors-multiples", "title": "Prime and Composite Numbers", "description": "A prime has exactly two factors: 1 and itself. Test candidates by trying small divisors (2, 3, 5, 7), and settle the special case: 1 has only one factor, so it is neither prime nor composite.", "outcomes": ["Can identify primes and composites up to 100 by testing small divisors", "Can explain why 1 is neither prime nor composite", "Can show a composite number as a rectangle array with more than one row"], "prereqs": ["g5.num.factors-multiples.factor-pairs"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.factors-multiples.factor-count-surprise", "parent": "g5.num.factors-multiples", "title": "Who Has More Factors? Size Doesn't Decide", "description": "Count factors of several numbers and discover that bigger does not mean more factors: a small number like 12 can beat a bigger one like 25, and huge primes have only two.", "outcomes": ["Can count and compare the number of factors of two numbers", "Can give an example showing a bigger number with fewer factors"], "prereqs": ["g5.num.factors-multiples.prime-composite", "g5.num.factors-multiples.factor-vs-multiple"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g5.num.fractions-equivalent-compare", "title": "Equivalent Fractions and Comparison", "grade": 5, "strand": "num", "description": "Different fractions can name the same amount: 1/2, 2/4 and 3/6 all sit at the same point. You make equivalent fractions by multiplying or dividing BOTH the numerator and denominator by the same number. With equivalence in hand you can compare any two fractions — by common denominators, by same numerators, or by clever benchmarks like 'how far from one whole?'.", "prereqs": ["g4.num.fractions-equal-parts"], "outcomes": ["Can generate equivalent fractions by multiplying or dividing both terms by the same number", "Can reduce a fraction to its simplest form", "Can compare fractions with the same denominator, the same numerator, or neither", "Can use benchmarks (1/2, 1 whole, distance from 1) to compare fractions mentally"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g5.num.fractions-equivalent-compare.make-equivalent", "parent": "g5.num.fractions-equivalent-compare", "title": "Making Equivalent Fractions", "description": "Generate fractions that name the same amount by multiplying BOTH the numerator and denominator by the same number — re-cutting every piece into equal sub-pieces on a fraction wall.", "outcomes": ["Can generate equivalent fractions by multiplying both terms by the same number", "Can explain with a picture why multiplying both terms keeps the amount unchanged"], "prereqs": ["g4.num.fractions-equal-parts"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.fractions-equivalent-compare.simplest-form", "parent": "g5.num.fractions-equivalent-compare", "title": "Reducing to Simplest Form", "description": "Run equivalence backwards: divide both terms by the same number until no common divisor is left, giving the fraction in its simplest form.", "outcomes": ["Can reduce a fraction like 6/8 to its simplest form", "Can check that a fraction is fully simplified by hunting for common divisors"], "prereqs": ["g5.num.fractions-equivalent-compare.make-equivalent"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.num.fractions-equivalent-compare.same-denominator-numerator", "parent": "g5.num.fractions-equivalent-compare", "title": "Comparing with Same Denominators or Same Numerators", "description": "Two quick comparison rules: same denominator — more pieces wins; same numerator — the bigger denominator means smaller pieces, so it LOSES.", "outcomes": ["Can compare fractions with equal denominators by comparing numerators", "Can compare fractions with equal numerators by reasoning about piece size"], "prereqs": ["g5.num.fractions-equivalent-compare.make-equivalent"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.num.fractions-equivalent-compare.common-denominator-compare", "parent": "g5.num.fractions-equivalent-compare", "title": "Comparing Any Two Fractions with a Common Denominator", "description": "When neither the tops nor the bottoms match, rewrite both fractions with a common denominator using equivalence, then compare the numerators.", "outcomes": ["Can compare two unlike fractions by rewriting both over a common denominator", "Can pick a sensible common denominator for a pair of fractions"], "prereqs": ["g5.num.fractions-equivalent-compare.make-equivalent", "g5.num.fractions-equivalent-compare.same-denominator-numerator"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g5.num.fractions-equivalent-compare.benchmark-compare", "parent": "g5.num.fractions-equivalent-compare", "title": "Benchmark Tricks: Half and Distance from One Whole", "description": "Compare fractions mentally against benchmarks: is each more or less than 1/2? For near-whole fractions like 5/6 and 7/8, compare the SIZE of the missing piece instead of the count.", "outcomes": ["Can decide whether a fraction is more or less than 1/2 without computing", "Can compare near-whole fractions by comparing their distances from 1"], "prereqs": ["g5.num.fractions-equivalent-compare.common-denominator-compare"], "est_minutes": 15, "difficulty": 3, "question": true}]}, {"id": "g5.num.fractions-add-sub", "title": "Adding and Subtracting Fractions (Like and Related Denominators)", "grade": 5, "strand": "num", "description": "Fractions can only be added or subtracted when the pieces are the same size — the same denominator. With like denominators you simply add or subtract the counts of pieces. When one denominator is a multiple of the other (halves and quarters, thirds and sixths), you first re-cut one fraction into the finer pieces, then combine. Wholes join in by renaming 1 as 4/4, 8/8 and so on.", "prereqs": ["g5.num.fractions-equivalent-compare", "g4.num.fractions-equal-parts"], "outcomes": ["Can add and subtract fractions with the same denominator, keeping the denominator fixed", "Can add and subtract fractions where one denominator is a multiple of the other", "Can rename a whole as an equivalent fraction to subtract from it", "Can solve one-step fraction word problems about sharing food, time and lengths"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g5.num.fractions-add-sub.like-denominators", "parent": "g5.num.fractions-add-sub", "title": "Adding and Subtracting Like Fractions", "description": "With the same denominator, only the counts of pieces are added or subtracted — the denominator is the NAME of the piece and stays put: 3 eighths + 2 eighths = 5 eighths.", "outcomes": ["Can add and subtract fractions with the same denominator", "Can explain why the denominator does not change during the operation"], "prereqs": ["g4.num.fractions-equal-parts"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.num.fractions-add-sub.rename-then-add", "parent": "g5.num.fractions-add-sub", "title": "Adding with Related Denominators", "description": "When one denominator is a multiple of the other (halves and quarters, thirds and sixths), first re-cut the coarser fraction into the finer pieces using equivalence, then add like fractions.", "outcomes": ["Can add fractions where one denominator is a multiple of the other", "Can write and verify the renaming step (1/2 = 2/4) before adding"], "prereqs": ["g5.num.fractions-add-sub.like-denominators", "g5.num.fractions-equivalent-compare.make-equivalent"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.fractions-add-sub.rename-then-subtract", "parent": "g5.num.fractions-add-sub", "title": "Subtracting with Related Denominators", "description": "Subtract fractions like 3/4 - 1/8 by first renaming the coarser fraction into the finer pieces (3/4 = 6/8), then subtracting the counts.", "outcomes": ["Can subtract fractions where one denominator is a multiple of the other", "Can check a fraction subtraction by adding back"], "prereqs": ["g5.num.fractions-add-sub.rename-then-add"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g5.num.fractions-add-sub.subtract-from-whole", "parent": "g5.num.fractions-add-sub", "title": "Taking a Fraction Away from a Whole", "description": "Rename 1 as 4/4, 8/8 or whatever denominator is needed — the same whole in different clothes — so that fractions can be subtracted from wholes.", "outcomes": ["Can rewrite 1 (or 2, 3, ...) as an equivalent fraction with any denominator", "Can subtract a fraction from a whole number"], "prereqs": ["g5.num.fractions-add-sub.like-denominators"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.num.fractions-add-sub.word-problems", "parent": "g5.num.fractions-add-sub", "title": "Fraction Word Problems: Food, Time and Lengths", "description": "Solve one-step story problems about sharing food, cooking measures, time and lengths by choosing add or subtract, renaming where needed, and sanity-checking the answer against the whole.", "outcomes": ["Can translate a one-step fraction story into an addition or subtraction", "Can judge whether a fraction answer is sensible (not bigger than the whole, etc.)"], "prereqs": ["g5.num.fractions-add-sub.rename-then-subtract", "g5.num.fractions-add-sub.subtract-from-whole"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g5.num.decimals-intro", "title": "Decimals: Tenths and Hundredths", "grade": 5, "strand": "num", "description": "Decimals extend place value to the right of the ones: tenths and hundredths, separated by the decimal point. 0.7 means 7 tenths (7/10), and 0.07 means 7 hundredths — ten times smaller. Decimals run our money (₹ and paise), our measurements (metres and centimetres) and every price tag, so reading them correctly matters every day.", "prereqs": ["g4.num.fractions-equal-parts", "g4.num.numbers-to-100000"], "outcomes": ["Can read and write tenths and hundredths as fractions and as decimals", "Can place decimals like 0.3 and 0.45 on a number line between whole numbers", "Can compare two decimals by comparing place by place, not by digit count", "Can connect decimals to money (₹1 = 100 paise) and measures (1 m = 100 cm)"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g5.num.decimals-intro.tenths-on-number-line", "parent": "g5.num.decimals-intro", "title": "Tenths on the Number Line", "description": "Cut the gap between whole numbers into ten equal hops: each hop is one tenth, written 0.1. Read and place numbers like 0.4 and 2.7 on the number line and connect them to fractions like 4/10.", "outcomes": ["Can write tenths as both fractions (7/10) and decimals (0.7)", "Can place and read tenths on a number line between whole numbers"], "prereqs": ["g4.num.fractions-equal-parts"], "est_minutes": 20, "difficulty": 1, "question": true}, {"id": "g5.num.decimals-intro.hundredths-and-money", "parent": "g5.num.decimals-intro", "title": "Hundredths and Money", "description": "Split each tenth into ten again to get hundredths: 0.07 is 7/100, ten times smaller than 0.7. Money makes it concrete — 1 rupee is 100 paise, so 45 paise is Rs 0.45.", "outcomes": ["Can write hundredths as fractions and decimals and tell them apart from tenths", "Can convert between rupees-and-paise and decimal rupee amounts"], "prereqs": ["g5.num.decimals-intro.tenths-on-number-line"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.decimals-intro.place-value-table-extension", "parent": "g5.num.decimals-intro", "title": "Extending the Place-value Table Past the Point", "description": "Add tenths and hundredths columns to the right of the ones: each step right divides by 10. Name every digit by its column, and see why 0.30 equals 0.3 but 0.03 does not.", "outcomes": ["Can state the place value of any digit in a number like 3.65", "Can explain why a zero at the right end after the point changes nothing"], "prereqs": ["g5.num.decimals-intro.hundredths-and-money"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.decimals-intro.comparing-decimals", "parent": "g5.num.decimals-intro", "title": "Comparing Decimals Place by Place", "description": "Compare decimals by lining up the places and comparing from the left, padding with zeros so both have the same number of places — never by counting digits.", "outcomes": ["Can compare two decimals by padding to equal places and comparing place by place", "Can order a mixed list like 0.5, 0.45, 0.7 from smallest to largest"], "prereqs": ["g5.num.decimals-intro.place-value-table-extension"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.decimals-intro.decimals-vs-fractions-link", "parent": "g5.num.decimals-intro", "title": "Decimals and Fractions: Two Names, One Number", "description": "Translate both ways between decimals and fractions with denominators 10 and 100 (0.25 = 25/100 = 1/4), and place both forms at the same point on the number line.", "outcomes": ["Can convert tenths and hundredths between fraction and decimal form both ways", "Can show that a decimal and its fraction sit at the same point on the number line"], "prereqs": ["g5.num.decimals-intro.comparing-decimals"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g5.num.decimals-add-sub", "title": "Adding and Subtracting Decimals", "grade": 5, "strand": "num", "description": "Adding and subtracting decimals works exactly like whole numbers — as long as you line up the decimal points so tenths sit under tenths and hundredths under hundredths. Appending zeros (4.5 = 4.50) makes ragged numbers tidy. These are the calculations of shopkeepers and shoppers: totals, change and measurements every single day.", "prereqs": ["g5.num.decimals-intro", "g4.num.add-sub-large"], "outcomes": ["Can add and subtract decimals by aligning the decimal points", "Can pad with trailing zeros to equalise decimal places before computing", "Can regroup across the decimal point (10 tenths = 1 one)", "Can solve money and measurement problems, including making change"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g5.num.decimals-add-sub.line-up-points", "parent": "g5.num.decimals-add-sub", "title": "Lining Up the Decimal Points", "description": "Set up decimal additions in columns with the decimal points in one vertical line, padding ragged numbers with trailing zeros (4.5 becomes 4.50) so every column is complete.", "outcomes": ["Can set up and add decimals with different numbers of places correctly", "Can explain why right-aligning the digits (ignoring the points) gives wrong answers"], "prereqs": ["g5.num.decimals-intro.place-value-table-extension", "g4.num.add-sub-large"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.num.decimals-add-sub.regroup-across-point", "parent": "g5.num.decimals-add-sub", "title": "Carrying Across the Decimal Point", "description": "See the carry cross the point: 8 tenths + 6 tenths = 14 tenths = 1 whole and 4 tenths. The point separates columns, not two different numbers.", "outcomes": ["Can add decimals where tenths regroup into ones (and hundredths into tenths)", "Can explain a carry across the point using tenths language"], "prereqs": ["g5.num.decimals-add-sub.line-up-points"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.num.decimals-add-sub.subtract-decimals", "parent": "g5.num.decimals-add-sub", "title": "Subtracting Decimals with Borrowing", "description": "Subtract decimals in columns, padding with zeros (6 becomes 6.00) so borrows can visibly cross the decimal point, and check by adding back or counting up.", "outcomes": ["Can subtract decimals including borrows that cross the decimal point", "Can check a decimal subtraction by counting up from the smaller number"], "prereqs": ["g5.num.decimals-add-sub.line-up-points", "g5.num.decimals-add-sub.regroup-across-point"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g5.num.decimals-add-sub.money-change-problems", "parent": "g5.num.decimals-add-sub", "title": "Bills and Change with Money", "description": "Total a shopping bill in rupees and paise and work out the change from a note, using column work or the shopkeeper's counting-up method.", "outcomes": ["Can total a bill of two or three decimal money amounts", "Can compute change from a note, borrowing across the point correctly"], "prereqs": ["g5.num.decimals-add-sub.subtract-decimals"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g5.num.decimals-add-sub.measures-add-sub", "parent": "g5.num.decimals-add-sub", "title": "Adding and Subtracting Measures", "description": "Apply decimal addition and subtraction to real measures — race timings in seconds, weights in kilograms, lengths in metres — keeping units consistent throughout.", "outcomes": ["Can add and subtract decimal measurements of length, weight and time", "Can state the answer with its correct unit"], "prereqs": ["g5.num.decimals-add-sub.regroup-across-point", "g5.num.decimals-add-sub.subtract-decimals"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g5.geo.angles-intro", "title": "Angles: Right Angles and Degree Intuition", "grade": 5, "strand": "geo", "description": "An angle measures a TURN — how far one arm swings away from the other. A right angle (a square corner) is 90 degrees, a straight angle is 180, and a full turn is 360. Angle size depends only on the amount of turn, not on how long the arms are drawn or which way the corner faces.", "prereqs": ["g3.geo.lines-shapes"], "outcomes": ["Can identify right, acute and obtuse angles in shapes and surroundings", "Can state the degree landmarks: 90 (right), 180 (straight), 360 (full turn)", "Can compare two angles by amount of turn, ignoring arm length and orientation", "Can estimate everyday angles (clock hands, open doors, scissors) against the 90-degree benchmark"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": [{"id": "g5.geo.angles-intro.angle-as-turn", "parent": "g5.geo.angles-intro", "title": "An Angle Is a Turn", "description": "An angle measures how far one arm swings away from the other — the opening, not the drawing. Longer arms do not make a bigger angle.", "outcomes": ["Can compare two angles by their openings, ignoring arm length", "Can demonstrate an angle as a turn with arms, scissors or clock hands"], "prereqs": ["g3.geo.lines-shapes"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.geo.angles-intro.right-angle-tester", "parent": "g5.geo.angles-intro", "title": "Right Angles in Every Direction", "description": "Make a folded-paper corner tester and use it to find right angles around you — including tilted ones. The tester fits or it doesn't; the tilt is irrelevant.", "outcomes": ["Can test any corner for a right angle with a folded-paper tester", "Can recognise right angles in non-standard orientations"], "prereqs": ["g5.geo.angles-intro.angle-as-turn"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.geo.angles-intro.degree-landmarks", "parent": "g5.geo.angles-intro", "title": "Degree Landmarks: 90, 180, 360", "description": "Anchor the three big degree landmarks with body turns and the clock: a quarter turn is 90 (right angle), a half turn is 180 (straight angle), a full spin is 360.", "outcomes": ["Can state the degrees in a right angle, straight angle and full turn", "Can show that four square corners fill a full turn (4 x 90 = 360)"], "prereqs": ["g5.geo.angles-intro.right-angle-tester"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.geo.angles-intro.classify-acute-obtuse", "parent": "g5.geo.angles-intro", "title": "Acute, Right, Obtuse, Straight", "description": "Classify angles against the 90-degree benchmark: smaller than a right angle is acute, bigger (but less than straight) is obtuse. Use the corner tester as the judge.", "outcomes": ["Can classify a drawn angle as acute, right, obtuse or straight", "Can find one angle of each type in the classroom"], "prereqs": ["g5.geo.angles-intro.degree-landmarks"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.geo.angles-intro.estimate-everyday-angles", "parent": "g5.geo.angles-intro", "title": "Estimating Everyday Angles", "description": "Estimate the angles made by clock hands, door openings, scissors and laptop lids by comparing them with the 90-degree benchmark and its half, 45.", "outcomes": ["Can estimate a real-world angle to the nearest landmark (45, 90, 180)", "Can state the angle between clock hands at o'clock times like 3:00 and 6:00"], "prereqs": ["g5.geo.angles-intro.classify-acute-obtuse"], "est_minutes": 15, "difficulty": 2, "question": true}]}, {"id": "g5.geo.nets-3d", "title": "3D Shapes, Boxes and Nets", "grade": 5, "strand": "geo", "description": "A net is a flat pattern that folds up into a solid — unfold a toothpaste box and you are looking at its net. You will count faces, edges and corners of cubes and cuboids, decide which arrangements of squares fold into a cube and which do not, and sketch boxes on flat paper. This is the skill of packaging designers everywhere.", "prereqs": ["g2.geo.2d-3d-shapes", "g3.geo.lines-shapes"], "outcomes": ["Can count faces, edges and vertices of cubes and cuboids", "Can decide by mental folding whether a given arrangement of squares is a net of a cube", "Can match a box to its net and mark which faces end up opposite each other", "Can draw a simple net for an open or closed box"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g5.geo.nets-3d.faces-edges-vertices", "parent": "g5.geo.nets-3d", "title": "Faces, Edges and Vertices of Boxes", "description": "Count the 6 faces, 12 edges and 8 vertices of cubes and cuboids using real boxes and paint-stamping, remembering that a drawing hides half the faces.", "outcomes": ["Can count faces, edges and vertices of cubes and cuboids, including hidden ones", "Can mark the hidden faces on a sketch of a box"], "prereqs": ["g2.geo.2d-3d-shapes", "g3.geo.lines-shapes"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.geo.nets-3d.cube-net-or-not", "parent": "g5.geo.nets-3d", "title": "Will It Fold into a Cube?", "description": "Test arrangements of six squares by real and mental folding. Six squares are necessary but not enough — the ARRANGEMENT decides whether it closes into a cube.", "outcomes": ["Can decide by folding (mental or paper) whether a 6-square arrangement is a cube net", "Can explain why a 1x6 strip and a 2x3 block fail as cube nets"], "prereqs": ["g5.geo.nets-3d.faces-edges-vertices"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g5.geo.nets-3d.many-nets-one-box", "parent": "g5.geo.nets-3d", "title": "Many Nets, One Box", "description": "Unfold identical boxes along different edges to collect different-looking nets of the same cube — cross, T and Z shapes are all valid. A net records the unfolding path, not the solid's silhouette.", "outcomes": ["Can accept and verify unfamiliar-looking valid cube nets", "Can produce two different nets of the same box by unfolding along different edges"], "prereqs": ["g5.geo.nets-3d.cube-net-or-not"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.geo.nets-3d.opposite-faces", "parent": "g5.geo.nets-3d", "title": "Opposite Faces on a Net", "description": "Predict which faces of a net end up opposite each other after folding, and check with a dice — opposite faces of a dice always add up to 7.", "outcomes": ["Can mark pairs of opposite faces on a cube net before folding", "Can use the opposite-faces-sum-to-7 rule of a dice"], "prereqs": ["g5.geo.nets-3d.many-nets-one-box"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g5.geo.nets-3d.draw-nets-sketches", "parent": "g5.geo.nets-3d", "title": "Drawing Nets and Box Sketches", "description": "Draw a correct net for an open or closed box and make a simple 3D sketch of a box on flat paper, choosing the right number of faces for each design.", "outcomes": ["Can draw a net for a closed box (6 faces) and an open box (5 faces)", "Can sketch a cuboid showing its hidden edges with dotted lines"], "prereqs": ["g5.geo.nets-3d.opposite-faces"], "est_minutes": 25, "difficulty": 2, "question": true}]}, {"id": "g5.geo.patterns-symmetry-turns", "title": "Symmetry, Turns and Tiling Patterns", "grade": 5, "strand": "geo", "description": "Some shapes look exactly the same after a quarter turn (90°) or a half turn (180°) — that is turning (rotational) symmetry, a cousin of mirror symmetry but not the same thing. Turns also build patterns: many rangoli, tile and border designs repeat a single motif by rotating it again and again. You will predict what a shape looks like after a turn and continue turn-based patterns.", "prereqs": ["g4.geo.symmetry-reflection", "g4.alg.patterns-rules", "g5.geo.angles-intro"], "outcomes": ["Can state that a quarter turn is 90°, a half turn 180° and a full turn 360°", "Can predict what a shape or letter looks like after a quarter or half turn", "Can test whether a figure looks the same after a given turn, and distinguish this from mirror symmetry", "Can continue and create tiling/border patterns built from repeated turns of one motif"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": [{"id": "g5.geo.patterns-symmetry-turns.turn-vocabulary", "parent": "g5.geo.patterns-symmetry-turns", "title": "Quarter, Half and Full Turns", "description": "Connect turn words to degrees and directions: a quarter turn is 90, a half turn 180, a full turn 360 — and turns add up, so two quarter turns make a half turn.", "outcomes": ["Can state the degrees for quarter, half and full turns", "Can combine turns (two quarters make a half; four quarters return home)"], "prereqs": ["g5.geo.angles-intro.degree-landmarks"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.geo.patterns-symmetry-turns.predict-after-turn", "parent": "g5.geo.patterns-symmetry-turns", "title": "Predicting a Shape After a Turn", "description": "Predict what a letter or shape looks like after a quarter or half turn using trace-and-turn: trace it, pin the centre, rotate the tracing. Turning is spinning flat — not flipping over.", "outcomes": ["Can draw or pick the image of a shape after a 90 or 180 degree turn", "Can distinguish the result of a turn from the result of a mirror flip"], "prereqs": ["g5.geo.patterns-symmetry-turns.turn-vocabulary", "g4.geo.symmetry-reflection"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.geo.patterns-symmetry-turns.rotational-symmetry-test", "parent": "g5.geo.patterns-symmetry-turns", "title": "The Trace-and-Turn Symmetry Test", "description": "Test whether a figure has turning symmetry: trace it, rotate the tracing a quarter or half turn, and see if it truly matches — and notice this is independent of mirror symmetry.", "outcomes": ["Can test a figure for quarter-turn and half-turn symmetry with a tracing", "Can give an example with turning symmetry but no mirror line (like S), and the reverse"], "prereqs": ["g5.geo.patterns-symmetry-turns.predict-after-turn"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.geo.patterns-symmetry-turns.turn-tiling-patterns", "parent": "g5.geo.patterns-symmetry-turns", "title": "Patterns Built from Turns", "description": "Continue and create border and tiling patterns made by repeating one motif with a quarter or half turn each time, as in rangoli and railway-station floors.", "outcomes": ["Can continue a border pattern whose rule is 'turn the motif 90 degrees each time'", "Can design a four-tile motif pattern using repeated quarter turns"], "prereqs": ["g5.geo.patterns-symmetry-turns.rotational-symmetry-test", "g4.alg.patterns-rules"], "est_minutes": 20, "difficulty": 2, "question": false}]}, {"id": "g5.mea.area-perimeter-rect", "title": "Area and Perimeter of Rectangles (Formulas)", "grade": 5, "strand": "mea", "description": "Counting squares one by one is slow — for rectangles, multiplication does it instantly: area = length × width, because the squares sit in equal rows. Perimeter has its own shortcut: 2 × (length + width). The two formulas answer two different questions (covering vs surrounding), use different units (square cm vs cm), and mixing them up is the classic trap.", "prereqs": ["g4.mea.area-intro", "g4.mea.perimeter-intro", "g4.num.mult-multi-digit"], "outcomes": ["Can compute the area of a rectangle as length × width and justify it with rows of squares", "Can compute the perimeter of a rectangle as 2 × (length + width)", "Can attach the correct units: square units for area, length units for perimeter", "Can find a missing side given the area or perimeter, and compare rectangles with equal perimeter"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g5.mea.area-perimeter-rect.area-formula-rows", "parent": "g5.mea.area-perimeter-rect", "title": "Area Formula from Rows of Squares", "description": "Turn square-counting into multiplication: a rectangle's unit squares sit in equal rows, so area = length x width. The formula is a fast way of counting squares, and its unit is SQUARE units.", "outcomes": ["Can compute a rectangle's area with length x width and justify it with rows", "Can attach square units (sq cm, sq m) to every area answer"], "prereqs": ["g4.mea.area-intro", "g4.num.mult-multi-digit"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.mea.area-perimeter-rect.perimeter-formula", "parent": "g5.mea.area-perimeter-rect", "title": "Perimeter Formula: 2 x (Length + Width)", "description": "Walk the boundary — long, short, long, short — and compress it into the shortcut perimeter = 2 x (length + width), measured in plain length units.", "outcomes": ["Can compute a rectangle's perimeter with 2 x (length + width)", "Can explain the formula as walking all four sides"], "prereqs": ["g4.mea.perimeter-intro", "g5.mea.area-perimeter-rect.area-formula-rows"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.mea.area-perimeter-rect.units-and-which-formula", "parent": "g5.mea.area-perimeter-rect", "title": "Cover It or Go Around It? Choosing Formula and Unit", "description": "Sort real problems by the question they ask — covering (area, square units) or surrounding (perimeter, length units) — before touching any numbers.", "outcomes": ["Can decide whether a word problem needs area or perimeter", "Can pick the correct unit (cm vs sq cm, m vs sq m) for each answer"], "prereqs": ["g5.mea.area-perimeter-rect.area-formula-rows", "g5.mea.area-perimeter-rect.perimeter-formula"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.mea.area-perimeter-rect.missing-side", "parent": "g5.mea.area-perimeter-rect", "title": "Finding a Missing Side", "description": "Run the formulas backwards: given a rectangle's area (or perimeter) and one side, find the other side by dividing (or halving then subtracting).", "outcomes": ["Can find a missing side from the area and one side", "Can find a missing side from the perimeter and one side"], "prereqs": ["g5.mea.area-perimeter-rect.units-and-which-formula"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g5.mea.area-perimeter-rect.same-perimeter-different-area", "parent": "g5.mea.area-perimeter-rect", "title": "Same Fence, Different Fields", "description": "Explore rectangles sharing one perimeter and discover their areas differ — the squarer the rectangle, the more it encloses. Equal boundary never guarantees equal area.", "outcomes": ["Can build several rectangles with the same perimeter and compute each area", "Can explain why a fixed fence length can enclose different amounts of ground"], "prereqs": ["g5.mea.area-perimeter-rect.perimeter-formula", "g5.mea.area-perimeter-rect.missing-side"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g5.mea.volume-intuition", "title": "Volume Intuition with Unit Cubes", "grade": 5, "strand": "mea", "description": "Volume measures how much space something fills, and we measure it by counting unit cubes — including the ones hidden inside and underneath. A box packs cubes in layers: cubes per layer × number of layers. Rearranging the same cubes into a tower or a slab changes the shape but never the volume.", "prereqs": ["g4.mea.area-intro", "g5.geo.nets-3d", "g3.num.mult-tables"], "outcomes": ["Can find the volume of a cube-built solid by counting unit cubes, including hidden ones", "Can use layers to count: cubes in one layer × number of layers", "Can explain that rearranging cubes changes shape but not volume", "Can compare volumes of two cube buildings and order containers by how much they hold"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g5.mea.volume-intuition.count-unit-cubes", "parent": "g5.mea.volume-intuition", "title": "Volume Is Counting Cubes", "description": "Volume measures filled space, and its unit is a little cube — not a flat square. Find the volume of small cube buildings by counting every unit cube.", "outcomes": ["Can find the volume of a simple cube building by counting unit cubes", "Can state that volume is measured in cubes while area is measured in squares"], "prereqs": ["g4.mea.area-intro", "g3.num.mult-tables"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g5.mea.volume-intuition.hidden-cubes", "parent": "g5.mea.volume-intuition", "title": "X-ray Counting: The Hidden Cubes", "description": "Drawings hide cubes at the back and underneath, but they still count. Practise X-ray counting: for each visible column, count how many cubes stand in it top to bottom.", "outcomes": ["Can count all cubes in a drawn stack, including hidden ones", "Can verify a drawing count by building the solid from real cubes"], "prereqs": ["g5.mea.volume-intuition.count-unit-cubes"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.mea.volume-intuition.layer-counting", "parent": "g5.mea.volume-intuition", "title": "Counting by Layers", "description": "A box packs cubes in identical layers, so the fast count is cubes in one layer x number of layers — watched live by filling a real box layer by layer.", "outcomes": ["Can compute a box's cube count as one layer x layers", "Can find the cubes in one layer as rows x columns"], "prereqs": ["g5.mea.volume-intuition.hidden-cubes"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.mea.volume-intuition.rearrange-conserve", "parent": "g5.mea.volume-intuition", "title": "Rearranging Never Changes Volume", "description": "Rebuild the same set of cubes from a tall tower into a flat slab and back: the shape changes, the count never does. Height and spread trade off; nothing is created or destroyed.", "outcomes": ["Can state that rearranging cubes preserves volume, with a demonstration", "Can reject 'taller means more' by counting both builds"], "prereqs": ["g5.mea.volume-intuition.layer-counting"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g5.mea.volume-intuition.compare-order-volumes", "parent": "g5.mea.volume-intuition", "title": "Comparing and Ordering Volumes", "description": "Compare cube buildings by count (not by look) and order containers by how much they hold, previewing capacity: pouring and packing decide, not height alone.", "outcomes": ["Can compare two cube buildings by computing both volumes", "Can order three containers or builds from smallest to largest volume"], "prereqs": ["g5.mea.volume-intuition.rearrange-conserve"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g5.dat.data-interpretation", "title": "Interpreting Tables, Bar Graphs and Simple Pie Charts", "grade": 5, "strand": "dat", "description": "Data answers questions — if you read it correctly. You will pull values out of tables, read scaled bar graphs precisely (including part-divisions), and interpret simple pie charts where a slice is a fraction of the total. The golden rules: check the scale, and remember a pie slice is a fraction — its actual count depends on the total.", "prereqs": ["g4.dat.bar-charts", "g4.num.fractions-equal-parts"], "outcomes": ["Can extract and compare values from a data table, including finding least and greatest", "Can read bar graphs with scaled axes, including bars ending between gridlines", "Can interpret a simple pie chart by applying its fractions (half, quarter) to the stated total", "Can answer multi-step questions combining two or more readings from one display"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g5.dat.data-interpretation.read-tables", "parent": "g5.dat.data-interpretation", "title": "Reading Data Tables", "description": "Pull the right value out of a table, then compare entries to find least and greatest — routing every comparison through place value, not first digits.", "outcomes": ["Can extract a named value from a data table", "Can find the least and greatest entries in a table column correctly"], "prereqs": ["g4.dat.bar-charts", "g5.num.large-numbers.compare-order"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g5.dat.data-interpretation.bar-graph-scale", "parent": "g5.dat.data-interpretation", "title": "Bar Graphs with Scaled Axes", "description": "Read bar graphs where one division stands for 5, 10 or more: run the scale-check ritual first, and read bars that end between gridlines exactly — the half division is data too.", "outcomes": ["Can state a bar graph's scale before reading any bar", "Can read a bar ending mid-division as divisions x scale, including the half"], "prereqs": ["g5.dat.data-interpretation.read-tables"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.dat.data-interpretation.pie-chart-fractions", "parent": "g5.dat.data-interpretation", "title": "Pie Slices Are Fractions of the Total", "description": "Read a simple pie chart by writing the total above it first, then computing each slice as a fraction OF that total: half of 80 is 40, a quarter of 80 is 20.", "outcomes": ["Can compute the count for a half or quarter slice from the stated total", "Can explain why the same slice means different counts for different totals"], "prereqs": ["g5.dat.data-interpretation.read-tables", "g4.num.fractions-equal-parts"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g5.dat.data-interpretation.compare-two-pies", "parent": "g5.dat.data-interpretation", "title": "Comparing Pie Charts with Different Totals", "description": "Compare slices across two pie charts with different totals and discover that a smaller slice of a bigger total can beat a bigger slice of a smaller total.", "outcomes": ["Can compare slice counts across two pies by applying each fraction to its own total", "Can explain why slice size alone cannot be compared across pies"], "prereqs": ["g5.dat.data-interpretation.pie-chart-fractions"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g5.dat.data-interpretation.multi-step-questions", "parent": "g5.dat.data-interpretation", "title": "Multi-step Questions from One Display", "description": "Answer questions that need two or more readings from the same table or graph — totals across rows, differences between bars, and 'how many more' comparisons.", "outcomes": ["Can combine two readings from one display into a total or difference", "Can answer 'how many more' questions from tables and bar graphs"], "prereqs": ["g5.dat.data-interpretation.bar-graph-scale", "g5.dat.data-interpretation.pie-chart-fractions"], "est_minutes": 20, "difficulty": 3, "question": false}]}, {"id": "g6.num.knowing-numbers", "title": "Knowing Our Numbers: Large Numbers and Estimation", "grade": 6, "strand": "num", "description": "You will read, write, compare and order large numbers in both the Indian (lakh, crore) and international (million, billion) systems, and use rounding to estimate sums, differences and products. Estimation is the everyday superpower of mathematics: it lets you sanity-check bills, budgets and news headlines in seconds.", "prereqs": ["g5.num.large-numbers"], "outcomes": ["Can read and write numbers up to crores using both Indian and international place-value systems, with correct comma placement", "Can compare and order large numbers by aligning place values, not just by looking at leading digits", "Can round a number to the nearest ten, hundred, thousand or lakh", "Can estimate the result of an addition, subtraction or multiplication and judge whether an exact answer is reasonable"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g6.num.knowing-numbers.place-value-recap", "parent": "g6.num.knowing-numbers", "title": "Place Value up to Lakhs: Recap and Warm-up", "description": "Revise the Indian place-value chart up to lakhs: face value versus place value, and expanded form of 5- and 6-digit numbers.", "outcomes": ["Can state the place value and face value of any digit in a 6-digit number", "Can write a 6-digit number in expanded form and rebuild it from expanded form"], "prereqs": ["g5.num.large-numbers"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.num.knowing-numbers.reading-writing-crores", "parent": "g6.num.knowing-numbers", "title": "Reading and Writing Numbers up to Crores", "description": "Extend the Indian system to ten lakh, crore and ten crore, placing commas after thousands, lakhs and crores (3-2-2 pattern) and reading number names aloud.", "outcomes": ["Can insert commas correctly in the Indian system for numbers up to 10 crore", "Can write the number name for a given numeral and the numeral for a given name"], "prereqs": ["g6.num.knowing-numbers.place-value-recap"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g6.num.knowing-numbers.international-system", "parent": "g6.num.knowing-numbers", "title": "The International System: Millions and Billions", "description": "Read and write the same digit string in the international system (thousand, million, billion) and convert between lakhs/crores and millions.", "outcomes": ["Can punctuate a number with international commas (groups of 3) and read it", "Can convert between lakh/crore and hundred thousand/million (1 lakh = 100 thousand, 1 crore = 10 million)"], "prereqs": ["g6.num.knowing-numbers.reading-writing-crores"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.knowing-numbers.comparing-ordering", "parent": "g6.num.knowing-numbers", "title": "Comparing and Ordering Large Numbers", "description": "Compare large numbers by first counting digits, then comparing place by place from the left; order lists ascending and descending and build greatest/smallest numbers from given digits.", "outcomes": ["Can compare two large numbers using digit count first, then leftmost differing digit", "Can arrange four or more large numbers in ascending or descending order", "Can form the greatest and smallest numbers from a set of digits"], "prereqs": ["g6.num.knowing-numbers.place-value-recap"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.knowing-numbers.rounding-numbers", "parent": "g6.num.knowing-numbers", "title": "Rounding to Tens, Hundreds, Thousands and Lakhs", "description": "Round a number to a chosen place by underlining the rounding place and letting only the single digit to its right decide up or down, verified on a number line.", "outcomes": ["Can round any number to the nearest ten, hundred, thousand or lakh", "Can justify a rounding decision by naming which two multiples the number lies between and which is nearer"], "prereqs": ["g6.num.knowing-numbers.comparing-ordering"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.knowing-numbers.estimating-outcomes", "parent": "g6.num.knowing-numbers", "title": "Estimating Sums, Differences and Products", "description": "Use controlled rounding to estimate the result of an addition, subtraction or multiplication before (or instead of) computing exactly, and judge whether an exact answer is reasonable.", "outcomes": ["Can estimate a sum or difference by rounding each number to a sensible place", "Can estimate a product by rounding each factor and explain why the estimate is not a random guess"], "prereqs": ["g6.num.knowing-numbers.rounding-numbers"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g6.num.whole-numbers", "title": "Whole Numbers and Their Properties", "grade": 6, "strand": "num", "description": "Whole numbers are the counting numbers together with zero. You will explore their behaviour on the number line and the properties of addition and multiplication — commutativity, associativity, distributivity and the special roles of 0 and 1 — and use these properties to compute cleverly instead of laboriously.", "prereqs": ["g6.num.knowing-numbers", "g5.num.mult-div-large"], "outcomes": ["Can identify predecessors and successors and locate whole numbers on a number line", "Can state which operations on whole numbers are commutative and associative, with counterexamples for subtraction and division", "Can use distributivity and regrouping to simplify calculations such as 8 × 293 × 125 mentally", "Can explain the roles of 0 and 1 as identities and why division by zero is undefined"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g6.num.whole-numbers.zero-and-number-line", "parent": "g6.num.whole-numbers", "title": "Whole Numbers, Zero and the Number Line", "description": "Meet the whole numbers as the counting numbers together with 0, locate them on the number line, and find successors and predecessors.", "outcomes": ["Can explain that 0 is the smallest whole number and that every whole number has a successor", "Can find the successor and predecessor of any whole number and model addition/subtraction as jumps on the number line"], "prereqs": ["g6.num.knowing-numbers.place-value-recap"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g6.num.whole-numbers.commutativity-associativity", "parent": "g6.num.whole-numbers", "title": "Commutativity and Associativity of Addition and Multiplication", "description": "Discover that addition and multiplication can be done in any order and any grouping, and test whether subtraction and division share these properties (they do not).", "outcomes": ["Can state and use a + b = b + a and (a + b) + c = a + (b + c), and the same for multiplication", "Can give a counterexample showing subtraction and division are not commutative"], "prereqs": ["g6.num.whole-numbers.zero-and-number-line"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.whole-numbers.identities-zero-one", "parent": "g6.num.whole-numbers", "title": "The Special Roles of 0 and 1", "description": "Explore 0 as the additive identity and 1 as the multiplicative identity, what multiplying by zero does, and why division by zero is not defined.", "outcomes": ["Can use a + 0 = a, a x 1 = a and a x 0 = 0 fluently", "Can explain with a sharing or repeated-subtraction argument why dividing by 0 is undefined"], "prereqs": ["g6.num.whole-numbers.zero-and-number-line"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g6.num.whole-numbers.distributivity", "parent": "g6.num.whole-numbers", "title": "Distributivity of Multiplication over Addition", "description": "Use a x (b + c) = a x b + a x c, seen through area/array pictures, making sure the outside factor multiplies BOTH terms inside the bracket.", "outcomes": ["Can expand a x (b + c) correctly, distributing over every term", "Can use distributivity to compute products like 6 x 105 or 8 x 99 mentally"], "prereqs": ["g6.num.whole-numbers.commutativity-associativity"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.whole-numbers.clever-calculation", "parent": "g6.num.whole-numbers", "title": "Clever Calculation Using Properties", "description": "Combine commutativity, associativity and distributivity to reorder and regroup computations (like pairing 4 x 25 = 100 or 8 x 125 = 1000) and simplify multi-step arithmetic.", "outcomes": ["Can rearrange a sum or product to create friendly pairs before computing", "Can name which property justifies each rearrangement step"], "prereqs": ["g6.num.whole-numbers.distributivity", "g6.num.whole-numbers.identities-zero-one"], "est_minutes": 20, "difficulty": 3, "question": false}]}, {"id": "g6.num.playing-with-numbers", "title": "Factors, Multiples, Divisibility, HCF and LCM", "grade": 6, "strand": "num", "description": "Numbers have hidden structure: factors, multiples, primes and composites. You will learn divisibility tests, prime factorisation, and how to find the HCF (highest common factor) and LCM (lowest common multiple) of numbers — tools you will use constantly with fractions, ratios and repeating events.", "prereqs": ["g5.num.factors-multiples", "g3.num.division-intro"], "outcomes": ["Can list factors and multiples of a number and classify numbers as prime or composite", "Can apply divisibility tests for 2, 3, 4, 5, 6, 8, 9, 10 and 11", "Can find HCF and LCM using prime factorisation and choose which one a word problem needs", "Can verify and use the relation HCF × LCM = product of the two numbers"], "difficulty": 2, "est_minutes": 50, "stub": false, "micros": [{"id": "g6.num.playing-with-numbers.factors-multiples-review", "parent": "g6.num.playing-with-numbers", "title": "Factors and Multiples: Properties Review", "description": "Revise factors and multiples and establish their key properties: 1 is a factor of every number, every number is a factor and multiple of itself, factors are finitely many while multiples never end.", "outcomes": ["Can list all factors of a number systematically using factor pairs", "Can list multiples of a number and state which of the factor/multiple properties applies in an example"], "prereqs": ["g5.num.factors-multiples", "g3.num.division-intro"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.num.playing-with-numbers.primes-and-composites", "parent": "g6.num.playing-with-numbers", "title": "Prime and Composite Numbers", "description": "Classify numbers as prime (exactly two factors) or composite (more than two), see why 1 is neither, and sieve out the primes up to 100.", "outcomes": ["Can decide whether a number under 100 is prime, composite, or neither", "Can explain why 1 is not prime and why 2 is the only even prime"], "prereqs": ["g6.num.playing-with-numbers.factors-multiples-review"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.playing-with-numbers.divisibility-tests", "parent": "g6.num.playing-with-numbers", "title": "Divisibility Tests for 2, 3, 4, 5, 6, 8, 9, 10 and 11", "description": "Learn and apply the quick divisibility tests, distinguishing last-digit tests (2, 5, 10), last-digits tests (4, 8) and digit-sum tests (3, 9).", "outcomes": ["Can apply the correct test to check divisibility by 2, 3, 4, 5, 6, 8, 9, 10 or 11 without dividing", "Can explain why divisibility by 3 depends on the digit sum, not the last digit"], "prereqs": ["g6.num.playing-with-numbers.factors-multiples-review"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g6.num.playing-with-numbers.prime-factorisation", "parent": "g6.num.playing-with-numbers", "title": "Prime Factorisation", "description": "Break a number into a product of primes using a factor tree or repeated division, and check that the factorisation is complete (every factor prime).", "outcomes": ["Can find the prime factorisation of numbers up to 4 digits by factor tree or division ladder", "Can check whether a claimed factorisation is truly into primes"], "prereqs": ["g6.num.playing-with-numbers.primes-and-composites", "g6.num.playing-with-numbers.divisibility-tests"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.playing-with-numbers.finding-hcf", "parent": "g6.num.playing-with-numbers", "title": "Highest Common Factor (HCF)", "description": "Find the HCF of two or three numbers by listing common factors and by taking the common prime factors, and interpret HCF as the largest number dividing all of them.", "outcomes": ["Can find the HCF of two or three numbers by listing and by prime factorisation", "Can explain in words what the HCF of two numbers means"], "prereqs": ["g6.num.playing-with-numbers.prime-factorisation"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.playing-with-numbers.finding-lcm", "parent": "g6.num.playing-with-numbers", "title": "Lowest Common Multiple (LCM)", "description": "Find the LCM of two or three numbers by listing multiples and by prime factorisation, and notice that the LCM equals the product only when the numbers share no common factor.", "outcomes": ["Can find the LCM of two or three numbers by listing and by prime factorisation", "Can give an example where the LCM is smaller than the product of the numbers"], "prereqs": ["g6.num.playing-with-numbers.prime-factorisation"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.playing-with-numbers.hcf-lcm-problems", "parent": "g6.num.playing-with-numbers", "title": "HCF and LCM Word Problems", "description": "Decide which of HCF or LCM a story situation needs: 'largest piece / greatest measure that fits exactly' means HCF; 'when do repeating events coincide / smallest common quantity' means LCM.", "outcomes": ["Can classify a word problem as an HCF problem or an LCM problem before computing", "Can solve two-step HCF/LCM word problems and check the answer against the story"], "prereqs": ["g6.num.playing-with-numbers.finding-hcf", "g6.num.playing-with-numbers.finding-lcm"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g6.num.integers-intro", "title": "Integers: Negative Numbers, Ordering, Addition and Subtraction", "grade": 6, "strand": "num", "description": "Integers extend the number line to the left of zero, letting us describe temperatures below freezing, depths below sea level and money owed. You will order integers, and add and subtract them using the number line and zero-pair models — the foundation for all of algebra.", "prereqs": ["g6.num.whole-numbers"], "outcomes": ["Can represent real situations (temperature, altitude, credit/debit) with positive and negative integers", "Can place integers on a number line and compare/order them correctly", "Can add integers with like and unlike signs using number-line moves or zero pairs", "Can subtract integers, including subtracting a negative, and explain why 5 − (−2) = 7"], "difficulty": 2, "est_minutes": 50, "stub": false, "micros": [{"id": "g6.num.integers-intro.negatives-in-real-life", "parent": "g6.num.integers-intro", "title": "Negative Numbers in Real Life", "description": "Meet negative numbers through temperatures below zero, floors below ground level, debts and depths below sea level, and use the sign to encode direction or opposite-ness.", "outcomes": ["Can represent real situations (temperature, money owed, depth) with signed numbers", "Can state the opposite of a given situation and its integer"], "prereqs": ["g6.num.whole-numbers.zero-and-number-line"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.num.integers-intro.number-line-extension", "parent": "g6.num.integers-intro", "title": "Extending the Number Line to the Left", "description": "Extend the number line past zero, place negative integers, and see that every integer has an opposite the same distance from 0 on the other side.", "outcomes": ["Can mark any integer between -20 and 20 on a number line", "Can name the opposite of an integer and locate both on the line"], "prereqs": ["g6.num.integers-intro.negatives-in-real-life"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.num.integers-intro.ordering-integers", "parent": "g6.num.integers-intro", "title": "Comparing and Ordering Integers", "description": "Compare integers by position on the number line: numbers further right are greater, so every negative number is less than zero and -3 is greater than -5.", "outcomes": ["Can compare any two integers using the number line and the < and > symbols", "Can order a mixed list of positive and negative integers ascending or descending"], "prereqs": ["g6.num.integers-intro.number-line-extension"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.integers-intro.absolute-value-idea", "parent": "g6.num.integers-intro", "title": "Absolute Value as Distance from Zero", "description": "Understand |a| as the distance of a from 0, so |-7| = |7| = 7, and separate the two questions 'which is greater?' and 'which is farther from zero?'.", "outcomes": ["Can find the absolute value of any integer", "Can explain why -8 < 2 even though |-8| > |2|"], "prereqs": ["g6.num.integers-intro.number-line-extension"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g6.num.integers-intro.adding-integers-same-sign", "parent": "g6.num.integers-intro", "title": "Adding Integers with the Same Sign", "description": "Add two negatives (or two positives) using number-line jumps or counters: add the magnitudes and keep the common sign.", "outcomes": ["Can add two integers of the same sign with number-line or counter models", "Can state the rule 'add magnitudes, keep the sign' and say why it works"], "prereqs": ["g6.num.integers-intro.absolute-value-idea"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.integers-intro.adding-integers-different-sign", "parent": "g6.num.integers-intro", "title": "Adding Integers with Different Signs", "description": "Add a positive and a negative by cancelling opposite pairs: subtract the smaller magnitude from the larger and take the sign of the larger.", "outcomes": ["Can add integers of opposite signs using zero pairs or number-line jumps", "Can predict the sign of the answer before computing"], "prereqs": ["g6.num.integers-intro.adding-integers-same-sign"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.integers-intro.subtracting-integers", "parent": "g6.num.integers-intro", "title": "Subtracting Integers", "description": "Subtract any integer by adding its opposite, so 5 - (-2) = 5 + 2 = 7, and see that subtracting a bigger number from a smaller one is now perfectly possible.", "outcomes": ["Can rewrite any subtraction as adding the opposite and evaluate it", "Can compute differences like 3 - 9 and explain the negative answer on the number line"], "prereqs": ["g6.num.integers-intro.adding-integers-different-sign"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g6.num.fractions-ops", "title": "Fractions: Proper, Improper, Mixed; Addition and Subtraction", "grade": 6, "strand": "num", "description": "You will work confidently with proper fractions, improper fractions and mixed numbers, convert between forms, and add and subtract fractions with unlike denominators using equivalent fractions and the LCM. This is where fraction arithmetic becomes a reliable tool instead of a guessing game.", "prereqs": ["g5.num.fractions-add-sub", "g5.num.fractions-equivalent-compare", "g6.num.playing-with-numbers"], "outcomes": ["Can convert between improper fractions and mixed numbers in both directions", "Can compare fractions by making denominators (or numerators) equal", "Can add and subtract fractions with unlike denominators using the LCM as common denominator", "Can solve word problems involving addition and subtraction of fractions and judge whether the answer is reasonable"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": [{"id": "g6.num.fractions-ops.fraction-review-number-line", "parent": "g6.num.fractions-ops", "title": "Fractions as Parts and as Points on the Number Line", "description": "Revise a fraction as equal parts of a whole and of a collection, and place fractions on the number line between whole numbers.", "outcomes": ["Can represent a fraction as part of a whole, part of a collection, and a point on the number line", "Can identify the fraction shown by a marked point between 0 and 2"], "prereqs": ["g5.num.fractions-equivalent-compare"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.num.fractions-ops.proper-improper-mixed", "parent": "g6.num.fractions-ops", "title": "Proper, Improper and Mixed Fractions", "description": "Classify fractions as proper or improper, see that improper fractions are perfectly legitimate numbers bigger than or equal to 1, and convert between improper fractions and mixed numbers.", "outcomes": ["Can convert a mixed number to an improper fraction and back", "Can explain that 2 3/4 means 2 + 3/4, not 2 x 3/4", "Can place improper fractions like 7/4 on the number line"], "prereqs": ["g6.num.fractions-ops.fraction-review-number-line"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.fractions-ops.simplest-form", "parent": "g6.num.fractions-ops", "title": "Equivalent Fractions and Simplest Form", "description": "Generate equivalent fractions by multiplying or dividing numerator and denominator by the same number, and reduce a fraction to simplest form by dividing out the HCF.", "outcomes": ["Can test whether two fractions are equivalent", "Can reduce a fraction to simplest form using the HCF of numerator and denominator"], "prereqs": ["g6.num.fractions-ops.fraction-review-number-line", "g6.num.playing-with-numbers.finding-hcf"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g6.num.fractions-ops.comparing-fractions", "parent": "g6.num.fractions-ops", "title": "Comparing Like and Unlike Fractions", "description": "Compare fractions with the same denominator directly, unit fractions by reasoning about piece size, and unlike fractions by converting to a common denominator.", "outcomes": ["Can explain why 1/4 > 1/8 using piece size, not digit size", "Can compare and order unlike fractions using a common denominator"], "prereqs": ["g6.num.fractions-ops.simplest-form", "g6.num.playing-with-numbers.finding-lcm"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g6.num.fractions-ops.add-sub-like", "parent": "g6.num.fractions-ops", "title": "Adding and Subtracting Like Fractions", "description": "Add and subtract fractions with the same denominator by combining numerators while the denominator - the name of the piece size - stays the same.", "outcomes": ["Can add and subtract like fractions and simplify the result", "Can explain why the denominator does not change when adding like fractions"], "prereqs": ["g6.num.fractions-ops.fraction-review-number-line"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g6.num.fractions-ops.add-sub-unlike", "parent": "g6.num.fractions-ops", "title": "Adding and Subtracting Unlike Fractions", "description": "Add and subtract fractions with different denominators by first rewriting both over the LCM of the denominators, then combining numerators.", "outcomes": ["Can add and subtract unlike fractions using the LCM as common denominator", "Can spot and explain the error in 1/2 + 1/3 = 2/5"], "prereqs": ["g6.num.fractions-ops.add-sub-like", "g6.num.fractions-ops.comparing-fractions"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g6.num.fractions-ops.mixed-number-add-sub", "parent": "g6.num.fractions-ops", "title": "Adding and Subtracting Mixed Numbers", "description": "Add and subtract mixed numbers either by converting to improper fractions or by handling wholes and parts separately with regrouping, and use them in word problems.", "outcomes": ["Can add and subtract mixed numbers by both methods", "Can solve one-step word problems involving mixed numbers of metres, litres or hours"], "prereqs": ["g6.num.fractions-ops.add-sub-unlike", "g6.num.fractions-ops.proper-improper-mixed"], "est_minutes": 25, "difficulty": 4, "question": false}]}, {"id": "g6.num.decimals-ops", "title": "Decimals: Comparing, Adding, Subtracting; Units", "grade": 6, "strand": "num", "description": "Decimals are fractions with denominators 10, 100, 1000 written in place-value form. You will compare decimals correctly, add and subtract them by aligning the decimal point, and use them with money and metric units — where decimals live in real life.", "prereqs": ["g5.num.decimals-intro", "g5.num.decimals-add-sub"], "outcomes": ["Can read and write decimals up to thousandths and connect them to fractions", "Can compare and order decimals by place value, including cases like 0.5 vs 0.45", "Can add and subtract decimals by aligning decimal points, padding with zeros where needed", "Can convert between units using decimals (e.g. 145 cm = 1.45 m, 75 paise = ₹0.75)"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g6.num.decimals-ops.decimal-place-value", "parent": "g6.num.decimals-ops", "title": "Decimal Place Value: Tenths, Hundredths, Thousandths", "description": "Extend the place-value chart to the right of the ones: tenths, hundredths and thousandths, reading and writing decimals in figures, words and expanded form.", "outcomes": ["Can state the place value of any digit in a decimal like 12.305", "Can write a decimal in expanded form (e.g. 4.56 = 4 + 5/10 + 6/100)"], "prereqs": ["g5.num.decimals-intro"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.num.decimals-ops.decimals-and-fractions", "parent": "g6.num.decimals-ops", "title": "Decimals as Fractions and on the Number Line", "description": "Convert between decimals and fractions with denominators 10, 100 and 1000, and locate decimals between whole numbers on a zoomed-in number line.", "outcomes": ["Can convert between tenths/hundredths fractions and decimals in both directions", "Can place decimals like 0.7 and 1.35 on a number line"], "prereqs": ["g6.num.decimals-ops.decimal-place-value", "g6.num.fractions-ops.fraction-review-number-line"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g6.num.decimals-ops.comparing-decimals", "parent": "g6.num.decimals-ops", "title": "Comparing and Ordering Decimals", "description": "Compare decimals place by place from the left after padding with zeros, so 0.5 = 0.50 > 0.45, defeating the 'longer is larger' trap.", "outcomes": ["Can compare any two decimals by padding to equal length and comparing place by place", "Can explain why 0.7 and 0.70 are the same number"], "prereqs": ["g6.num.decimals-ops.decimals-and-fractions"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.decimals-ops.adding-decimals", "parent": "g6.num.decimals-ops", "title": "Adding Decimals", "description": "Add decimals by lining up the decimal points (padding with zeros where needed) so that tenths sit under tenths and hundredths under hundredths.", "outcomes": ["Can add decimals of different lengths by aligning decimal points", "Can estimate the sum first to catch alignment errors"], "prereqs": ["g6.num.decimals-ops.comparing-decimals", "g5.num.decimals-add-sub"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.decimals-ops.subtracting-decimals", "parent": "g6.num.decimals-ops", "title": "Subtracting Decimals", "description": "Subtract decimals with decimal-point alignment and zero-padding, including borrowing across the decimal point.", "outcomes": ["Can subtract decimals of different lengths, borrowing across the point where needed", "Can check a subtraction by adding back"], "prereqs": ["g6.num.decimals-ops.adding-decimals"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.decimals-ops.money-length-weight-units", "parent": "g6.num.decimals-ops", "title": "Decimals in Money, Length and Weight", "description": "Use decimals to convert within units: paise to rupees (divide by 100), cm to m (divide by 100), mm to cm (divide by 10), g to kg (divide by 1000), moving the decimal point the right number of places.", "outcomes": ["Can convert between paise/rupees, mm/cm/m/km and g/kg using decimals", "Can decide how many places (and in which direction) the decimal point moves for a given conversion"], "prereqs": ["g6.num.decimals-ops.decimal-place-value"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g6.num.ratio-proportion", "title": "Ratio, Proportion and the Unitary Method", "grade": 6, "strand": "num", "description": "A ratio compares quantities by division rather than subtraction, and a proportion says two ratios are equal. With the unitary method — find the value of ONE, then scale — you can solve price, speed and recipe problems. This multiplicative way of thinking underpins percentages, similar triangles and trigonometry later.", "prereqs": ["g5.num.fractions-equivalent-compare", "g5.num.mult-div-large"], "outcomes": ["Can express a comparison as a ratio in simplest form, attending to order and same units", "Can test whether four numbers are in proportion (a:b = c:d)", "Can use the unitary method: find the value of one unit, then find the value of many", "Can solve real problems on prices, speeds and mixtures using ratio reasoning"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g6.num.ratio-proportion.ratio-idea", "parent": "g6.num.ratio-proportion", "title": "Ratio as Comparison by Division", "description": "Compare two quantities of the same kind by division rather than subtraction, write the comparison as a:b, and see that the order of the terms matters.", "outcomes": ["Can write the ratio of two quantities in the stated order after matching units", "Can explain the difference between comparing by subtraction and comparing by ratio"], "prereqs": ["g5.num.mult-div-large", "g6.num.fractions-ops.simplest-form"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.num.ratio-proportion.equivalent-ratios", "parent": "g6.num.ratio-proportion", "title": "Equivalent Ratios and Simplest Form", "description": "Scale a ratio up or down by multiplying or dividing BOTH terms by the same number, and reduce ratios to simplest form - adding the same amount to both terms breaks the ratio.", "outcomes": ["Can generate equivalent ratios and reduce a ratio to simplest form", "Can show with an example why adding the same number to both terms changes the ratio"], "prereqs": ["g6.num.ratio-proportion.ratio-idea", "g5.num.fractions-equivalent-compare"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.ratio-proportion.part-and-whole", "parent": "g6.num.ratio-proportion", "title": "Part-to-Part and Part-to-Whole Ratios", "description": "Distinguish ratios between two parts (boys:girls) from ratios of a part to the whole (boys:class), and move between the two by finding the total.", "outcomes": ["Can extract both part-to-part and part-to-whole ratios from the same data", "Can find the whole from a part-to-part ratio and a total"], "prereqs": ["g6.num.ratio-proportion.ratio-idea"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.ratio-proportion.proportion-idea", "parent": "g6.num.ratio-proportion", "title": "Proportion: When Two Ratios Are Equal", "description": "Say four quantities are in proportion when the ratio of the first pair equals the ratio of the second pair (a:b :: c:d), and test proportionality by simplifying both ratios.", "outcomes": ["Can test whether four numbers are in proportion", "Can find a missing term in a simple proportion"], "prereqs": ["g6.num.ratio-proportion.equivalent-ratios"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.num.ratio-proportion.unitary-method", "parent": "g6.num.ratio-proportion", "title": "The Unitary Method", "description": "Solve value problems by first finding the value of ONE unit (divide), then scaling to the required number of units (multiply), checking that the answer moves in the sensible direction.", "outcomes": ["Can solve cost/quantity problems via the value of one unit", "Can check direction: fewer items must cost less, more items must cost more"], "prereqs": ["g6.num.ratio-proportion.proportion-idea"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g6.num.ratio-proportion.ratio-applications", "parent": "g6.num.ratio-proportion", "title": "Dividing a Quantity in a Given Ratio", "description": "Split money, lengths or ingredients in a given ratio by adding the ratio terms to find the number of equal shares, then multiplying each term by the share size.", "outcomes": ["Can divide a quantity in a given two-term ratio", "Can solve recipe and map-scale style problems combining ratio and the unitary method"], "prereqs": ["g6.num.ratio-proportion.unitary-method", "g6.num.ratio-proportion.part-and-whole"], "est_minutes": 25, "difficulty": 4, "question": false}]}, {"id": "g6.alg.intro-algebra", "title": "Introduction to Algebra: Variables and Expressions", "grade": 6, "strand": "alg", "description": "Algebra begins when a letter stands for a number that can vary. You will write rules for patterns (like the perimeter of a square, 4s), build expressions from operations, and evaluate them for given values. Learning to treat a letter as a NUMBER — not an object or a label — is the single most important idea of this chapter.", "prereqs": ["g4.alg.patterns-rules", "g6.num.whole-numbers"], "outcomes": ["Can use a variable to state a general rule for a pattern (e.g. matchstick patterns, perimeter formulas)", "Can translate word phrases into algebraic expressions and back", "Can evaluate an expression like 2n + 3 for a given value of n", "Can explain that a variable stands for a number that can take many values"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g6.alg.intro-algebra.patterns-to-rules", "parent": "g6.alg.intro-algebra", "title": "From Matchstick Patterns to Rules", "description": "Build matchstick and dot patterns, tabulate how the count grows, and describe the rule in words ('twice the number of shapes') as a bridge to letters.", "outcomes": ["Can extend a growing pattern and tabulate shape number against stick count", "Can state the general rule of a linear pattern in words"], "prereqs": ["g4.alg.patterns-rules"], "est_minutes": 20, "difficulty": 1, "question": false}, {"id": "g6.alg.intro-algebra.idea-of-variable", "parent": "g6.alg.intro-algebra", "title": "The Idea of a Variable", "description": "Meet a letter as a placeholder for ANY number - not an object, not a fixed secret, and not its alphabet position - so one rule like 2n covers every case of a pattern at once.", "outcomes": ["Can explain that a variable stands for a number that can vary", "Can use a rule like 2n to compute the pattern value for any given n"], "prereqs": ["g6.alg.intro-algebra.patterns-to-rules"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.alg.intro-algebra.forming-expressions", "parent": "g6.alg.intro-algebra", "title": "Forming Expressions with Variables", "description": "Build expressions like x + 3, y - 5, 4m and p/2 from operations on a variable, keeping addition visible: 3 + x cannot be squeezed into 3x.", "outcomes": ["Can form an expression from a described operation on a variable", "Can explain the difference between 3 + x and 3x"], "prereqs": ["g6.alg.intro-algebra.idea-of-variable"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.alg.intro-algebra.rules-as-expressions", "parent": "g6.alg.intro-algebra", "title": "Writing Everyday and Geometry Rules with Letters", "description": "Express familiar rules with variables: perimeter of a square is 4s, of a rectangle 2(l + b), and arithmetic properties like a + b = b + a, seeing algebra as compressed language.", "outcomes": ["Can write perimeter and simple everyday rules as expressions", "Can state a number property (commutativity, distributivity) using letters"], "prereqs": ["g6.alg.intro-algebra.forming-expressions", "g6.num.whole-numbers.commutativity-associativity"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g6.alg.intro-algebra.substituting-values", "parent": "g6.alg.intro-algebra", "title": "Evaluating Expressions by Substitution", "description": "Replace the variable with a chosen number and evaluate the expression, remembering that 2n means 2 x n, never the two-digit numeral '2 then n'.", "outcomes": ["Can evaluate expressions like 2n + 3 or 10 - m for given values", "Can compare values of an expression as the variable changes"], "prereqs": ["g6.alg.intro-algebra.forming-expressions"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.alg.intro-algebra.equations-intro", "parent": "g6.alg.intro-algebra", "title": "What Is an Equation? Solving by Trial", "description": "Distinguish an equation (a condition with an equals sign, true only for certain values) from an expression, and find solutions of simple equations like x + 4 = 9 by systematic trial.", "outcomes": ["Can tell an equation from an expression and test whether a value satisfies an equation", "Can solve simple one-step equations by trial and error"], "prereqs": ["g6.alg.intro-algebra.substituting-values"], "est_minutes": 20, "difficulty": 3, "question": false}]}, {"id": "g6.geo.basic-ideas", "title": "Basic Geometrical Ideas: Points, Lines, Curves, Polygons, Circles", "grade": 6, "strand": "geo", "description": "Geometry's vocabulary starts here: points, line segments, rays and lines; open and closed curves; polygons with their sides, vertices and diagonals; and the circle with its centre, radius, diameter and chords. Precise language now makes every later theorem readable.", "prereqs": ["g3.geo.lines-shapes", "g4.geo.circle-intro"], "outcomes": ["Can distinguish a line, a line segment and a ray, and use correct notation for each", "Can identify open/closed curves, and the interior, boundary and exterior of a closed curve", "Can name the parts of a polygon (sides, vertices, adjacent sides, diagonals)", "Can identify centre, radius, diameter, chord, arc and sector of a circle and relate diameter to radius"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g6.geo.basic-ideas.points-lines-segments", "parent": "g6.geo.basic-ideas", "title": "Points, Line Segments, Lines and Rays", "description": "Distinguish the four basic objects: a point (position only), a segment (two endpoints, definite length), a ray (one endpoint, extends forever one way) and a line (no endpoints, extends forever both ways).", "outcomes": ["Can name and notate points, segments, rays and lines from a figure", "Can say which of the four objects have a measurable length and why"], "prereqs": ["g3.geo.lines-shapes"], "est_minutes": 20, "difficulty": 1, "question": true}, {"id": "g6.geo.basic-ideas.intersecting-parallel", "parent": "g6.geo.basic-ideas", "title": "Intersecting and Parallel Lines", "description": "Classify pairs of lines as intersecting (meet at exactly one point) or parallel (never meet however far extended), reasoning about the full lines rather than the drawn segments.", "outcomes": ["Can identify intersecting and parallel line pairs and the point of intersection", "Can explain why two segments that do not touch on the page may still lie on intersecting lines"], "prereqs": ["g6.geo.basic-ideas.points-lines-segments"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g6.geo.basic-ideas.curves-open-closed", "parent": "g6.geo.basic-ideas", "title": "Curves: Open, Closed, Interior and Exterior", "description": "Classify curves as open or closed and simple or self-crossing, and for closed curves identify the interior, the boundary and the exterior.", "outcomes": ["Can classify a drawn curve as open/closed and simple/not simple", "Can mark points in the interior, on the boundary and in the exterior of a closed curve"], "prereqs": ["g6.geo.basic-ideas.points-lines-segments"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.geo.basic-ideas.polygons-intro", "parent": "g6.geo.basic-ideas", "title": "Polygons: Sides, Vertices and Diagonals", "description": "Define a polygon as a simple closed figure made ENTIRELY of line segments, and name its sides, vertices, adjacent sides and diagonals.", "outcomes": ["Can decide whether a figure is a polygon and justify using the definition", "Can count and name sides, vertices and diagonals of polygons up to hexagons"], "prereqs": ["g6.geo.basic-ideas.curves-open-closed"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.geo.basic-ideas.angles-intro", "parent": "g6.geo.basic-ideas", "title": "Angles: Vertex, Arms, Interior and Exterior", "description": "See an angle as two rays sharing a common endpoint, name it with three letters (vertex in the middle), and identify its interior and exterior regions.", "outcomes": ["Can identify and name the vertex and arms of an angle using three-letter notation", "Can decide whether a point lies in the interior, on the angle, or in the exterior"], "prereqs": ["g6.geo.basic-ideas.points-lines-segments"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g6.geo.basic-ideas.circle-parts", "parent": "g6.geo.basic-ideas", "title": "Parts of a Circle", "description": "Identify centre, radius, diameter, chord, arc, sector and segment of a circle, and establish that the diameter is a chord through the centre, twice the radius.", "outcomes": ["Can label centre, radius, diameter, chord and arc on a circle", "Can use diameter = 2 x radius in both directions"], "prereqs": ["g6.geo.basic-ideas.curves-open-closed", "g4.geo.circle-intro"], "est_minutes": 20, "difficulty": 2, "question": true}]}, {"id": "g6.geo.elementary-shapes", "title": "Understanding Elementary Shapes: Angles, Triangles, Quadrilaterals, Solids", "grade": 6, "strand": "geo", "description": "You will measure and classify angles (acute, right, obtuse, straight, reflex), classify triangles by sides and angles, meet the family of quadrilaterals, and recognise common solids with their faces, edges and vertices. Classifying shapes trains you to reason from properties rather than appearances.", "prereqs": ["g6.geo.basic-ideas", "g5.geo.angles-intro"], "outcomes": ["Can classify angles as acute, right, obtuse, straight or reflex, and estimate angle sizes", "Can classify triangles by sides (scalene, isosceles, equilateral) and by angles (acute, right, obtuse)", "Can name quadrilaterals and state their defining properties, including how the special quadrilaterals nest (every square is a rectangle)", "Can identify faces, edges and vertices of cubes, cuboids, cylinders, cones, spheres, prisms and pyramids"], "difficulty": 2, "est_minutes": 50, "stub": false, "micros": [{"id": "g6.geo.elementary-shapes.measuring-segments", "parent": "g6.geo.elementary-shapes", "title": "Measuring and Comparing Line Segments", "description": "Compare segments by observation, by tracing, and accurately with a divider and ruler, avoiding end-of-ruler and eye-position errors.", "outcomes": ["Can measure a segment correctly with a ruler, starting from the zero mark", "Can compare two segments with a divider without measuring numbers"], "prereqs": ["g6.geo.basic-ideas.points-lines-segments"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.geo.elementary-shapes.angles-as-turns", "parent": "g6.geo.elementary-shapes", "title": "Angles as Turns: Right, Straight and Complete", "description": "Measure angle as an amount of TURN between the arms - a quarter turn is a right angle, a half turn a straight angle, a full turn a complete angle - independent of how long the arms are drawn.", "outcomes": ["Can relate quarter, half and full turns to right, straight and complete angles", "Can explain why redrawing an angle with longer arms does not change the angle"], "prereqs": ["g6.geo.basic-ideas.angles-intro", "g5.geo.angles-intro"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g6.geo.elementary-shapes.classifying-angles", "parent": "g6.geo.elementary-shapes", "title": "Classifying Angles: Acute, Right, Obtuse, Straight, Reflex", "description": "Classify angles by comparing with the right angle (90 degrees) and straight angle (180 degrees): acute below 90, obtuse between 90 and 180, reflex beyond 180.", "outcomes": ["Can classify a given angle as acute, right, obtuse, straight or reflex", "Can estimate whether an angle is more or less than 90 degrees using a corner of paper"], "prereqs": ["g6.geo.elementary-shapes.angles-as-turns"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.geo.elementary-shapes.measuring-with-protractor", "parent": "g6.geo.elementary-shapes", "title": "Measuring Angles with a Protractor", "description": "Measure angles in degrees with a protractor - centre on the vertex, baseline on one arm, read the correct scale - and confirm that arm length never affects the measure.", "outcomes": ["Can measure an angle to the nearest degree, choosing the correct protractor scale", "Can predict the size class of an angle before measuring and use it to catch wrong-scale readings"], "prereqs": ["g6.geo.elementary-shapes.classifying-angles"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g6.geo.elementary-shapes.perpendicular-lines", "parent": "g6.geo.elementary-shapes", "title": "Perpendicular Lines and Perpendicular Bisectors", "description": "Recognise perpendicular lines as lines meeting at a right angle, spot perpendiculars in the environment, and meet the idea of a perpendicular bisector of a segment.", "outcomes": ["Can identify perpendicular pairs in figures and surroundings", "Can describe what makes a line the perpendicular bisector of a segment"], "prereqs": ["g6.geo.elementary-shapes.classifying-angles"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g6.geo.elementary-shapes.classifying-triangles", "parent": "g6.geo.elementary-shapes", "title": "Classifying Triangles by Sides and Angles", "description": "Classify triangles as scalene, isosceles or equilateral (by sides) and acute, right or obtuse (by angles), seeing that the categories overlap: every equilateral triangle is also isosceles.", "outcomes": ["Can classify a triangle simultaneously by sides and by angles", "Can explain why an equilateral triangle is a special isosceles triangle"], "prereqs": ["g6.geo.elementary-shapes.measuring-segments", "g6.geo.elementary-shapes.classifying-angles"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.geo.elementary-shapes.classifying-quadrilaterals", "parent": "g6.geo.elementary-shapes", "title": "Quadrilaterals: Squares, Rectangles, Parallelograms, Rhombuses, Trapeziums", "description": "Sort quadrilaterals by their properties (parallel sides, equal sides, right angles) and build the inclusion ladder: a square is a special rectangle and a special rhombus, and all three are parallelograms.", "outcomes": ["Can name a quadrilateral from its side/angle properties", "Can justify from properties why every square is a rectangle"], "prereqs": ["g6.geo.elementary-shapes.perpendicular-lines"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g6.geo.elementary-shapes.three-d-shapes", "parent": "g6.geo.elementary-shapes", "title": "Three-Dimensional Shapes: Faces, Edges and Vertices", "description": "Recognise cubes, cuboids, cylinders, cones, spheres, prisms and pyramids, and count faces, edges and vertices of the straight-edged solids.", "outcomes": ["Can name common solids from pictures and real objects", "Can count faces, edges and vertices of a cube, cuboid, prism and pyramid"], "prereqs": ["g5.geo.nets-3d"], "est_minutes": 20, "difficulty": 2, "question": false}]}, {"id": "g6.geo.symmetry", "title": "Symmetry: Lines of Symmetry", "grade": 6, "strand": "geo", "description": "A figure has line symmetry when one half folds exactly onto the other. You will find all lines of symmetry of common shapes and letters, and complete half-drawn symmetric figures. Symmetry sharpens visual reasoning and reappears in reflections, transformations and even algebraic graphs.", "prereqs": ["g4.geo.symmetry-reflection"], "outcomes": ["Can test a proposed line of symmetry by (mentally or physically) folding", "Can find ALL lines of symmetry of standard shapes: square (4), rectangle (2), equilateral triangle (3), circle (infinitely many)", "Can identify shapes with no line of symmetry (e.g. scalene triangle, parallelogram)", "Can complete the other half of a figure given the mirror line"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": [{"id": "g6.geo.symmetry.symmetry-idea", "parent": "g6.geo.symmetry", "title": "The Idea of Line Symmetry: Fold and Mirror Tests", "description": "A figure has line symmetry when folding along a line makes the two halves match exactly; test symmetry by folding paper cutouts and with a mirror on the fold line.", "outcomes": ["Can test a proposed line of symmetry by the fold or mirror test", "Can explain why matching halves must coincide exactly, not merely have equal areas"], "prereqs": ["g4.geo.symmetry-reflection"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.geo.symmetry.finding-lines-of-symmetry", "parent": "g6.geo.symmetry", "title": "Finding ALL Lines of Symmetry", "description": "Hunt systematically for every line of symmetry of a figure - vertical, horizontal AND slanted - rotating the page so no direction gets special treatment.", "outcomes": ["Can find all lines of symmetry of a given figure, including slanted ones", "Can verify a claimed count of symmetry lines by testing each candidate"], "prereqs": ["g6.geo.symmetry.symmetry-idea"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.geo.symmetry.symmetry-of-standard-shapes", "parent": "g6.geo.symmetry", "title": "Symmetry of Standard Shapes", "description": "Catalogue the lines of symmetry of rectangles, squares, triangles, rhombuses, regular polygons and circles, discovering that a rectangle's diagonal is NOT a symmetry line and side count need not equal line count.", "outcomes": ["Can state the number of lines of symmetry of common shapes", "Can demonstrate by folding why the diagonal of a (non-square) rectangle is not a line of symmetry"], "prereqs": ["g6.geo.symmetry.finding-lines-of-symmetry", "g6.geo.elementary-shapes.classifying-quadrilaterals"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.geo.symmetry.shapes-without-symmetry", "parent": "g6.geo.symmetry", "title": "Shapes with No Lines of Symmetry (and Shapes with Many)", "description": "Meet figures with zero lines of symmetry (scalene triangle, parallelogram, letter F) and figures with many (regular polygons, circle), breaking the belief that every shape has at least one.", "outcomes": ["Can give examples of shapes with 0, 1, 2, 3 and infinitely many lines of symmetry", "Can justify why a scalene triangle has no line of symmetry"], "prereqs": ["g6.geo.symmetry.finding-lines-of-symmetry"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g6.geo.symmetry.completing-figures", "parent": "g6.geo.symmetry", "title": "Completing Symmetric Figures and Reflections", "description": "Complete the other half of a figure given its line of symmetry on squared paper, and connect line symmetry with mirror reflection (left-right reversal, distances preserved).", "outcomes": ["Can complete a half-drawn figure across a given symmetry line on a grid", "Can predict the mirror image of a simple shape or letter"], "prereqs": ["g6.geo.symmetry.symmetry-of-standard-shapes"], "est_minutes": 20, "difficulty": 3, "question": false}]}, {"id": "g6.geo.constructions-intro", "title": "Constructions with Ruler and Compass", "grade": 6, "strand": "geo", "description": "Using only an unmarked straightedge and a compass, you will construct circles, copy segments, draw perpendiculars and perpendicular bisectors, and build angles of 60°, 30°, 90° and 120°. Constructions teach WHY figures have their properties — every arc is a statement about equal distances.", "prereqs": ["g6.geo.basic-ideas", "g4.geo.circle-intro"], "outcomes": ["Can draw a circle of given radius and copy a line segment with compass and ruler", "Can construct the perpendicular bisector of a segment and a perpendicular through a point", "Can construct 60° and related angles (120°, 30°, 90°) and bisect a given angle", "Can explain why a construction works in terms of equal radii (equal distances)"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g6.geo.constructions-intro.tools-and-idea", "parent": "g6.geo.constructions-intro", "title": "The Idea of Construction: Ruler-and-Compass Rules", "description": "Learn what counts as a geometric construction - figures produced with an unmarked straightedge and a compass by steps that can be justified - as opposed to measuring with protractor or marked ruler.", "outcomes": ["Can name the allowed tools and moves in ruler-and-compass construction", "Can explain why constructing differs from measuring and drawing"], "prereqs": ["g6.geo.basic-ideas.points-lines-segments"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g6.geo.constructions-intro.drawing-circles", "parent": "g6.geo.constructions-intro", "title": "Drawing Circles with a Compass", "description": "Draw circles of a given radius with a compass, keeping the opening fixed while rotating, and see the circle as all points at one fixed distance from the centre.", "outcomes": ["Can draw a circle of given radius smoothly with a fixed compass opening", "Can explain why a slipping compass opening spoils the circle"], "prereqs": ["g6.geo.constructions-intro.tools-and-idea", "g6.geo.basic-ideas.circle-parts"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.geo.constructions-intro.copying-a-segment", "parent": "g6.geo.constructions-intro", "title": "Constructing and Copying a Line Segment", "description": "Construct a segment of given length and copy a given segment onto another line using the compass as a distance-carrier, without reading a marked scale.", "outcomes": ["Can copy a segment onto a given ray using only compass and straightedge", "Can construct a segment equal to the sum or difference of two given segments"], "prereqs": ["g6.geo.constructions-intro.drawing-circles"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g6.geo.constructions-intro.perpendicular-through-point", "parent": "g6.geo.constructions-intro", "title": "Perpendicular to a Line Through a Point", "description": "Construct the perpendicular to a given line through a point on the line, and through a point not on the line, using pairs of equal arcs.", "outcomes": ["Can construct a perpendicular through a point on the line", "Can construct a perpendicular from an external point and check it with a set-square"], "prereqs": ["g6.geo.constructions-intro.copying-a-segment", "g6.geo.elementary-shapes.perpendicular-lines"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g6.geo.constructions-intro.perpendicular-bisector", "parent": "g6.geo.constructions-intro", "title": "The Perpendicular Bisector of a Segment", "description": "Construct the perpendicular bisector with intersecting arcs from both endpoints, and understand it as the line that BOTH passes through the midpoint AND meets the segment at 90 degrees.", "outcomes": ["Can construct the perpendicular bisector of a segment with equal arcs from both ends", "Can state both defining properties (midpoint and right angle) and check them"], "prereqs": ["g6.geo.constructions-intro.perpendicular-through-point"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g6.geo.constructions-intro.copying-an-angle", "parent": "g6.geo.constructions-intro", "title": "Copying an Angle of Unknown Measure", "description": "Copy a given angle onto a new ray using two arcs and a transferred chord distance - no protractor and no knowledge of the angle's degree measure needed.", "outcomes": ["Can copy any given angle with compass and straightedge", "Can explain which equal distances make the copy exact"], "prereqs": ["g6.geo.constructions-intro.copying-a-segment", "g6.geo.elementary-shapes.measuring-with-protractor"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g6.geo.constructions-intro.bisecting-an-angle", "parent": "g6.geo.constructions-intro", "title": "Bisecting an Angle", "description": "Bisect an angle with an arc from the vertex and two equal arcs from the crossing points, and see that any sufficiently large compass opening gives the SAME bisector.", "outcomes": ["Can bisect any angle with compass and straightedge and verify by measuring both halves", "Can explain why the choice of arc radius does not change the bisector"], "prereqs": ["g6.geo.constructions-intro.copying-an-angle"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g6.mea.mensuration-perimeter-area", "title": "Mensuration: Perimeter and Area of Squares and Rectangles", "grade": 6, "strand": "mea", "description": "Perimeter measures the boundary of a figure; area measures the surface it covers. You will use the formulas for squares and rectangles, work with the right units (cm vs cm²), and discover that figures with the same perimeter can enclose very different areas.", "prereqs": ["g5.mea.area-perimeter-rect"], "outcomes": ["Can compute perimeters of rectangles, squares and figures made of straight segments", "Can compute areas of rectangles and squares, and of shapes decomposable into rectangles", "Can attach correct units: linear units for perimeter, square units for area", "Can explain with examples that equal perimeters do not force equal areas (and vice versa)"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g6.mea.mensuration-perimeter-area.perimeter-idea", "parent": "g6.mea.mensuration-perimeter-area", "title": "Perimeter as Distance Around", "description": "Establish perimeter as the total length of the boundary - walked, fenced or traced - and find perimeters of arbitrary straight-sided figures by adding ALL the sides.", "outcomes": ["Can find the perimeter of any polygon by summing every side", "Can identify real situations (fencing, lace border, running a lap) that call for perimeter"], "prereqs": ["g4.mea.perimeter-intro"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.mea.mensuration-perimeter-area.perimeter-formulas", "parent": "g6.mea.mensuration-perimeter-area", "title": "Perimeter Formulas for Rectangles and Squares", "description": "Compress side-adding into formulas - rectangle: 2 x (length + breadth), square: 4 x side - remembering the shape has four sides, so length + breadth is only halfway there.", "outcomes": ["Can apply P = 2(l + b) and P = 4s correctly with units", "Can find a missing side given the perimeter"], "prereqs": ["g6.mea.mensuration-perimeter-area.perimeter-idea"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.mea.mensuration-perimeter-area.area-counting-squares", "parent": "g6.mea.mensuration-perimeter-area", "title": "Area by Counting Unit Squares", "description": "Measure area as the number of unit squares a region covers, counting full squares, half squares, and estimating for more-than-half / less-than-half squares on grid paper.", "outcomes": ["Can find areas of grid figures including halves and irregular edges", "Can explain area as covered surface, distinct from distance around"], "prereqs": ["g4.mea.area-intro"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.mea.mensuration-perimeter-area.area-formulas", "parent": "g6.mea.mensuration-perimeter-area", "title": "Area Formulas for Rectangles and Squares", "description": "Derive area = length x breadth from rows of unit squares, use area = side x side for squares, and attach SQUARE units (cm2, m2) because area counts squares, not lengths.", "outcomes": ["Can compute areas of rectangles and squares with correct square units", "Can find a missing side from the area and explain why area units are squared"], "prereqs": ["g6.mea.mensuration-perimeter-area.area-counting-squares", "g5.mea.area-perimeter-rect"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.mea.mensuration-perimeter-area.perimeter-vs-area", "parent": "g6.mea.mensuration-perimeter-area", "title": "Same Perimeter, Different Area (and Vice Versa)", "description": "Build different rectangles with equal perimeters and compare their areas (and equal areas with different perimeters), proving the two measures are independent.", "outcomes": ["Can construct rectangles with the same perimeter but different areas", "Can explain why knowing the perimeter does not determine the area"], "prereqs": ["g6.mea.mensuration-perimeter-area.perimeter-formulas", "g6.mea.mensuration-perimeter-area.area-formulas"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g6.mea.mensuration-perimeter-area.real-world-problems", "parent": "g6.mea.mensuration-perimeter-area", "title": "Choosing Perimeter or Area in Word Problems", "description": "Solve fencing, framing, tiling and painting problems by first deciding which measure the situation needs - boundary length (perimeter) or covered surface (area) - including cost calculations.", "outcomes": ["Can classify a real problem as a perimeter or an area problem before computing", "Can solve cost problems like fencing at Rs per metre or tiling at Rs per square metre"], "prereqs": ["g6.mea.mensuration-perimeter-area.perimeter-vs-area"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g6.dat.data-handling", "title": "Data Handling: Tally Marks, Pictographs, Bar Graphs", "grade": 6, "strand": "dat", "description": "Data becomes useful when organised: you will record data with tally marks, and read and draw pictographs and bar graphs — including ones where a symbol or one unit of height stands for many items. Reading scales correctly is the key skill; it protects you from misleading graphs forever after.", "prereqs": ["g5.dat.data-interpretation"], "outcomes": ["Can record raw data in a frequency table using tally marks (bundles of five)", "Can read and draw a pictograph where one symbol represents multiple units, including half symbols", "Can read and draw a bar graph, choosing and using a sensible scale", "Can answer comparison questions ('how many more…?') from a graph, applying the scale correctly"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g6.dat.data-handling.collecting-organising", "parent": "g6.dat.data-handling", "title": "Collecting and Organising Data", "description": "Gather raw data from a survey, and organise it into a frequency table so questions like 'which is most common?' can be answered at a glance.", "outcomes": ["Can record survey responses and organise raw data into a frequency table", "Can answer simple most/least/how-many questions from an organised table"], "prereqs": ["g4.dat.bar-charts"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g6.dat.data-handling.tally-marks", "parent": "g6.dat.data-handling", "title": "Recording with Tally Marks", "description": "Use tally marks in bundles of five - four strokes and a fifth diagonal across - to record counts quickly and read them back by counting bundles, not strokes.", "outcomes": ["Can record counts in five-bar tally bundles", "Can read a tally accurately as 5 per full bundle plus leftover singles"], "prereqs": ["g6.dat.data-handling.collecting-organising"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g6.dat.data-handling.pictographs", "parent": "g6.dat.data-handling", "title": "Reading and Drawing Pictographs", "description": "Interpret and draw pictographs where one symbol stands for a scaled quantity given by the key, handling half-symbols as half the key value.", "outcomes": ["Can read a pictograph by multiplying symbol count by the key value, including half symbols", "Can choose a sensible key and draw a pictograph for given data"], "prereqs": ["g6.dat.data-handling.tally-marks"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.dat.data-handling.reading-bar-graphs", "parent": "g6.dat.data-handling", "title": "Reading Bar Graphs with a Scale", "description": "Read bar graphs whose axis uses a scale (1 unit = 10, 20, 100...), converting bar heights into actual values before answering any question.", "outcomes": ["Can convert bar heights to values using the stated scale", "Can answer comparison and total questions from a scaled bar graph"], "prereqs": ["g6.dat.data-handling.collecting-organising", "g5.dat.data-interpretation"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g6.dat.data-handling.drawing-bar-graphs", "parent": "g6.dat.data-handling", "title": "Drawing Bar Graphs", "description": "Draw bar graphs from frequency tables: choose an appropriate scale, keep bar widths and gaps equal, and label axes and title.", "outcomes": ["Can choose a scale that fits the data on the grid", "Can draw a correctly labelled bar graph with uniform bars and gaps"], "prereqs": ["g6.dat.data-handling.reading-bar-graphs"], "est_minutes": 25, "difficulty": 2, "question": false}, {"id": "g6.dat.data-handling.comparing-with-graphs", "parent": "g6.dat.data-handling", "title": "Answering Comparison Questions from Graphs", "description": "Answer 'how many more', 'how many fewer' and 'total' questions from bar graphs and pictographs by computing differences and sums of the actual values - not just naming the bigger category.", "outcomes": ["Can answer how-many-more questions by subtracting the two values", "Can combine values from a graph to answer total and two-step questions"], "prereqs": ["g6.dat.data-handling.reading-bar-graphs", "g6.dat.data-handling.pictographs"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g7.num.integers-ops", "title": "Integers: Multiplication, Division and Properties", "grade": 7, "strand": "num", "description": "Building on integer addition and subtraction, you will multiply and divide integers, master the sign rules (and why they work), and use properties like distributivity with negative numbers. These rules power all of algebra — every bracket you expand later depends on them.", "prereqs": ["g6.num.integers-intro", "g3.num.mult-tables"], "outcomes": ["Can multiply integers with any combination of signs and justify the sign of the product", "Can divide integers and connect division to multiplication facts", "Can apply commutativity, associativity and distributivity with negative numbers", "Can solve multi-step problems mixing all four operations with integers"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g7.num.integers-ops.add-sub-revision", "parent": "g7.num.integers-ops", "title": "Warm-up: Adding and Subtracting Integers", "description": "Revise integer addition and subtraction with the number line and debt model, firmly separating them from the multiplication sign rules to come.", "outcomes": ["Can add and subtract any two integers fluently", "Can explain why (−3) + (−5) = −8 using the debt model"], "prereqs": ["g6.num.integers-intro"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g7.num.integers-ops.mult-pos-neg", "parent": "g7.num.integers-ops", "title": "Multiplying a Positive by a Negative", "description": "Build 4 × (−3) as repeated addition of debts, and (−3) × 4 via commutativity, establishing that unlike signs give a negative product.", "outcomes": ["Can compute products of one positive and one negative integer", "Can justify the negative sign using repeated addition or a real context"], "prereqs": ["g7.num.integers-ops.add-sub-revision", "g3.num.mult-tables"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.num.integers-ops.mult-neg-neg", "parent": "g7.num.integers-ops", "title": "Why Negative × Negative Is Positive", "description": "Use the descending pattern 3×(−6), 2×(−6), 1×(−6), 0×(−6), ... to force (−1)×(−6) = +6, and frame negative × negative as reversing a reversal.", "outcomes": ["Can multiply two negative integers correctly", "Can justify the sign of the product with the pattern argument"], "prereqs": ["g7.num.integers-ops.mult-pos-neg"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.num.integers-ops.divide-integers", "parent": "g7.num.integers-ops", "title": "Dividing Integers with Sign Rules", "description": "Connect every division to its multiplication check — (−36) ÷ 4 = q means q × 4 = −36 — so the same sign rules govern quotients.", "outcomes": ["Can divide integers with any combination of signs", "Can verify a quotient's sign via the multiplication check"], "prereqs": ["g7.num.integers-ops.mult-neg-neg"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.num.integers-ops.properties-and-brackets", "parent": "g7.num.integers-ops", "title": "Properties of Operations and Opening Brackets", "description": "Use commutativity, associativity and distributivity with negatives, reading −(a + b) as (−1) × (a + b) so the minus reaches EVERY term inside.", "outcomes": ["Can use distributivity to simplify computations like (−4) × 103", "Can expand −(a + b) correctly to −a − b and check numerically"], "prereqs": ["g7.num.integers-ops.mult-neg-neg"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.num.integers-ops.mixed-ops-problems", "parent": "g7.num.integers-ops", "title": "Multi-step Problems with All Four Operations", "description": "Solve real contexts — quiz scoring, draining tanks, falling temperatures — that mix addition, subtraction, multiplication and division of integers.", "outcomes": ["Can translate a signed real-world situation into an integer expression", "Can evaluate multi-step integer expressions respecting order of operations"], "prereqs": ["g7.num.integers-ops.divide-integers", "g7.num.integers-ops.properties-and-brackets"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g7.num.fractions-decimals-ops", "title": "Fractions and Decimals: Multiplication and Division", "grade": 7, "strand": "num", "description": "You will multiply and divide fractions and decimals, understand 'of' as multiplication, and see why dividing by a fraction means multiplying by its reciprocal. Along the way you will confront a big surprise: multiplying can make numbers smaller, and dividing can make them bigger.", "prereqs": ["g6.num.fractions-ops", "g6.num.decimals-ops"], "outcomes": ["Can multiply fractions (including mixed numbers) and interpret 'of' as multiplication", "Can divide by a fraction using the reciprocal, and explain why the method works", "Can multiply and divide decimals, placing the decimal point by counting decimal places", "Can predict whether a product/quotient will be bigger or smaller than the starting number"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": [{"id": "g7.num.fractions-decimals-ops.fraction-of-quantity", "parent": "g7.num.fractions-decimals-ops", "title": "'Of' Means Multiply: Fraction of a Quantity", "description": "Interpret 3/4 of 20 as 3/4 × 20 with pictures and sharing, meeting the first surprise: taking a fraction OF something makes it smaller.", "outcomes": ["Can find a fraction of a whole-number quantity", "Can explain why multiplying by a fraction less than 1 shrinks the result"], "prereqs": ["g6.num.fractions-ops"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.num.fractions-decimals-ops.multiply-fractions", "parent": "g7.num.fractions-decimals-ops", "title": "Multiplying Fractions with the Area Model", "description": "Multiply fractions 'tops times tops, bottoms times bottoms', backed by the shaded-rectangle area model so the rule has an image behind it.", "outcomes": ["Can multiply two fractions and simplify the product", "Can draw an area model showing why 2/3 × 4/5 = 8/15"], "prereqs": ["g7.num.fractions-decimals-ops.fraction-of-quantity"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.num.fractions-decimals-ops.multiply-mixed-numbers", "parent": "g7.num.fractions-decimals-ops", "title": "Multiplying Mixed Numbers", "description": "Convert mixed numbers to improper fractions before multiplying, and see with numbers why multiplying whole and fraction parts separately undercounts.", "outcomes": ["Can multiply mixed numbers via improper fractions", "Can estimate the product first to catch conversion errors"], "prereqs": ["g7.num.fractions-decimals-ops.multiply-fractions"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.num.fractions-decimals-ops.divide-by-fraction", "parent": "g7.num.fractions-decimals-ops", "title": "Dividing by a Fraction: Keep–Change–Flip and Why", "description": "Anchor a ÷ (1/2) in 'how many halves fit in a?', then formalise: keep the dividend, change ÷ to ×, flip the DIVISOR — and verify by multiplying back.", "outcomes": ["Can divide fractions by inverting the divisor only", "Can explain the reciprocal rule with a fitting-in picture and check answers by multiplication"], "prereqs": ["g7.num.fractions-decimals-ops.multiply-fractions"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g7.num.fractions-decimals-ops.multiply-decimals", "parent": "g7.num.fractions-decimals-ops", "title": "Multiplying Decimals: Counting Decimal Places", "description": "Route decimal products through fractions (0.3 × 0.2 = 3/10 × 2/10 = 6/100), then formalise: the product carries as many decimal places as both factors combined.", "outcomes": ["Can multiply decimals and place the point by counting places", "Can catch place-value errors with an estimation check"], "prereqs": ["g7.num.fractions-decimals-ops.multiply-fractions", "g6.num.decimals-ops"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.num.fractions-decimals-ops.divide-decimals", "parent": "g7.num.fractions-decimals-ops", "title": "Dividing Decimals", "description": "Divide decimals by whole numbers, then by decimals by scaling both numbers by the same power of 10 until the divisor is whole.", "outcomes": ["Can divide a decimal by a whole number keeping the point aligned", "Can divide by a decimal by shifting both points equally (3.6 ÷ 0.4 = 36 ÷ 4)"], "prereqs": ["g7.num.fractions-decimals-ops.multiply-decimals"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g7.num.fractions-decimals-ops.predict-size", "parent": "g7.num.fractions-decimals-ops", "title": "Will the Answer Be Bigger or Smaller?", "description": "Build the prediction habit: multiplying by a number less than 1 shrinks, dividing by a number less than 1 enlarges — overturning the primary-school instinct.", "outcomes": ["Can predict whether a product or quotient exceeds the starting number before computing", "Can state the boundary role of 1 in both operations"], "prereqs": ["g7.num.fractions-decimals-ops.divide-by-fraction", "g7.num.fractions-decimals-ops.multiply-decimals"], "est_minutes": 15, "difficulty": 3, "question": true}]}, {"id": "g7.num.rational-numbers-intro", "title": "Rational Numbers: Representation and Comparison", "grade": 7, "strand": "num", "description": "Rational numbers are all numbers expressible as p/q with integers p, q and q ≠ 0 — uniting integers, fractions and their negatives into one family. You will write rationals in standard form, place them on the number line, compare them, and find rationals between any two given ones.", "prereqs": ["g6.num.integers-intro", "g6.num.fractions-ops"], "outcomes": ["Can write a rational number in standard form (positive denominator, lowest terms)", "Can place positive and negative rationals on the number line", "Can compare and order rational numbers, including negatives", "Can find rational numbers between two given rational numbers"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g7.num.rational-numbers-intro.what-is-rational", "parent": "g7.num.rational-numbers-intro", "title": "What Counts as a Rational Number", "description": "Define rationals as p/q with integers p, q and q ≠ 0, and show integers and terminating decimals joining the family via 5 = 5/1 and 0.7 = 7/10.", "outcomes": ["Can decide whether a given number is rational and write it as p/q", "Can draw the nested-sets picture: integers inside rationals"], "prereqs": ["g6.num.fractions-ops", "g6.num.integers-intro"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.num.rational-numbers-intro.standard-form", "parent": "g7.num.rational-numbers-intro", "title": "Standard Form: Where the Sign Lives", "description": "Establish that −5/8, 5/−8 and −(5/8) are one number, and write rationals in standard form: sign in the numerator, positive denominator, lowest terms.", "outcomes": ["Can rewrite any rational with a positive denominator in lowest terms", "Can recognise equivalent forms of the same negative rational"], "prereqs": ["g7.num.rational-numbers-intro.what-is-rational"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.num.rational-numbers-intro.number-line", "parent": "g7.num.rational-numbers-intro", "title": "Rationals on the Number Line", "description": "Place positive and negative rationals by subdividing the gaps between integers, locating numbers like −3/4 between −1 and 0.", "outcomes": ["Can plot any rational number by subdividing unit intervals", "Can read off the rational represented by a marked point"], "prereqs": ["g7.num.rational-numbers-intro.standard-form"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.num.rational-numbers-intro.compare-order", "parent": "g7.num.rational-numbers-intro", "title": "Comparing and Ordering Rationals", "description": "Compare rationals via common denominators and the number line, mastering the reflection principle: comparing negatives reverses the comparison of their positives.", "outcomes": ["Can order a mixed list of positive and negative rationals", "Can explain why −3/4 < −1/2 although 3/4 > 1/2"], "prereqs": ["g7.num.rational-numbers-intro.number-line"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.num.rational-numbers-intro.between-rationals", "parent": "g7.num.rational-numbers-intro", "title": "Finding Rationals Between Rationals", "description": "Use averaging and denominator enlargement (1/3 = 10/30, 1/2 = 15/30) to exhibit rationals between any two given ones — and see the supply never ends.", "outcomes": ["Can find several rationals between two given rationals", "Can argue that infinitely many rationals lie between any two distinct rationals"], "prereqs": ["g7.num.rational-numbers-intro.compare-order"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g7.num.comparing-quantities", "title": "Comparing Quantities: Percentage, Profit and Loss, Simple Interest", "grade": 7, "strand": "num", "description": "Percentages turn every comparison into 'per hundred', making unlike things comparable. You will convert between fractions, decimals and percents, compute percentage increase/decrease, profit and loss on cost price, and simple interest. These are the most-used school mathematics in adult life.", "prereqs": ["g6.num.ratio-proportion", "g6.num.decimals-ops"], "outcomes": ["Can convert fluently between fractions, decimals and percentages", "Can find a percentage of a quantity and express one quantity as a percentage of another", "Can compute profit/loss and profit/loss percent on the cost price", "Can compute simple interest with SI = P × R × T / 100 and find the amount"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": [{"id": "g7.num.comparing-quantities.fdp-conversions", "parent": "g7.num.comparing-quantities", "title": "Fractions, Decimals and Percents: One Family", "description": "Convert fluently between the three notations — 3/5 = 0.6 = 60% — reading percent as 'per hundred' throughout.", "outcomes": ["Can convert any of fraction, decimal, percent into the other two", "Can recall benchmark equivalents (1/2, 1/4, 3/4, 1/5, 1/10)"], "prereqs": ["g6.num.ratio-proportion", "g6.num.decimals-ops"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g7.num.comparing-quantities.percent-of-quantity", "parent": "g7.num.comparing-quantities", "title": "Finding a Percent of a Quantity", "description": "Compute p% of a quantity by translating the percent into a fraction EVERY time: 15% of 400 = 15/100 × 400 — the rate must act on the base.", "outcomes": ["Can find a given percent of a quantity", "Can keep the rate (%) and the result (units) clearly separate"], "prereqs": ["g7.num.comparing-quantities.fdp-conversions", "g7.num.fractions-decimals-ops.fraction-of-quantity"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.num.comparing-quantities.express-as-percent", "parent": "g7.num.comparing-quantities", "title": "Expressing One Quantity as a Percent of Another", "description": "Turn part/whole comparisons into percents to compare unlike bases fairly — 18 out of 25 versus 68 out of 100 — always asking 'percent OF WHAT?'.", "outcomes": ["Can express one quantity as a percentage of another", "Can compare quantities with different bases by converting both to percents"], "prereqs": ["g7.num.comparing-quantities.percent-of-quantity"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.num.comparing-quantities.percent-change", "parent": "g7.num.comparing-quantities", "title": "Percentage Increase and Decrease", "description": "Compute percent change on the ORIGINAL value, and discover with ₹100 → ₹110 → ₹99 why an x% rise followed by an x% cut does not return home.", "outcomes": ["Can compute percentage increase or decrease of a quantity", "Can explain why successive +10% and −10% changes do not cancel"], "prereqs": ["g7.num.comparing-quantities.express-as-percent"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.num.comparing-quantities.profit-loss", "parent": "g7.num.comparing-quantities", "title": "Profit and Loss Percent on the Cost Price", "description": "Compute profit or loss in rupees and as a percent whose base is always the COST price — the money originally invested.", "outcomes": ["Can compute profit/loss and profit/loss percent from CP and SP", "Can find SP given CP and a profit percent (and vice versa in simple cases)"], "prereqs": ["g7.num.comparing-quantities.percent-of-quantity"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g7.num.comparing-quantities.simple-interest", "parent": "g7.num.comparing-quantities", "title": "Simple Interest and the Amount", "description": "Use SI = P × R × T / 100 for deposits and loans, keeping interest and the final amount (principal + interest) clearly distinct.", "outcomes": ["Can compute simple interest given principal, rate and time", "Can find the amount and solve for one missing quantity in the formula"], "prereqs": ["g7.num.comparing-quantities.percent-of-quantity"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g7.num.exponents-intro", "title": "Exponents and Powers: Laws and Standard Form", "grade": 7, "strand": "num", "description": "Exponents compress repeated multiplication: 10⁵ instead of 10×10×10×10×10. You will evaluate powers, use the laws of exponents (product, quotient, power of a power), and write large numbers in standard form. Exponents are the language of both astronomy and algebra.", "prereqs": ["g6.num.whole-numbers", "g7.num.integers-ops"], "outcomes": ["Can evaluate powers with whole-number exponents, including powers of negative bases", "Can apply a^m × a^n = a^(m+n), a^m ÷ a^n = a^(m−n) and (a^m)^n = a^(mn) with justification", "Can use a⁰ = 1 (a ≠ 0) and explain it via the quotient pattern", "Can express large numbers in standard form k × 10^n with 1 ≤ k < 10"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g7.num.exponents-intro.power-notation", "parent": "g7.num.exponents-intro", "title": "Reading and Writing Powers", "description": "Read a^n as 'a used as a factor n times', evaluating small powers and contrasting 2³ = 8 with 2 × 3 = 6 until the two never blur.", "outcomes": ["Can evaluate powers with whole-number bases and exponents", "Can express a repeated product in exponential form and identify base and exponent"], "prereqs": ["g6.num.whole-numbers"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g7.num.exponents-intro.negative-base-powers", "parent": "g7.num.exponents-intro", "title": "Powers of Negative Bases", "description": "Track the sign of (−a)^n through the sign rules: even exponents give positive results, odd exponents keep the minus — and (−2)⁴ differs from −2⁴.", "outcomes": ["Can evaluate powers of negative integers", "Can predict the sign of (−a)^n from the parity of n"], "prereqs": ["g7.num.exponents-intro.power-notation", "g7.num.integers-ops.mult-neg-neg"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.num.exponents-intro.product-law", "parent": "g7.num.exponents-intro", "title": "Product Law: Add the Exponents", "description": "Derive a^m × a^n = a^(m+n) by expanding both powers into factors at least once, so the shortcut is earned rather than memorised.", "outcomes": ["Can simplify products of same-base powers by adding exponents", "Can justify the law by expansion and spot when it does NOT apply (different bases)"], "prereqs": ["g7.num.exponents-intro.power-notation"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.num.exponents-intro.quotient-law-zero-exponent", "parent": "g7.num.exponents-intro", "title": "Quotient Law and Why a⁰ = 1", "description": "Derive a^m ÷ a^n = a^(m−n) by cancelling factors, then walk the ladder 7³, 7², 7¹, 7⁰ — each step divides by 7 — to land on a⁰ = 1.", "outcomes": ["Can simplify quotients of same-base powers by subtracting exponents", "Can explain via the ladder or quotient law why a⁰ = 1 for a ≠ 0"], "prereqs": ["g7.num.exponents-intro.product-law"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.num.exponents-intro.power-of-a-power", "parent": "g7.num.exponents-intro", "title": "Power of a Power and Power of a Product", "description": "Establish (a^m)^n = a^(mn) and (ab)^m = a^m b^m by expansion, completing the toolkit of exponent laws.", "outcomes": ["Can simplify expressions like (2³)² and (3 × 5)²", "Can choose the correct law when several could apply"], "prereqs": ["g7.num.exponents-intro.product-law"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g7.num.exponents-intro.standard-form-large", "parent": "g7.num.exponents-intro", "title": "Standard Form for Large Numbers", "description": "Write large numbers as k × 10^n with 1 ≤ k < 10, choosing the power by counting DECIMAL SHIFTS from after the leading digit — not by counting zeros.", "outcomes": ["Can express large numbers in standard form and convert back", "Can compare magnitudes of numbers given in standard form"], "prereqs": ["g7.num.exponents-intro.power-notation"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g7.alg.simple-equations", "title": "Simple Equations: Solving One-variable Linear Equations", "grade": 7, "strand": "alg", "description": "An equation is a balance: whatever you do to one side you must do to the other. You will solve equations like 5x − 3 = 12 by systematic inverse operations (or transposition done with understanding), check solutions by substitution, and translate word problems into equations.", "prereqs": ["g6.alg.intro-algebra", "g6.num.integers-intro"], "outcomes": ["Can maintain balance: perform the same operation on both sides of an equation", "Can solve one- and two-step linear equations in one variable, including with integer solutions", "Can verify a solution by substituting it back into the original equation", "Can set up and solve an equation from a word problem"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g7.alg.simple-equations.what-an-equation-says", "parent": "g7.alg.simple-equations", "title": "What an Equation Says", "description": "Read '=' as 'both sides weigh the same' — a statement, not an instruction to compute — using equations written in every orientation, including 12 = x + 5.", "outcomes": ["Can state what an equation claims and identify its two sides", "Can decide whether a given value makes an equation true or false"], "prereqs": ["g6.alg.intro-algebra"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g7.alg.simple-equations.balance-model", "parent": "g7.alg.simple-equations", "title": "The Balance Model: Same Move on Both Sides", "description": "Use a pan balance (drawn or physical) to see that adding, subtracting, multiplying or dividing must hit BOTH sides, or the equation tips into falsehood.", "outcomes": ["Can perform the same operation on both sides and keep the equation true", "Can spot and explain the error when an operation touches only one side"], "prereqs": ["g7.alg.simple-equations.what-an-equation-says"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.alg.simple-equations.solve-by-inverse-ops", "parent": "g7.alg.simple-equations", "title": "Solving by Inverse Operations", "description": "Solve one- and two-step equations like 3x + 4 = 19 by peeling operations off in reverse order, deriving 'transposition' honestly from both-sides moves.", "outcomes": ["Can solve two-step linear equations including negative solutions", "Can narrate each transposition as its underlying both-sides operation"], "prereqs": ["g7.alg.simple-equations.balance-model", "g6.num.integers-intro"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g7.alg.simple-equations.check-your-solution", "parent": "g7.alg.simple-equations", "title": "Check Your Solution by Substitution", "description": "Make substitution the mandatory last step of every solve: put the value back into the ORIGINAL equation and record a ✓ or ✗ — a failed check locates the wrong move.", "outcomes": ["Can verify a proposed solution by substituting into the original equation", "Can use a failed check to hunt down the erroneous step"], "prereqs": ["g7.alg.simple-equations.solve-by-inverse-ops"], "est_minutes": 10, "difficulty": 2, "question": true}, {"id": "g7.alg.simple-equations.variable-both-sides-intro", "parent": "g7.alg.simple-equations", "title": "First Steps with the Variable on Both Sides", "description": "Solve equations like 5x = 2x + 9 by collecting the variable terms on one side with balance moves — a gentle preview of the Class 8 staple.", "outcomes": ["Can solve simple equations with the variable appearing on both sides", "Can decide which side to collect variable terms on and why"], "prereqs": ["g7.alg.simple-equations.solve-by-inverse-ops"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g7.alg.simple-equations.from-words-to-equations", "parent": "g7.alg.simple-equations", "title": "From Words to Equations", "description": "Translate word problems — fares, recharges, consecutive numbers — into equations: name the unknown, encode the relationships, solve, and answer the question actually asked.", "outcomes": ["Can set up a linear equation from a word problem", "Can solve it and interpret the solution back in context"], "prereqs": ["g7.alg.simple-equations.check-your-solution"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g7.alg.expressions", "title": "Algebraic Expressions: Terms, Like Terms, Evaluation", "grade": 7, "strand": "alg", "description": "You will take expressions apart into terms, factors and coefficients, combine like terms, add and subtract whole expressions, and evaluate them for given values — including negative ones. Fluency here is what makes equation-solving and identities feel easy next year.", "prereqs": ["g6.alg.intro-algebra", "g7.num.integers-ops"], "outcomes": ["Can identify terms, factors, coefficients, and classify monomials/binomials/trinomials", "Can identify like terms and combine them correctly", "Can add and subtract algebraic expressions, distributing the minus sign over every term", "Can evaluate expressions at given values, including negative values"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g7.alg.expressions.terms-factors-coefficients", "parent": "g7.alg.expressions", "title": "Terms, Factors and Coefficients", "description": "Take expressions apart with tree diagrams: terms are joined by + and −, each term is a product of factors, and the numerical factor is the coefficient — including the invisible 1 in x and −1 in −x.", "outcomes": ["Can list the terms and factors of an expression", "Can state the coefficient of any term, including lone and negated variables"], "prereqs": ["g6.alg.intro-algebra"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.alg.expressions.classify-expressions", "parent": "g7.alg.expressions", "title": "Monomials, Binomials, Trinomials", "description": "Classify expressions by their number of (unlike) terms, first simplifying so that disguised like terms don't inflate the count.", "outcomes": ["Can classify expressions as monomial, binomial or trinomial", "Can explain why 3x + 2x is a monomial in disguise"], "prereqs": ["g7.alg.expressions.terms-factors-coefficients"], "est_minutes": 10, "difficulty": 1, "question": false}, {"id": "g7.alg.expressions.like-terms", "parent": "g7.alg.expressions", "title": "Like Terms and How to Combine Them", "description": "Sort terms into bins by their EXACT variable part and add coefficients within a bin — verifying with number substitution that unlike terms refuse to merge.", "outcomes": ["Can identify like terms among terms with several variables and powers", "Can combine like terms and leave unlike terms alone"], "prereqs": ["g7.alg.expressions.terms-factors-coefficients"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.alg.expressions.add-expressions", "parent": "g7.alg.expressions", "title": "Adding Algebraic Expressions", "description": "Add whole expressions by regrouping like terms, horizontally and in columns, keeping every sign attached to its term.", "outcomes": ["Can add two or three expressions and simplify the result", "Can verify an addition by substituting a test value"], "prereqs": ["g7.alg.expressions.like-terms"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.alg.expressions.subtract-expressions", "parent": "g7.alg.expressions", "title": "Subtracting Expressions: The Minus Reaches Every Term", "description": "Rewrite subtraction as adding (−1) × (bracket) and distribute the −1 to EVERY term with drawn arrows, then combine like terms.", "outcomes": ["Can subtract one expression from another, flipping every sign in the subtrahend", "Can check the result numerically"], "prereqs": ["g7.alg.expressions.add-expressions"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.alg.expressions.evaluate-expressions", "parent": "g7.alg.expressions", "title": "Evaluating Expressions, Including Negative Values", "description": "Substitute values with bracket discipline — always (−2)², never bare −2² — and evaluate expressions used in perimeter and pattern formulas.", "outcomes": ["Can evaluate an expression at given positive and negative values", "Can distinguish (−2)² from −(2²) and compute each correctly"], "prereqs": ["g7.alg.expressions.like-terms", "g7.num.integers-ops.mult-neg-neg"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g7.geo.lines-angles", "title": "Lines and Angles: Angle Pairs, Parallel Lines and Transversals", "grade": 7, "strand": "geo", "description": "You will work with complementary, supplementary, adjacent and vertically opposite angles, then study what happens when a transversal cuts parallel lines: corresponding and alternate angles are equal, and co-interior angles add to 180°. These angle facts are the raw material of all later geometric proof.", "prereqs": ["g6.geo.elementary-shapes"], "outcomes": ["Can find complements (to 90°) and supplements (to 180°) of given angles", "Can identify and use vertically opposite angles and linear pairs", "Can name corresponding, alternate and co-interior angle pairs at a transversal", "Can compute unknown angles when a transversal cuts parallel lines, justifying each step"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g7.geo.lines-angles.complementary-supplementary", "parent": "g7.geo.lines-angles", "title": "Complementary and Supplementary Angles", "description": "Find partners to 90° (Corner) and 180° (Straight), anchoring which word goes with which number so the two never swap.", "outcomes": ["Can compute the complement and supplement of a given angle", "Can classify a pair of angles as complementary, supplementary or neither"], "prereqs": ["g5.geo.angles-intro", "g6.geo.elementary-shapes"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g7.geo.lines-angles.adjacent-linear-pair", "parent": "g7.geo.lines-angles", "title": "Adjacent Angles and Linear Pairs", "description": "Identify adjacent angles (common arm, common vertex, no overlap) and see that a linear pair — adjacent angles on a straight line — always totals 180°.", "outcomes": ["Can identify adjacent angles and linear pairs in a figure", "Can find the missing angle of a linear pair"], "prereqs": ["g7.geo.lines-angles.complementary-supplementary"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.geo.lines-angles.vertically-opposite", "parent": "g7.geo.lines-angles", "title": "Vertically Opposite Angles Are Equal", "description": "At any crossing of two lines, rotate a traced copy 180° to see opposite angles coincide — EQUAL, while the adjacent pairs are the ones summing to 180°.", "outcomes": ["Can find all four angles at a crossing from any one of them", "Can justify why vertically opposite angles are equal using linear pairs"], "prereqs": ["g7.geo.lines-angles.adjacent-linear-pair"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.geo.lines-angles.transversal-angle-pairs", "parent": "g7.geo.lines-angles", "title": "Naming Angle Pairs at a Transversal", "description": "When a transversal cuts two lines, learn to NAME the eight angles' relationships — corresponding (F), alternate (Z), co-interior (C/U) — before any equality rules are invoked.", "outcomes": ["Can identify corresponding, alternate interior/exterior and co-interior pairs", "Can locate a named pair in any orientation of the figure"], "prereqs": ["g7.geo.lines-angles.vertically-opposite"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g7.geo.lines-angles.parallel-angle-rules", "parent": "g7.geo.lines-angles", "title": "Angle Rules for Parallel Lines", "description": "With parallel lines, corresponding and alternate angles are EQUAL while co-interior angles are SUPPLEMENTARY — sorted physically with tracing-paper slides and half-turns.", "outcomes": ["Can compute every angle at a transversal of parallel lines from one given angle", "Can justify each step by naming the pair and its rule"], "prereqs": ["g7.geo.lines-angles.transversal-angle-pairs"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g7.geo.lines-angles.are-lines-parallel", "parent": "g7.geo.lines-angles", "title": "Are These Lines Parallel? Rules Need a Licence", "description": "Use the converses — equal corresponding/alternate angles, or supplementary co-interior angles, certify parallelism — and never apply parallel-line rules without first stating which lines are parallel and why.", "outcomes": ["Can test whether two lines are parallel from measured transversal angles", "Can reject a rule application when the parallel condition is unverified"], "prereqs": ["g7.geo.lines-angles.parallel-angle-rules"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g7.geo.triangle-properties", "title": "The Triangle and Its Properties: Angle Sum, Exterior Angle, Pythagoras Intro", "grade": 7, "strand": "geo", "description": "Every triangle hides three strong laws: its angles sum to 180°, an exterior angle equals the sum of the two remote interior angles, and any two sides together exceed the third. For right triangles you will meet the Pythagoras property relating the squares on the sides.", "prereqs": ["g7.geo.lines-angles"], "outcomes": ["Can use the angle-sum property (180°) to find unknown angles", "Can apply the exterior-angle property: exterior = sum of the two remote interior angles", "Can test whether three lengths can form a triangle (triangle inequality)", "Can use the Pythagoras property to check for right angles and find a missing side in simple cases"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g7.geo.triangle-properties.medians-altitudes", "parent": "g7.geo.triangle-properties", "title": "Medians and Altitudes of a Triangle", "description": "Meet the triangle's internal lines: a median joins a vertex to the midpoint of the opposite side; an altitude drops perpendicularly from a vertex — sometimes landing outside the triangle.", "outcomes": ["Can draw the three medians and three altitudes of a triangle", "Can explain when an altitude falls outside the triangle"], "prereqs": ["g6.geo.elementary-shapes"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.geo.triangle-properties.angle-sum", "parent": "g7.geo.triangle-properties", "title": "The Angle Sum Is 180°", "description": "Tear the corners off paper triangles and line them up along a ruler edge — a straight 180°, never a full turn — then compute unknown angles with the property.", "outcomes": ["Can find the third angle of a triangle from the other two", "Can solve angle problems combining the angle sum with linear pairs"], "prereqs": ["g7.geo.triangle-properties.medians-altitudes", "g7.geo.lines-angles.parallel-angle-rules"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.geo.triangle-properties.exterior-angle", "parent": "g7.geo.triangle-properties", "title": "The Exterior Angle Property", "description": "Extend one side and colour-code the two REMOTE interior angles: the exterior angle equals their sum, provable two ways via the angle sum and the straight line.", "outcomes": ["Can compute an exterior angle from the two remote interior angles", "Can find a remote interior angle given the exterior angle"], "prereqs": ["g7.geo.triangle-properties.angle-sum"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.geo.triangle-properties.isosceles-equilateral", "parent": "g7.geo.triangle-properties", "title": "Isosceles and Equilateral Triangle Angles", "description": "Use 'angles opposite equal sides are equal' to solve isosceles and equilateral angle problems, combining it with the angle-sum property.", "outcomes": ["Can find base angles of an isosceles triangle from the apex angle and vice versa", "Can justify why every equilateral triangle has three 60° angles"], "prereqs": ["g7.geo.triangle-properties.angle-sum"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g7.geo.triangle-properties.triangle-inequality", "parent": "g7.geo.triangle-properties", "title": "The Triangle Inequality", "description": "Fail to close a triangle with sticks of lengths 3, 4 and 8, then formulate the rule from the experience: each side must be less than the sum of the other two.", "outcomes": ["Can test whether three lengths can form a triangle", "Can find the possible range for a third side given two sides"], "prereqs": ["g7.geo.triangle-properties.medians-altitudes"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.geo.triangle-properties.pythagoras-intro", "parent": "g7.geo.triangle-properties", "title": "The Pythagoras Property of Right Triangles", "description": "In RIGHT triangles only, the square on the hypotenuse equals the sum of the squares on the legs — used to find missing sides and to test for right angles.", "outcomes": ["Can find a missing side of a right triangle in simple whole-number cases", "Can use the converse to check whether a triangle is right-angled"], "prereqs": ["g7.geo.triangle-properties.angle-sum", "g7.geo.triangle-properties.triangle-inequality"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g7.geo.congruence", "title": "Congruence of Triangles: SSS, SAS, ASA, RHS", "grade": 7, "strand": "geo", "description": "Two figures are congruent when one fits exactly on the other. For triangles you don't need to check all six parts: the criteria SSS, SAS, ASA and RHS each guarantee congruence from just three well-chosen parts. Congruence is your first taste of deductive proof.", "prereqs": ["g7.geo.triangle-properties"], "outcomes": ["Can state what congruence means and write correspondences (ΔABC ≅ ΔPQR) in the right order", "Can select and apply the appropriate criterion: SSS, SAS, ASA or RHS", "Can explain why AAA and SSA are NOT valid congruence criteria", "Can extract equal corresponding parts (CPCT) from a stated congruence"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g7.geo.congruence.congruence-meaning", "parent": "g7.geo.congruence", "title": "What Congruence Means", "description": "Two figures are congruent when one superposes exactly on the other — same shape AND size — which is stronger than merely having equal areas or looking alike.", "outcomes": ["Can decide congruence of simple figures by superposition reasoning", "Can give examples of equal-area figures that are not congruent"], "prereqs": ["g6.geo.elementary-shapes"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.geo.congruence.correspondence-cpct", "parent": "g7.geo.congruence", "title": "Correspondence and Reading Off Equal Parts", "description": "In ΔABC ≅ ΔPQR the letter positions ARE the matching: A↔P, B↔Q, C↔R. Read all six equal parts from the statement alone — that is CPCT.", "outcomes": ["Can write a congruence statement in the correct vertex order", "Can extract all corresponding equal sides and angles from a stated congruence"], "prereqs": ["g7.geo.congruence.congruence-meaning"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.geo.congruence.sss-criterion", "parent": "g7.geo.congruence", "title": "The SSS Criterion", "description": "Three matched sides force congruence: a triangle with fixed side lengths is rigid — the reason trusses and brackets are triangular.", "outcomes": ["Can apply SSS to justify congruence of two triangles", "Can connect SSS to the rigidity of triangles in structures"], "prereqs": ["g7.geo.congruence.congruence-meaning", "g7.geo.triangle-properties.triangle-inequality"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.geo.congruence.sas-included-angle", "parent": "g7.geo.congruence", "title": "SAS: The Angle Must Be Included", "description": "Two sides with the angle BETWEEN them determine a triangle; the same data with a non-included angle (SSA) can produce two different triangles.", "outcomes": ["Can apply SAS with the included angle correctly identified", "Can reject an SAS claim when the given angle is not between the given sides"], "prereqs": ["g7.geo.congruence.sss-criterion"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.geo.congruence.asa-rhs-criteria", "parent": "g7.geo.congruence", "title": "ASA and RHS Criteria", "description": "Two angles with the included side (ASA) pin a triangle down; for right triangles, the hypotenuse and one side (RHS) suffice — completing the toolkit of four criteria.", "outcomes": ["Can apply ASA and RHS to justify congruence", "Can select the appropriate criterion from the data given"], "prereqs": ["g7.geo.congruence.sas-included-angle"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g7.geo.congruence.why-not-aaa-ssa", "parent": "g7.geo.congruence", "title": "Why AAA and SSA Fail", "description": "Nested equilateral triangles kill AAA (same angles, different sizes); the double-crossing compass arc kills SSA — sharpening what a criterion must guarantee.", "outcomes": ["Can produce a counterexample showing AAA does not force congruence", "Can explain the ambiguous case that defeats SSA"], "prereqs": ["g7.geo.congruence.asa-rhs-criteria"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g7.geo.symmetry-rotational", "title": "Symmetry: Line and Rotational", "grade": 7, "strand": "geo", "description": "Beyond mirror lines, shapes can also match themselves under turning: a shape has rotational symmetry of order n if it looks unchanged n times during a full 360° turn. You will find orders and angles of rotation, and discover that line symmetry and rotational symmetry are independent properties.", "prereqs": ["g6.geo.symmetry"], "outcomes": ["Can find the order of rotational symmetry of a figure and its angle of rotation (360°/order)", "Can locate the centre of rotation of a symmetric figure", "Can give examples of shapes with line symmetry only, rotational only, both, and neither", "Can explain why every figure trivially matches itself after a full 360° turn (order at least 1)"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g7.geo.symmetry-rotational.line-symmetry-review", "parent": "g7.geo.symmetry-rotational", "title": "Line Symmetry Revisited — Fold Tests, Not Guesses", "description": "Re-establish mirror lines by folding, including the surprise that a generic parallelogram has NONE — its diagonal fold leaves flipped, non-matching halves.", "outcomes": ["Can count the lines of symmetry of standard polygons by fold reasoning", "Can explain why a parallelogram's diagonals are not mirror lines"], "prereqs": ["g6.geo.symmetry"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.geo.symmetry-rotational.rotational-symmetry-order", "parent": "g7.geo.symmetry-rotational", "title": "Rotational Symmetry and Its Order", "description": "Rotate a marked cut-out through a full turn and tally every position where the outline matches — the order counts ALL matches in 360°, including the return home.", "outcomes": ["Can find the order of rotational symmetry of a figure by rotation-tallying", "Can explain why every figure has order at least 1"], "prereqs": ["g7.geo.symmetry-rotational.line-symmetry-review"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.geo.symmetry-rotational.angle-of-rotation", "parent": "g7.geo.symmetry-rotational", "title": "Angle of Rotation and the Centre", "description": "Pin down angle = 360° ÷ order with a table (order 2 ↔ 180°, order 3 ↔ 120°, order 4 ↔ 90°) and locate the centre of rotation of symmetric figures.", "outcomes": ["Can compute the smallest angle of rotation from the order and vice versa", "Can locate the centre of rotation of a figure"], "prereqs": ["g7.geo.symmetry-rotational.rotational-symmetry-order"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.geo.symmetry-rotational.line-vs-rotational", "parent": "g7.geo.symmetry-rotational", "title": "Line and Rotational Symmetry Are Independent", "description": "Fill a 2×2 sorting grid with counterexamples in every cell — square (both), isosceles trapezium (line only), parallelogram and letter S (rotation only), scalene triangle (neither).", "outcomes": ["Can give an example shape for each combination of line/rotational symmetry", "Can classify a given figure into the correct cell of the grid"], "prereqs": ["g7.geo.symmetry-rotational.angle-of-rotation"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g7.geo.visualising-solids", "title": "Visualising Solid Shapes: Nets, Sketches, Cross-sections", "grade": 7, "strand": "geo", "description": "Solids live in 3D but we draw them in 2D. You will match solids with their nets, draw oblique and isometric sketches, imagine cross-sections made by cuts, and read views (top, front, side) and shadows. Strong 3D visualisation pays off in geometry, science diagrams and engineering drawing.", "prereqs": ["g5.geo.nets-3d", "g6.geo.elementary-shapes"], "outcomes": ["Can count and name faces, edges and vertices of common solids", "Can decide whether a given net folds into a given solid (cube, cuboid, cylinder, cone)", "Can describe the cross-section produced by a horizontal or vertical cut of a solid", "Can interpret and draw top, front and side views of simple solid arrangements"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g7.geo.visualising-solids.faces-edges-vertices", "parent": "g7.geo.visualising-solids", "title": "Faces, Edges and Vertices", "description": "Attach each word to a gesture on a real solid — palm on a FACE, finger along an EDGE, fingertip on a VERTEX — and tabulate F, E, V for cubes, cuboids, prisms and pyramids.", "outcomes": ["Can count faces, edges and vertices of common solids", "Can keep the three words attached to the right parts, counting hidden ones from a sketch"], "prereqs": ["g5.geo.nets-3d", "g6.geo.elementary-shapes"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g7.geo.visualising-solids.nets-of-solids", "parent": "g7.geo.visualising-solids", "title": "Nets That Fold — and Nets That Don't", "description": "Fold printed 6-square arrangements to discover which become cubes, building checking strategies (no 2×2 block, at most four in a row) from real failures; extend to cuboid, cylinder and cone nets.", "outcomes": ["Can decide whether a given net folds into a given solid", "Can draw at least two distinct valid nets of a cube"], "prereqs": ["g7.geo.visualising-solids.faces-edges-vertices"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.geo.visualising-solids.oblique-isometric-sketches", "parent": "g7.geo.visualising-solids", "title": "Oblique and Isometric Sketches", "description": "Draw solids two ways — oblique sketches on plain paper and isometric sketches on dot paper — marking hidden edges dashed and keeping a real cube in hand while drawing.", "outcomes": ["Can make an oblique sketch of a cube or cuboid with hidden edges dashed", "Can draw a cuboid of given dimensions on isometric dot paper"], "prereqs": ["g7.geo.visualising-solids.faces-edges-vertices"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g7.geo.visualising-solids.cross-sections", "parent": "g7.geo.visualising-solids", "title": "Cross-sections: The Cut's Direction Decides", "description": "Slice solids (clay, cucumber) horizontally AND vertically and trace the exposed faces — a cylinder yields a circle one way and a rectangle the other; the direction of cut is part of every answer.", "outcomes": ["Can name the cross-section from a described horizontal or vertical cut", "Can explain why one solid can produce different cross-sections"], "prereqs": ["g7.geo.visualising-solids.oblique-isometric-sketches"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.geo.visualising-solids.views-and-shadows", "parent": "g7.geo.visualising-solids", "title": "Top, Front and Side Views; Shadows", "description": "Read and draw the three standard views of cube arrangements and everyday objects, and reason about the shadows solids cast — different 2D pictures of one 3D reality.", "outcomes": ["Can draw top, front and side views of a simple solid arrangement", "Can match a solid to its set of three views"], "prereqs": ["g7.geo.visualising-solids.oblique-isometric-sketches"], "est_minutes": 20, "difficulty": 3, "question": false}]}, {"id": "g7.geo.practical-geometry", "title": "Practical Geometry: Parallel Lines and Triangle Constructions", "grade": 7, "strand": "geo", "description": "With ruler and compass you will construct a line parallel to a given line through a point, and triangles from given data: three sides (SSS), two sides and the included angle (SAS), two angles and a side (ASA), and right triangles (RHS). Each construction succeeds exactly when the corresponding congruence criterion holds — construction and congruence are two sides of the same coin.", "prereqs": ["g6.geo.constructions-intro", "g7.geo.lines-angles", "g7.geo.congruence"], "outcomes": ["Can construct a line parallel to a given line through an external point using equal alternate/corresponding angles", "Can construct triangles from SSS, SAS, ASA and RHS data", "Can recognise data sets that give no triangle (violating the triangle inequality) or more than one triangle", "Can connect each construction to the congruence criterion that guarantees uniqueness"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g7.geo.practical-geometry.parallel-through-point", "parent": "g7.geo.practical-geometry", "title": "Constructing a Parallel Line Through a Point", "description": "Draw a transversal through the external point, then copy its angle with compass arcs at the new point — equal alternate/corresponding angles GUARANTEE parallelism, no eyeballing.", "outcomes": ["Can construct a line through a given point parallel to a given line", "Can justify the construction via the equal-angles condition for parallel lines"], "prereqs": ["g6.geo.constructions-intro", "g7.geo.lines-angles.parallel-angle-rules"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g7.geo.practical-geometry.construct-sss", "parent": "g7.geo.practical-geometry", "title": "Constructing a Triangle from Three Sides (SSS)", "description": "Lay the base, then swing arcs of the other two lengths from its ends — after FIRST checking the triangle inequality, so doomed data is caught before the compass moves.", "outcomes": ["Can construct a triangle from three given side lengths", "Can predict from the triangle inequality when the arcs will fail to meet"], "prereqs": ["g6.geo.constructions-intro", "g7.geo.triangle-properties.triangle-inequality", "g7.geo.congruence.sss-criterion"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.geo.practical-geometry.construct-sas", "parent": "g7.geo.practical-geometry", "title": "Constructing a Triangle from SAS", "description": "Draw one side, copy the given angle AT ITS END, and mark the second side along the new ray — the angle must sit BETWEEN the two given sides for the triangle to be unique.", "outcomes": ["Can construct a triangle from two sides and the included angle", "Can explain why placing the angle elsewhere can yield two different triangles"], "prereqs": ["g7.geo.practical-geometry.construct-sss", "g7.geo.congruence.sas-included-angle"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.geo.practical-geometry.construct-asa", "parent": "g7.geo.practical-geometry", "title": "Constructing a Triangle from ASA", "description": "Draw the given side and copy the two given angles at its ends; when the data gives a NON-included side, first find the third angle via the 180° sum, justifying each step aloud.", "outcomes": ["Can construct a triangle from two angles and the included side", "Can convert AAS data to ASA using the angle-sum property"], "prereqs": ["g7.geo.practical-geometry.construct-sas"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g7.geo.practical-geometry.construct-rhs", "parent": "g7.geo.practical-geometry", "title": "Constructing a Right Triangle from RHS", "description": "Erect a perpendicular at one end of a leg, then cut the hypotenuse arc from the other end — with a one-line justification for every arc, so the steps are reasons, not ritual.", "outcomes": ["Can construct a right triangle given the hypotenuse and one side", "Can justify each construction step and connect it to the RHS criterion"], "prereqs": ["g7.geo.practical-geometry.construct-asa"], "est_minutes": 20, "difficulty": 3, "question": false}]}, {"id": "g7.mea.perimeter-area", "title": "Perimeter and Area: Triangles, Parallelograms, Circles", "grade": 7, "strand": "mea", "description": "You will extend area from rectangles to parallelograms (base × height) and triangles (half of that), and meet the circle's two famous formulas: circumference 2πr and area πr². Choosing the RIGHT base–height pair, and the right formula, is the heart of this chapter.", "prereqs": ["g6.mea.mensuration-perimeter-area", "g7.num.fractions-decimals-ops", "g4.geo.circle-intro"], "outcomes": ["Can compute areas of parallelograms and triangles using base and the PERPENDICULAR height", "Can compute circumference and area of circles, using π ≈ 22/7 or 3.14", "Can solve problems with paths, borders and combined figures", "Can convert between units of area (cm², m²) where needed"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g7.mea.perimeter-area.perimeter-vs-area", "parent": "g7.mea.perimeter-area", "title": "Perimeter or Area? Choosing the Right Measure", "description": "Re-anchor the two measures with actions — WALK the boundary (perimeter) vs COVER the surface (area) — and sort mixed word problems into P-questions and A-questions before solving any.", "outcomes": ["Can decide whether a context calls for perimeter or area", "Can compute both for rectangles and squares as revision"], "prereqs": ["g6.mea.mensuration-perimeter-area"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g7.mea.perimeter-area.area-parallelogram", "parent": "g7.mea.perimeter-area", "title": "Area of a Parallelogram: Base × Perpendicular Height", "description": "Slice the slanted end off a paper parallelogram and slide it across to make a rectangle — area = base × height, where the height is the measurement carrying the right-angle mark, never the slant side.", "outcomes": ["Can compute a parallelogram's area choosing the correct base–height pair", "Can reject a slant side offered as a 'height'"], "prereqs": ["g7.mea.perimeter-area.perimeter-vs-area"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.mea.perimeter-area.area-triangle", "parent": "g7.mea.perimeter-area", "title": "Area of a Triangle: Half a Parallelogram", "description": "Cut a parallelogram along a diagonal into two identical triangles — so triangle area = ½ × base × perpendicular height, with the ½ earned, not memorised.", "outcomes": ["Can compute triangle areas with the correct base–height pair", "Can explain where the ½ comes from"], "prereqs": ["g7.mea.perimeter-area.area-parallelogram"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.mea.perimeter-area.circle-circumference", "parent": "g7.mea.perimeter-area", "title": "Circumference of a Circle", "description": "Wrap a string around a tin — about 3 diameters and a bit — to meet π, then use C = 2πr (or πd) with π ≈ 22/7 or 3.14 for wheels, tracks and trundle problems.", "outcomes": ["Can compute circumference from radius or diameter", "Can solve rotation-distance problems (how far one wheel turn travels)"], "prereqs": ["g7.mea.perimeter-area.perimeter-vs-area", "g7.num.fractions-decimals-ops.multiply-decimals"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.mea.perimeter-area.circle-area", "parent": "g7.mea.perimeter-area", "title": "Area of a Circle", "description": "Cut a circle into thin sectors and rearrange them into a near-rectangle of width r and length πr — so area = πr², with careful radius-vs-diameter reading in every problem.", "outcomes": ["Can compute a circle's area from its radius or diameter", "Can keep 2πr and πr² apart using dimension sense"], "prereqs": ["g7.mea.perimeter-area.circle-circumference"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g7.mea.perimeter-area.paths-combined-figures", "parent": "g7.mea.perimeter-area", "title": "Paths, Borders and Combined Figures", "description": "Find areas of paths around or across parks by subtracting rectangles, handle figures built from rectangles, triangles and semicircles, and convert between cm² and m² where needed.", "outcomes": ["Can compute the area of a uniform path around or through a rectangle", "Can decompose a combined figure into standard shapes and convert area units"], "prereqs": ["g7.mea.perimeter-area.area-triangle", "g7.mea.perimeter-area.circle-area"], "est_minutes": 25, "difficulty": 4, "question": false}]}, {"id": "g7.dat.data-handling-averages", "title": "Data Handling: Mean, Median, Mode, Range and Chance", "grade": 7, "strand": "dat", "description": "One number can represent a whole data set: the mean (fair share), median (middle of the sorted list) and mode (most frequent value) — each useful in different situations, with range measuring spread. You will also take your first formal steps into probability as a number between 0 and 1.", "prereqs": ["g6.dat.data-handling", "g6.num.decimals-ops", "g7.num.fractions-decimals-ops"], "outcomes": ["Can compute the mean and explain it as equal sharing / balance point", "Can find the median (after sorting!) and the mode of a data set", "Can choose which average best represents a data set and critique a poor choice", "Can assign simple probabilities as favourable outcomes over total equally likely outcomes"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g7.dat.data-handling-averages.organise-data", "parent": "g7.dat.data-handling-averages", "title": "Collecting and Organising Data", "description": "Move from raw lists to frequency tables with tally marks, and pose the chapter's driving question: what ONE number could speak for this whole data set?", "outcomes": ["Can build a frequency table from raw data", "Can read simple summaries (largest, smallest, most common) from the table"], "prereqs": ["g6.dat.data-handling"], "est_minutes": 10, "difficulty": 1, "question": false}, {"id": "g7.dat.data-handling-averages.mean", "parent": "g7.dat.data-handling-averages", "title": "The Mean as Equal Sharing", "description": "Level cube towers to see the mean as the equal-share value — total ÷ count — which may be a decimal and need not appear anywhere in the data.", "outcomes": ["Can compute the mean of a data set", "Can explain why the mean can be a value not in the list"], "prereqs": ["g7.dat.data-handling-averages.organise-data", "g6.num.decimals-ops"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g7.dat.data-handling-averages.median", "parent": "g7.dat.data-handling-averages", "title": "The Median: Sort First, Then Find the Middle", "description": "Line the data up in order — a non-negotiable first step — then take the middle value (or the mean of the middle two) as the median.", "outcomes": ["Can find the median of odd- and even-sized data sets after sorting", "Can show how skipping the sort produces a wrong median"], "prereqs": ["g7.dat.data-handling-averages.mean"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g7.dat.data-handling-averages.mode-range", "parent": "g7.dat.data-handling-averages", "title": "Mode and Range", "description": "MOde = MOst often — the most frequent value, found easily from a frequency table — and range = largest minus smallest, a first measure of spread.", "outcomes": ["Can find the mode(s) and range of a data set", "Can keep mode, maximum and mean verbally and computationally distinct"], "prereqs": ["g7.dat.data-handling-averages.median"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g7.dat.data-handling-averages.choose-average", "parent": "g7.dat.data-handling-averages", "title": "Which Average Represents the Data Best?", "description": "Pit the three averages against each other on skewed data — one luxury flat among modest rents — and choose the representative that honestly answers the question asked.", "outcomes": ["Can choose an appropriate average for a context and justify the choice", "Can explain how an outlier drags the mean but not the median"], "prereqs": ["g7.dat.data-handling-averages.mode-range"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g7.dat.data-handling-averages.double-bar-graphs", "parent": "g7.dat.data-handling-averages", "title": "Bar Graphs and Double Bar Graphs", "description": "Choose a sensible scale, draw bar graphs, and use DOUBLE bars to compare two data sets side by side — this year's marks against last year's.", "outcomes": ["Can draw a bar graph with an appropriate scale", "Can read and compare paired categories from a double bar graph"], "prereqs": ["g7.dat.data-handling-averages.organise-data"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g7.dat.data-handling-averages.chance-probability", "parent": "g7.dat.data-handling-averages", "title": "First Steps in Probability", "description": "Assign probabilities as favourable outcomes over total EQUALLY LIKELY outcomes, placing events on the 0-to-1 scale — and testing by experiment that 'it happens or it doesn't' is not 50-50.", "outcomes": ["Can list equally likely outcomes and compute simple probabilities", "Can place impossible, unlikely, even, likely and certain events on the 0–1 scale"], "prereqs": ["g7.dat.data-handling-averages.organise-data"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g8.num.rational-numbers", "title": "Rational Numbers: Properties and Density", "grade": 8, "strand": "num", "description": "You will study rational numbers as a system: closure, commutativity and associativity, the roles of 0 and 1, negatives (additive inverses) and reciprocals (multiplicative inverses), and distributivity as a computation shortcut. The headline property is density — between any two rationals lie infinitely many more.", "prereqs": ["g7.num.rational-numbers-intro", "g7.num.fractions-decimals-ops"], "outcomes": ["Can state and use the properties of operations on rational numbers, with counterexamples for subtraction/division", "Can find additive and multiplicative inverses and keep the two ideas apart", "Can use distributivity to simplify computations like a×b + a×c", "Can find (infinitely many) rational numbers between two given rationals"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g8.num.rational-numbers.ops-revision", "parent": "g8.num.rational-numbers", "title": "Warm-up: Four Operations on Rationals", "description": "Revise adding, subtracting, multiplying and dividing rational numbers in fraction form, including negatives.", "outcomes": ["Can compute a±b, a×b, a÷b for any two rationals", "Can handle signs correctly through each operation"], "prereqs": ["g7.num.rational-numbers-intro", "g7.num.fractions-decimals-ops"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g8.num.rational-numbers.closure-commutativity", "parent": "g8.num.rational-numbers", "title": "Closure, Commutativity and Associativity", "description": "Test which of the four operations keep rationals closed, commutative and associative — and catch subtraction and division failing the last two.", "outcomes": ["Can state which properties hold for which operations", "Can produce a counterexample when a property fails"], "prereqs": ["g8.num.rational-numbers.ops-revision"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.num.rational-numbers.identities-inverses", "parent": "g8.num.rational-numbers", "title": "Identities, Opposites and Reciprocals", "description": "Fix 0 and 1 as the additive and multiplicative identities, and sharply separate the additive inverse (opposite) from the multiplicative inverse (reciprocal) — noting 0 has no reciprocal.", "outcomes": ["Can give the additive and multiplicative inverse of any rational", "Can explain why 0 has no reciprocal"], "prereqs": ["g8.num.rational-numbers.ops-revision"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.num.rational-numbers.distributivity", "parent": "g8.num.rational-numbers", "title": "Distributivity and Smart Computation", "description": "Use a(b + c) = ab + ac to reorganise messy rational calculations into easy ones.", "outcomes": ["Can apply distributivity to simplify computations like 3/7 × 5/6 + 3/7 × 1/6"], "prereqs": ["g8.num.rational-numbers.closure-commutativity"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g8.num.rational-numbers.number-line", "parent": "g8.num.rational-numbers", "title": "Rationals on the Number Line", "description": "Locate any rational, positive or negative, on the number line by subdividing unit intervals.", "outcomes": ["Can mark rationals like −7/4 on a number line accurately"], "prereqs": ["g8.num.rational-numbers.ops-revision"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g8.num.rational-numbers.density", "parent": "g8.num.rational-numbers", "title": "Density: Rationals Between Rationals", "description": "Discover that between ANY two rationals lie infinitely many more, using averages and common denominators.", "outcomes": ["Can find n rationals between two given rationals", "Can argue why the process never runs out"], "prereqs": ["g8.num.rational-numbers.number-line"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g8.num.squares-roots", "title": "Squares and Square Roots", "grade": 8, "strand": "num", "description": "Perfect squares are numbers like 1, 4, 9, 16 — areas of whole-number squares. You will spot their patterns (unit digits, odd-number sums), find square roots by prime factorisation and by long division, and estimate roots of non-perfect squares. Square roots return in Pythagoras, quadratics and beyond.", "prereqs": ["g7.num.exponents-intro", "g6.num.playing-with-numbers"], "outcomes": ["Can compute squares efficiently and recognise perfect squares up to at least 400", "Can use unit-digit and other patterns to rule out non-squares (no perfect square ends in 2, 3, 7 or 8)", "Can find square roots by prime factorisation and by the long-division method", "Can estimate the square root of a non-perfect square between consecutive integers"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g8.num.squares-roots.perfect-square-patterns", "parent": "g8.num.squares-roots", "title": "Perfect Squares and Their Fingerprints", "description": "Generate squares 1–30 and read off their properties: possible unit digits, behaviour of trailing zeros, and sums of odd numbers.", "outcomes": ["Can list unit digits a perfect square can end in", "Can reject candidates like 4058 as perfect squares by inspection"], "prereqs": ["g7.num.exponents-intro", "g5.num.factors-multiples"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.num.squares-roots.square-decimals-fractions", "parent": "g8.num.squares-roots", "title": "Squaring Fractions and Decimals", "description": "Square rationals like 3/4 and 0.4, tracking why squaring a number between 0 and 1 makes it SMALLER and where the decimal point lands.", "outcomes": ["Can square any fraction or decimal correctly", "Can explain why (0.4)² < 0.4"], "prereqs": ["g8.num.squares-roots.perfect-square-patterns", "g7.num.fractions-decimals-ops"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g8.num.squares-roots.sqrt-prime-factorisation", "parent": "g8.num.squares-roots", "title": "Square Roots by Prime Factorisation", "description": "Find square roots of perfect squares by pairing prime factors, and find the smallest multiplier/divisor that makes a number a perfect square.", "outcomes": ["Can compute √ of a perfect square via factor pairs", "Can find the least number to multiply by to reach a perfect square"], "prereqs": ["g8.num.squares-roots.perfect-square-patterns", "g6.num.playing-with-numbers"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g8.num.squares-roots.sqrt-long-division", "parent": "g8.num.squares-roots", "title": "Square Roots by Long Division", "description": "Use the long-division algorithm for square roots of large perfect squares and decimals.", "outcomes": ["Can extract √ of 4-5 digit numbers by long division", "Can extend the method past the decimal point"], "prereqs": ["g8.num.squares-roots.sqrt-prime-factorisation", "g4.num.division-long-intro"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g8.num.squares-roots.estimate-roots", "parent": "g8.num.squares-roots", "title": "Estimating Square Roots", "description": "Trap non-perfect squares between consecutive perfect squares to estimate roots like √60 ≈ 7.7.", "outcomes": ["Can state between which two integers √n lies", "Can give a one-decimal estimate of a square root"], "prereqs": ["g8.num.squares-roots.sqrt-long-division"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g8.num.squares-roots.root-of-sum-trap", "parent": "g8.num.squares-roots", "title": "√ Does Not Split Over + and −", "description": "Confront the error √(a+b) = √a + √b with numeric ambushes like √(9+16), and establish that roots split only over × and ÷.", "outcomes": ["Can evaluate √(a+b) correctly by adding first", "Can state for which operations √ distributes"], "prereqs": ["g8.num.squares-roots.sqrt-prime-factorisation"], "est_minutes": 15, "difficulty": 3, "question": true}]}, {"id": "g8.num.cubes-roots", "title": "Cubes and Cube Roots", "grade": 8, "strand": "num", "description": "Cubing a number multiplies it by itself three times — the volume of a cube of that side. You will recognise perfect cubes, use prime factorisation (triples of factors) to find cube roots, and exploit unit-digit patterns for quick mental roots. Unlike squares, cubes of negatives stay negative.", "prereqs": ["g8.num.squares-roots"], "outcomes": ["Can compute cubes and recognise perfect cubes up to 1000 (and 12³ = 1728)", "Can find cube roots by grouping prime factors into triples", "Can use unit-digit patterns to find cube roots of perfect cubes mentally", "Can explain why cubes of negative numbers are negative, unlike squares"], "difficulty": 3, "est_minutes": 40, "stub": false, "micros": [{"id": "g8.num.cubes-roots.cubes-patterns", "parent": "g8.num.cubes-roots", "title": "Cubes and Their Patterns", "description": "Build cubes 1–20 as n × n × n (not n × 3), and explore unit-digit patterns — cubes, unlike squares, can end in ANY digit.", "outcomes": ["Can compute cubes of numbers up to 20", "Can state the unit digit of a cube from the unit digit of the number"], "prereqs": ["g8.num.squares-roots.perfect-square-patterns", "g7.num.exponents-intro"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.num.cubes-roots.cubes-of-negatives", "parent": "g8.num.cubes-roots", "title": "Cubes of Negative Numbers", "description": "Establish that an odd number of negative factors leaves the product negative: cubing preserves sign.", "outcomes": ["Can cube negative integers and rationals correctly", "Can explain the sign via counting negative factors"], "prereqs": ["g8.num.cubes-roots.cubes-patterns", "g7.num.integers-ops"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g8.num.cubes-roots.cube-root-factorisation", "parent": "g8.num.cubes-roots", "title": "Cube Roots by Prime Factorisation", "description": "Find cube roots by grouping prime factors in TRIPLES, and find the smallest multiplier that turns a number into a perfect cube.", "outcomes": ["Can compute ∛ of a perfect cube via factor triples", "Can find the least factor needed to complete a perfect cube"], "prereqs": ["g8.num.cubes-roots.cubes-patterns", "g8.num.squares-roots.sqrt-prime-factorisation"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.num.cubes-roots.estimate-cube-roots", "parent": "g8.num.cubes-roots", "title": "Estimating Cube Roots of Perfect Cubes", "description": "Use the unit digit and thousands-grouping trick to read off cube roots of perfect cubes up to six digits.", "outcomes": ["Can find ∛ of a 4-6 digit perfect cube by the two-group estimation method"], "prereqs": ["g8.num.cubes-roots.cube-root-factorisation"], "est_minutes": 15, "difficulty": 2, "question": false}]}, {"id": "g8.num.comparing-quantities", "title": "Comparing Quantities: Discounts, Compound Interest", "grade": 8, "strand": "num", "description": "Real prices move in chains: marked price → discount → sales tax/GST → final bill, and savings grow by compound interest, where each year's interest itself earns interest. You will compute successive percentage changes correctly by multiplying growth factors — the single most useful trick in consumer maths.", "prereqs": ["g7.num.comparing-quantities"], "outcomes": ["Can compute discount, sale price, and tax/GST on a purchase", "Can handle successive percentage changes by multiplying factors (×0.9, ×1.18, …)", "Can compute compound interest annually (and half-yearly) using A = P(1 + r/100)ⁿ", "Can explain why compound interest exceeds simple interest after the first period"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": [{"id": "g8.num.comparing-quantities.percent-revision", "parent": "g8.num.comparing-quantities", "title": "Warm-up: Ratios and Percentage Change", "description": "Revise converting between fractions, ratios and per cents, and computing increase/decrease as a percentage of the ORIGINAL value.", "outcomes": ["Can find x% of a quantity and a percentage change", "Can identify the base quantity a per cent acts on"], "prereqs": ["g7.num.comparing-quantities"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g8.num.comparing-quantities.discount-marked-price", "parent": "g8.num.comparing-quantities", "title": "Discount and Marked Price", "description": "Work the trio marked price, discount, sale price — the discount per cent always bites the MARKED price.", "outcomes": ["Can compute sale price from MP and discount %", "Can recover MP or discount % from the other two"], "prereqs": ["g8.num.comparing-quantities.percent-revision"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.num.comparing-quantities.successive-changes", "parent": "g8.num.comparing-quantities", "title": "Successive Percentage Changes", "description": "Chain two percentage changes multiplicatively and see why 10% off then 20% off is 28% off — never 30% — and why +10% then −10% does not restore the price.", "outcomes": ["Can compute the net effect of two successive % changes", "Can explain why successive per cents don't add"], "prereqs": ["g8.num.comparing-quantities.discount-marked-price"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.num.comparing-quantities.tax-and-vat", "parent": "g8.num.comparing-quantities", "title": "Sales Tax, VAT and GST", "description": "Add tax percentages onto bills and extract the pre-tax price from a tax-inclusive total.", "outcomes": ["Can compute a bill including tax", "Can find the original price given a tax-inclusive amount"], "prereqs": ["g8.num.comparing-quantities.discount-marked-price"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g8.num.comparing-quantities.compound-interest", "parent": "g8.num.comparing-quantities", "title": "Compound Interest: Interest on Interest", "description": "Contrast CI with SI year by year on the same principal, then compress the growth into A = P(1 + r/100)ⁿ.", "outcomes": ["Can compute CI for 2-3 years both stepwise and by formula", "Can say exactly where CI and SI diverge and why"], "prereqs": ["g8.num.comparing-quantities.successive-changes", "g7.num.exponents-intro"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.num.comparing-quantities.ci-applications", "parent": "g8.num.comparing-quantities", "title": "CI Applications: Growth and Depreciation", "description": "Apply the compound formula to population growth, bacterial growth and depreciation (negative rate), including half-yearly compounding.", "outcomes": ["Can adapt A = P(1 ± r/100)ⁿ to growth and depreciation contexts", "Can halve the rate and double the periods for half-yearly compounding"], "prereqs": ["g8.num.comparing-quantities.compound-interest"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g8.num.exponents-powers", "title": "Exponents and Powers: Negative Exponents, Scientific Notation", "grade": 8, "strand": "num", "description": "Negative exponents extend the power ladder below 1: 10⁻³ means 1/10³, letting scientific notation describe the very small (a bacterium's width) as easily as the very large. You will apply all the exponent laws with integer exponents and convert numbers to and from standard form in both directions.", "prereqs": ["g7.num.exponents-intro", "g7.num.rational-numbers-intro"], "outcomes": ["Can evaluate powers with negative integer exponents via a⁻ⁿ = 1/aⁿ", "Can apply the laws of exponents across integer exponents, including a⁰ = 1", "Can write very small numbers in standard form k × 10⁻ⁿ and convert back", "Can compare magnitudes expressed in scientific notation"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g8.num.exponents-powers.laws-revision", "parent": "g8.num.exponents-powers", "title": "Warm-up: Laws of Exponents", "description": "Revise aᵐ × aⁿ = aᵐ⁺ⁿ and aᵐ ÷ aⁿ = aᵐ⁻ⁿ with positive exponents — exponents ADD and SUBTRACT, they are never multiplied or divided across the laws.", "outcomes": ["Can apply the product and quotient laws with positive integer exponents"], "prereqs": ["g7.num.exponents-intro"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g8.num.exponents-powers.negative-exponents", "parent": "g8.num.exponents-powers", "title": "What a Negative Exponent Means", "description": "Extend the descending pattern 2³, 2², 2¹, 2⁰, ... to force 2⁻ⁿ = 1/2ⁿ: a negative exponent flips into a reciprocal, it never makes the value negative.", "outcomes": ["Can evaluate powers with negative exponents", "Can explain 2⁻³ = 1/8 via the halving pattern"], "prereqs": ["g8.num.exponents-powers.laws-revision", "g8.num.rational-numbers.identities-inverses"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g8.num.exponents-powers.laws-with-negatives", "parent": "g8.num.exponents-powers", "title": "Exponent Laws with Negative Exponents", "description": "Run all the laws — product, quotient, power of a power, power of a product — with integer (including negative) exponents.", "outcomes": ["Can simplify expressions like (2⁻³ × 2⁷) ÷ 2² fully", "Can combine laws in multi-step simplifications"], "prereqs": ["g8.num.exponents-powers.negative-exponents"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g8.num.exponents-powers.scientific-notation-large", "parent": "g8.num.exponents-powers", "title": "Standard Form for Large Numbers", "description": "Write large numbers like 149,600,000 km as a × 10ⁿ with 1 ≤ a < 10, counting decimal SHIFTS rather than zeros.", "outcomes": ["Can convert large numbers to standard form and back", "Can compare two numbers written in standard form"], "prereqs": ["g8.num.exponents-powers.laws-revision", "g6.num.knowing-numbers"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g8.num.exponents-powers.scientific-notation-small", "parent": "g8.num.exponents-powers", "title": "Standard Form for Small Numbers", "description": "Use negative powers of 10 for very small measurements (0.00052 m = 5.2 × 10⁻⁴ m), pinning down the sign and size of the exponent by counting shifts.", "outcomes": ["Can convert small decimals to standard form with the right negative exponent"], "prereqs": ["g8.num.exponents-powers.scientific-notation-large", "g8.num.exponents-powers.negative-exponents"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g8.num.direct-inverse-proportion", "title": "Direct and Inverse Proportion", "grade": 8, "strand": "num", "description": "Two quantities are in direct proportion when their RATIO stays constant (double one, double the other) and in inverse proportion when their PRODUCT stays constant (double one, halve the other). The crucial skill is deciding which model — if either — fits a situation before computing.", "prereqs": ["g6.num.ratio-proportion", "g7.num.fractions-decimals-ops"], "outcomes": ["Can test whether tabled data shows direct proportion (y/x constant) or inverse proportion (xy constant)", "Can solve direct-proportion problems via the constant ratio or unitary method", "Can solve inverse-proportion problems (workers–days, speed–time) via the constant product", "Can identify situations that are NEITHER kind of proportion (e.g. age vs height)"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g8.num.direct-inverse-proportion.recognise-variation", "parent": "g8.num.direct-inverse-proportion", "title": "Direct or Inverse? Recognising the Relationship", "description": "Sort real situations by asking 'when one doubles, does the other double or halve?' — and spot relationships that are NEITHER.", "outcomes": ["Can classify a situation as direct, inverse, or neither", "Can justify the classification with a doubling test"], "prereqs": ["g6.num.ratio-proportion", "g7.num.comparing-quantities"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.num.direct-inverse-proportion.direct-solve", "parent": "g8.num.direct-inverse-proportion", "title": "Solving Direct Proportion Problems", "description": "Set up x/y = constant (or the unitary method) for direct variation — a multiplicative relationship, not 'add the same amount'.", "outcomes": ["Can solve for the missing value in a direct proportion", "Can verify the answer keeps the ratio constant"], "prereqs": ["g8.num.direct-inverse-proportion.recognise-variation"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.num.direct-inverse-proportion.inverse-solve", "parent": "g8.num.direct-inverse-proportion", "title": "Solving Inverse Proportion Problems", "description": "Use x₁y₁ = x₂y₂ — the PRODUCT stays constant — for inverse variation, resisting both the additive shortcut and the direct-proportion reflex.", "outcomes": ["Can solve for the missing value in an inverse proportion", "Can check the answer by comparing products"], "prereqs": ["g8.num.direct-inverse-proportion.direct-solve"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.num.direct-inverse-proportion.mixed-applications", "parent": "g8.num.direct-inverse-proportion", "title": "Mixed and Multi-step Proportion Problems", "description": "Tackle problems mixing both variation types (speed-time-distance, recipes scaled for more people in less time), choosing the model before computing.", "outcomes": ["Can solve two-step problems involving both direct and inverse variation"], "prereqs": ["g8.num.direct-inverse-proportion.inverse-solve"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g8.num.playing-numbers", "title": "Playing with Numbers: General Form and Divisibility", "grade": 8, "strand": "num", "description": "Writing a two-digit number as 10a + b turns number tricks into algebra: you can PROVE why ab + ba is always divisible by 11, justify the divisibility tests for 3 and 9, and crack letter-for-digit puzzles. This chapter is a first taste of proof through generalisation.", "prereqs": ["g6.num.playing-with-numbers", "g7.alg.expressions"], "outcomes": ["Can express 2- and 3-digit numbers in general form (10a + b, 100a + 10b + c)", "Can prove simple facts like 11 | (ab + ba) and 9 | (abc − cba variants) using the general form", "Can justify the divisibility tests for 2, 3, 5, 9 and 10 from place value", "Can solve letter-digit (cryptarithm) puzzles using digit constraints"], "difficulty": 3, "est_minutes": 40, "stub": false, "micros": [{"id": "g8.num.playing-numbers.general-form", "parent": "g8.num.playing-numbers", "title": "Numbers in General Form", "description": "Write any two- or three-digit numeral algebraically — 'ab' means 10a + b, never a × b — and use it to explain simple number tricks.", "outcomes": ["Can expand a numeral into general form and back", "Can express 'reverse the digits' algebraically"], "prereqs": ["g6.num.playing-with-numbers", "g7.alg.expressions"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.num.playing-numbers.reversed-digit-results", "parent": "g8.num.playing-numbers", "title": "Adding and Subtracting Reversed Numbers", "description": "Prove with general form why (10a+b) + (10b+a) is always divisible by 11, and the difference by 9 — the classic reversal results.", "outcomes": ["Can prove the 11 and 9 divisibility facts for reversed two-digit numbers", "Can extend the argument to three-digit reversals (divisibility by 99)"], "prereqs": ["g8.num.playing-numbers.general-form"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g8.num.playing-numbers.digit-puzzles", "parent": "g8.num.playing-numbers", "title": "Letters for Digits: Cryptarithm Puzzles", "description": "Solve addition and multiplication puzzles where letters stand for digits, respecting the rules: one digit per letter, 0-9 only, carries tracked, no leading zeros.", "outcomes": ["Can solve one- and two-carry cryptarithms systematically", "Can state and use the digit constraints explicitly"], "prereqs": ["g8.num.playing-numbers.general-form"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.num.playing-numbers.divisibility-justified", "parent": "g8.num.playing-numbers", "title": "Why the Divisibility Tests Work", "description": "Use general form to justify the tests for 2, 5, 10 (last digit) and 3, 9 (digit sum) — and see why 3's test looks at ALL digits, and why divisible-by-3 does not mean divisible-by-9.", "outcomes": ["Can apply the tests for 2, 3, 5, 9, 10 correctly", "Can explain via 10 = 9 + 1 why digit sums govern 3 and 9"], "prereqs": ["g8.num.playing-numbers.reversed-digit-results"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g8.alg.linear-equations-1var", "title": "Linear Equations in One Variable: Variables on Both Sides", "grade": 8, "strand": "alg", "description": "Equations now carry the variable on BOTH sides (2x + 5 = x + 9), and may involve fractions or expressions that need simplifying first. You will reduce them systematically to x = value, and use them to crack age, number, perimeter and money problems.", "prereqs": ["g7.alg.simple-equations", "g8.num.rational-numbers"], "outcomes": ["Can solve linear equations with variables on both sides", "Can clear fractions by multiplying EVERY term by the common denominator", "Can reduce word problems (ages, numbers, money) to linear equations and solve them", "Can verify solutions by substitution and interpret them in context"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g8.alg.linear-equations-1var.transpose-revision", "parent": "g8.alg.linear-equations-1var", "title": "Warm-up: Transposing with Inverse Operations", "description": "Revise solving ax + b = c by moving terms with their operations INVERTED — plus becomes minus, times becomes divide.", "outcomes": ["Can solve one-side linear equations fluently", "Can name the inverse operation used at each step"], "prereqs": ["g7.alg.simple-equations"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g8.alg.linear-equations-1var.variables-both-sides", "parent": "g8.alg.linear-equations-1var", "title": "Variables on Both Sides", "description": "Collect variable terms on one side and constants on the other, changing the SIGN of every term that crosses the equals sign.", "outcomes": ["Can solve equations like 2x + 5 = x + 9", "Can verify a solution by substitution"], "prereqs": ["g8.alg.linear-equations-1var.transpose-revision"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.alg.linear-equations-1var.brackets", "parent": "g8.alg.linear-equations-1var", "title": "Equations with Brackets", "description": "Expand brackets — multiplying EVERY term inside — before collecting, as in 3(x − 2) = 2(x + 1) + 1.", "outcomes": ["Can solve equations with bracketed terms on either side"], "prereqs": ["g8.alg.linear-equations-1var.variables-both-sides", "g7.alg.expressions"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g8.alg.linear-equations-1var.fractions-clear", "parent": "g8.alg.linear-equations-1var", "title": "Clearing Fractions", "description": "Multiply BOTH SIDES — every single term — by the LCM of the denominators to turn fractional equations into integer ones.", "outcomes": ["Can clear denominators correctly and solve", "Can spot the error of multiplying only the fraction term"], "prereqs": ["g8.alg.linear-equations-1var.brackets", "g6.num.playing-with-numbers"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.alg.linear-equations-1var.reduce-to-linear", "parent": "g8.alg.linear-equations-1var", "title": "Equations Reducible to Linear Form", "description": "Solve equations like (x + 1)/(2x + 3) = 3/8 by cross-multiplication, checking the solution keeps denominators nonzero.", "outcomes": ["Can cross-multiply and solve rational equations that reduce to linear", "Can reject values that zero a denominator"], "prereqs": ["g8.alg.linear-equations-1var.fractions-clear"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g8.alg.linear-equations-1var.word-problems", "parent": "g8.alg.linear-equations-1var", "title": "Word Problems: Set Up, Solve, ANSWER", "description": "Translate age, number, perimeter and money stories into equations — then finish: solve fully and answer the question actually asked.", "outcomes": ["Can model a word problem as a linear equation", "Can present the final answer in the problem's terms, checked against the story"], "prereqs": ["g8.alg.linear-equations-1var.reduce-to-linear"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g8.alg.expressions-identities", "title": "Algebraic Expressions and Identities", "grade": 8, "strand": "alg", "description": "You will multiply monomials, binomials and polynomials, and meet the standard identities: (a+b)² = a²+2ab+b², (a−b)² = a²−2ab+b², and (a+b)(a−b) = a²−b². Identities are equalities true for ALL values — and they turn ugly arithmetic like 103² into two-second mental maths.", "prereqs": ["g7.alg.expressions", "g7.num.exponents-intro"], "outcomes": ["Can multiply monomials and binomials, applying exponent rules to variables", "Can expand using the three standard identities and recognise when they apply", "Can distinguish an identity (true for all values) from an equation (true for some)", "Can use identities for fast numeric computation (103², 98², 52 × 48)"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g8.alg.expressions-identities.multiply-monomials", "parent": "g8.alg.expressions-identities", "title": "Multiplying Monomials", "description": "Multiply coefficients and ADD exponents of like bases: 3x × 4x = 12x², handling several variables at once.", "outcomes": ["Can multiply two or three monomials correctly", "Can track coefficients and exponents separately"], "prereqs": ["g7.alg.expressions", "g7.num.exponents-intro"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g8.alg.expressions-identities.multiply-binomials", "parent": "g8.alg.expressions-identities", "title": "Multiplying Binomials: Every Term Meets Every Term", "description": "Expand (x + 2)(x + 3) by distributing each term of the first bracket over ALL of the second — four products, then collect.", "outcomes": ["Can expand a binomial × binomial fully", "Can verify an expansion numerically with a test value"], "prereqs": ["g8.alg.expressions-identities.multiply-monomials"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.alg.expressions-identities.identity-a-plus-b-squared", "parent": "g8.alg.expressions-identities", "title": "The Identity (a + b)² = a² + 2ab + b²", "description": "Derive the square-of-a-sum identity by multiplication and by area picture — the middle term 2ab is the two rectangles a term-by-term squaring forgets.", "outcomes": ["Can expand (a + b)² for numeric and algebraic a, b", "Can point to 2ab in the area model"], "prereqs": ["g8.alg.expressions-identities.multiply-binomials"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g8.alg.expressions-identities.identity-a-minus-b-squared", "parent": "g8.alg.expressions-identities", "title": "The Identity (a − b)² = a² − 2ab + b²", "description": "Adapt the sum identity to differences, nailing the signs: middle term negative, last term still POSITIVE.", "outcomes": ["Can expand (a − b)² with correct signs", "Can explain why b² keeps a plus sign"], "prereqs": ["g8.alg.expressions-identities.identity-a-plus-b-squared"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g8.alg.expressions-identities.identity-difference-of-squares", "parent": "g8.alg.expressions-identities", "title": "The Identity (a + b)(a − b) = a² − b²", "description": "See the cross terms cancel in (a + b)(a − b), leaving a difference of squares — and distinguish it firmly from (a − b)².", "outcomes": ["Can expand (a + b)(a − b) instantly", "Can say which of a² − b² and (a − b)² goes with which expression"], "prereqs": ["g8.alg.expressions-identities.identity-a-minus-b-squared"], "est_minutes": 15, "difficulty": 3, "question": false}, {"id": "g8.alg.expressions-identities.apply-identities-mental-math", "parent": "g8.alg.expressions-identities", "title": "Identities as Mental-Math Weapons", "description": "Compute 103², 98², 51 × 49 and similar in the head by choosing the right identity around a round number.", "outcomes": ["Can pick and apply the right identity for a numeric shortcut", "Can compute products like 51 × 49 mentally"], "prereqs": ["g8.alg.expressions-identities.identity-difference-of-squares"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g8.alg.factorisation", "title": "Factorisation of Algebraic Expressions", "grade": 8, "strand": "alg", "description": "Factorisation reverses expansion: rewriting an expression as a product of factors. You will take out common factors, regroup, apply the identities backwards (a² − b² = (a+b)(a−b)), split the middle term of x² + bx + c, and divide expressions cleanly — with a spotlight on the cancellation errors everyone must unlearn.", "prereqs": ["g8.alg.expressions-identities", "g6.num.playing-with-numbers"], "outcomes": ["Can factor out the greatest common monomial factor completely", "Can factorise using identities, especially the difference of squares", "Can factorise trinomials x² + bx + c by splitting the middle term", "Can divide a polynomial by a monomial correctly, term by term"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": [{"id": "g8.alg.factorisation.common-factors", "parent": "g8.alg.factorisation", "title": "Taking Out Common Factors", "description": "Factor the HCF out of every term — 6x + 9 = 3(2x + 3) — and check by expanding back.", "outcomes": ["Can factor out the greatest common monomial factor", "Can verify a factorisation by re-expanding"], "prereqs": ["g8.alg.expressions-identities.multiply-monomials", "g6.num.playing-with-numbers"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.alg.factorisation.regrouping", "parent": "g8.alg.factorisation", "title": "Factorisation by Regrouping", "description": "Group four-term expressions like ax + bx + ay + by into pairs sharing a factor, then pull out the common bracket.", "outcomes": ["Can factor four-term expressions by grouping", "Can re-group when the first pairing fails"], "prereqs": ["g8.alg.factorisation.common-factors"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g8.alg.factorisation.factor-identities", "parent": "g8.alg.factorisation", "title": "Factoring with the Identities", "description": "Run the three identities backwards: spot a² + 2ab + b², a² − 2ab + b², and especially a² − b² = (a+b)(a−b) — which is NOT (a − b)².", "outcomes": ["Can recognise and factor perfect-square trinomials", "Can factor any difference of squares"], "prereqs": ["g8.alg.factorisation.common-factors", "g8.alg.expressions-identities.identity-difference-of-squares"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.alg.factorisation.split-middle-term", "parent": "g8.alg.factorisation", "title": "Factorising x² + bx + c by Splitting the Middle Term", "description": "Hunt for two numbers whose SUM is the middle coefficient b and whose PRODUCT is the constant c, then split and group.", "outcomes": ["Can factor monic quadratics by splitting the middle term", "Can state which target is the sum and which the product"], "prereqs": ["g8.alg.factorisation.regrouping", "g8.alg.factorisation.factor-identities"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g8.alg.factorisation.divide-expressions", "parent": "g8.alg.factorisation", "title": "Dividing Algebraic Expressions", "description": "Divide polynomials by monomials by factoring first — the divisor must cancel from EVERY term, or from a common FACTOR, never from a single term of a sum.", "outcomes": ["Can divide a polynomial by a monomial via factorisation", "Can spot and refute illegal single-term cancellation"], "prereqs": ["g8.alg.factorisation.split-middle-term"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g8.alg.graphs-intro", "title": "Introduction to Graphs: Coordinates and Linear Graphs", "grade": 8, "strand": "alg", "description": "The coordinate plane turns pairs of numbers into points and relationships into pictures. You will plot points, read line graphs, and draw the graphs of simple linear relationships like y = 2x — seeing for the first time that an equation IS a line. This bridge between algebra and geometry carries all of higher mathematics.", "prereqs": ["g6.num.integers-intro", "g8.alg.linear-equations-1var"], "outcomes": ["Can plot and read points (x, y), respecting the order of coordinates", "Can locate points on the axes and state where axis points belong", "Can check whether a point lies on the graph of a simple equation like y = 2x", "Can interpret real line graphs (distance–time, cost–quantity) including rates as steepness"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g8.alg.graphs-intro.plot-points", "parent": "g8.alg.graphs-intro", "title": "The Coordinate Plane: Plotting Points", "description": "Set up x- and y-axes and plot ordered pairs, establishing that ORDER matters: (3, 5) and (5, 3) are different points.", "outcomes": ["Can plot and read off points in the first quadrant", "Can explain why coordinate order matters"], "prereqs": ["g6.dat.data-handling", "g6.geo.basic-ideas"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.alg.graphs-intro.points-on-axes", "parent": "g8.alg.graphs-intro", "title": "Points on the Axes and the Origin", "description": "Pin down where (0, y) and (x, 0) live: a zero x-coordinate means NO horizontal movement — the point sits on the y-axis.", "outcomes": ["Can place points with a zero coordinate correctly", "Can characterise the axes as 'y = 0' and 'x = 0' point sets"], "prereqs": ["g8.alg.graphs-intro.plot-points"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g8.alg.graphs-intro.read-graphs", "parent": "g8.alg.graphs-intro", "title": "Reading Line Graphs and Scales", "description": "Extract information from time-series line graphs, always reading axis labels, units and scales before comparing anything.", "outcomes": ["Can read values and trends off a line graph", "Can explain how a changed scale changes apparent steepness"], "prereqs": ["g8.alg.graphs-intro.plot-points", "g6.dat.data-handling"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g8.alg.graphs-intro.draw-linear-graphs", "parent": "g8.alg.graphs-intro", "title": "Drawing Graphs of Linear Relationships", "description": "Tabulate values for relationships like y = 2x + 1 or simple-interest-vs-time, plot, and draw the line through them.", "outcomes": ["Can build a table and draw a straight-line graph", "Can use the graph to read off unplotted values"], "prereqs": ["g8.alg.graphs-intro.points-on-axes", "g8.alg.graphs-intro.read-graphs", "g8.alg.linear-equations-1var.variables-both-sides"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g8.alg.graphs-intro.between-the-points", "parent": "g8.alg.graphs-intro", "title": "Every Point on the Line Counts", "description": "Establish that a linear graph is a continuum: any point on the line — plotted or not — satisfies the relationship, and coordinates can be read at ANY x.", "outcomes": ["Can decide whether a given point lies on a drawn line", "Can interpolate values between tabled points"], "prereqs": ["g8.alg.graphs-intro.draw-linear-graphs"], "est_minutes": 15, "difficulty": 3, "question": true}]}, {"id": "g8.geo.quadrilaterals", "title": "Understanding Quadrilaterals: Polygon Angle Sums and Parallelograms", "grade": 8, "strand": "geo", "description": "The interior angles of an n-sided polygon sum to (n−2)×180°, while exterior angles always total 360°. You will use these facts, then dive into the parallelogram family — opposite sides and angles equal, diagonals bisecting each other — and see how rectangle, rhombus and square refine it step by step.", "prereqs": ["g7.geo.triangle-properties", "g6.geo.elementary-shapes"], "outcomes": ["Can compute interior angle sums of polygons via (n−2) × 180° and use the 360° exterior-angle fact", "Can use parallelogram properties (opposite sides/angles equal, adjacent angles supplementary, diagonals bisect each other) to find unknowns", "Can state which extra properties rectangles, rhombuses and squares add", "Can place the special quadrilaterals in a correct hierarchy"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g8.geo.quadrilaterals.polygon-classification", "parent": "g8.geo.quadrilaterals", "title": "Polygons: Convex, Concave, Regular", "description": "Classify polygons by number of sides, convexity, and regularity, revising the vocabulary of diagonals and interior angles.", "outcomes": ["Can classify a polygon as convex/concave and regular/irregular", "Can count the diagonals of small polygons"], "prereqs": ["g6.geo.elementary-shapes", "g7.geo.lines-angles"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g8.geo.quadrilaterals.angle-sum-polygons", "parent": "g8.geo.quadrilaterals", "title": "Interior Angle Sums of Polygons", "description": "Triangulate an n-gon into (n − 2) triangles to get the angle-sum formula — 360° belongs to quadrilaterals ONLY.", "outcomes": ["Can compute the interior angle sum of any polygon", "Can find one interior angle of a regular n-gon"], "prereqs": ["g8.geo.quadrilaterals.polygon-classification", "g7.geo.triangle-properties"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.geo.quadrilaterals.exterior-angles", "parent": "g8.geo.quadrilaterals", "title": "Exterior Angles Always Total 360°", "description": "Walk around any convex polygon to see the exterior angles complete one full turn — a constant 360° regardless of n.", "outcomes": ["Can use the exterior-angle sum to find unknown angles", "Can find the number of sides of a regular polygon from one exterior angle"], "prereqs": ["g8.geo.quadrilaterals.angle-sum-polygons"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g8.geo.quadrilaterals.parallelogram-angles", "parent": "g8.geo.quadrilaterals", "title": "Parallelogram Properties: Sides and Angles", "description": "Derive from parallel sides that opposite sides and opposite angles are EQUAL while adjacent angles are SUPPLEMENTARY.", "outcomes": ["Can find all angles of a parallelogram from one", "Can justify each property via parallel lines and transversals"], "prereqs": ["g8.geo.quadrilaterals.polygon-classification", "g7.geo.lines-angles"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.geo.quadrilaterals.parallelogram-diagonals", "parent": "g8.geo.quadrilaterals", "title": "Diagonals of a Parallelogram", "description": "Show the diagonals BISECT each other — but are equal only in rectangles, and perpendicular only in rhombuses.", "outcomes": ["Can use diagonal bisection to find lengths", "Can state which special quadrilaterals have equal or perpendicular diagonals"], "prereqs": ["g8.geo.quadrilaterals.parallelogram-angles"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g8.geo.quadrilaterals.quad-hierarchy", "parent": "g8.geo.quadrilaterals", "title": "The Quadrilateral Family Tree", "description": "Order trapezium, kite, parallelogram, rectangle, rhombus, square by inclusion: every square IS a rhombus IS a parallelogram — the arrows never reverse.", "outcomes": ["Can decide the truth of 'every X is a Y' claims for special quadrilaterals", "Can draw the inclusion diagram from memory"], "prereqs": ["g8.geo.quadrilaterals.parallelogram-diagonals"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g8.geo.practical-geometry-quads", "title": "Practical Geometry: Constructing Quadrilaterals", "grade": 8, "strand": "geo", "description": "A quadrilateral needs five independent measurements to be pinned down — four sides alone leave it floppy. You will construct quadrilaterals from five given parts (e.g. four sides and a diagonal) by splitting them into two triangles, reusing everything you know about triangle construction.", "prereqs": ["g8.geo.quadrilaterals", "g7.geo.practical-geometry"], "outcomes": ["Can explain why 5 measurements (suitably chosen) determine a quadrilateral while 4 do not", "Can construct quadrilaterals given: 4 sides + 1 diagonal; 3 sides + 2 diagonals; 2 adjacent sides + 3 angles; 3 sides + 2 included angles", "Can decompose the construction into two triangle constructions sharing a diagonal", "Can detect impossible data (triangle inequality failing inside a component triangle)"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g8.geo.practical-geometry-quads.why-five-parts", "parent": "g8.geo.practical-geometry-quads", "title": "Why Five Measurements?", "description": "Discover with cut-out strips that four given sides leave a quadrilateral FLOPPY — unlike a triangle — and that five well-chosen parts pin it down.", "outcomes": ["Can demonstrate that four sides do not fix a quadrilateral", "Can list the five standard measurement combinations that do"], "prereqs": ["g7.geo.congruence", "g8.geo.quadrilaterals.polygon-classification"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.geo.practical-geometry-quads.construct-4sides-diagonal", "parent": "g8.geo.practical-geometry-quads", "title": "Constructing with Four Sides and a Diagonal", "description": "Split the target into two triangles along the given diagonal, build each with compass arcs, and check feasibility with the triangle inequality first.", "outcomes": ["Can construct a quadrilateral from 4 sides + 1 diagonal", "Can reject infeasible data before drawing"], "prereqs": ["g8.geo.practical-geometry-quads.why-five-parts", "g7.geo.practical-geometry"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.geo.practical-geometry-quads.construct-diagonals", "parent": "g8.geo.practical-geometry-quads", "title": "Constructing with Two Diagonals and Three Sides", "description": "Locate vertices as intersections of compass arcs when both diagonals and three sides are given.", "outcomes": ["Can construct a quadrilateral from 2 diagonals + 3 sides", "Can identify which triangle to draw first"], "prereqs": ["g8.geo.practical-geometry-quads.construct-4sides-diagonal"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g8.geo.practical-geometry-quads.construct-angles", "parent": "g8.geo.practical-geometry-quads", "title": "Constructing with Sides and Angles", "description": "Construct quadrilaterals from two adjacent sides + three angles, or three sides + two included angles, using protractor-and-ruler sequences.", "outcomes": ["Can carry out both angle-based construction recipes", "Can check the given angles are consistent (sum 360°)"], "prereqs": ["g8.geo.practical-geometry-quads.construct-diagonals", "g8.geo.quadrilaterals.angle-sum-polygons"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g8.geo.practical-geometry-quads.construct-special", "parent": "g8.geo.practical-geometry-quads", "title": "Special Cases Need Fewer Measurements", "description": "Exploit known properties: a square from one side, a rhombus from its diagonals — properties substitute for measurements.", "outcomes": ["Can construct squares, rectangles and rhombuses from reduced data", "Can say which property replaces which measurement"], "prereqs": ["g8.geo.practical-geometry-quads.construct-angles", "g8.geo.quadrilaterals.parallelogram-diagonals"], "est_minutes": 20, "difficulty": 3, "question": false}]}, {"id": "g8.geo.visualising-solids", "title": "Visualising Solid Shapes: Views and Euler's Relation", "grade": 8, "strand": "geo", "description": "You will map solids from different viewpoints (top, front, side), read simple maps, and discover Euler's beautiful relation for polyhedra: F + V − E = 2 — faces plus vertices minus edges equals two, for EVERY polyhedron from a cube to a football. It is many students' first universal theorem about 3D space.", "prereqs": ["g7.geo.visualising-solids"], "outcomes": ["Can draw and match top, front and side views of solids and cube arrangements", "Can distinguish polyhedra (flat faces) from non-polyhedra (cylinder, sphere, cone)", "Can verify Euler's relation F + V − E = 2 on prisms and pyramids", "Can use Euler's relation to find a missing count (e.g. faces from V and E)"], "difficulty": 3, "est_minutes": 40, "stub": false, "micros": [{"id": "g8.geo.visualising-solids.views-of-solids", "parent": "g8.geo.visualising-solids", "title": "Front, Side and Top Views", "description": "Draw and match the three standard views of everyday solids and cube stacks — the top view of a cylinder is a CIRCLE.", "outcomes": ["Can draw front/side/top views of a given solid", "Can identify a solid from its three views"], "prereqs": ["g7.geo.visualising-solids"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.geo.visualising-solids.mapping-space", "parent": "g8.geo.visualising-solids", "title": "Maps, Scale and Location", "description": "Read and draw simple maps with a scale, contrasting a map's proportional layout with a picture's perspective.", "outcomes": ["Can interpret distances on a scaled map", "Can draw a simple scaled map of a familiar space"], "prereqs": ["g8.geo.visualising-solids.views-of-solids", "g6.num.ratio-proportion"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g8.geo.visualising-solids.faces-edges-vertices", "parent": "g8.geo.visualising-solids", "title": "Counting Faces, Edges and Vertices", "description": "Count F, E, V systematically on prisms and pyramids from nets and sketches — flat faces only — including the hidden ones.", "outcomes": ["Can count F, E, V for prisms and pyramids of any base", "Can organise counts from the base polygon (e.g. n-prism: F = n+2)"], "prereqs": ["g8.geo.visualising-solids.views-of-solids", "g5.geo.nets-3d"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g8.geo.visualising-solids.euler-relation", "parent": "g8.geo.visualising-solids", "title": "Euler's Relation: F + V − E = 2", "description": "Verify F + V − E = 2 across polyhedra, use it to find a missing count, and mark its boundary: polyhedra only — no cylinders, cones or spheres.", "outcomes": ["Can apply F + V − E = 2 to find an unknown count", "Can state why the relation excludes curved solids"], "prereqs": ["g8.geo.visualising-solids.faces-edges-vertices"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g8.mea.mensuration", "title": "Mensuration: Trapezium, Polygon Areas; Surface Area and Volume", "grade": 8, "strand": "mea", "description": "You will find areas of trapeziums and general quadrilaterals via triangles, then step into 3D: surface areas and volumes of cuboids and cylinders. Keeping 'how much to paint' (surface area) separate from 'how much it holds' (volume) — and their different units — is the chapter's central discipline.", "prereqs": ["g7.mea.perimeter-area", "g5.mea.volume-intuition"], "outcomes": ["Can compute the area of a trapezium as ½(a + b)h and of polygons by triangulation", "Can compute lateral/total surface area of cuboids, cubes and cylinders", "Can compute volumes of cuboids, cubes and cylinders", "Can choose between surface area and volume from context, with correct units (cm² vs cm³)", "Can reason about scaling: doubling an edge multiplies volume by 8"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": [{"id": "g8.mea.mensuration.area-trapezium", "parent": "g8.mea.mensuration", "title": "Area of a Trapezium", "description": "Derive A = ½(a + b)h by splitting or doubling into a parallelogram: average the parallel sides FIRST, then multiply by the height.", "outcomes": ["Can compute trapezium areas from parallel sides and height", "Can recover a missing side or height from the area"], "prereqs": ["g7.mea.perimeter-area"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.mea.mensuration.area-general-quad", "parent": "g8.mea.mensuration", "title": "Areas of General Quadrilaterals and Polygons", "description": "Split any quadrilateral or polygon into triangles/trapeziums using diagonals and perpendicular offsets, then add the pieces.", "outcomes": ["Can compute the area of a quadrilateral as ½ d(h₁ + h₂)", "Can decompose a field-book style polygon and total its parts"], "prereqs": ["g8.mea.mensuration.area-trapezium"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g8.mea.mensuration.surface-area-cube-cuboid", "parent": "g8.mea.mensuration", "title": "Surface Area of Cubes and Cuboids", "description": "Unfold cuboids into nets to build TSA = 2(lb + bh + hl) — surface area answers 'how much covering?', a square-unit question.", "outcomes": ["Can compute total and lateral surface area of cuboids", "Can choose surface area (not volume) for covering/painting contexts"], "prereqs": ["g8.mea.mensuration.area-general-quad", "g5.geo.nets-3d"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.mea.mensuration.cylinder-surface", "parent": "g8.mea.mensuration", "title": "Surface Area of a Cylinder", "description": "Unroll the curved surface into a rectangle of width 2πr to get CSA = 2πrh and TSA = 2πr(r + h).", "outcomes": ["Can compute CSA and TSA of a cylinder", "Can explain the 2πr × h rectangle behind the formula"], "prereqs": ["g8.mea.mensuration.surface-area-cube-cuboid", "g7.mea.perimeter-area"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.mea.mensuration.volume-solids", "parent": "g8.mea.mensuration", "title": "Volume of Cubes, Cuboids and Cylinders", "description": "Build volume as layers of unit cubes — base area × height — for cuboids and cylinders, and keep the units cubic.", "outcomes": ["Can compute volumes of cuboids and cylinders", "Can select volume (not surface area) for filling/capacity contexts"], "prereqs": ["g8.mea.mensuration.cylinder-surface", "g5.mea.volume-intuition"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g8.mea.mensuration.units-and-scaling", "parent": "g8.mea.mensuration", "title": "Capacity Units and How Measures Scale", "description": "Relate cm³, m³, mL and L, and confront non-linear scaling: doubling every edge quadruples surface area and multiplies volume by EIGHT.", "outcomes": ["Can convert between volume and capacity units", "Can state the effect of scaling lengths by k on area (k²) and volume (k³)"], "prereqs": ["g8.mea.mensuration.volume-solids"], "est_minutes": 20, "difficulty": 4, "question": true}]}, {"id": "g8.dat.data-handling", "title": "Data Handling: Histograms, Pie Charts, Probability Intro", "grade": 8, "strand": "dat", "description": "You will group data into class intervals and draw histograms (bars touching — the scale is continuous), build and read pie charts where slices are proportional shares of 360°, and compute probabilities of equally likely outcomes — learning why a coin has no memory.", "prereqs": ["g7.dat.data-handling-averages"], "outcomes": ["Can group raw data into class intervals and draw/read a histogram", "Can explain why histogram bars touch while bar-graph bars do not", "Can convert data shares into pie-chart angles (fraction × 360°) and read pie charts", "Can compute probabilities as favourable/total for equally likely outcomes, and recognise independence of successive trials"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g8.dat.data-handling.grouping-data", "parent": "g8.dat.data-handling", "title": "Grouping Data into Class Intervals", "description": "Organise raw data into frequency tables with equal class intervals, fixing the lower-inclusive convention for boundary values.", "outcomes": ["Can build a grouped frequency table from raw data", "Can place a boundary value in the correct class"], "prereqs": ["g7.dat.data-handling-averages"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g8.dat.data-handling.histograms", "parent": "g8.dat.data-handling", "title": "Histograms for Grouped Data", "description": "Draw and read histograms — bars on a CONTINUOUS numerical axis, touching because each class hands over to the next, unlike category bar graphs.", "outcomes": ["Can draw a histogram from a grouped frequency table", "Can articulate the histogram/bar-graph distinction"], "prereqs": ["g8.dat.data-handling.grouping-data", "g6.dat.data-handling"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g8.dat.data-handling.pie-charts", "parent": "g8.dat.data-handling", "title": "Pie Charts: From Shares to Angles", "description": "Convert each category's FRACTION of the whole into a central angle — fraction × 360° — since the circle's 360° represents 100%.", "outcomes": ["Can compute central angles from fractions or percentages", "Can read shares back off a pie chart"], "prereqs": ["g8.dat.data-handling.grouping-data", "g6.num.ratio-proportion"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g8.dat.data-handling.chance-randomness", "parent": "g8.dat.data-handling", "title": "Chance, Randomness and Independent Trials", "description": "Explore random experiments and equally likely outcomes, and confront the gambler's fallacy: a fair coin has no memory.", "outcomes": ["Can list equally likely outcomes of coin/die/spinner experiments", "Can explain why past outcomes don't shift the next trial's chances"], "prereqs": ["g8.dat.data-handling.grouping-data"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g8.dat.data-handling.probability-as-fraction", "parent": "g8.dat.data-handling", "title": "Probability = Favourable / Total", "description": "Compute probabilities as favourable outcomes over ALL outcomes — part-to-WHOLE — and locate them on the 0-to-1 scale.", "outcomes": ["Can compute event probabilities for marbles, dice and spinners", "Can distinguish probability (part:whole) from odds (part:part)"], "prereqs": ["g8.dat.data-handling.chance-randomness", "g6.num.fractions-ops"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g9.num.number-systems", "title": "Number Systems: Irrational Numbers, Real Number Line, Rationalisation", "grade": 9, "strand": "num", "description": "Not every number can be written as a fraction: numbers like √2 and π have decimal expansions that never end and never repeat. This node extends the number line to all real numbers, teaches you to spot rational versus irrational numbers from their decimal expansions, to locate irrationals like √2 on the number line, and to simplify expressions with surds by rationalising denominators. It is the foundation for all later algebra, since from now on 'number' means 'real number'.", "prereqs": ["g8.num.rational-numbers", "g8.num.squares-roots", "g8.num.exponents-powers"], "outcomes": ["Can classify a given number as natural, whole, integer, rational or irrational with justification", "Can decide from a decimal expansion (terminating, recurring, non-recurring) whether a number is rational or irrational", "Can represent numbers like √2 and √3 on the number line using right triangles", "Can rationalise denominators of the form 1/(a+b√c) and simplify surd expressions using laws of exponents"], "difficulty": 3, "est_minutes": 80, "stub": false, "micros": [{"id": "g9.num.number-systems.rational-recap-density", "parent": "g9.num.number-systems", "title": "Rational Numbers Recap and Density", "description": "Revise what makes a number rational (p/q form, q ≠ 0) and establish that between any two rationals there are infinitely many more — the number line is already crowded before irrationals arrive.", "outcomes": ["Can write terminating and recurring decimals as p/q", "Can insert several rational numbers between any two given rationals"], "prereqs": ["g8.num.rational-numbers"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.num.number-systems.decimal-expansions", "parent": "g9.num.number-systems", "title": "Decimal Expansions: Terminating, Recurring, Neither", "description": "Sort decimal expansions into three kinds — terminating, non-terminating recurring, and non-terminating non-recurring — and see that only the last kind escapes the rationals.", "outcomes": ["Can classify a decimal expansion as terminating, recurring, or non-recurring", "Can convert a recurring decimal like 0.4747… into p/q form", "Can state which expansion types correspond to rational numbers"], "prereqs": ["g9.num.number-systems.rational-recap-density"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g9.num.number-systems.irrational-numbers", "parent": "g9.num.number-systems", "title": "Irrational Numbers: √2, π and Friends", "description": "Define irrational numbers as reals that cannot be written as p/q, meet the classic examples (√2, √3, π), and learn to tell genuinely irrational roots from disguised integers like √49.", "outcomes": ["Can decide whether a given root such as √8 or √36 is rational or irrational", "Can explain why π ≠ 22/7 even though they are close"], "prereqs": ["g9.num.number-systems.decimal-expansions"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g9.num.number-systems.real-line-representation", "parent": "g9.num.number-systems", "title": "Locating Irrationals on the Number Line", "description": "Every point on the line is a real number: construct √2, √3, √5 exactly with right triangles (the square-root spiral) and zoom in on decimals by successive magnification.", "outcomes": ["Can construct √2 and √3 on the number line using right triangles", "Can locate a number like 2.665 by successive magnification"], "prereqs": ["g9.num.number-systems.irrational-numbers", "g8.num.squares-roots"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g9.num.number-systems.surds-operations", "parent": "g9.num.number-systems", "title": "Operations with Surds and Real Numbers", "description": "Add, subtract, multiply and divide expressions with square roots, discovering which combinations of rationals and irrationals stay irrational — and why √(a+b) is NOT √a + √b.", "outcomes": ["Can simplify expressions like √2 × √8 and (3 + √3)(3 − √3)", "Can give examples where a sum or product of two irrationals is rational", "Can explain why square roots do not distribute over addition"], "prereqs": ["g9.num.number-systems.irrational-numbers", "g8.num.squares-roots"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.num.number-systems.exponent-laws-real", "parent": "g9.num.number-systems", "title": "Laws of Exponents for Real Numbers", "description": "Extend the exponent laws to rational powers: define a^(1/n) as the nth root and a^(m/n) accordingly, then compute expressions like 64^(2/3) and 125^(−1/3).", "outcomes": ["Can evaluate powers with fractional and negative exponents such as 32^(2/5)", "Can simplify products and quotients like 2^(2/3) · 2^(1/3) using the laws"], "prereqs": ["g8.num.exponents-powers", "g9.num.number-systems.surds-operations"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g9.num.number-systems.rationalisation", "parent": "g9.num.number-systems", "title": "Rationalising the Denominator", "description": "Clear roots out of denominators: multiply by √a/√a for single surds, and by the conjugate for two-term denominators like 1/(√5 − 2), using (a − b)(a + b) = a² − b².", "outcomes": ["Can rationalise denominators of the forms 1/√a and 1/(a + √b)", "Can pick the correct conjugate and expand the difference of squares without sign errors"], "prereqs": ["g9.num.number-systems.surds-operations"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g9.alg.polynomials", "title": "Polynomials: Zeroes, Remainder and Factor Theorems, Identities", "grade": 9, "strand": "alg", "description": "A polynomial is an expression built from a variable using only addition, subtraction and whole-number powers — the workhorse of algebra. Here you learn to evaluate polynomials, find their zeroes, use the Remainder and Factor Theorems to divide and factorise without long division, and wield algebraic identities like (a+b)², a³+b³ and (a+b+c)² to compute and factorise at speed. Everything from quadratic equations to calculus stands on this node.", "prereqs": ["g8.alg.expressions-identities", "g8.alg.factorisation", "g8.alg.linear-equations-1var"], "outcomes": ["Can identify polynomials, state their degree, and classify them as linear, quadratic or cubic", "Can evaluate p(x) at a given value and verify whether a given number is a zero of p(x)", "Can apply the Remainder Theorem (remainder of p(x) ÷ (x−a) is p(a)) and the Factor Theorem to factorise cubics", "Can expand and factorise using standard identities including (a±b)², a²−b², (x+a)(x+b), (a+b+c)² and a³±b³"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g9.alg.polynomials.polynomial-degree-types", "parent": "g9.alg.polynomials", "title": "Polynomials: Terms, Coefficients, Degree, Types", "description": "Pin down what is (and is not) a polynomial, read off terms and coefficients, and classify by degree (linear, quadratic, cubic) and by number of terms (monomial, binomial, trinomial).", "outcomes": ["Can decide whether an expression like x + 1/x or √2·x² is a polynomial", "Can state the degree of any polynomial, including constants", "Can classify polynomials as linear/quadratic/cubic and monomial/binomial/trinomial"], "prereqs": ["g8.alg.expressions-identities"], "est_minutes": 20, "difficulty": 1, "question": true}, {"id": "g9.alg.polynomials.value-and-zeroes", "parent": "g9.alg.polynomials", "title": "Value of a Polynomial and Its Zeroes", "description": "Evaluate p(x) at given numbers, define a zero as a value where p(x) = 0, and explore how many zeroes a polynomial can have — including quadratics like x² + 1 with none at all.", "outcomes": ["Can compute p(a) for any polynomial and number a", "Can verify whether a given number is a zero of a polynomial", "Can explain why degree n allows AT MOST n real zeroes, not exactly n"], "prereqs": ["g9.alg.polynomials.polynomial-degree-types"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.alg.polynomials.remainder-theorem", "parent": "g9.alg.polynomials", "title": "The Remainder Theorem", "description": "Divide polynomials by linear factors the long way once, then shortcut: the remainder when p(x) is divided by (x − a) is simply p(a) — watching the sign of a like a hawk.", "outcomes": ["Can find the remainder on division by (x − a) or (x + a) using substitution", "Can state which value to substitute: the zero of the divisor, not its visible sign"], "prereqs": ["g9.alg.polynomials.value-and-zeroes"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.alg.polynomials.factor-theorem", "parent": "g9.alg.polynomials", "title": "The Factor Theorem", "description": "Specialise the remainder theorem: (x − a) is a factor of p(x) exactly when p(a) = 0. Use it to test candidate factors and to hunt zeroes of cubics among divisors of the constant term.", "outcomes": ["Can test whether (x − a) or (x + a) is a factor of a given polynomial", "Can find one linear factor of a cubic by trying divisors of the constant term"], "prereqs": ["g9.alg.polynomials.remainder-theorem"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g9.alg.polynomials.factorise-quadratics-splitting", "parent": "g9.alg.polynomials", "title": "Factorising Quadratics by Splitting the Middle Term", "description": "Factorise ax² + bx + c by finding two numbers with product ac and sum b, splitting the middle term, and grouping — the workhorse method for board-style factorisation.", "outcomes": ["Can factorise quadratics like 6x² + 17x + 5 by splitting the middle term", "Can verify a factorisation by expanding it back"], "prereqs": ["g9.alg.polynomials.factor-theorem", "g8.alg.factorisation"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g9.alg.polynomials.algebraic-identities-recap-extend", "parent": "g9.alg.polynomials", "title": "Identities: Squares of Binomials and Trinomials", "description": "Consolidate (a ± b)², a² − b² and (x + a)(x + b), then extend to (a + b + c)² = a² + b² + c² + 2ab + 2bc + 2ca, using each identity both to expand and to factorise.", "outcomes": ["Can expand squares of binomials and trinomials without dropping cross terms", "Can use identities in reverse to factorise expressions like 4x² + 12xy + 9y²", "Can evaluate products like 103 × 97 mentally via identities"], "prereqs": ["g8.alg.expressions-identities"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g9.alg.polynomials.cubic-identities", "parent": "g9.alg.polynomials", "title": "Cubic Identities", "description": "Master (a ± b)³, the factorisations a³ ± b³, and the star identity a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) with its special case when a + b + c = 0.", "outcomes": ["Can expand (a + b)³ and evaluate cubes like 104³ using it", "Can factorise sums and differences of cubes", "Can apply the a + b + c = 0 shortcut: a³ + b³ + c³ = 3abc"], "prereqs": ["g9.alg.polynomials.algebraic-identities-recap-extend"], "est_minutes": 30, "difficulty": 4, "question": true}]}, {"id": "g9.alg.linear-equations-2var", "title": "Linear Equations in Two Variables", "grade": 9, "strand": "alg", "description": "An equation like 2x + y = 7 does not have one answer — it has infinitely many solutions, each an ordered pair (x, y), and together they draw a straight line in the Cartesian plane. This node connects algebra to geometry: every solution is a point on the line, and every point on the line is a solution. Mastering this picture prepares you for solving pairs of such equations in Class 10 and for functions and graphs beyond.", "prereqs": ["g8.alg.linear-equations-1var", "g8.alg.graphs-intro", "g9.geo.coordinate-geometry"], "outcomes": ["Can write a linear equation in two variables in the standard form ax + by + c = 0 and identify a, b, c", "Can find several solutions of a given equation and verify whether a given ordered pair is a solution", "Can explain why such an equation has infinitely many solutions and why its graph is a straight line", "Can graph equations including the special forms x = k and y = k"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g9.alg.linear-equations-2var.standard-form-two-vars", "parent": "g9.alg.linear-equations-2var", "title": "The Form ax + by + c = 0", "description": "Meet equations with two unknowns: write situations like 'a notebook costs twice a pen' as ax + by + c = 0, and identify a, b, c after rearranging.", "outcomes": ["Can express a two-variable relationship as ax + by + c = 0", "Can read off a, b and c from any rearranged linear equation"], "prereqs": ["g8.alg.linear-equations-1var"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.alg.linear-equations-2var.solutions-ordered-pairs", "parent": "g9.alg.linear-equations-2var", "title": "Solutions as Ordered Pairs — Infinitely Many", "description": "A solution of 2x + y = 7 is a PAIR (x, y), and there are infinitely many of them: generate solutions by choosing x freely, and check candidate pairs by substitution in the given order.", "outcomes": ["Can generate at least four solutions of a given two-variable equation", "Can verify whether an ordered pair solves an equation, respecting the order", "Can explain why the solution set is infinite"], "prereqs": ["g9.alg.linear-equations-2var.standard-form-two-vars"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g9.alg.linear-equations-2var.graph-of-linear-equation", "parent": "g9.alg.linear-equations-2var", "title": "Graphing a Linear Equation", "description": "Plot several solutions of an equation like y = 2x + 1 and see them fall on a straight line — the graph IS the complete solution set, so a point lies on the line exactly when it solves the equation.", "outcomes": ["Can draw the graph of a linear equation from a table of solutions", "Can test whether a point lies on a given line by substitution", "Can read solutions off a graph, e.g. where it crosses the axes"], "prereqs": ["g9.alg.linear-equations-2var.solutions-ordered-pairs", "g8.alg.graphs-intro"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g9.alg.linear-equations-2var.lines-parallel-axes", "parent": "g9.alg.linear-equations-2var", "title": "The Lines x = a and y = b", "description": "Decode the deceptively simple equations x = a (a vertical line) and y = b (a horizontal line) in two variables, contrasting them with their one-variable, single-point meaning.", "outcomes": ["Can graph x = a and y = b correctly in the Cartesian plane", "Can explain why x = 3 is a whole line of points (3, y), not one point"], "prereqs": ["g9.alg.linear-equations-2var.graph-of-linear-equation"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.alg.linear-equations-2var.two-var-word-problems", "parent": "g9.alg.linear-equations-2var", "title": "Modelling with Two-Variable Equations", "description": "Translate real situations — taxi fares, costs of pens and pencils, temperature conversion F = (9/5)C + 32 — into linear equations, graph them, and interpret points on the graph in context.", "outcomes": ["Can set up a linear equation in two variables from a word problem", "Can interpret a specific point on the graph in the problem's real terms"], "prereqs": ["g9.alg.linear-equations-2var.graph-of-linear-equation"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g9.geo.coordinate-geometry", "title": "Coordinate Geometry: The Cartesian Plane", "grade": 9, "strand": "geo", "description": "René Descartes' big idea: describe every point in the plane with a pair of numbers. This node sets up the Cartesian plane — two perpendicular axes, four quadrants, and the (x, y) address system — and teaches you to plot points, read coordinates, and reason about signs, axes and distances from the axes. It is the bridge on which algebra and geometry meet, and every graph you ever draw lives here.", "prereqs": ["g8.alg.graphs-intro", "g6.num.integers-intro"], "outcomes": ["Can name the axes, origin, quadrants, abscissa and ordinate, and plot any point (x, y) accurately", "Can determine the quadrant or axis on which a point lies from the signs of its coordinates", "Can read off perpendicular distances of a point from the axes", "Can explain why (a, b) and (b, a) are different points when a ≠ b"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g9.geo.coordinate-geometry.axes-quadrants-setup", "parent": "g9.geo.coordinate-geometry", "title": "The Cartesian Plane: Axes, Origin, Quadrants", "description": "Set up the plane properly: two perpendicular number lines meeting at the origin, the x-axis and y-axis, and the four quadrants numbered anticlockwise starting from the top right.", "outcomes": ["Can label the axes, origin and quadrants I–IV correctly", "Can explain the anticlockwise numbering of quadrants"], "prereqs": ["g8.alg.graphs-intro"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.geo.coordinate-geometry.plotting-points", "parent": "g9.geo.coordinate-geometry", "title": "Plotting Points: x Along, Then y Up", "description": "Read and plot points (x, y): the first coordinate is ALWAYS the horizontal move, the second the vertical — so (3, 4) and (4, 3) are different addresses.", "outcomes": ["Can plot any point with integer coordinates accurately", "Can state the abscissa and ordinate of a point and demonstrate that (a, b) ≠ (b, a)"], "prereqs": ["g9.geo.coordinate-geometry.axes-quadrants-setup"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.geo.coordinate-geometry.quadrant-signs", "parent": "g9.geo.coordinate-geometry", "title": "Sign Patterns of the Four Quadrants", "description": "Link each quadrant to its sign pair — I (+,+), II (−,+), III (−,−), IV (+,−) — so any point's quadrant can be read straight from its signs, and vice versa.", "outcomes": ["Can name the quadrant of any point from the signs of its coordinates", "Can produce an example point for each quadrant on demand"], "prereqs": ["g9.geo.coordinate-geometry.plotting-points"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g9.geo.coordinate-geometry.points-on-axes", "parent": "g9.geo.coordinate-geometry", "title": "Points on the Axes and the Origin", "description": "Handle the edge cases: points with a zero coordinate sit ON an axis (x = 0 puts you on the y-axis, y = 0 on the x-axis) and belong to no quadrant; (0, 0) is the origin.", "outcomes": ["Can place points like (0, −4) and (5, 0) on the correct axis", "Can explain why axis points belong to no quadrant"], "prereqs": ["g9.geo.coordinate-geometry.plotting-points"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g9.geo.coordinate-geometry.coordinate-applications", "parent": "g9.geo.coordinate-geometry", "title": "Using Coordinates: Shapes and Mirror Images", "description": "Put the plane to work: plot vertices to identify shapes, find missing vertices of rectangles and squares, and reflect points across the axes by flipping the right sign.", "outcomes": ["Can find the fourth vertex of a rectangle from three given vertices", "Can write the mirror image of a point in the x-axis or y-axis"], "prereqs": ["g9.geo.coordinate-geometry.quadrant-signs", "g9.geo.coordinate-geometry.points-on-axes"], "est_minutes": 20, "difficulty": 2, "question": false}]}, {"id": "g9.geo.euclid", "title": "Introduction to Euclid's Geometry", "grade": 9, "strand": "geo", "description": "Around 300 BCE, Euclid organised all known geometry into a single logical structure: start from a handful of self-evident statements (axioms and postulates) and derive everything else by pure reasoning. This node introduces that deductive game — definitions, axioms, postulates, theorems — and the famous fifth postulate whose questioning eventually gave birth to entirely new geometries. It teaches you what 'proof' means, which is the operating system for the rest of school geometry.", "prereqs": ["g6.geo.basic-ideas"], "outcomes": ["Can distinguish between definitions, axioms/postulates (assumed) and theorems (proved)", "Can state and apply Euclid's axioms (e.g. things equal to the same thing are equal to one another) in simple deductions", "Can state Euclid's postulates, including the fifth, and its equivalent version: through a point not on a line there is exactly one parallel line", "Can justify simple statements (e.g. two distinct lines cannot share more than one point) using axioms"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": [{"id": "g9.geo.euclid.undefined-terms-definitions", "parent": "g9.geo.euclid", "title": "Points, Lines, Planes: Definitions and Undefined Terms", "description": "See why every definition chain must bottom out somewhere: point, line and plane are taken as undefined terms, and a line — unlike a segment — extends endlessly in both directions.", "outcomes": ["Can distinguish a line, a line segment and a ray precisely", "Can explain why point, line and plane are left undefined in Euclid's system"], "prereqs": ["g6.geo.basic-ideas"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g9.geo.euclid.axioms-vs-theorems", "parent": "g9.geo.euclid", "title": "Axioms, Postulates and Theorems", "description": "Sort mathematical statements into starting assumptions (axioms for all mathematics, postulates for geometry) and theorems, which must be PROVED from those assumptions.", "outcomes": ["Can state the difference between an axiom and a theorem", "Can classify statements like 'the whole is greater than the part' as axioms", "Can list Euclid's axioms about equality (equals added to equals, etc.)"], "prereqs": ["g9.geo.euclid.undefined-terms-definitions"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.geo.euclid.euclids-five-postulates", "parent": "g9.geo.euclid", "title": "Euclid's Five Postulates", "description": "Meet the five geometric postulates — from 'a straight line may be drawn between any two points' to the famously long-winded fifth — and use the first four in small arguments.", "outcomes": ["Can state all five postulates in their own words", "Can identify which postulate justifies a given elementary step"], "prereqs": ["g9.geo.euclid.axioms-vs-theorems"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g9.geo.euclid.fifth-postulate-parallels", "parent": "g9.geo.euclid", "title": "The Fifth Postulate and Parallel Lines", "description": "Unpack the fifth postulate — when interior angles on one side of a transversal sum to less than two right angles, the lines meet on that side — and see its equivalence to Playfair's axiom about unique parallels.", "outcomes": ["Can state the fifth postulate and Playfair's version and connect the two", "Can explain that the postulate guarantees parallels EXIST when the angle sum is exactly 180°"], "prereqs": ["g9.geo.euclid.euclids-five-postulates"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.geo.euclid.deductive-proof-with-axioms", "parent": "g9.geo.euclid", "title": "First Deductive Proofs from Axioms", "description": "Write tiny two-to-three step proofs citing axioms by name — e.g. given AC = BD with C between A and B-style configurations, prove AB = CD using 'equals subtracted from equals'.", "outcomes": ["Can justify each step of a short proof with a named axiom", "Can prove statements like 'if AC = BD then AB = CD' on a line figure"], "prereqs": ["g9.geo.euclid.axioms-vs-theorems"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g9.geo.lines-angles", "title": "Lines and Angles: Formal Proofs", "grade": 9, "strand": "geo", "description": "You have measured angles before; now you prove things about them. Starting from axioms about linear pairs and vertically opposite angles, this node builds formal arguments about intersecting lines, parallel lines cut by a transversal (corresponding, alternate and co-interior angles), and the angle sum of a triangle. The skill being trained is writing a chain of statements, each justified by a reason — the grammar of all future proofs.", "prereqs": ["g7.geo.lines-angles", "g9.geo.euclid"], "outcomes": ["Can apply the linear pair axiom and prove that vertically opposite angles are equal", "Can identify corresponding, alternate interior and co-interior angle pairs and state their properties for parallel lines", "Can compute unknown angles in figures with parallel lines and transversals, justifying each step", "Can prove and apply the angle sum property of a triangle and the exterior angle theorem"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g9.geo.lines-angles.angle-pairs-recap", "parent": "g9.geo.lines-angles", "title": "Complementary and Supplementary Pairs", "description": "Nail the vocabulary before proving anything: complementary angles sum to 90°, supplementary to 180°, adjacent angles share an arm — with drills to keep 90 and 180 firmly apart.", "outcomes": ["Can find complements and supplements of given angles", "Can identify adjacent angle pairs in a figure"], "prereqs": ["g7.geo.lines-angles"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g9.geo.lines-angles.linear-pair-axiom", "parent": "g9.geo.lines-angles", "title": "The Linear Pair Axiom", "description": "Formalise 'angles on a straight line': if a ray stands on a line, the two adjacent angles sum to 180°, and conversely, if adjacent angles sum to 180° their outer arms form a line.", "outcomes": ["Can apply the linear pair axiom to find unknown angles at a point on a line", "Can use the converse to prove three points are collinear"], "prereqs": ["g9.geo.lines-angles.angle-pairs-recap"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g9.geo.lines-angles.vertically-opposite-proof", "parent": "g9.geo.lines-angles", "title": "Vertically Opposite Angles: The Proof", "description": "Prove — not just observe — that vertically opposite angles are EQUAL, by writing two linear-pair equations that share an angle and subtracting.", "outcomes": ["Can reproduce the proof that vertically opposite angles are equal", "Can compute all four angles at an intersection from any one of them"], "prereqs": ["g9.geo.lines-angles.linear-pair-axiom"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.geo.lines-angles.parallel-lines-transversal", "parent": "g9.geo.lines-angles", "title": "Parallel Lines and a Transversal", "description": "Organise the eight angles a transversal creates: corresponding and alternate pairs are EQUAL, but co-interior (allied) pairs are SUPPLEMENTARY — the one relationship students flatten into 'all equal'.", "outcomes": ["Can name every angle pair (corresponding, alternate, co-interior) in a transversal figure", "Can compute unknown angles using the correct equal-or-supplementary rule for each pair"], "prereqs": ["g9.geo.lines-angles.vertically-opposite-proof", "g7.geo.lines-angles"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.geo.lines-angles.converse-tests-parallelism", "parent": "g9.geo.lines-angles", "title": "Proving Lines Parallel: The Converses", "description": "Run the transversal facts backwards: equal corresponding or alternate angles — or supplementary co-interior angles — PROVE two lines parallel, and lines parallel to the same line are parallel to each other.", "outcomes": ["Can decide from given angle data whether two lines must be parallel", "Can chain parallelism: if l ∥ m and m ∥ n then l ∥ n"], "prereqs": ["g9.geo.lines-angles.parallel-lines-transversal"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g9.geo.lines-angles.triangle-angle-sum-proof", "parent": "g9.geo.lines-angles", "title": "Angle Sum and Exterior Angle: Proved", "description": "Use a line through a vertex parallel to the opposite side to PROVE the angle sum of a triangle is 180°, and derive the exterior angle theorem: exterior angle = sum of the two interior opposite angles.", "outcomes": ["Can reproduce the parallel-line proof of the 180° angle sum", "Can apply the exterior angle theorem in multi-step angle chases"], "prereqs": ["g9.geo.lines-angles.parallel-lines-transversal", "g7.geo.triangle-properties"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g9.geo.triangles", "title": "Triangles: Congruence Proofs and Inequalities", "grade": 9, "strand": "geo", "description": "Two triangles are congruent when one fits exactly on the other — and remarkably, you never need to check all six parts. This node proves and applies the congruence criteria (SAS, ASA, AAS, SSS, RHS), uses them to establish properties like 'angles opposite equal sides are equal', and explores triangle inequalities: bigger sides face bigger angles, and any two sides together must out-length the third. These tools power almost every geometry proof that follows.", "prereqs": ["g7.geo.congruence", "g7.geo.triangle-properties", "g9.geo.lines-angles"], "outcomes": ["Can select and apply the appropriate congruence criterion (SAS, ASA, AAS, SSS, RHS) with correct correspondence of vertices", "Can prove that angles opposite equal sides of a triangle are equal, and use the converse", "Can use the triangle inequality to decide whether three lengths can form a triangle", "Can order the angles of a triangle given its sides (and vice versa) using the side-angle relationship"], "difficulty": 4, "est_minutes": 80, "stub": false, "micros": [{"id": "g9.geo.triangles.congruence-cpct", "parent": "g9.geo.triangles", "title": "Congruence Statements and CPCT", "description": "Read ΔABC ≅ ΔPQR as a letter-by-letter correspondence — A↔P, B↔Q, C↔R — so CPCT hands you exactly which sides and angles match, and reordering the letters changes the claim.", "outcomes": ["Can extract all six equal parts from a congruence statement using the vertex order", "Can explain why ΔABC ≅ ΔPQR and ΔABC ≅ ΔQRP are different claims"], "prereqs": ["g7.geo.congruence"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.geo.triangles.sas-asa-aas", "parent": "g9.geo.triangles", "title": "SAS, ASA and AAS Criteria", "description": "Prove triangles congruent from three well-chosen parts: SAS (the angle INCLUDED between the sides), ASA, and AAS via the angle-sum property — and practise naming the criterion actually used.", "outcomes": ["Can select and justify the correct criterion for a given data set", "Can check that the angle in SAS is genuinely the included angle", "Can write a two-column congruence proof"], "prereqs": ["g9.geo.triangles.congruence-cpct"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g9.geo.triangles.sss-rhs", "parent": "g9.geo.triangles", "title": "SSS and RHS Criteria", "description": "Complete the toolkit: three equal sides force congruence (SSS), and for right triangles, the hypotenuse plus one side suffices (RHS) — the one legitimate two-sides-and-a-non-included-angle case.", "outcomes": ["Can apply SSS and RHS in proofs, stating hypotenuse and right angle explicitly for RHS", "Can explain why RHS works even though the right angle is not included"], "prereqs": ["g9.geo.triangles.sas-asa-aas"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g9.geo.triangles.why-aaa-ssa-fail", "parent": "g9.geo.triangles", "title": "Why AAA and SSA Are Not Criteria", "description": "Build counterexamples: two triangles with identical angles but different sizes (AAA gives similarity, not congruence), and the SSA 'swinging arm' that produces two different triangles from the same data.", "outcomes": ["Can produce a counterexample showing AAA does not force congruence", "Can explain the SSA ambiguity with the swinging-side picture"], "prereqs": ["g9.geo.triangles.sss-rhs"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g9.geo.triangles.isosceles-theorems", "parent": "g9.geo.triangles", "title": "Isosceles Triangle Theorems", "description": "Prove that angles opposite equal sides are equal (and the converse) using a well-chosen congruence, then deploy both directions in angle chases.", "outcomes": ["Can prove the base angles of an isosceles triangle are equal", "Can find all angles of an isosceles triangle from one given angle"], "prereqs": ["g9.geo.triangles.sas-asa-aas"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.geo.triangles.inequalities-side-angle", "parent": "g9.geo.triangles", "title": "Bigger Side, Bigger Opposite Angle", "description": "Prove the ordering theorems: in any triangle the larger side faces the larger angle and vice versa — where 'faces' means OPPOSITE, not sharing a letter.", "outcomes": ["Can rank the angles of a triangle given its three sides (and vice versa)", "Can identify which angle is opposite which side without letter-matching errors"], "prereqs": ["g9.geo.triangles.isosceles-theorems"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.geo.triangles.triangle-inequality", "parent": "g9.geo.triangles", "title": "The Triangle Inequality", "description": "Establish that any two sides of a triangle must together exceed the third, use it to reject impossible triples, and bound the third side between the difference and sum of the other two.", "outcomes": ["Can test whether three lengths can form a triangle", "Can state the allowed range for the third side given two sides"], "prereqs": ["g9.geo.triangles.inequalities-side-angle"], "est_minutes": 20, "difficulty": 2, "question": true}]}, {"id": "g9.geo.quadrilaterals", "title": "Quadrilaterals: Parallelogram Theorems and the Midpoint Theorem", "grade": 9, "strand": "geo", "description": "Parallelograms hide a bundle of always-true facts: opposite sides and angles are equal, diagonals bisect each other — and each fact, remarkably, also works in reverse as a test. This node proves the parallelogram theorems using triangle congruence, learns which conditions guarantee a parallelogram (and which don't), and crowns it with the Midpoint Theorem: the segment joining midpoints of two sides of a triangle is parallel to the third side and half its length.", "prereqs": ["g8.geo.quadrilaterals", "g9.geo.triangles"], "outcomes": ["Can prove and apply properties of a parallelogram: opposite sides equal, opposite angles equal, diagonals bisect each other", "Can decide whether a given condition is sufficient to guarantee that a quadrilateral is a parallelogram", "Can compute unknown angles in parallelograms using co-interior and opposite angle relationships", "Can state, prove and apply the Midpoint Theorem and its converse"], "difficulty": 4, "est_minutes": 70, "stub": false, "micros": [{"id": "g9.geo.quadrilaterals.angle-sum-quadrilateral", "parent": "g9.geo.quadrilaterals", "title": "Angle Sum of a Quadrilateral", "description": "Split any quadrilateral into two triangles along a diagonal to prove its angles sum to 360°, and use the result to find unknown angles, including ratio-style board questions.", "outcomes": ["Can prove the 360° angle sum using a diagonal", "Can find missing quadrilateral angles, including angles given in ratio"], "prereqs": ["g8.geo.quadrilaterals", "g9.geo.lines-angles.triangle-angle-sum-proof"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.geo.quadrilaterals.parallelogram-properties", "parent": "g9.geo.quadrilaterals", "title": "Parallelogram Properties: Sides and Angles", "description": "Prove via a diagonal and ASA that a parallelogram's opposite sides are equal and opposite angles are equal — while adjacent angles are supplementary, not equal.", "outcomes": ["Can prove opposite sides/angles of a parallelogram are equal", "Can compute all four angles of a parallelogram from one angle"], "prereqs": ["g9.geo.quadrilaterals.angle-sum-quadrilateral", "g9.geo.triangles.sas-asa-aas"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g9.geo.quadrilaterals.diagonals-bisect", "parent": "g9.geo.quadrilaterals", "title": "Diagonals of a Parallelogram", "description": "Prove that the diagonals of a parallelogram bisect each other — and sort out which special quadrilaterals add equal diagonals (rectangle), perpendicular diagonals (rhombus), or both (square).", "outcomes": ["Can prove the diagonals of a parallelogram bisect each other", "Can match diagonal properties (equal, perpendicular, bisecting) to the right quadrilaterals"], "prereqs": ["g9.geo.quadrilaterals.parallelogram-properties"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.geo.quadrilaterals.tests-for-parallelogram", "parent": "g9.geo.quadrilaterals", "title": "Tests for a Parallelogram (The Converses)", "description": "Reverse each property into a test: both pairs of opposite sides equal, both pairs of opposite angles equal, diagonals bisecting each other, or ONE pair of opposite sides both equal AND parallel.", "outcomes": ["Can list the four valid tests for a parallelogram", "Can explain with a counterexample why one pair of equal opposite sides alone is not enough"], "prereqs": ["g9.geo.quadrilaterals.diagonals-bisect"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.geo.quadrilaterals.midpoint-theorem", "parent": "g9.geo.quadrilaterals", "title": "The Midpoint Theorem", "description": "Prove that the segment joining the midpoints of two sides of a triangle is parallel to the third side and HALF its length — the ½ being precisely what students drop under exam pressure.", "outcomes": ["Can state and prove the midpoint theorem", "Can compute lengths using the half relationship in triangle figures"], "prereqs": ["g9.geo.quadrilaterals.tests-for-parallelogram"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.geo.quadrilaterals.midpoint-converse-applications", "parent": "g9.geo.quadrilaterals", "title": "Midpoint Converse and the Hidden Parallelogram", "description": "Use the converse (a line through one midpoint parallel to another side bisects the third side) and the classic application: joining the midpoints of any quadrilateral's sides always forms a parallelogram.", "outcomes": ["Can apply the converse of the midpoint theorem in proofs", "Can prove the midpoints of any quadrilateral's sides form a parallelogram"], "prereqs": ["g9.geo.quadrilaterals.midpoint-theorem"], "est_minutes": 25, "difficulty": 4, "question": false}]}, {"id": "g9.geo.circles", "title": "Circles: Chords, Arcs and Cyclic Quadrilaterals", "grade": 9, "strand": "geo", "description": "A circle is perfectly symmetric, and that symmetry generates powerful theorems: the perpendicular from the centre bisects a chord, equal chords sit at equal distances from the centre, the angle an arc subtends at the centre is double the angle at the circumference, angles in the same segment are equal, and opposite angles of a cyclic quadrilateral are supplementary. This node proves these results and uses them to crack angle-chasing problems.", "prereqs": ["g9.geo.triangles", "g9.geo.quadrilaterals", "g6.geo.basic-ideas"], "outcomes": ["Can apply chord properties: perpendicular from the centre bisects a chord, and equal chords are equidistant from the centre", "Can use the theorem 'angle at the centre is twice the angle at the circumference subtended by the same arc'", "Can identify and use 'angles in the same segment are equal' and 'angle in a semicircle is 90°'", "Can apply the cyclic quadrilateral property: opposite angles sum to 180°"], "difficulty": 4, "est_minutes": 80, "stub": false, "micros": [{"id": "g9.geo.circles.circle-vocabulary", "parent": "g9.geo.circles", "title": "Circle Vocabulary: Chords, Arcs, Segments, Sectors", "description": "Fix the language before the theorems: radius, diameter, chord, minor/major arc, segment vs sector, semicircle, and congruent circles — each with a labelled sketch.", "outcomes": ["Can label chord, arc, segment and sector correctly on a figure", "Can distinguish a segment (chord-bounded) from a sector (radius-bounded)"], "prereqs": ["g6.geo.basic-ideas"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.geo.circles.chord-perpendicular-centre", "parent": "g9.geo.circles", "title": "Perpendicular from the Centre to a Chord", "description": "Prove with RHS congruence that the perpendicular from the centre bisects a chord (and its converse) — stressing that perpendicularity is the non-negotiable hypothesis.", "outcomes": ["Can prove the perpendicular from the centre bisects the chord", "Can state why a non-perpendicular line from the centre need not bisect the chord"], "prereqs": ["g9.geo.circles.circle-vocabulary", "g9.geo.triangles.sss-rhs"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g9.geo.circles.chords-distance-centre", "parent": "g9.geo.circles", "title": "Chord Length and Distance from the Centre", "description": "Combine the bisected chord with Pythagoras: radius² = (half-chord)² + distance², so equal chords lie at equal distances from the centre, and longer chords lie closer.", "outcomes": ["Can compute chord length, radius or distance given the other two", "Can prove equal chords are equidistant from the centre", "Can rank chords by length from their distances"], "prereqs": ["g9.geo.circles.chord-perpendicular-centre", "g7.geo.triangle-properties"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g9.geo.circles.angle-centre-circumference", "parent": "g9.geo.circles", "title": "Angle at the Centre Is Twice the Angle at the Circumference", "description": "Prove the central angle theorem — the angle an arc subtends at the centre is double the angle it subtends anywhere on the remaining circle — across all three figure cases.", "outcomes": ["Can state and apply the 2:1 relationship in the correct direction", "Can handle the reflex-centre case for angles in the major segment"], "prereqs": ["g9.geo.circles.chords-distance-centre", "g9.geo.triangles.isosceles-theorems"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g9.geo.circles.angles-same-segment", "parent": "g9.geo.circles", "title": "Angles in the Same Segment", "description": "Derive from the central angle theorem that all angles subtended by a chord in the same segment are equal — and use the converse to prove four points are concyclic.", "outcomes": ["Can find equal angles in circle figures using the same-segment theorem", "Can apply the converse to show points lie on one circle"], "prereqs": ["g9.geo.circles.angle-centre-circumference"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g9.geo.circles.semicircle-right-angle", "parent": "g9.geo.circles", "title": "The Angle in a Semicircle", "description": "Specialise the central angle theorem to a diameter: the 180° centre angle halves to 90°, so every angle in a semicircle is right — with the converse locating circle centres on hypotenuses.", "outcomes": ["Can apply the 90°-in-a-semicircle fact in angle chases", "Can use the converse: a right angle subtending a segment means that segment is a diameter of the circumcircle"], "prereqs": ["g9.geo.circles.angle-centre-circumference"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g9.geo.circles.cyclic-quadrilaterals", "parent": "g9.geo.circles", "title": "Cyclic Quadrilaterals", "description": "Prove that opposite angles of a cyclic quadrilateral are SUPPLEMENTARY (sum 180°, not equal) using the two arcs a diagonal pair of vertices creates, plus the exterior angle corollary and the converse test.", "outcomes": ["Can compute angles of cyclic quadrilaterals using the 180° opposite-angle rule", "Can apply the converse to prove four points are concyclic"], "prereqs": ["g9.geo.circles.angles-same-segment", "g9.geo.quadrilaterals.angle-sum-quadrilateral"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g9.geo.constructions", "title": "Constructions: Bisectors and Triangles", "grade": 9, "strand": "geo", "description": "With only an ungraduated ruler and a compass — no protractor — you can bisect any angle, erect perpendicular bisectors, build 60°, 30°, 90° and 45° exactly, and construct triangles from indirect data such as base, base angle and the sum or difference of the other two sides. Each construction comes with a proof of WHY it works, turning drawing into applied congruence.", "prereqs": ["g6.geo.constructions-intro", "g7.geo.practical-geometry", "g9.geo.triangles"], "outcomes": ["Can bisect a given angle and construct the perpendicular bisector of a segment, and justify both constructions using congruence", "Can construct angles of 60°, 30°, 90°, 45° and their combinations with ruler and compass only", "Can construct a triangle given its base, a base angle, and the sum (or difference) of the other two sides", "Can check the feasibility of a construction using the triangle inequality before starting"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g9.geo.constructions.rules-of-the-game", "parent": "g9.geo.constructions", "title": "Rules of the Game: Straightedge and Compass Only", "description": "Set the ground rules: constructions use an UNMARKED straightedge and a compass — no protractor, no measuring — and every construction must come with a congruence-based justification.", "outcomes": ["Can state which tools and moves are legal in a construction", "Can explain why a protractor measurement is not a construction"], "prereqs": ["g6.geo.constructions-intro"], "est_minutes": 10, "difficulty": 1, "question": true}, {"id": "g9.geo.constructions.bisect-angle", "parent": "g9.geo.constructions", "title": "Bisecting an Angle", "description": "Construct the bisector of any angle with two matched arcs, and justify it: the two arc intersections and the vertex build congruent triangles by SSS.", "outcomes": ["Can bisect any given angle with straightedge and compass", "Can justify the construction with an SSS congruence argument"], "prereqs": ["g9.geo.constructions.rules-of-the-game"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g9.geo.constructions.perpendicular-bisector", "parent": "g9.geo.constructions", "title": "Perpendicular Bisector of a Segment", "description": "Construct the perpendicular bisector with arcs of EQUAL radius (more than half the segment) from both endpoints, and prove every point of it is equidistant from the two endpoints.", "outcomes": ["Can construct a perpendicular bisector that actually intersects twice", "Can explain both radius conditions: equal at both ends, and more than half the segment"], "prereqs": ["g9.geo.constructions.rules-of-the-game"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.geo.constructions.standard-angles", "parent": "g9.geo.constructions", "title": "Constructing 60°, 30°, 90°, 45°", "description": "Build the standard angles from scratch: 60° from the equilateral arc, 30° by bisecting it, 90° from adjacent arcs (or bisecting a straight angle), 45° by bisecting again.", "outcomes": ["Can construct 60°, 30°, 90° and 45° with justification", "Can plan a construction route to composite angles like 75° or 105°"], "prereqs": ["g9.geo.constructions.bisect-angle", "g9.geo.constructions.perpendicular-bisector"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g9.geo.constructions.triangle-constructions-indirect", "parent": "g9.geo.constructions", "title": "Triangles from Indirect Data", "description": "Construct triangles given base, a base angle and the SUM or DIFFERENCE of the other two sides, or the perimeter with two base angles — first checking the data is feasible at all.", "outcomes": ["Can execute the sum-of-sides and difference-of-sides constructions", "Can check feasibility (e.g. AB + AC > BC) before starting", "Can justify the key isosceles/perpendicular-bisector step in each construction"], "prereqs": ["g9.geo.constructions.standard-angles", "g7.geo.practical-geometry", "g9.geo.triangles.triangle-inequality"], "est_minutes": 30, "difficulty": 4, "question": true}]}, {"id": "g9.mea.herons-formula", "title": "Heron's Formula", "grade": 9, "strand": "mea", "description": "Area = ½ × base × height is useless when you know all three sides but no height. Heron's formula rescues you: with semi-perimeter s = (a+b+c)/2, the area is √(s(s−a)(s−b)(s−c)) — no heights, no angles, just the sides. This node applies it to triangles and to quadrilaterals that can be split into triangles, a genuinely practical tool for surveyors and anyone measuring land.", "prereqs": ["g7.mea.perimeter-area", "g8.num.squares-roots"], "outcomes": ["Can compute the semi-perimeter and apply Heron's formula to find the area of a triangle from its three sides", "Can simplify the resulting square roots, leaving answers in exact surd form where appropriate", "Can find areas of quadrilaterals by splitting them into triangles with a known diagonal", "Can cross-check Heron's result against ½ × base × height for right triangles"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g9.mea.herons-formula.area-formula-limits", "parent": "g9.mea.herons-formula", "title": "When ½ × base × height Fails", "description": "Revise ½ × base × height and hit its wall: with three sides given and no height, the old formula is unusable — motivating a side-only formula and burying the myth that ½ × (side × side) is an area.", "outcomes": ["Can compute triangle areas when a height IS available", "Can explain why ½ × product of two sides is not the area without the height between them"], "prereqs": ["g7.mea.perimeter-area"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.mea.herons-formula.semi-perimeter", "parent": "g9.mea.herons-formula", "title": "The Semi-Perimeter s", "description": "Define s = (a + b + c)/2 — HALF the perimeter — and drill computing s, s − a, s − b, s − c cleanly, since every Heron's calculation lives or dies on this step.", "outcomes": ["Can compute s and the three differences s − a, s − b, s − c for any triangle", "Can sanity-check that s − a, s − b, s − c are all positive for a valid triangle"], "prereqs": ["g9.mea.herons-formula.area-formula-limits"], "est_minutes": 15, "difficulty": 1, "question": true}, {"id": "g9.mea.herons-formula.apply-herons-formula", "parent": "g9.mea.herons-formula", "title": "Applying Heron's Formula", "description": "Compute areas as √(s(s−a)(s−b)(s−c)) end-to-end: find s, form the four factors, multiply, and take the square root — the step exam scripts most often skip.", "outcomes": ["Can compute the area of any triangle from its three sides", "Can verify Heron's answer against ½ × base × height on a right triangle", "Can carry units correctly (cm² for area)"], "prereqs": ["g9.mea.herons-formula.semi-perimeter", "g9.num.number-systems.surds-operations"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g9.mea.herons-formula.equilateral-isosceles-shortcuts", "parent": "g9.mea.herons-formula", "title": "Equilateral and Isosceles Special Cases", "description": "Run Heron's formula symbolically on special triangles: derive (√3/4)a² for the equilateral case and clean surd forms for isosceles triangles, keeping the surd arithmetic honest.", "outcomes": ["Can derive and use the (√3/4)a² formula for equilateral triangles", "Can compute isosceles triangle areas leaving answers in surd form"], "prereqs": ["g9.mea.herons-formula.apply-herons-formula"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g9.mea.herons-formula.quadrilateral-split-applications", "parent": "g9.mea.herons-formula", "title": "Quadrilateral Areas by Triangulation", "description": "Split quadrilaterals (fields, park plots, rhombus-shaped tiles) along a diagonal into two triangles and apply Heron's formula to each — the classic board application question.", "outcomes": ["Can find a quadrilateral's area by splitting along a diagonal", "Can solve mixed word problems (cost of levelling, paint per m²) built on Heron's formula"], "prereqs": ["g9.mea.herons-formula.apply-herons-formula"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g9.mea.surface-volume", "title": "Surface Areas and Volumes: Cone, Sphere, Cylinder", "grade": 9, "strand": "mea", "description": "Cylinders, cones and spheres are the curved solids of daily life — pipes, ice-cream cones, footballs. This node derives and applies their surface areas (curved and total) and volumes: cylinder (2πrh, πr²h), cone (πrl, ⅓πr²h) and sphere (4πr², 4/3πr³), including the beautiful facts that a cone is one-third of its cylinder and a sphere is two-thirds of its enclosing cylinder. You also learn to keep slant height l and vertical height h firmly apart.", "prereqs": ["g8.mea.mensuration", "g7.mea.perimeter-area", "g7.geo.triangle-properties"], "outcomes": ["Can compute curved and total surface areas of cylinders, cones and spheres, choosing the right one for the context", "Can compute volumes of cylinders, cones, spheres and hemispheres", "Can relate slant height, vertical height and radius of a cone by l² = r² + h² and use the correct one in each formula", "Can predict how surface area and volume scale when the radius is doubled or halved"], "difficulty": 3, "est_minutes": 80, "stub": false, "micros": [{"id": "g9.mea.surface-volume.cylinder-csa-tsa", "parent": "g9.mea.surface-volume", "title": "Cylinder: Curved vs Total Surface Area", "description": "Unroll a cylinder's label into a rectangle to get CSA = 2πrh, then add the two circular lids for TSA = 2πr(r + h) — and decide from context (pipe? closed tank?) which one a problem wants.", "outcomes": ["Can compute CSA and TSA of a cylinder", "Can choose CSA or TSA correctly from the real-world context"], "prereqs": ["g8.mea.mensuration"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g9.mea.surface-volume.cylinder-volume", "parent": "g9.mea.surface-volume", "title": "Cylinder Volume", "description": "Stack circular cross-sections to get V = πr²h, practise unit conversions (1 L = 1000 cm³), and solve inverse problems finding r or h from a given capacity.", "outcomes": ["Can compute cylinder volumes and convert between cm³, m³ and litres", "Can find a missing dimension from a given volume"], "prereqs": ["g9.mea.surface-volume.cylinder-csa-tsa"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g9.mea.surface-volume.cone-slant-height", "parent": "g9.mea.surface-volume", "title": "The Cone and Its Slant Height", "description": "Distinguish a cone's vertical height h from its slant height l once and for all, linked by l² = r² + h² — the right triangle hiding inside every cone.", "outcomes": ["Can compute l from r and h (and any one from the other two)", "Can point to h and l correctly on a cone diagram"], "prereqs": ["g9.mea.surface-volume.cylinder-csa-tsa", "g7.geo.triangle-properties"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.mea.surface-volume.cone-csa-volume", "parent": "g9.mea.surface-volume", "title": "Cone: Surface Area and Volume", "description": "Apply CSA = πrl, TSA = πr(l + r) and V = (1/3)πr²h — keeping the rule straight: l for surfaces, h for volume, and the 1/3 that makes a cone one third of its cylinder.", "outcomes": ["Can compute a cone's CSA, TSA and volume choosing l and h correctly", "Can explain the 1/3 factor via the three-cones-fill-a-cylinder experiment"], "prereqs": ["g9.mea.surface-volume.cone-slant-height", "g9.mea.surface-volume.cylinder-volume"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g9.mea.surface-volume.sphere-hemisphere-surface", "parent": "g9.mea.surface-volume", "title": "Sphere and Hemisphere: Surface Areas", "description": "Learn the striking fact that a sphere's surface is 4πr² — exactly four great circles — and assemble hemisphere areas: curved 2πr², total 3πr² with the flat face included.", "outcomes": ["Can compute surface areas of spheres and solid hemispheres", "Can decide when the hemisphere's flat circular face must be counted"], "prereqs": ["g9.mea.surface-volume.cylinder-csa-tsa"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g9.mea.surface-volume.sphere-hemisphere-volume", "parent": "g9.mea.surface-volume", "title": "Sphere and Hemisphere: Volumes", "description": "Use V = (4/3)πr³ for the sphere and (2/3)πr³ for the hemisphere in board-style problems — dome capacities, metal spheres melted and recast — keeping the volume and surface formulas unswapped.", "outcomes": ["Can compute volumes of spheres and hemispheres", "Can solve melt-and-recast problems by equating volumes"], "prereqs": ["g9.mea.surface-volume.sphere-hemisphere-surface"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g9.mea.surface-volume.scaling-and-comparison", "parent": "g9.mea.surface-volume", "title": "How Scaling Really Works: r → 2r", "description": "Confront the linear-scaling instinct: doubling the radius multiplies surface areas by 4 and volumes by 8, because area is r² and volume is r³ — explored through ratio and percentage questions.", "outcomes": ["Can compute the effect on area and volume of scaling a dimension", "Can solve ratio problems comparing solids of different sizes"], "prereqs": ["g9.mea.surface-volume.sphere-hemisphere-volume", "g9.mea.surface-volume.cone-csa-volume"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g9.dat.statistics", "title": "Statistics: Grouped Data, Histograms, Frequency Polygons", "grade": 9, "strand": "dat", "description": "Raw data is a crowd; statistics gives it a face. This node organises data into ungrouped and grouped frequency distributions, draws and reads bar graphs, histograms (including the subtle case of unequal class widths, where bar AREA carries the frequency) and frequency polygons, and computes class marks. It builds the visual literacy needed to spot the story — and the lie — in a chart.", "prereqs": ["g8.dat.data-handling"], "outcomes": ["Can construct grouped frequency distributions, identifying class limits, class width and class marks", "Can draw and interpret histograms, adjusting bar heights (frequency density) when class widths are unequal", "Can draw a frequency polygon from a histogram or directly from class marks", "Can choose correctly between a bar graph (categorical data) and a histogram (continuous grouped data)"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g9.dat.statistics.data-types-collection", "parent": "g9.dat.statistics", "title": "Raw Data: Collection and Types", "description": "Distinguish primary from secondary data, handle raw ungrouped data, and compute the range — establishing why a crowd of numbers needs organising before it says anything.", "outcomes": ["Can classify data as primary or secondary", "Can find the range and organise raw data in order"], "prereqs": ["g8.dat.data-handling"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.dat.statistics.frequency-distributions", "parent": "g9.dat.statistics", "title": "Frequency Distributions and Class Marks", "description": "Build ungrouped and grouped frequency tables: choose classes, apply the lower-limit-included convention for continuous classes, and compute each class mark as the MIDPOINT of its class.", "outcomes": ["Can construct a grouped frequency table from raw data", "Can state which class a boundary value like 30 belongs to", "Can compute class marks and class widths"], "prereqs": ["g9.dat.statistics.data-types-collection"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g9.dat.statistics.bar-graphs-revisit", "parent": "g9.dat.statistics", "title": "Bar Graphs, Done Properly", "description": "Draw and read bar graphs for categorical data with exam-grade discipline: equal bar widths, equal gaps, a labelled frequency axis starting at zero.", "outcomes": ["Can draw a correctly scaled and labelled bar graph", "Can extract and compare values from a given bar graph"], "prereqs": ["g9.dat.statistics.frequency-distributions"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.dat.statistics.histograms-equal-widths", "parent": "g9.dat.statistics", "title": "Histograms with Equal Class Widths", "description": "Draw histograms for continuous grouped data — bars touching, x-axis a real number line of class boundaries — and contrast point-by-point with the gapped, categorical bar graph.", "outcomes": ["Can draw a histogram from a grouped frequency table", "Can list the differences between a histogram and a bar graph and say WHY the bars touch"], "prereqs": ["g9.dat.statistics.frequency-distributions", "g9.dat.statistics.bar-graphs-revisit"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g9.dat.statistics.histograms-unequal-widths", "parent": "g9.dat.statistics", "title": "Histograms with Unequal Class Widths", "description": "Handle the trap classes: when widths differ, bar AREA must represent frequency, so heights are adjusted to frequency density — (frequency/class width) × smallest width.", "outcomes": ["Can compute adjusted heights (proportional frequencies) for unequal classes", "Can explain why plotting raw frequency as height misleads when widths differ"], "prereqs": ["g9.dat.statistics.histograms-equal-widths"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g9.dat.statistics.frequency-polygons", "parent": "g9.dat.statistics", "title": "Frequency Polygons", "description": "Turn histograms into frequency polygons by joining the midpoints of bar tops — or draw them directly from class marks — closing the figure with imagined zero-frequency classes at both ends.", "outcomes": ["Can draw a frequency polygon with or without its histogram", "Can compare two distributions by drawing their polygons on one grid"], "prereqs": ["g9.dat.statistics.histograms-equal-widths"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g9.dat.probability-empirical", "title": "Probability: The Empirical Approach", "grade": 9, "strand": "dat", "description": "Before theory, there is experiment: toss a coin 500 times, count heads, and the fraction of heads is the empirical (experimental) probability. This node defines P(event) = (trials where the event happened)/(total trials), explores how this settles down as trials grow, and establishes the ground rules — probabilities live between 0 and 1, and the probabilities of an event and its complement sum to 1. It is the honest, data-first doorway to the classical probability of Class 10.", "prereqs": ["g8.dat.data-handling", "g7.dat.data-handling-averages"], "outcomes": ["Can compute empirical probabilities from frequency data (coin tosses, dice records, survey tables)", "Can explain why every probability lies between 0 and 1, and use P(not E) = 1 − P(E)", "Can describe how empirical probability stabilises as the number of trials increases", "Can distinguish what a probability claims about the long run from what happens in any short run"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": [{"id": "g9.dat.probability-empirical.experiments-trials-outcomes", "parent": "g9.dat.probability-empirical", "title": "Experiments, Trials, Events", "description": "Fix the vocabulary of chance: an experiment (toss a coin), a trial (one toss), an outcome (heads), an event (getting heads) — and gather real class data to work with next.", "outcomes": ["Can identify experiment, trial, outcome and event in a described situation", "Can record trial data in a frequency table ready for probability estimates"], "prereqs": ["g8.dat.data-handling"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g9.dat.probability-empirical.empirical-probability-formula", "parent": "g9.dat.probability-empirical", "title": "The Empirical Probability Formula", "description": "Define P(E) = (number of trials where E happened)/(total number of trials): a FRACTION of trials, computed from actual data — never a raw count.", "outcomes": ["Can compute empirical probabilities from frequency data", "Can express the result as a fraction, decimal or percentage correctly"], "prereqs": ["g9.dat.probability-empirical.experiments-trials-outcomes"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g9.dat.probability-empirical.probability-as-number-0-1", "parent": "g9.dat.probability-empirical", "title": "Probability Lives Between 0 and 1", "description": "Establish the hard boundaries: every probability is between 0 (never happened in the trials) and 1 (happened every time), and the probabilities of all outcomes of an experiment sum to 1.", "outcomes": ["Can reject impossible probability values like 1.4 or −0.2 on sight", "Can use the sum-to-1 property to find a missing probability"], "prereqs": ["g9.dat.probability-empirical.empirical-probability-formula"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g9.dat.probability-empirical.long-run-interpretation", "parent": "g9.dat.probability-empirical", "title": "What a Probability Actually Promises", "description": "Interpret P = 1/6 honestly: a long-run fraction that experimental results approach as trials grow — not a short-run guarantee, and not something real data must match exactly.", "outcomes": ["Can explain P(six) = 1/6 as a long-run statement, with counterexamples to the every-6-rolls reading", "Can explain why 240 heads in 500 tosses does not contradict a fair coin"], "prereqs": ["g9.dat.probability-empirical.empirical-probability-formula"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g9.dat.probability-empirical.independence-fallacy", "parent": "g9.dat.probability-empirical", "title": "Independent Trials and the Gambler's Fallacy", "description": "Confront the 'due' instinct: a fair coin has no memory, so after five heads the next toss is still 50–50 — past outcomes cannot lean on future ones.", "outcomes": ["Can state that successive trials of a fair coin or die are independent", "Can debunk a gambler's-fallacy argument in a given scenario"], "prereqs": ["g9.dat.probability-empirical.long-run-interpretation"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g10.num.real-numbers", "title": "Real Numbers: Fundamental Theorem of Arithmetic, Irrationality Proofs", "grade": 10, "strand": "num", "description": "Every integer greater than 1 factors into primes in exactly one way — the Fundamental Theorem of Arithmetic. From this single fact flow practical tools (HCF and LCM via prime factorisation, and the relation HCF × LCM = product of the two numbers), a crisp test for which fractions have terminating decimals, and elegant proofs by contradiction that numbers like √2, √3 and √5 are irrational. This node upgrades your Class 9 acquaintance with irrationals into actual proof.", "prereqs": ["g9.num.number-systems", "g6.num.playing-with-numbers"], "outcomes": ["Can find HCF and LCM of two numbers by prime factorisation and verify HCF × LCM = product of the numbers", "Can prove the irrationality of numbers like √2, √5, and combinations like 3 + 2√5, by contradiction", "Can decide, without dividing, whether a rational number p/q has a terminating or non-terminating recurring decimal expansion (after reducing, q must be of the form 2ᵐ5ⁿ)", "Can apply HCF/LCM reasoning to problems about bells tolling together, stacking, and circular tracks"], "difficulty": 3, "est_minutes": 70, "stub": false, "micros": [{"id": "g10.num.real-numbers.fta-prime-factorisation", "parent": "g10.num.real-numbers", "title": "The Fundamental Theorem of Arithmetic", "description": "Every integer greater than 1 factors into primes in exactly one way, apart from the order of factors. Build factor trees, express numbers as products of prime powers, and see why 1 is excluded from the primes.", "outcomes": ["Can express any given composite number as a product of prime powers via a factor tree", "Can state the Fundamental Theorem of Arithmetic and explain why admitting 1 as a prime would destroy uniqueness"], "prereqs": ["g6.num.playing-with-numbers"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g10.num.real-numbers.hcf-lcm-prime-method", "parent": "g10.num.real-numbers", "title": "HCF and LCM by Prime Factorisation", "description": "Compute HCF (smallest powers of common primes) and LCM (greatest powers of all primes) directly from prime factorisations, and apply them to bells-tolling, tiling and circular-track problems.", "outcomes": ["Can find the HCF and LCM of two or three numbers from their prime factorisations using min/max exponents", "Can decide whether a word problem (bells ringing together, largest square tile, meeting on a track) needs HCF or LCM and solve it"], "prereqs": ["g10.num.real-numbers.fta-prime-factorisation"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g10.num.real-numbers.hcf-lcm-product-identity", "parent": "g10.num.real-numbers", "title": "The Identity HCF × LCM = Product (Two Numbers Only)", "description": "For exactly two numbers a and b, HCF(a,b) × LCM(a,b) = a × b, because min + max of each prime's exponents equals their sum. Use it to find one quantity from the other three — and know it fails for three numbers.", "outcomes": ["Can use HCF × LCM = a × b to find an unknown HCF or LCM without factorising afresh", "Can produce a counterexample showing the identity does not extend to three numbers"], "prereqs": ["g10.num.real-numbers.hcf-lcm-prime-method"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g10.num.real-numbers.terminating-decimal-test", "parent": "g10.num.real-numbers", "title": "Terminating vs Recurring Decimals: The 2ᵐ5ⁿ Test", "description": "A rational number p/q in lowest terms has a terminating decimal exactly when q has no prime factor other than 2 and 5. Master the two-step protocol: reduce first, then factor the denominator.", "outcomes": ["Can decide, without dividing, whether a given rational number terminates or recurs", "Can explain why only the primes 2 and 5 can be 'cleared' into a power of 10", "Can state after how many decimal places a terminating expansion ends, from the exponents of 2 and 5"], "prereqs": ["g10.num.real-numbers.fta-prime-factorisation", "g7.num.rational-numbers-intro"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g10.num.real-numbers.irrationality-proof-root2", "parent": "g10.num.real-numbers", "title": "Proving √2 (and √3, √5) Irrational by Contradiction", "description": "Assume √2 = p/q in lowest terms, square both sides, and use the theorem 'if a prime divides a² then it divides a' to force a common factor — contradiction. Run the same engine for √3 and √5.", "outcomes": ["Can reproduce the full contradiction proof that √2 is irrational, justifying each step", "Can adapt the proof to √3 or √5 using the lemma that p | a² implies p | a for a prime p"], "prereqs": ["g10.num.real-numbers.fta-prime-factorisation", "g9.num.number-systems"], "est_minutes": 25, "difficulty": 4, "question": false}, {"id": "g10.num.real-numbers.irrational-combinations", "parent": "g10.num.real-numbers", "title": "Irrationality of Combinations like 3 + 2√5", "description": "Rationals are closed under +, −, × and ÷ (by nonzero). So if 3 + 2√5 were rational, isolating √5 would make √5 rational — contradiction. One irrational ingredient poisons the whole expression.", "outcomes": ["Can prove expressions like 3 + 2√5, 5 − √3 and √2/7 irrational using closure of the rationals plus contradiction", "Can classify every real number as exactly one of rational or irrational"], "prereqs": ["g10.num.real-numbers.irrationality-proof-root2"], "est_minutes": 20, "difficulty": 4, "question": true}]}, {"id": "g10.alg.polynomials", "title": "Polynomials: Zeroes and Coefficients", "grade": 10, "strand": "alg", "description": "A quadratic's zeroes are not random: their sum is −b/a and their product is c/a, straight from the coefficients. This node connects the geometry (zeroes are where the graph crosses the x-axis) with the algebra (factoring, and building a quadratic back from its zeroes), so you can read a polynomial's roots from its graph and its graph from its roots. It is the launchpad for quadratic equations.", "prereqs": ["g9.alg.polynomials"], "outcomes": ["Can find the zeroes of a quadratic polynomial by factorisation and verify the relationships sum = −b/a, product = c/a", "Can read the number of zeroes of a polynomial from the number of times its graph meets the x-axis", "Can construct a quadratic polynomial from a given sum and product of zeroes", "Can evaluate symmetric expressions in the zeroes (α + β, αβ, α² + β²) without finding the zeroes themselves"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g10.alg.polynomials.zeroes-and-graphs", "parent": "g10.alg.polynomials", "title": "Zeroes Geometrically: Where the Graph Meets the x-axis", "description": "A zero of p(x) is an input x with p(x) = 0, so the point (x, 0) lies on the x-axis. Read the number of zeroes straight off a graph, and see that a degree-n polynomial has AT MOST n real zeroes — possibly fewer.", "outcomes": ["Can state the number of zeroes of a polynomial from its graph by counting x-axis meetings", "Can distinguish the y-intercept p(0) from the zeroes (solutions of p(x) = 0)", "Can sketch parabolas with two, one and zero real zeroes"], "prereqs": ["g9.alg.polynomials", "g8.alg.graphs-intro"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g10.alg.polynomials.zeroes-by-factorisation", "parent": "g10.alg.polynomials", "title": "Finding Zeroes of a Quadratic by Factorisation", "description": "Split the middle term, factor the quadratic into two linear brackets, and read off the zeroes with their correct signs. Verify by substituting back.", "outcomes": ["Can factor a quadratic polynomial by splitting the middle term and state its zeroes", "Can verify claimed zeroes by direct substitution, catching sign errors"], "prereqs": ["g10.alg.polynomials.zeroes-and-graphs", "g8.alg.factorisation"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.alg.polynomials.sum-product-relations", "parent": "g10.alg.polynomials", "title": "Sum and Product of Zeroes vs Coefficients", "description": "For ax² + bx + c with zeroes α and β: α + β = −b/a and αβ = c/a. Derive the relations by comparing a(x − α)(x − β) with the expanded form, and drill the minus sign.", "outcomes": ["Can state and verify α + β = −b/a and αβ = c/a for any quadratic", "Can use the relations to check factorisations without re-expanding"], "prereqs": ["g10.alg.polynomials.zeroes-by-factorisation"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g10.alg.polynomials.build-quadratic-from-zeroes", "parent": "g10.alg.polynomials", "title": "Constructing a Quadratic from Sum and Product of Zeroes", "description": "Any quadratic with zero-sum S and zero-product P is k[x² − Sx + P]. Build polynomials from given zeroes or from given S and P, watching where each sign lands.", "outcomes": ["Can write a quadratic polynomial with a given sum and product of zeroes using x² − Sx + P", "Can explain why the answer is unique only up to a nonzero constant multiple k"], "prereqs": ["g10.alg.polynomials.sum-product-relations"], "est_minutes": 15, "difficulty": 3, "question": false}, {"id": "g10.alg.polynomials.symmetric-expressions", "parent": "g10.alg.polynomials", "title": "Evaluating Symmetric Expressions in the Zeroes", "description": "Compute α² + β², 1/α + 1/β, α/β + β/α and similar expressions directly from α + β and αβ, without ever finding α and β themselves. Key identity: α² + β² = (α + β)² − 2αβ.", "outcomes": ["Can evaluate α² + β² and 1/α + 1/β from the coefficient relations alone", "Can rewrite a symmetric expression in terms of α + β and αβ before substituting"], "prereqs": ["g10.alg.polynomials.sum-product-relations", "g8.alg.expressions-identities"], "est_minutes": 20, "difficulty": 4, "question": true}]}, {"id": "g10.alg.linear-pair-2var", "title": "Pair of Linear Equations in Two Variables", "grade": 10, "strand": "alg", "description": "Two conditions, two unknowns: a pair of linear equations is two lines on the same plane, and everything depends on how those lines relate — crossing (one solution), parallel (none), or coincident (infinitely many), which the coefficient ratios a₁/a₂, b₁/b₂, c₁/c₂ diagnose without drawing. You will solve systems by substitution and elimination and use them to crack age, cost, speed and fraction word problems — the single most examined chapter of Class 10 algebra.", "prereqs": ["g9.alg.linear-equations-2var", "g8.alg.linear-equations-1var"], "outcomes": ["Can classify a pair of linear equations as consistent (unique or infinite solutions) or inconsistent using coefficient ratios", "Can solve a pair of linear equations by substitution and by elimination, choosing the more efficient method", "Can interpret the solution graphically as the intersection of two lines", "Can translate word problems (ages, costs, digits, speeds, fractions) into pairs of equations and solve them"], "difficulty": 4, "est_minutes": 85, "stub": false, "micros": [{"id": "g10.alg.linear-pair-2var.pair-as-two-lines", "parent": "g10.alg.linear-pair-2var", "title": "A Pair of Equations as Two Lines", "description": "Each linear equation in x and y draws a line; solving the pair means finding points lying on BOTH lines. Crossing lines give one solution, parallel lines none, coincident lines infinitely many.", "outcomes": ["Can solve a pair of linear equations graphically by plotting both lines and reading the intersection", "Can name the three geometric possibilities (intersecting, parallel, coincident) and their solution counts"], "prereqs": ["g9.alg.linear-equations-2var"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g10.alg.linear-pair-2var.consistency-ratio-test", "parent": "g10.alg.linear-pair-2var", "title": "Consistency by Coefficient Ratios", "description": "Compare a₁/a₂, b₁/b₂ and c₁/c₂: unequal first two ratios means one solution; all three equal means infinitely many; first two equal but third different means none. All three ratios, always.", "outcomes": ["Can classify a pair of equations as unique-solution, no-solution or infinitely-many using the ratio table", "Can find a parameter value (like k) that makes a pair consistent, inconsistent or dependent"], "prereqs": ["g10.alg.linear-pair-2var.pair-as-two-lines"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.alg.linear-pair-2var.substitution-method", "parent": "g10.alg.linear-pair-2var", "title": "Solving by Substitution", "description": "Isolate one variable from the simpler equation, substitute the expression into the other, solve the resulting one-variable equation, and back-substitute. Best when a coefficient is already 1.", "outcomes": ["Can solve a pair of linear equations by substitution, including fraction-producing cases", "Can choose which variable and which equation to isolate for the least algebra"], "prereqs": ["g10.alg.linear-pair-2var.pair-as-two-lines", "g8.alg.linear-equations-1var"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g10.alg.linear-pair-2var.elimination-method", "parent": "g10.alg.linear-pair-2var", "title": "Solving by Elimination", "description": "Scale the equations so one variable has matching coefficients, then add or subtract whole equations to eliminate it. Bracket discipline: the minus sign distributes through EVERY term of the subtracted equation.", "outcomes": ["Can eliminate a chosen variable by scaling and adding/subtracting equations with correct signs throughout", "Can convert a subtraction into 'multiply by −1 and add' to avoid sign errors"], "prereqs": ["g10.alg.linear-pair-2var.substitution-method"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.alg.linear-pair-2var.degenerate-outcomes", "parent": "g10.alg.linear-pair-2var", "title": "Interpreting 0 = 0 and 0 = k Endings", "description": "When elimination wipes out BOTH variables, the leftover statement is the verdict: 0 = (nonzero) means parallel lines and no solution; 0 = 0 means the same line twice and infinitely many solutions.", "outcomes": ["Can interpret a variable-free ending of elimination correctly instead of forcing a numeric answer", "Can connect each algebraic ending to its picture: parallel lines or coincident lines"], "prereqs": ["g10.alg.linear-pair-2var.elimination-method", "g10.alg.linear-pair-2var.consistency-ratio-test"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g10.alg.linear-pair-2var.word-problems-two-unknowns", "parent": "g10.alg.linear-pair-2var", "title": "Word Problems: Ages, Costs, Digits, Speeds, Fractions", "description": "Translate two verbal conditions into two equations: define variables precisely, encode each sentence, solve, and answer the question actually asked. Covers ages, prices, two-digit numbers, boat/stream and fraction problems.", "outcomes": ["Can set up a pair of linear equations from a two-condition word problem with clearly defined variables", "Can solve and interpret the result, checking both original conditions", "Can handle upstream/downstream and two-digit-number templates"], "prereqs": ["g10.alg.linear-pair-2var.elimination-method"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g10.alg.quadratic-equations", "title": "Quadratic Equations: Factoring, Formula, Discriminant", "grade": 10, "strand": "alg", "description": "When a problem multiplies an unknown by itself — areas, projectiles, speed-time — you get a quadratic equation ax² + bx + c = 0. This node solves them three ways (factorisation, completing the square, and the quadratic formula) and reads the discriminant D = b² − 4ac as a forecast: D > 0 two distinct real roots, D = 0 two equal roots, D < 0 no real roots. It is the first equation family where 'how many solutions?' becomes a serious question.", "prereqs": ["g10.alg.polynomials", "g8.alg.factorisation", "g8.num.squares-roots"], "outcomes": ["Can solve quadratic equations by factorisation using the zero-product principle", "Can apply the quadratic formula accurately, including sign handling for negative b and c", "Can compute the discriminant and state the nature of the roots without solving", "Can model word problems (areas, ages, speed-time) as quadratic equations, solve, and reject inadmissible roots"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g10.alg.quadratic-equations.standard-form-recognition", "parent": "g10.alg.quadratic-equations", "title": "Standard Form: Recognising a Quadratic Equation", "description": "An equation is quadratic when, after expanding and simplifying, it takes the form ax² + bx + c = 0 with a ≠ 0. Squared terms can cancel and cubes can survive — always simplify before judging.", "outcomes": ["Can reduce a given equation to standard form and decide whether it is quadratic", "Can identify a, b and c with correct signs from the standard form"], "prereqs": ["g8.alg.expressions-identities"], "est_minutes": 10, "difficulty": 2, "question": true}, {"id": "g10.alg.quadratic-equations.solve-by-factoring", "parent": "g10.alg.quadratic-equations", "title": "Solving by Factorisation and the Zero-Product Principle", "description": "Bring everything to one side, factor, and use the special power of zero: a product is 0 only when a factor is 0. Never divide an equation by an expression that could be zero — factor instead.", "outcomes": ["Can solve quadratic equations by factorisation, keeping both roots alive", "Can explain why pq = 0 forces p = 0 or q = 0, while pq = 12 forces nothing", "Can spot and avoid the root-killing move of dividing through by x"], "prereqs": ["g10.alg.quadratic-equations.standard-form-recognition", "g10.alg.polynomials.zeroes-by-factorisation"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.alg.quadratic-equations.complete-the-square-idea", "parent": "g10.alg.quadratic-equations", "title": "Completing the Square", "description": "Turn ax² + bx + c = 0 into a(x + d)² = e by adding the right constant, then square-root both sides. This method solves every quadratic and is the engine that derives the quadratic formula.", "outcomes": ["Can solve a quadratic by completing the square, including cases with a ≠ 1", "Can explain the geometric picture: rearranging an x²-plus-strips area into a literal square"], "prereqs": ["g10.alg.quadratic-equations.solve-by-factoring", "g8.num.squares-roots"], "est_minutes": 20, "difficulty": 4, "question": false}, {"id": "g10.alg.quadratic-equations.quadratic-formula", "parent": "g10.alg.quadratic-equations", "title": "The Quadratic Formula", "description": "x = (−b ± √(b² − 4ac))/(2a) solves any quadratic. Master the bracket-substitution ritual: write empty brackets first, then fill each with the SIGNED coefficient, so −b and −4ac come out right.", "outcomes": ["Can apply the quadratic formula accurately when b or c is negative", "Can simplify the resulting roots, including surd answers, to lowest form"], "prereqs": ["g10.alg.quadratic-equations.complete-the-square-idea"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.alg.quadratic-equations.discriminant-nature-of-roots", "parent": "g10.alg.quadratic-equations", "title": "The Discriminant and the Nature of Roots", "description": "D = b² − 4ac forecasts the roots without solving: D > 0 two distinct real roots, D = 0 two equal real roots, D < 0 no real roots. Geometrically: the parabola crosses, touches, or misses the x-axis.", "outcomes": ["Can compute D and state the nature of the roots, with correct language ('no REAL roots', not 'no solution')", "Can find parameter values making roots equal (D = 0)", "Can match each discriminant case to its parabola picture"], "prereqs": ["g10.alg.quadratic-equations.quadratic-formula"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g10.alg.quadratic-equations.word-problems-model-then-solve", "parent": "g10.alg.quadratic-equations", "title": "Word Problems: Model, Solve, Reject Inadmissible Roots", "description": "Areas, consecutive numbers, ages and speed-time situations become quadratics. Set up the equation, solve by the best method, then test each root against reality — lengths and speeds cannot be negative.", "outcomes": ["Can translate an area, number or speed-time story into a quadratic equation", "Can solve and then reject roots that violate the physical constraints, stating why", "Can verify the surviving root against the original story"], "prereqs": ["g10.alg.quadratic-equations.solve-by-factoring", "g10.alg.quadratic-equations.quadratic-formula"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g10.alg.arithmetic-progressions", "title": "Arithmetic Progressions: nth Term and Sum", "grade": 10, "strand": "alg", "description": "Add the same amount each step — salaries with fixed annual raises, theatre rows growing seat by seat, EMI schedules — and you get an arithmetic progression. This node nails the two master formulas: the nth term aₙ = a + (n−1)d and the sum Sₙ = n/2[2a + (n−1)d] = n/2(first + last), plus the art of recognising when a situation IS an AP and when it merely looks like one.", "prereqs": ["g8.alg.linear-equations-1var", "g7.alg.expressions"], "outcomes": ["Can identify whether a sequence is an AP by checking for a constant common difference", "Can compute any term of an AP using aₙ = a + (n−1)d, and solve for a, d or n given the others", "Can compute the sum of the first n terms using both forms of the sum formula", "Can model real situations (instalments, stacked rows, salary increments) as APs and answer questions about them"], "difficulty": 3, "est_minutes": 75, "stub": false, "micros": [{"id": "g10.alg.arithmetic-progressions.recognise-ap", "parent": "g10.alg.arithmetic-progressions", "title": "Recognising an AP: The Constant Common Difference", "description": "A sequence is an arithmetic progression exactly when EVERY gap between consecutive terms is the same number d. Check all gaps, not just the first — patterns that grow by changing steps are not APs.", "outcomes": ["Can test whether a given sequence is an AP by computing consecutive differences", "Can state the first term a and common difference d (including negative and fractional d)"], "prereqs": ["g7.alg.expressions"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g10.alg.arithmetic-progressions.nth-term-formula", "parent": "g10.alg.arithmetic-progressions", "title": "The nth Term: aₙ = a + (n − 1)d", "description": "From the first term you take only n − 1 steps to reach the nth term — hence a + (n − 1)d, not a + nd. Compute any requested term of an AP, including APs with negative common difference.", "outcomes": ["Can compute the nth term of an AP using aₙ = a + (n − 1)d", "Can explain the (n − 1) by counting steps between terms"], "prereqs": ["g10.alg.arithmetic-progressions.recognise-ap"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g10.alg.arithmetic-progressions.solve-for-a-d-n", "parent": "g10.alg.arithmetic-progressions", "title": "Working Backwards: Finding a, d or n", "description": "Use the nth-term formula in reverse: from two given terms build simultaneous equations for a and d; from a given value find which term it is (n must come out a positive integer); check membership of a number in an AP.", "outcomes": ["Can find a and d from two given terms of an AP by solving a linear pair", "Can determine which term of an AP equals a given value, and reject non-integer n as 'not a term'"], "prereqs": ["g10.alg.arithmetic-progressions.nth-term-formula", "g10.alg.linear-pair-2var.elimination-method"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g10.alg.arithmetic-progressions.sum-first-n-terms", "parent": "g10.alg.arithmetic-progressions", "title": "The Sum Sₙ = n/2 [2a + (n − 1)d]", "description": "Gauss's pairing trick: writing the sum forwards and backwards makes every pair total the same, giving Sₙ = n/2 [2a + (n − 1)d]. Distinguish sharply between the nth TERM and the SUM of n terms.", "outcomes": ["Can compute Sₙ for a given AP and n", "Can decide from the wording of a problem whether the nth term or the sum is being asked", "Can use aₙ = Sₙ − Sₙ₋₁ to recover terms from a sum formula"], "prereqs": ["g10.alg.arithmetic-progressions.nth-term-formula"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.alg.arithmetic-progressions.sum-with-last-term", "parent": "g10.alg.arithmetic-progressions", "title": "The Sum via the Last Term: Sₙ = n/2 (a + l)", "description": "When the last term l is known, Sₙ = n/2 (a + l) is faster — but you must first count the terms correctly using l = a + (n − 1)d. Classic use: sums like 3 + 7 + 11 + ... + 83.", "outcomes": ["Can count the number of terms of a finite AP from its first and last terms", "Can compute sums of the form a + ... + l with Sₙ = n/2 (a + l)"], "prereqs": ["g10.alg.arithmetic-progressions.sum-first-n-terms"], "est_minutes": 15, "difficulty": 3, "question": false}, {"id": "g10.alg.arithmetic-progressions.ap-word-problems", "parent": "g10.alg.arithmetic-progressions", "title": "AP Word Problems: Instalments, Rows and Increments", "description": "Salaries with fixed annual increments, loan instalments decreasing steadily, logs stacked in shrinking rows, flag posts and potato races — recognise the AP, decide term-vs-sum, and solve.", "outcomes": ["Can model a real situation as an AP, identifying a, d and what n means in context", "Can choose between the term formula and the sum formula from the question's wording", "Can interpret and reject unrealistic solutions (e.g. negative counts of rows)"], "prereqs": ["g10.alg.arithmetic-progressions.sum-with-last-term", "g10.alg.arithmetic-progressions.solve-for-a-d-n"], "est_minutes": 25, "difficulty": 4, "question": false}]}, {"id": "g10.geo.triangles-similarity", "title": "Triangles: Similarity, Basic Proportionality Theorem, Pythagoras", "grade": 10, "strand": "geo", "description": "Similar figures have the same shape at different sizes: angles match, and corresponding sides scale by one common ratio. This node proves the Basic Proportionality (Thales) Theorem — a line parallel to one side of a triangle divides the other two sides proportionally — establishes the AA, SSS and SAS similarity criteria, and puts them to work, including in proofs and applications of the Pythagoras theorem. Similarity is the mathematics of maps, models, shadows and zoom.", "prereqs": ["g9.geo.triangles", "g7.geo.triangle-properties", "g6.num.ratio-proportion"], "outcomes": ["Can state and apply the Basic Proportionality Theorem and its converse to compute segment lengths", "Can prove triangles similar using AA, SSS or SAS similarity criteria with correct correspondence", "Can compute unknown sides of similar triangles using the scale factor (multiplicative, not additive)", "Can apply the Pythagoras theorem and its converse in computations and proofs"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g10.geo.triangles-similarity.similarity-and-scale-factor", "parent": "g10.geo.triangles-similarity", "title": "Similar Figures and the Scale Factor", "description": "Similar figures have equal corresponding angles and proportional corresponding sides — same shape, possibly different size. Scaling is multiplicative: every side is MULTIPLIED by the same factor, never increased by the same amount.", "outcomes": ["Can state the two conditions for similarity of polygons and contrast similarity with congruence", "Can compute unknown sides of similar figures using a multiplicative scale factor"], "prereqs": ["g7.geo.congruence", "g6.num.ratio-proportion"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g10.geo.triangles-similarity.bpt-thales", "parent": "g10.geo.triangles-similarity", "title": "The Basic Proportionality Theorem (Thales)", "description": "A line parallel to one side of a triangle divides the other two sides in the same ratio: if DE ∥ BC then AD/DB = AE/EC. Prove it with equal-area arguments and use it to compute segment lengths.", "outcomes": ["Can state and prove the Basic Proportionality Theorem", "Can compute unknown segment lengths using AD/DB = AE/EC and its equivalent forms (AD/AB = AE/AC)"], "prereqs": ["g10.geo.triangles-similarity.similarity-and-scale-factor"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.geo.triangles-similarity.bpt-converse", "parent": "g10.geo.triangles-similarity", "title": "Converse of the Basic Proportionality Theorem", "description": "If a line divides two sides of a triangle in the same ratio, it must be parallel to the third side. Use it to prove parallelism from measurements, including the midpoint-theorem special case.", "outcomes": ["Can apply the converse of BPT to establish that a line is parallel to a side", "Can recognise the midpoint theorem as the ratio-1:1 case of BPT and its converse"], "prereqs": ["g10.geo.triangles-similarity.bpt-thales", "g9.geo.quadrilaterals"], "est_minutes": 15, "difficulty": 3, "question": false}, {"id": "g10.geo.triangles-similarity.aa-similarity-criterion", "parent": "g10.geo.triangles-similarity", "title": "The AA Similarity Criterion", "description": "Two matching angles force the third to match and the triangles to be similar. Write the correspondence in the correct order (△ABC ∼ △PQR pairs A↔P, B↔Q, C↔R) and extract side ratios from it.", "outcomes": ["Can prove two triangles similar by AA, stating the correspondence in correct vertex order", "Can read off the proportional sides from a written similarity statement", "Can spot AA pairs generated by parallel lines, common angles and vertical angles"], "prereqs": ["g10.geo.triangles-similarity.similarity-and-scale-factor", "g9.geo.triangles"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g10.geo.triangles-similarity.sss-sas-similarity", "parent": "g10.geo.triangles-similarity", "title": "SSS and SAS Similarity Criteria", "description": "All three side-pairs in one ratio (SSS), or two side-pairs in ratio with the INCLUDED angles equal (SAS), also force similarity. Choose the right criterion from the given data.", "outcomes": ["Can verify SSS similarity by checking all three ratios are equal", "Can apply SAS similarity, checking the equal angle is the included one", "Can select the appropriate criterion (AA, SSS, SAS) for a given problem"], "prereqs": ["g10.geo.triangles-similarity.aa-similarity-criterion"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g10.geo.triangles-similarity.areas-of-similar-triangles", "parent": "g10.geo.triangles-similarity", "title": "Areas of Similar Triangles Scale as the Square", "description": "If sides are in ratio k, areas are in ratio k². Both base AND height scale by k, so area picks up the factor twice. Solve area-ratio problems and reverse ones (side ratio from area ratio).", "outcomes": ["Can state and use: ratio of areas of similar triangles = square of the ratio of corresponding sides", "Can recover the side ratio from a given area ratio by taking a square root"], "prereqs": ["g10.geo.triangles-similarity.aa-similarity-criterion", "g7.mea.perimeter-area"], "est_minutes": 20, "difficulty": 4, "question": true}, {"id": "g10.geo.triangles-similarity.pythagoras-and-converse", "parent": "g10.geo.triangles-similarity", "title": "Pythagoras Theorem and Its Converse", "description": "Prove Pythagoras via the similar triangles cut off by the altitude to the hypotenuse; apply a² + b² = c² to find sides, and use the converse to certify right angles. Squares combine — sides do not.", "outcomes": ["Can apply the Pythagoras theorem to compute an unknown side of a right triangle", "Can use the converse to test whether a triangle with given sides is right-angled", "Can explain why √(a² + b²) ≠ a + b using a concrete triangle"], "prereqs": ["g10.geo.triangles-similarity.aa-similarity-criterion", "g7.geo.triangle-properties"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g10.geo.coordinate-geometry", "title": "Coordinate Geometry: Distance, Section Formula, Areas", "grade": 10, "strand": "geo", "description": "Once points have coordinates, geometry becomes computation. The distance formula (Pythagoras in disguise) measures lengths, the section formula finds the point dividing a segment in a given ratio (midpoint as the friendly special case), and a determinant-style formula computes triangle areas — including the test for three points lying on one line. This node turns classification problems ('is this a rhombus?') into arithmetic.", "prereqs": ["g9.geo.coordinate-geometry", "g10.geo.triangles-similarity"], "outcomes": ["Can compute the distance between two points and use it to classify triangles and quadrilaterals", "Can apply the section formula to find a point dividing a segment in ratio m:n, and the midpoint as a special case", "Can find the area of a triangle from its vertices and use area = 0 as a collinearity test", "Can solve reverse problems: find a coordinate or ratio given a distance, midpoint or section condition"], "difficulty": 3, "est_minutes": 70, "stub": false, "micros": [{"id": "g10.geo.coordinate-geometry.distance-formula", "parent": "g10.geo.coordinate-geometry", "title": "The Distance Formula", "description": "Drop horizontal and vertical legs between two points and apply Pythagoras: d = √((x₂ − x₁)² + (y₂ − y₁)²). Square the differences, add, THEN take the square root — no linear shortcuts.", "outcomes": ["Can compute the distance between two given points, including with negative coordinates", "Can derive the formula from Pythagoras with a sketch of the right triangle"], "prereqs": ["g9.geo.coordinate-geometry", "g10.geo.triangles-similarity.pythagoras-and-converse"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g10.geo.coordinate-geometry.classify-figures-by-distance", "parent": "g10.geo.coordinate-geometry", "title": "Classifying Triangles and Quadrilaterals by Distances", "description": "Compute all side lengths (and diagonals) to certify a figure: isosceles or equilateral triangles, right triangles via the converse of Pythagoras, squares vs rhombi (equal sides, but check the diagonals).", "outcomes": ["Can classify a triangle from its vertex coordinates by comparing squared side lengths", "Can distinguish a square from a rhombus using diagonals, and a rectangle from a parallelogram"], "prereqs": ["g10.geo.coordinate-geometry.distance-formula"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g10.geo.coordinate-geometry.midpoint-formula", "parent": "g10.geo.coordinate-geometry", "title": "The Midpoint Formula", "description": "The midpoint averages the endpoints: M = ((x₁ + x₂)/2, (y₁ + y₂)/2). Adding coordinates without dividing by 2 lands you outside the segment entirely.", "outcomes": ["Can compute the midpoint of a segment from its endpoints", "Can find an unknown endpoint given the midpoint and the other endpoint"], "prereqs": ["g10.geo.coordinate-geometry.distance-formula"], "est_minutes": 10, "difficulty": 2, "question": false}, {"id": "g10.geo.coordinate-geometry.section-formula", "parent": "g10.geo.coordinate-geometry", "title": "The Section Formula", "description": "The point dividing AB in ratio m : n (from A) is ((mx₂ + nx₁)/(m + n), (my₂ + ny₁)/(m + n)): the weight m multiplies the FAR endpoint B. The midpoint is the 1 : 1 special case.", "outcomes": ["Can apply the section formula for internal division with the weights on the correct endpoints", "Can verify an answer by checking the point lies between the endpoints, nearer the correct one"], "prereqs": ["g10.geo.coordinate-geometry.midpoint-formula"], "est_minutes": 20, "difficulty": 4, "question": true}, {"id": "g10.geo.coordinate-geometry.triangle-area-collinearity", "parent": "g10.geo.coordinate-geometry", "title": "Area of a Triangle and the Collinearity Test", "description": "Area = ½|x₁(y₂ − y₃) + x₂(y₃ − y₁) + x₃(y₁ − y₂)|. Take the absolute value of the WHOLE sum at the end; if the area is 0 the three points are collinear.", "outcomes": ["Can compute the area of a triangle from its vertex coordinates", "Can test three points for collinearity using area = 0", "Can find an unknown coordinate given the area or a collinearity condition"], "prereqs": ["g10.geo.coordinate-geometry.distance-formula"], "est_minutes": 20, "difficulty": 4, "question": true}, {"id": "g10.geo.coordinate-geometry.reverse-coordinate-problems", "parent": "g10.geo.coordinate-geometry", "title": "Reverse Problems: Unknown Ratios, Points and Parameters", "description": "Run the formulas backwards: find the ratio in which the x-axis or y-axis cuts a segment (set y = 0 or x = 0), find a point equidistant from two given points, or find a coordinate from a given distance.", "outcomes": ["Can find the ratio in which a coordinate axis or a given point divides a segment", "Can set up and solve equations for unknown coordinates from distance or section conditions"], "prereqs": ["g10.geo.coordinate-geometry.section-formula", "g10.geo.coordinate-geometry.triangle-area-collinearity"], "est_minutes": 25, "difficulty": 4, "question": false}]}, {"id": "g10.geo.circles-tangents", "title": "Circles: Tangents and Their Properties", "grade": 10, "strand": "geo", "description": "A tangent kisses a circle at exactly one point — and at that point it stands perfectly perpendicular to the radius. From this single fact plus congruence comes the second gem: the two tangents drawn from an external point are equal in length. This short, elegant node proves both theorems and applies them to compute lengths and angles in tangent configurations, from bicycle chains to belt drives.", "prereqs": ["g9.geo.circles", "g9.geo.triangles"], "outcomes": ["Can define a tangent and distinguish it from a secant and a chord", "Can apply the theorem 'the tangent at any point is perpendicular to the radius through that point' in computations", "Can prove and use the equality of the two tangent lengths from an external point", "Can solve mixed problems combining tangents with Pythagoras and angle-chasing (e.g. the angle between two tangents)"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g10.geo.circles-tangents.tangent-secant-chord", "parent": "g10.geo.circles-tangents", "title": "Tangent vs Secant vs Chord", "description": "A secant cuts the circle at two points; a tangent touches it at exactly one (the point of contact); a chord joins two points on the circle. A tangent is the limiting position of a secant as its two intersection points merge.", "outcomes": ["Can define tangent, secant and chord and identify each in a figure", "Can state how many tangents pass through a point inside, on, and outside a circle (0, 1, 2)"], "prereqs": ["g9.geo.circles"], "est_minutes": 10, "difficulty": 2, "question": false}, {"id": "g10.geo.circles-tangents.tangent-radius-perpendicular", "parent": "g10.geo.circles-tangents", "title": "Tangent ⊥ Radius at the Point of Contact", "description": "The tangent at any point of a circle is perpendicular to the radius through that point — the right angle lives AT the point of contact. This turns every tangent problem into a right-triangle problem.", "outcomes": ["Can state and use the tangent-radius perpendicularity theorem with the right angle placed correctly", "Can compute tangent lengths from an external point using Pythagoras on triangle O-contact-external"], "prereqs": ["g10.geo.circles-tangents.tangent-secant-chord", "g10.geo.triangles-similarity.pythagoras-and-converse"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g10.geo.circles-tangents.equal-tangents-external-point", "parent": "g10.geo.circles-tangents", "title": "Equal Tangent Lengths from an External Point", "description": "The two tangent segments from an external point are equal: PA = PB, proved by RHS congruence of triangles OAP and OBP. Also, OP bisects the angle between the tangents.", "outcomes": ["Can prove PA = PB using RHS congruence built on the tangent-radius right angles", "Can chase equal tangent lengths around figures with several external points"], "prereqs": ["g10.geo.circles-tangents.tangent-radius-perpendicular", "g9.geo.triangles"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g10.geo.circles-tangents.angle-chasing-tangents", "parent": "g10.geo.circles-tangents", "title": "Angle Chasing with Tangents", "description": "In the kite OAPB formed by two tangents and two radii, the two contact angles are 90°, so ∠APB + ∠AOB = 180°. Combine this with isosceles triangles (OA = OB, PA = PB) to find any angle in the figure.", "outcomes": ["Can use the supplementary relation between the angle at the external point and the central angle", "Can find angles in figures mixing tangents, radii and chords"], "prereqs": ["g10.geo.circles-tangents.equal-tangents-external-point"], "est_minutes": 20, "difficulty": 4, "question": true}, {"id": "g10.geo.circles-tangents.circumscribed-figures", "parent": "g10.geo.circles-tangents", "title": "Circles Inside Polygons: Circumscribed Figures", "description": "When a polygon circumscribes a circle, every side is a tangent, so equal tangent lengths pair up around the figure. Key result: for a circumscribed quadrilateral, AB + CD = AD + BC.", "outcomes": ["Can prove AB + CD = AD + BC for a quadrilateral circumscribing a circle", "Can compute unknown sides and contact-segment lengths in circumscribed triangles and quadrilaterals"], "prereqs": ["g10.geo.circles-tangents.equal-tangents-external-point"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g10.geo.constructions", "title": "Constructions: Dividing Segments and Drawing Tangents", "grade": 10, "strand": "geo", "description": "Class 10 constructions are applied similarity and circle theory: divide a segment in any given ratio m:n, construct a triangle similar to a given one with a given scale factor, and draw the pair of tangents to a circle from an external point. Each construction must be justified — the parallel-line division leans on the Basic Proportionality Theorem, and the tangent construction leans on the angle in a semicircle being 90°.", "prereqs": ["g9.geo.constructions", "g10.geo.triangles-similarity", "g10.geo.circles-tangents"], "outcomes": ["Can divide a line segment internally in a given ratio m:n and justify the construction using the Basic Proportionality Theorem", "Can construct a triangle similar to a given triangle with a given scale factor (both smaller and larger than 1)", "Can construct the pair of tangents to a circle from an external point and justify why the construction works", "Can explain each construction's justification rather than merely reproduce its steps"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": [{"id": "g10.geo.constructions.divide-segment-ratio", "parent": "g10.geo.constructions", "title": "Dividing a Segment in a Given Ratio", "description": "To divide AB in ratio m : n, draw a ray from A, mark m + n equally spaced points with the compass, join the last point to B, and draw a parallel through the m-th point. The count is m + n — always.", "outcomes": ["Can divide a segment internally in ratio m : n with ruler and compass", "Can state why exactly m + n points are marked on the auxiliary ray"], "prereqs": ["g9.geo.constructions", "g10.geo.triangles-similarity.bpt-thales"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.geo.constructions.justify-segment-division", "parent": "g10.geo.constructions", "title": "Justifying the Division Construction", "description": "The parallel through the m-th point creates a BPT configuration: A₃C ∥ A₇B in triangle ABA₇ forces AC/CB = AA₃/A₃A₇ = m/n. Justification is the mathematical warranty, not decoration.", "outcomes": ["Can write the BPT-based justification of the segment-division construction", "Can explain why measuring the result is a check but never a proof"], "prereqs": ["g10.geo.constructions.divide-segment-ratio"], "est_minutes": 15, "difficulty": 4, "question": false}, {"id": "g10.geo.constructions.similar-triangle-smaller", "parent": "g10.geo.constructions", "title": "Constructing a Smaller Similar Triangle (Scale Factor < 1)", "description": "For scale factor m/n with m < n, mark n points on the ray from B, join the n-th to C, and draw a parallel through the m-th to cut BC. Complete with a parallel to AC. The copy sits inside the original.", "outcomes": ["Can construct a triangle similar to a given one with a fractional scale factor less than 1", "Can predict from the fraction alone that the image will be smaller than the original"], "prereqs": ["g10.geo.constructions.divide-segment-ratio", "g10.geo.triangles-similarity.similarity-and-scale-factor"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g10.geo.constructions.similar-triangle-larger", "parent": "g10.geo.constructions", "title": "Constructing a Larger Similar Triangle (Scale Factor > 1)", "description": "For scale factor m/n with m > n, mark m points (the larger number), join the n-th to C, and extend: the parallel through the m-th point lands BEYOND C, producing an enlarged copy.", "outcomes": ["Can construct a similar triangle with scale factor greater than 1, extending sides as needed", "Can decide from m/n vs 1 whether the construction shrinks or enlarges, and how many points to mark"], "prereqs": ["g10.geo.constructions.similar-triangle-smaller"], "est_minutes": 20, "difficulty": 4, "question": true}, {"id": "g10.geo.constructions.tangents-from-external-point", "parent": "g10.geo.constructions", "title": "Constructing Tangents from an External Point", "description": "Bisect OP, draw the circle on OP as diameter, and mark where it cuts the given circle: those are the contact points. Justification: the angle in a semicircle is 90°, giving the required tangent-radius perpendicularity.", "outcomes": ["Can construct the pair of tangents from an external point to a given circle", "Can justify the construction via the angle-in-a-semicircle theorem"], "prereqs": ["g10.geo.circles-tangents.tangent-radius-perpendicular", "g9.geo.constructions"], "est_minutes": 20, "difficulty": 4, "question": false}]}, {"id": "g10.tri.intro", "title": "Introduction to Trigonometry: Ratios and Identities", "grade": 10, "strand": "tri", "description": "Trigonometry begins with a right triangle and one acute angle: the ratios of its sides — sine, cosine, tangent and their reciprocals — depend only on the angle, not on the triangle's size. This node defines the six ratios, computes exact values at 0°, 30°, 45°, 60° and 90°, and proves and applies the fundamental identity sin²θ + cos²θ = 1 and its companions. These ratios are how astronomers measured the unreachable — and how you will, too.", "prereqs": ["g10.geo.triangles-similarity", "g7.geo.triangle-properties", "g6.num.ratio-proportion", "g9.num.number-systems"], "outcomes": ["Can define sin, cos, tan (and their reciprocals) for an acute angle of a right triangle and compute them from given sides", "Can recall and use the exact values of the trigonometric ratios at 0°, 30°, 45°, 60° and 90°", "Can find the remaining ratios when one ratio is given, using Pythagoras", "Can prove and apply the identities sin²θ + cos²θ = 1, 1 + tan²θ = sec²θ, 1 + cot²θ = cosec²θ"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g10.tri.intro.ratio-definitions", "parent": "g10.tri.intro", "title": "Defining sin, cos and tan in a Right Triangle", "description": "For an acute angle θ of a right triangle: sin θ = opposite/hypotenuse, cos θ = adjacent/hypotenuse, tan θ = opposite/adjacent. 'Opposite' and 'adjacent' are relative to θ — relabel when the angle changes.", "outcomes": ["Can compute sin, cos and tan of a specified angle from given triangle sides", "Can re-identify opposite and adjacent sides when the reference angle switches"], "prereqs": ["g10.geo.triangles-similarity.pythagoras-and-converse", "g6.num.ratio-proportion"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g10.tri.intro.ratios-are-size-free", "parent": "g10.tri.intro", "title": "Why the Ratios Depend Only on the Angle", "description": "Two right triangles sharing an acute angle are similar (AA), so their side ratios are identical: sin 30° is the same in a tiny triangle and a giant one. Trig ratios are properties of the ANGLE, not of the triangle.", "outcomes": ["Can argue via AA similarity that trigonometric ratios are independent of triangle size", "Can reject 'bigger triangle, bigger sine' with a concrete counterexample"], "prereqs": ["g10.tri.intro.ratio-definitions", "g10.geo.triangles-similarity.aa-similarity-criterion"], "est_minutes": 15, "difficulty": 3, "question": true}, {"id": "g10.tri.intro.reciprocal-ratios", "parent": "g10.tri.intro", "title": "The Reciprocal Ratios: cosec, sec, cot", "description": "cosec θ = 1/sin θ, sec θ = 1/cos θ, cot θ = 1/tan θ = cos θ/sin θ. Watch the criss-cross pairing: coSEC pairs with SIN, SEC pairs with COS.", "outcomes": ["Can compute all six ratios of an angle from a given right triangle", "Can convert between a ratio and its reciprocal without pairing errors"], "prereqs": ["g10.tri.intro.ratio-definitions"], "est_minutes": 10, "difficulty": 2, "question": false}, {"id": "g10.tri.intro.one-ratio-to-all", "parent": "g10.tri.intro", "title": "From One Ratio to All Six", "description": "Given one ratio, sketch a right triangle with matching sides, find the third side by Pythagoras, and read off the rest. Example: tan θ = 3/4 puts legs 3 and 4 in place, so the hypotenuse is 5.", "outcomes": ["Can construct a reference triangle from one given trigonometric ratio", "Can compute the remaining five ratios using Pythagoras"], "prereqs": ["g10.tri.intro.reciprocal-ratios"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.tri.intro.standard-angle-values", "parent": "g10.tri.intro", "title": "Exact Values at 0°, 30°, 45°, 60°, 90°", "description": "Derive the exact table from two triangles: the 45-45-90 (sides 1, 1, √2) and the half-equilateral 30-60-90 (sides 1, √3, 2). Values do NOT scale linearly with the angle: sin 60° ≠ 2 sin 30°.", "outcomes": ["Can recall or re-derive all standard values of sin, cos and tan at 0°, 30°, 45°, 60°, 90°", "Can evaluate numeric expressions like 2 tan²45° + cos²30° − sin²60° exactly"], "prereqs": ["g10.tri.intro.ratio-definitions"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.tri.intro.pythagorean-identity", "parent": "g10.tri.intro", "title": "The Identity sin²θ + cos²θ = 1", "description": "Divide a² + b² = c² by c² and the Pythagoras theorem becomes sin²θ + cos²θ = 1, true for every angle. Use it to trade sin for cos and to verify values from the standard table.", "outcomes": ["Can prove sin²θ + cos²θ = 1 from the Pythagoras theorem", "Can find cos θ from sin θ (or vice versa) without constructing the triangle"], "prereqs": ["g10.tri.intro.one-ratio-to-all", "g10.tri.intro.standard-angle-values"], "est_minutes": 15, "difficulty": 3, "question": false}, {"id": "g10.tri.intro.derived-identities-simplify", "parent": "g10.tri.intro", "title": "Derived Identities and Proving Simple Identities", "description": "Divide sin²θ + cos²θ = 1 by cos²θ or sin²θ to get 1 + tan²θ = sec²θ and 1 + cot²θ = cosec²θ. Use all three to simplify expressions and prove identities by reducing one side to the other.", "outcomes": ["Can derive and apply 1 + tan²θ = sec²θ and 1 + cot²θ = cosec²θ", "Can prove short identities by converting everything to sin and cos", "Can simplify expressions like sec²θ − tan²θ or (1 − cos²θ) cosec²θ instantly"], "prereqs": ["g10.tri.intro.pythagorean-identity"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g10.tri.applications", "title": "Applications of Trigonometry: Heights and Distances", "grade": 10, "strand": "tri", "description": "How tall is the tower you cannot climb, how far the ship you cannot reach? Stand somewhere, measure an angle of elevation or depression, and let trigonometry do the climbing. This node turns word descriptions into right-triangle diagrams, chooses the ratio that links the known and unknown sides (usually tan), and solves single- and double-triangle problems — the survey engineer's daily bread since long before lasers.", "prereqs": ["g10.tri.intro"], "outcomes": ["Can define and correctly place angles of elevation and depression in a diagram, both measured from the HORIZONTAL", "Can draw a correct right-triangle model from a verbal description, including observer height when given", "Can choose the appropriate trigonometric ratio and compute heights and distances using exact values (30°, 45°, 60°)", "Can solve two-triangle problems (two observation points, or two objects) by combining equations"], "difficulty": 4, "est_minutes": 70, "stub": false, "micros": [{"id": "g10.tri.applications.elevation-depression-definitions", "parent": "g10.tri.applications", "title": "Angles of Elevation and Depression", "description": "Both angles are measured FROM THE HORIZONTAL line of sight: elevation opens upward to a raised object, depression opens downward from an elevated observer. Alternate angles make the depression from A to B equal the elevation from B to A.", "outcomes": ["Can mark angles of elevation and depression correctly, always against the horizontal", "Can use the alternate-angle equality between depression from above and elevation from below"], "prereqs": ["g10.tri.intro.standard-angle-values", "g7.geo.lines-angles"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g10.tri.applications.diagram-from-description", "parent": "g10.tri.applications", "title": "Drawing the Right-Triangle Model", "description": "Convert words into a labelled right triangle: vertical heights, horizontal ground distances, and the slant line of sight are three DIFFERENT segments. Include the observer's height when given, and never swap slant with horizontal.", "outcomes": ["Can produce a correctly labelled diagram from a verbal description, distinguishing slant, vertical and horizontal lengths", "Can adjust the model for an observer of given height (adding a rectangle under the triangle)"], "prereqs": ["g10.tri.applications.elevation-depression-definitions"], "est_minutes": 15, "difficulty": 3, "question": false}, {"id": "g10.tri.applications.single-triangle-problems", "parent": "g10.tri.applications", "title": "Single-Triangle Heights and Distances", "description": "Pick the ratio that links the two sides in play — tan for opposite/adjacent (most common), sin or cos when the slant is involved — and solve with exact values for 30°, 45°, 60°.", "outcomes": ["Can choose the correct trigonometric ratio from the sides involved, not by habit", "Can compute heights and distances exactly, rationalising forms like 30/√3"], "prereqs": ["g10.tri.applications.diagram-from-description", "g10.tri.intro.standard-angle-values"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.tri.applications.two-position-problems", "parent": "g10.tri.applications", "title": "Two Observation Points: Walking-Toward Problems", "description": "One tower seen from two points gives two equations sharing the height. Typical: elevation grows from 30° to 60° after walking distance d toward the tower; subtract the horizontal distances to bring d in.", "outcomes": ["Can set up two tangent equations with a shared height and solve for the unknown", "Can manage exact-surd arithmetic like h√3 − h/√3 = d cleanly"], "prereqs": ["g10.tri.applications.single-triangle-problems"], "est_minutes": 25, "difficulty": 4, "question": false}, {"id": "g10.tri.applications.depression-two-object-problems", "parent": "g10.tri.applications", "title": "Depression Problems: Two Objects Below", "description": "From a lighthouse or building top, two depression angles to two objects give two horizontal distances from one height; subtract (same side) or add (opposite sides) to answer the question.", "outcomes": ["Can convert depression angles into base angles of right triangles via alternate angles", "Can decide whether to add or subtract the two computed distances from the geometry"], "prereqs": ["g10.tri.applications.single-triangle-problems"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g10.mea.areas-circles", "title": "Areas Related to Circles: Sectors and Segments", "grade": 10, "strand": "mea", "description": "A sector is a pizza slice, a segment is what a chord cuts off. This node computes arc lengths and sector areas as fractions (θ/360) of the whole circle's circumference and area, finds segment areas by subtracting the triangle from its sector, and handles combinations — flower beds on square lawns, wiper sweeps, and designs of overlapping circles. One idea powers it all: an angle's share of 360° is its share of the circle.", "prereqs": ["g7.mea.perimeter-area", "g6.num.ratio-proportion", "g10.tri.intro"], "outcomes": ["Can compute the arc length of a sector as (θ/360) × 2πr and its area as (θ/360) × πr²", "Can compute the perimeter of a sector (arc + two radii), distinguishing it from the arc length", "Can compute the area of a minor segment as sector area minus triangle area", "Can solve combination problems: sweeps of wiper blades, designs from squares and circles, grazing regions"], "difficulty": 3, "est_minutes": 65, "stub": false, "micros": [{"id": "g10.mea.areas-circles.circle-formula-review", "parent": "g10.mea.areas-circles", "title": "Warm-up: Circumference vs Area", "description": "Re-anchor C = 2πr (a length, in cm) and A = πr² (an area, in cm²) before fractions of circles appear — the unit check is the fastest way to tell them apart.", "outcomes": ["Can compute circumference and area of a circle fluently (with π and with 22/7)", "Can use units to decide which formula a question needs"], "prereqs": ["g7.mea.perimeter-area"], "est_minutes": 15, "difficulty": 1, "question": false}, {"id": "g10.mea.areas-circles.arc-length", "parent": "g10.mea.areas-circles", "title": "Arc Length as a Fraction of the Circumference", "description": "A sector's arc is (θ/360) of the full circumference 2πr. Build the fraction idea: the angle tells you what share of the circle you own.", "outcomes": ["Can compute arc length for any central angle", "Can explain why the fraction multiplies 2πr and not πr²"], "prereqs": ["g10.mea.areas-circles.circle-formula-review"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g10.mea.areas-circles.sector-area", "parent": "g10.mea.areas-circles", "title": "Area of a Sector", "description": "Sector area = (θ/360) × πr², the same share-of-the-circle fraction applied to the area formula. Contrast with arc length side by side.", "outcomes": ["Can compute the area of a sector for any central angle", "Can pick the correct base formula (2πr vs πr²) inside the fraction"], "prereqs": ["g10.mea.areas-circles.arc-length"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g10.mea.areas-circles.sector-perimeter", "parent": "g10.mea.areas-circles", "title": "Perimeter of a Sector: Arc Plus Two Radii", "description": "The boundary of a sector is the arc AND the two straight radii: P = arc + 2r. Trace the boundary with a finger before computing.", "outcomes": ["Can compute the perimeter of a sector as arc length + 2r", "Can decide from the question whether the arc alone or the full boundary is wanted"], "prereqs": ["g10.mea.areas-circles.arc-length"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g10.mea.areas-circles.segment-area", "parent": "g10.mea.areas-circles", "title": "Area of a Segment: Sector Minus Triangle", "description": "A chord splits the sector into a triangle and a segment: segment = sector − triangle. Compute the triangle with ½·base·height or ½r² sin θ for standard angles.", "outcomes": ["Can compute the area of a minor segment for 60°, 90°, 120° angles", "Can draw and label sector, chord, triangle and segment correctly"], "prereqs": ["g10.mea.areas-circles.sector-area", "g10.tri.intro.standard-angle-values"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g10.mea.areas-circles.combined-plane-figures", "parent": "g10.mea.areas-circles", "title": "Areas of Shaded and Combined Figures", "description": "Board-style shaded regions: circles inside squares, quadrants in corners, rings, flower designs. Strategy: name each region, then add/subtract whole-figure areas.", "outcomes": ["Can decompose a shaded region into standard figures with a labelled plan", "Can solve mixed square-circle-sector area problems accurately"], "prereqs": ["g10.mea.areas-circles.segment-area"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g10.mea.surface-volume", "title": "Surface Areas and Volumes: Combined Solids", "grade": 10, "strand": "mea", "description": "Real objects are combinations: a capsule is a cylinder with hemispherical ends, an ice-cream cone is a cone crowned by a hemisphere, a tent is a cylinder wearing a conical hat. This node computes surface areas of such composites (counting only the surfaces that actually show — glued faces vanish) and their volumes (which simply add), including melt-and-recast problems where one shape's volume becomes another's. It is Class 9 mensuration graduating into engineering.", "prereqs": ["g9.mea.surface-volume"], "outcomes": ["Can compute the surface area of a combined solid by summing only the EXPOSED surfaces of each component", "Can compute the volume of a combined solid by adding component volumes", "Can solve conversion problems (melting, recasting, pouring) using conservation of volume", "Can select the correct component formulas (CSA vs TSA, hemisphere vs sphere) for each part of a composite"], "difficulty": 4, "est_minutes": 80, "stub": false, "micros": [{"id": "g10.mea.surface-volume.formula-inventory", "parent": "g10.mea.surface-volume", "title": "Formula Inventory: CSA, TSA and Volume", "description": "Rebuild the table for cube, cuboid, cylinder, cone, sphere, hemisphere — separating curved surface, total surface (units²) and volume (units³) so they never swap.", "outcomes": ["Can state CSA, TSA and volume formulas for the six standard solids", "Can use dimensional units to catch a surface/volume formula swap"], "prereqs": ["g9.mea.surface-volume"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g10.mea.surface-volume.combined-surface-area", "parent": "g10.mea.surface-volume", "title": "Surface Area of Combined Solids", "description": "When solids are glued, the joined faces vanish inside: the surface of the combination is the sum of the EXPOSED (usually curved) surfaces only, never the sum of the TSAs.", "outcomes": ["Can identify which faces are exposed and which are hidden in a combined solid", "Can compute the surface area of toy (cone + hemisphere) and capsule-type solids"], "prereqs": ["g10.mea.surface-volume.formula-inventory"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g10.mea.surface-volume.combined-volume", "parent": "g10.mea.surface-volume", "title": "Volume of Combined Solids", "description": "Volumes simply add (and cavities subtract) because volume measures the space filled — unlike surface area, nothing vanishes at the joins.", "outcomes": ["Can compute the volume of a combined solid by adding component volumes", "Can subtract a carved-out or hollow part (e.g., a cavity or scooped hemisphere)"], "prereqs": ["g10.mea.surface-volume.combined-surface-area"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g10.mea.surface-volume.conversion-of-solids", "parent": "g10.mea.surface-volume", "title": "Melting and Recasting: Volume Is Conserved", "description": "When a solid is melted, remoulded or water is displaced, the VOLUME stays the same even though the shape and surface area change. Equate volumes to solve.", "outcomes": ["Can set up volume-of-old = volume-of-new equations for recasting problems", "Can find how many small solids a large one yields (and why the count scales with the cube)"], "prereqs": ["g10.mea.surface-volume.combined-volume"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g10.mea.surface-volume.word-problems-capacity", "parent": "g10.mea.surface-volume", "title": "Capacity, Water Level and Cost Problems", "description": "Full board problems: tents (canvas = surface, air = volume), tanks filling through pipes, water level rise when solids are dropped in, cost per m². Choose surface vs volume from what the question physically asks.", "outcomes": ["Can decide from context whether a quantity is a surface area or a volume", "Can solve multi-step capacity and cost problems with correct units"], "prereqs": ["g10.mea.surface-volume.conversion-of-solids"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g10.dat.statistics", "title": "Statistics: Mean, Median, Mode of Grouped Data; Ogives", "grade": 10, "strand": "dat", "description": "When data arrives pre-grouped into classes, the exact values are gone — so mean, median and mode must be estimated from the group structure: mean via class marks weighted by frequencies, median via the cumulative-frequency formula (or read off an ogive), and mode via the modal-class formula. This node teaches all three, the empirical bridge mode ≈ 3(median) − 2(mean), and when each measure is the right summary to report.", "prereqs": ["g9.dat.statistics", "g7.dat.data-handling-averages"], "outcomes": ["Can compute the mean of grouped data by the direct and assumed-mean methods using class marks and frequencies", "Can identify the modal class and median class of a grouped distribution", "Can compute the median of grouped data with the formula, and read it from an ogive at n/2", "Can apply the empirical relationship mode = 3(median) − 2(mean) and judge which average best represents a dataset"], "difficulty": 3, "est_minutes": 75, "stub": false, "micros": [{"id": "g10.dat.statistics.grouped-data-review", "parent": "g10.dat.statistics", "title": "Grouped Data: Class Marks and Cumulative Frequency", "description": "Set up the two working columns everything else depends on: class mark xᵢ = (lower + upper)/2 for each interval, and the running cumulative frequency (cf) column.", "outcomes": ["Can compute class marks and build a cumulative frequency column", "Can distinguish frequency of a class from cumulative frequency up to a class"], "prereqs": ["g9.dat.statistics", "g7.dat.data-handling-averages"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g10.dat.statistics.mean-direct-method", "parent": "g10.dat.statistics", "title": "Mean of Grouped Data: Direct Method", "description": "Mean = Σfᵢxᵢ / Σfᵢ — every class mark is WEIGHTED by its frequency. Contrast with the plain average of class marks to see why frequencies matter.", "outcomes": ["Can compute the mean of a grouped frequency table by the direct method", "Can explain why dividing by the number of classes gives a wrong answer"], "prereqs": ["g10.dat.statistics.grouped-data-review"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g10.dat.statistics.mean-assumed-step-deviation", "parent": "g10.dat.statistics", "title": "Assumed Mean and Step Deviation Methods", "description": "Shift by an assumed mean a (dᵢ = xᵢ − a) and optionally scale by h (uᵢ = dᵢ/h) to shrink the arithmetic; all three methods give the same mean.", "outcomes": ["Can compute a grouped mean by the assumed mean and step deviation methods", "Can verify that the shortcut agrees with the direct method"], "prereqs": ["g10.dat.statistics.mean-direct-method"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g10.dat.statistics.mode-of-grouped-data", "parent": "g10.dat.statistics", "title": "Mode of Grouped Data", "description": "Locate the modal class (highest frequency), then interpolate INSIDE it: mode = l + [(f₁ − f₀)/(2f₁ − f₀ − f₂)]·h. The mode is a data value, never a frequency.", "outcomes": ["Can identify the modal class and apply the mode formula correctly", "Can explain why the mode is pulled toward the stronger neighbouring class"], "prereqs": ["g10.dat.statistics.grouped-data-review"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g10.dat.statistics.median-of-grouped-data", "parent": "g10.dat.statistics", "title": "Median of Grouped Data", "description": "Find the class whose cumulative frequency first reaches n/2, then interpolate: median = l + [(n/2 − cf)/f]·h. The n/2 — not n — is the heart of the method.", "outcomes": ["Can locate the median class using the cf column and n/2", "Can apply the median formula with the PRECEDING class's cf"], "prereqs": ["g10.dat.statistics.grouped-data-review"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g10.dat.statistics.ogives", "parent": "g10.dat.statistics", "title": "Ogives and Reading the Median Graphically", "description": "Draw less-than and more-than ogives from cumulative frequencies; the median is the x-value at cumulative frequency n/2 — equivalently where the two ogives cross.", "outcomes": ["Can plot a less-than ogive from a cumulative frequency table", "Can read the median from an ogive at height n/2"], "prereqs": ["g10.dat.statistics.median-of-grouped-data"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g10.dat.probability", "title": "Probability: The Classical Approach", "grade": 10, "strand": "dat", "description": "When all outcomes are equally likely — a fair coin, an unloaded die, a well-shuffled deck — probability needs no experiment: P(E) = (favourable outcomes)/(total outcomes). This node counts outcomes carefully (including for two dice and two coins, where 'equally likely' takes real thought), uses complements, and locks in the boundaries: probabilities live in [0, 1], with 0 for impossible and 1 for certain events. It is the theoretical twin of Class 9's empirical approach.", "prereqs": ["g9.dat.probability-empirical"], "outcomes": ["Can compute classical probabilities by counting equally likely outcomes (coins, dice, cards, balls in bags)", "Can construct the full outcome set for compound experiments (two coins, two dice) and count favourable cases correctly", "Can use P(not E) = 1 − P(E) and identify impossible, sure and elementary events", "Can explain what a probability statement predicts about long-run frequency, and what it does not promise short-term"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g10.dat.probability.classical-definition", "parent": "g10.dat.probability", "title": "The Classical Definition of Probability", "description": "P(E) = favourable outcomes / total equally likely outcomes. Pin down the consequences: 0 ≤ P ≤ 1, P = 0 impossible, P = 1 sure — a probability is a proportion, never a raw count.", "outcomes": ["Can compute P(E) by counting favourable and total outcomes", "Can state and use the bounds 0 ≤ P(E) ≤ 1"], "prereqs": ["g9.dat.probability-empirical"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g10.dat.probability.equally-likely-outcomes", "parent": "g10.dat.probability", "title": "Counting Outcomes That Are Actually Equally Likely", "description": "The classical formula only works over equally likely outcomes. Two coins give the 4-outcome space HH, HT, TH, TT — not the 3 'kinds' 0, 1, 2 heads.", "outcomes": ["Can list a complete equally likely sample space for coins and dice", "Can spot when a proposed outcome list is not equally likely"], "prereqs": ["g10.dat.probability.classical-definition"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g10.dat.probability.single-event-problems", "parent": "g10.dat.probability", "title": "Cards, Dice and Balls: Single-Event Calculations", "description": "Fluency with the standard boards toolkit: the 52-card deck's structure (suits, colours, face cards), one die, and drawing from bags of counted balls.", "outcomes": ["Can compute probabilities for standard card-deck events (face card, red queen, not-an-ace)", "Can solve one-draw bag and die problems accurately"], "prereqs": ["g10.dat.probability.equally-likely-outcomes"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g10.dat.probability.complementary-events", "parent": "g10.dat.probability", "title": "Complementary Events: P(not E) = 1 − P(E)", "description": "E and not-E split certainty between them — and ONLY a complementary pair is guaranteed to sum to 1. Use the complement to shortcut 'at least one' and 'not' questions.", "outcomes": ["Can compute P(not E) from P(E) and recognise when the shortcut applies", "Can explain why two arbitrary events need not have probabilities summing to 1"], "prereqs": ["g10.dat.probability.classical-definition"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g10.dat.probability.independence-of-trials", "parent": "g10.dat.probability", "title": "What 1/6 Really Means: No Memory, No Quota", "description": "Probability describes long-run proportion, not a short-run quota: a fair coin or die has no memory, so past outcomes never shift the next trial's probability.", "outcomes": ["Can state the probability of the next trial after any streak", "Can explain the difference between P(a streak in advance) and P(next outcome)"], "prereqs": ["g10.dat.probability.classical-definition"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g10.dat.probability.two-stage-experiments", "parent": "g10.dat.probability", "title": "Two Dice and Other Two-Stage Experiments", "description": "Build the full 36-cell grid for two dice (ordered pairs!) and read event probabilities from it; extend to two coins + die and two draws with listing.", "outcomes": ["Can construct the 36-outcome table for two dice and count events in it", "Can compute probabilities for sums, doubles and comparisons of two dice"], "prereqs": ["g10.dat.probability.equally-likely-outcomes"], "est_minutes": 30, "difficulty": 4, "question": true}]}, {"id": "g11.alg.sets", "title": "Sets: Representation, Operations, Venn Diagrams", "grade": 11, "strand": "alg", "description": "Sets are the language in which the rest of higher mathematics is written: collections of well-defined objects, described in roster or set-builder form. You will operate on sets with union, intersection, difference and complement, picture them with Venn diagrams, and use counting rules like n(A∪B) = n(A) + n(B) − n(A∩B). Mastering this vocabulary pays off immediately in relations, functions and probability.", "prereqs": ["g9.num.number-systems"], "outcomes": ["Can write a set in roster and set-builder form and decide whether a collection is well-defined", "Can distinguish element membership (∈) from subset inclusion (⊂) and list all subsets of a small set", "Can compute union, intersection, difference and complement, and represent them on Venn diagrams", "Can use n(A∪B) = n(A) + n(B) − n(A∩B) to solve survey-style counting problems", "Can work with intervals of real numbers as sets and take complements within a universal set"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g11.alg.sets.set-notation", "parent": "g11.alg.sets", "title": "Roster and Set-Builder Notation", "description": "What makes a collection a set (well-definedness), and how to write the same set in roster form and set-builder form, translating fluently in both directions.", "outcomes": ["Can decide whether a described collection is well-defined enough to be a set", "Can convert between roster form and set-builder form for number sets like {x : x is an even natural number less than 10}"], "prereqs": ["g9.num.number-systems"], "est_minutes": 20, "difficulty": 1, "question": false}, {"id": "g11.alg.sets.types-of-sets", "parent": "g11.alg.sets", "title": "Empty, Finite, Infinite and Equal Sets", "description": "Classifying sets: the empty set (and why it is not {0}), singleton, finite vs infinite, and equality of sets independent of listing order or repetition.", "outcomes": ["Can identify whether a set is empty, singleton, finite or infinite and state n(A) for finite sets", "Can distinguish ∅, {0} and {∅} and explain why they are all different"], "prereqs": ["g11.alg.sets.set-notation"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g11.alg.sets.subsets-power-set", "parent": "g11.alg.sets", "title": "Subsets, Power Set and Intervals", "description": "Element membership (∈) versus subset inclusion (⊂), listing all subsets of a small set, the power set with its 2ⁿ count, and intervals as subsets of R.", "outcomes": ["Can correctly use ∈ vs ⊂ in statements like 2 ∈ A and {2} ⊂ A", "Can list all subsets of a set with up to 3 elements and compute n(P(A)) = 2ⁿ", "Can write intervals like [2, 5) as sets and mark them on the number line"], "prereqs": ["g11.alg.sets.types-of-sets"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g11.alg.sets.venn-union-intersection", "parent": "g11.alg.sets", "title": "Union, Intersection and Venn Diagrams", "description": "Computing A∪B and A∩B for given sets, representing them on Venn diagrams, and using the basic laws (commutative, associative, A∩A = A, A∪∅ = A).", "outcomes": ["Can compute unions and intersections of given sets, including intervals", "Can shade the region for a set expression like A∩B or (A∪B) on a two-set Venn diagram"], "prereqs": ["g11.alg.sets.subsets-power-set"], "est_minutes": 25, "difficulty": 2, "question": false}, {"id": "g11.alg.sets.difference-complement", "parent": "g11.alg.sets", "title": "Set Difference and Complement", "description": "A − B as 'in A but not in B' (and why A − B ≠ B − A), complements within a universal set, and De Morgan's laws seen on Venn diagrams.", "outcomes": ["Can compute A − B, B − A and A′ for given finite sets and intervals", "Can verify De Morgan's laws (A∪B)′ = A′∩B′ on a Venn diagram and with concrete sets"], "prereqs": ["g11.alg.sets.venn-union-intersection"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.alg.sets.counting-union", "parent": "g11.alg.sets", "title": "Counting with n(A∪B): Survey Problems", "description": "The inclusion-exclusion rule n(A∪B) = n(A) + n(B) − n(A∩B), applied to survey-style problems including 'neither' counts via the complement.", "outcomes": ["Can solve two-set survey problems for 'at least one', 'both' and 'neither' counts", "Can sanity-check answers against the total population (union cannot exceed it)"], "prereqs": ["g11.alg.sets.venn-union-intersection", "g11.alg.sets.difference-complement"], "est_minutes": 30, "difficulty": 3, "question": true}]}, {"id": "g11.alg.relations-functions", "title": "Relations and Functions: Domain, Range, Standard Functions", "grade": 11, "strand": "alg", "description": "A relation pairs elements of one set with another via the Cartesian product; a function is the special relation where every input gets exactly one output. You will find domains and ranges, and meet the standard function family — identity, constant, polynomial, rational, modulus, signum, greatest integer — with their graphs. Functions are the central objects of calculus, so fluency here directly powers limits and derivatives.", "prereqs": ["g11.alg.sets", "g8.alg.graphs-intro", "g9.geo.coordinate-geometry"], "outcomes": ["Can form Cartesian products and count/list relations from A to B", "Can decide whether a given relation (as pairs, arrow diagram or graph) is a function, citing the definition", "Can find the domain and range of algebraic functions involving fractions and square roots", "Can sketch and read graphs of identity, constant, modulus, signum and greatest-integer functions", "Can perform algebra of functions: sum, difference, product, quotient with correct domains"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": [{"id": "g11.alg.relations-functions.cartesian-product", "parent": "g11.alg.relations-functions", "title": "Ordered Pairs and Cartesian Products", "description": "Ordered pairs where (a, b) ≠ (b, a), the Cartesian product A × B, and counting n(A × B) = n(A) × n(B).", "outcomes": ["Can list A × B for small sets and locate it as a grid of points", "Can use n(A × B) = n(A)·n(B) and equality of ordered pairs to find unknowns"], "prereqs": ["g11.alg.sets.set-notation", "g9.geo.coordinate-geometry"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g11.alg.relations-functions.relations-arrow-diagrams", "parent": "g11.alg.relations-functions", "title": "Relations as Subsets of A × B", "description": "A relation from A to B as any subset of A × B, pictured with arrow diagrams; domain, codomain and range of a relation; counting relations as 2^(mn).", "outcomes": ["Can write a relation in roster and set-builder form and draw its arrow diagram", "Can read off the domain and range of a relation and count all relations from A to B"], "prereqs": ["g11.alg.relations-functions.cartesian-product"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g11.alg.relations-functions.function-definition", "parent": "g11.alg.relations-functions", "title": "When Is a Relation a Function?", "description": "The defining test: every input has exactly one output. Applying it to sets of pairs, arrow diagrams and graphs (vertical line test), while allowing many-to-one.", "outcomes": ["Can decide whether a relation given as pairs, arrows or a graph is a function, citing the definition", "Can explain why many-to-one is allowed but one-to-many is not"], "prereqs": ["g11.alg.relations-functions.relations-arrow-diagrams"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.alg.relations-functions.domain-range", "parent": "g11.alg.relations-functions", "title": "Domain and Range of Algebraic Functions", "description": "Finding natural domains via the danger scan (denominators ≠ 0, radicands ≥ 0) and ranges of simple rational and root functions; codomain vs range.", "outcomes": ["Can find the domain of functions like 1/(x²−9) and √(x−2) by excluding danger points", "Can find ranges of shifted squares and roots and distinguish range from codomain"], "prereqs": ["g11.alg.relations-functions.function-definition", "g9.num.number-systems"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g11.alg.relations-functions.standard-graphs", "parent": "g11.alg.relations-functions", "title": "Standard Functions and Their Graphs", "description": "The graph gallery: identity, constant, polynomial, rational 1/x, modulus |x|, signum and greatest-integer functions, with their domains, ranges and shapes.", "outcomes": ["Can sketch and label the graphs of |x|, sgn(x), [x] and 1/x", "Can read domain and range off each standard graph, including the jumps of [x]"], "prereqs": ["g11.alg.relations-functions.function-definition", "g8.alg.graphs-intro"], "est_minutes": 30, "difficulty": 3, "question": false}, {"id": "g11.alg.relations-functions.function-algebra", "parent": "g11.alg.relations-functions", "title": "Algebra of Real Functions", "description": "Building f + g, f − g, fg and f/g with correct (intersected, and quotient-restricted) domains — and why f(a + b) is generally NOT f(a) + f(b).", "outcomes": ["Can form sums, products and quotients of functions and state their domains", "Can evaluate expressions like f(x + h) correctly for f(x) = x² without illegal distribution"], "prereqs": ["g11.alg.relations-functions.domain-range"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g11.tri.functions", "title": "Trigonometric Functions: Radians, Identities, Graphs, Equations", "grade": 11, "strand": "tri", "description": "Trigonometry graduates from right-triangle ratios to genuine functions of a real number: angles in radians, the unit circle, signs in all four quadrants, and the wave-like graphs of sine and cosine. You will wield compound-angle and multiple-angle identities like sin(A±B), cos 2x, and solve trigonometric equations in full generality. These functions model every periodic phenomenon — sound, light, tides, alternating current — and their limits and derivatives are pillars of calculus.", "prereqs": ["g10.tri.intro", "g11.alg.relations-functions"], "outcomes": ["Can convert between degrees and radians and interpret radian measure as arc length over radius", "Can evaluate all six trigonometric functions at standard angles in any quadrant using the unit circle and sign rules", "Can sketch and interpret the graphs of sin, cos and tan, identifying period, amplitude and asymptotes", "Can apply compound-angle and double-angle identities such as sin(A+B), cos(A+B) and cos 2x to simplify and evaluate expressions", "Can write general solutions of equations like sin x = k, cos x = k, tan x = k"], "difficulty": 4, "est_minutes": 120, "stub": false, "micros": [{"id": "g11.tri.functions.radian-measure", "parent": "g11.tri.functions", "title": "Radian Measure and Degree Conversion", "description": "Radian as arc length over radius, the anchor π radians = 180°, converting both ways, and the arc-length formula l = rθ.", "outcomes": ["Can convert any angle between degrees and radians using π = 180°", "Can apply l = rθ (θ in radians) to arc-length problems"], "prereqs": ["g10.tri.intro"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g11.tri.functions.unit-circle-values", "parent": "g11.tri.functions", "title": "The Unit Circle and Standard Values", "description": "Redefining cos θ and sin θ as the (x, y) coordinates of a point on the unit circle, extending all six trigonometric functions to any real angle, with values at 0, π/6, π/4, π/3, π/2.", "outcomes": ["Can read sin and cos as coordinates on the unit circle for any rotation, including negative angles", "Can recall exact values of all six functions at the standard first-quadrant angles"], "prereqs": ["g11.tri.functions.radian-measure", "g10.tri.intro"], "est_minutes": 30, "difficulty": 3, "question": false}, {"id": "g11.tri.functions.quadrant-signs", "parent": "g11.tri.functions", "title": "Signs in the Four Quadrants", "description": "Deriving the sign of each trig function in each quadrant from unit-circle coordinates, then compressing with ASTC; evaluating functions of angles like 150°, 210°, 300°.", "outcomes": ["Can state the sign of any trig function in any quadrant from the (x, y) picture", "Can evaluate trig functions at non-first-quadrant standard angles using a reference angle plus a sign"], "prereqs": ["g11.tri.functions.unit-circle-values"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.tri.functions.allied-angles", "parent": "g11.tri.functions", "title": "Allied Angles and Reduction Formulas", "description": "Expressing trig functions of π ± x, π/2 ± x, 2π − x and −x in terms of functions of x, seen as reflections and rotations of the unit-circle point.", "outcomes": ["Can reduce expressions like cos(π − x) and sin(π/2 + x) to ± a function of x", "Can use even-odd properties: cos(−x) = cos x, sin(−x) = −sin x"], "prereqs": ["g11.tri.functions.quadrant-signs"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g11.tri.functions.graphs-periodicity", "parent": "g11.tri.functions", "title": "Graphs of sin, cos and tan; Period and Amplitude", "description": "Sketching the wave graphs of sine and cosine (period 2π, amplitude 1) and the branch-and-asymptote graph of tan (period π), and reading periodicity from them.", "outcomes": ["Can sketch sin, cos and tan over at least two periods with correct zeros, extremes and asymptotes", "Can determine the period and amplitude of variants like 3 sin 2x"], "prereqs": ["g11.tri.functions.unit-circle-values", "g11.alg.relations-functions.standard-graphs"], "est_minutes": 30, "difficulty": 3, "question": false}, {"id": "g11.tri.functions.compound-angles", "parent": "g11.tri.functions", "title": "Compound-Angle Identities", "description": "The identities for sin(A ± B), cos(A ± B) and tan(A ± B): why sin does NOT distribute over +, and using the formulas to evaluate angles like 15° and 75°.", "outcomes": ["Can expand sin(A ± B) and cos(A ± B) correctly, with the right sign structure", "Can compute exact values such as cos 75° and tan 15° from standard angles"], "prereqs": ["g11.tri.functions.allied-angles"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g11.tri.functions.multiple-angles", "parent": "g11.tri.functions", "title": "Double and Multiple Angle Identities", "description": "Deriving sin 2x, the three forms of cos 2x, tan 2x and sin 3x/cos 3x from the compound-angle identities, and choosing the convenient cos 2x form for a given problem.", "outcomes": ["Can derive and apply sin 2x = 2 sin x cos x and all three forms of cos 2x", "Can evaluate expressions like cos 2x from a given sin x without finding x"], "prereqs": ["g11.tri.functions.compound-angles"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g11.tri.functions.general-solutions", "parent": "g11.tri.functions", "title": "General Solutions of Trigonometric Equations", "description": "Solving sin x = k, cos x = k and tan x = k in full generality: principal solutions first, then the periodic families nπ + (−1)ⁿα, 2nπ ± α and nπ + α.", "outcomes": ["Can find all principal solutions of a basic trig equation in [0, 2π)", "Can write and justify the correct general-solution pattern for sin, cos and tan equations"], "prereqs": ["g11.tri.functions.graphs-periodicity", "g11.tri.functions.allied-angles"], "est_minutes": 30, "difficulty": 4, "question": true}]}, {"id": "g11.num.complex-quadratic", "title": "Complex Numbers and Quadratic Equations", "grade": 11, "strand": "num", "description": "To solve x² + 1 = 0 we extend the real numbers with i, where i² = −1, obtaining complex numbers a + bi with their own arithmetic, conjugates and modulus. Quadratic equations with negative discriminant now have two (conjugate) complex roots — the number system finally makes every quadratic solvable. Complex numbers are indispensable in AC circuit analysis, signal processing and quantum physics.", "prereqs": ["g10.alg.quadratic-equations", "g9.num.number-systems"], "outcomes": ["Can compute powers of i by reducing exponents modulo 4", "Can add, subtract, multiply and divide complex numbers, using the conjugate to rationalise quotients", "Can find the modulus and conjugate of a complex number and interpret a + bi as a point in the Argand plane", "Can solve quadratic equations with negative discriminant and express roots as conjugate pairs", "Can explain why rules like √a·√b = √(ab) fail when both a and b are negative"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": [{"id": "g11.num.complex-quadratic.iota-powers", "parent": "g11.num.complex-quadratic", "title": "The Imaginary Unit and Powers of i", "description": "Why i is introduced (solving x² + 1 = 0), the definition i² = −1, and the four-cycle i, −1, −i, 1 for reducing any power of i modulo 4.", "outcomes": ["Can state i² = −1 and evaluate i³, i⁴ and negative powers of i", "Can reduce iⁿ for large n by dividing the exponent by 4 and using the remainder"], "prereqs": ["g8.num.exponents-powers", "g10.alg.quadratic-equations"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g11.num.complex-quadratic.arithmetic", "parent": "g11.num.complex-quadratic", "title": "Adding, Subtracting and Multiplying Complex Numbers", "description": "Arithmetic with a + bi: combining real and imaginary parts, expanding products like binomials, and substituting i² = −1 explicitly in every expansion.", "outcomes": ["Can add, subtract and multiply complex numbers, simplifying every i² to −1", "Can equate real and imaginary parts to solve for unknowns"], "prereqs": ["g11.num.complex-quadratic.iota-powers", "g8.alg.expressions-identities"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.num.complex-quadratic.conjugate-division", "parent": "g11.num.complex-quadratic", "title": "Conjugates and Division", "description": "The conjugate a − bi, the key identity z·z̄ = a² + b², and dividing complex numbers by multiplying numerator and denominator by the conjugate.", "outcomes": ["Can find the conjugate of any complex number and compute z·z̄", "Can express a quotient of complex numbers in the standard form a + bi"], "prereqs": ["g11.num.complex-quadratic.arithmetic", "g9.num.number-systems"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.num.complex-quadratic.modulus-argand", "parent": "g11.num.complex-quadratic", "title": "Modulus and the Argand Plane", "description": "Plotting a + bi as the point (a, b), modulus |z| = √(a² + b²) as distance from the origin via Pythagoras, and why complex numbers themselves cannot be ordered.", "outcomes": ["Can plot complex numbers, their conjugates and negatives in the Argand plane", "Can compute |z| and explain why |z| values compare even though complex numbers do not"], "prereqs": ["g11.num.complex-quadratic.conjugate-division", "g9.geo.coordinate-geometry"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.num.complex-quadratic.sqrt-negatives", "parent": "g11.num.complex-quadratic", "title": "Square Roots of Negative Numbers", "description": "Writing √(−a) = i√a for a > 0, and the discipline of converting to i-form BEFORE multiplying — because √a·√b = √(ab) fails when both radicands are negative.", "outcomes": ["Can simplify expressions like √(−49) and √(−8) into i-form", "Can compute products of square roots of negatives correctly and explain the failing rule"], "prereqs": ["g11.num.complex-quadratic.iota-powers"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g11.num.complex-quadratic.quadratic-complex-roots", "parent": "g11.num.complex-quadratic", "title": "Quadratics with Negative Discriminant", "description": "Solving ax² + bx + c = 0 when b² − 4ac < 0: the two roots are complex conjugates (−b ± i√(4ac − b²))/2a, and every quadratic now has exactly two roots.", "outcomes": ["Can solve quadratics with negative discriminant and present roots in a + bi form", "Can verify that the two roots are conjugates and check them by substitution"], "prereqs": ["g11.num.complex-quadratic.sqrt-negatives", "g10.alg.quadratic-equations"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g11.alg.linear-inequalities", "title": "Linear Inequalities", "grade": 11, "strand": "alg", "description": "Inequalities describe ranges rather than single answers: solving them uses equation-like moves plus one crucial twist — multiplying or dividing by a negative number reverses the inequality sign. You will express solutions as intervals on the number line and handle systems of simultaneous inequalities. This is the toolkit behind constraints everywhere: budgets, safety limits, eligibility cut-offs, and later, linear programming.", "prereqs": ["g8.alg.linear-equations-1var", "g9.alg.linear-equations-2var"], "outcomes": ["Can solve linear inequalities in one variable, reversing the sign when multiplying/dividing by a negative", "Can express solution sets in interval notation and graph them on the number line", "Can solve a pair of simultaneous inequalities and intersect the solution sets", "Can translate word problems (marks, budgets, ranges) into inequalities and interpret the solution in context"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g11.alg.linear-inequalities.sign-flip-rules", "parent": "g11.alg.linear-inequalities", "title": "Operations on Inequalities and the Sign Flip", "description": "Which moves preserve an inequality (adding/subtracting anything, multiplying/dividing by positives) and the one that reverses it: multiplying or dividing by a negative.", "outcomes": ["Can solve one-step inequalities, reversing the sign exactly when multiplying/dividing by a negative", "Can verify a solution set by substituting a test value"], "prereqs": ["g8.alg.linear-equations-1var"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g11.alg.linear-inequalities.interval-notation", "parent": "g11.alg.linear-inequalities", "title": "Interval Notation and Number-Line Graphs", "description": "Writing solution sets three synchronized ways — inequality, interval, shaded number line — with open/closed brackets matched to strict/non-strict signs.", "outcomes": ["Can convert among inequality form, interval notation and number-line shading", "Can choose open vs closed endpoints by testing whether the boundary value satisfies the inequality"], "prereqs": ["g11.alg.sets.set-notation", "g9.num.number-systems"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g11.alg.linear-inequalities.solve-linear-1var", "parent": "g11.alg.linear-inequalities", "title": "Solving Linear Inequalities in One Variable", "description": "Multi-step inequalities with brackets and fractions, reported as full interval solution sets — an inequality's answer is a set of many values, not one boundary number.", "outcomes": ["Can solve inequalities like 3(x − 1) ≤ 2(x + 3) and present the answer as an interval and number line", "Can state whether specific values belong to the solution set"], "prereqs": ["g11.alg.linear-inequalities.sign-flip-rules", "g11.alg.linear-inequalities.interval-notation"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g11.alg.linear-inequalities.simultaneous-systems", "parent": "g11.alg.linear-inequalities", "title": "Simultaneous Inequalities: Intersecting Solutions", "description": "Solving two inequalities that must hold together: solve each, then take the INTERSECTION of the solution sets by overlaying number lines.", "outcomes": ["Can solve 'and'-joined systems and give the combined solution as a single interval", "Can explain why 'and' means intersection while 'or' would mean union"], "prereqs": ["g11.alg.linear-inequalities.solve-linear-1var", "g11.alg.sets.venn-union-intersection"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.alg.linear-inequalities.word-problems", "parent": "g11.alg.linear-inequalities", "title": "Modelling with Inequalities", "description": "Translating phrases — 'at least', 'at most', 'between', 'not more than' — into inequalities for marks, budgets and measurement ranges, then interpreting the solution in context.", "outcomes": ["Can set up and solve an inequality from a word problem, choosing strict vs non-strict correctly", "Can state the practical meaning of the boundary value"], "prereqs": ["g11.alg.linear-inequalities.solve-linear-1var"], "est_minutes": 30, "difficulty": 3, "question": true}]}, {"id": "g11.alg.permutations-combinations", "title": "Permutations and Combinations", "grade": 11, "strand": "alg", "description": "Counting without listing: the fundamental principle of counting multiplies choices made in sequence, factorials count arrangements, and the twin tools nPr and nCr count ordered selections versus unordered ones. The single most important skill is deciding whether order matters. These techniques power probability, the binomial theorem, and real questions from passwords to tournament fixtures.", "prereqs": ["g7.num.fractions-decimals-ops", "g7.alg.expressions"], "outcomes": ["Can apply the multiplication principle to multi-stage choice problems and the addition principle to exclusive cases", "Can compute and manipulate factorials, nPr and nCr, including simplifying quotients of factorials", "Can decide from context whether a problem needs permutations (order matters) or combinations (order doesn't)", "Can count arrangements with repeated objects (e.g. letters of APPLE) and selections with simple restrictions"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g11.alg.permutations-combinations.counting-principle", "parent": "g11.alg.permutations-combinations", "title": "The Fundamental Principle of Counting", "description": "Multiplying choices made in sequence (each stage's options available for every earlier choice) versus adding counts of mutually exclusive cases, seen through tree diagrams.", "outcomes": ["Can apply the multiplication principle to multi-stage problems like codes and outfits", "Can recognise when cases are exclusive and must be added instead"], "prereqs": ["g5.num.mult-div-large"], "est_minutes": 25, "difficulty": 2, "question": true}, {"id": "g11.alg.permutations-combinations.factorial-notation", "parent": "g11.alg.permutations-combinations", "title": "Factorials and Their Algebra", "description": "n! as the count of arrangements of n distinct objects, the convention 0! = 1, and simplifying factorial quotients like 8!/6! without full expansion.", "outcomes": ["Can evaluate and simplify expressions like 8!/6! and n!/(n−2)!", "Can justify 0! = 1 via the pattern n! = n·(n−1)!"], "prereqs": ["g11.alg.permutations-combinations.counting-principle", "g7.alg.expressions"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g11.alg.permutations-combinations.permutations-npr", "parent": "g11.alg.permutations-combinations", "title": "Permutations: nPr", "description": "Counting ordered arrangements of r objects from n distinct objects: nPr = n!/(n−r)! derived slot-by-slot from the multiplication principle.", "outcomes": ["Can compute nPr directly and via the slot method for codes, rankings and line-ups", "Can solve simple equations involving nPr"], "prereqs": ["g11.alg.permutations-combinations.factorial-notation"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g11.alg.permutations-combinations.repeated-objects", "parent": "g11.alg.permutations-combinations", "title": "Arrangements with Repeated Objects", "description": "Why identical objects shrink the count: n!/(p!·q!·...) for words like BANANA, dividing out the internal reorderings of each repeated letter.", "outcomes": ["Can count distinct arrangements of words with repeated letters", "Can explain the division by each repeat's factorial via the labelling argument"], "prereqs": ["g11.alg.permutations-combinations.permutations-npr"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.alg.permutations-combinations.combinations-ncr", "parent": "g11.alg.permutations-combinations", "title": "Combinations: nCr", "description": "Counting unordered selections: nCr = n!/(r!(n−r)!), built from nPr by dividing out the r! orderings of the chosen group, with the symmetry nCr = nC(n−r).", "outcomes": ["Can compute nCr efficiently, using symmetry to shrink the arithmetic", "Can derive nCr = nPr/r! and explain each factor's role"], "prereqs": ["g11.alg.permutations-combinations.permutations-npr"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.alg.permutations-combinations.order-or-not", "parent": "g11.alg.permutations-combinations", "title": "Deciding: Permutation or Combination?", "description": "The load-bearing skill: interrogating a context — arranging (line, code, ranking → P) versus choosing a group (committee, team, handshake → C) — including mixed problems with restrictions.", "outcomes": ["Can classify a word problem as permutation, combination or multi-stage mix before touching formulas", "Can solve selection-then-arrangement problems by chaining C and P steps"], "prereqs": ["g11.alg.permutations-combinations.combinations-ncr"], "est_minutes": 30, "difficulty": 4, "question": true}]}, {"id": "g11.alg.binomial-theorem", "title": "Binomial Theorem", "grade": 11, "strand": "alg", "description": "The binomial theorem expands (a + b)ⁿ without multiplying it out: each term is nCr a^(n−r) b^r, with coefficients readable from Pascal's triangle. You will find general terms, middle terms and specific coefficients, and handle expansions like (x − 2y)⁷ where signs alternate. It is the bridge between combinatorics and algebra, and later feeds probability distributions and approximations.", "prereqs": ["g11.alg.permutations-combinations", "g8.alg.expressions-identities", "g7.num.exponents-intro"], "outcomes": ["Can state and apply the binomial theorem for positive integral n, connecting coefficients to Pascal's triangle and nCr", "Can write the general term T(r+1) = nCr a^(n−r) b^r and use it to find any required term or coefficient", "Can handle expansions with negative or coefficient-bearing terms like (x − 2y)⁷ and (2x + 3)⁵, applying powers to the whole term", "Can count terms in an expansion and locate middle term(s)"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": [{"id": "g11.alg.binomial-theorem.pascal-coefficients", "parent": "g11.alg.binomial-theorem", "title": "Pascal's Triangle and Binomial Coefficients", "description": "Expanding (a+b)², (a+b)³ by hand to watch cross terms appear, reading coefficients from Pascal's triangle, and identifying each row entry as nCr.", "outcomes": ["Can build Pascal's triangle and match row n to the coefficients of (a+b)ⁿ", "Can explain via small cases why (a+b)ⁿ ≠ aⁿ + bⁿ"], "prereqs": ["g11.alg.permutations-combinations.combinations-ncr", "g8.alg.expressions-identities"], "est_minutes": 25, "difficulty": 2, "question": false}, {"id": "g11.alg.binomial-theorem.theorem-expansion", "parent": "g11.alg.binomial-theorem", "title": "The Binomial Theorem for Positive Integral n", "description": "The full statement (a+b)ⁿ = Σ nCr a^(n−r) b^r and writing complete expansions, tracking how powers of a fall while powers of b rise, always summing to n.", "outcomes": ["Can write the complete expansion of (a+b)ⁿ for small n with correct coefficients and exponents", "Can verify an expansion numerically, e.g. sum of coefficients = 2ⁿ at a = b = 1"], "prereqs": ["g11.alg.binomial-theorem.pascal-coefficients"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.alg.binomial-theorem.general-term", "parent": "g11.alg.binomial-theorem", "title": "The General Term T(r+1)", "description": "Using T(r+1) = nCr a^(n−r) b^r to reach any term directly: the k-th term corresponds to r = k − 1, since the first term has r = 0.", "outcomes": ["Can find a specified term of an expansion via the general term without expanding everything", "Can find the term containing a given power of x by solving for r"], "prereqs": ["g11.alg.binomial-theorem.theorem-expansion"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.alg.binomial-theorem.sign-and-coefficient-terms", "parent": "g11.alg.binomial-theorem", "title": "Expansions with Signs and Coefficients", "description": "Handling (x − 2y)ⁿ and (2x + 3)ⁿ: carrying (−b)^r as a unit so signs alternate as (−1)^r, and raising the WHOLE bracket (2x)^k, not just the variable.", "outcomes": ["Can compute any term of expansions like (x − 2y)⁷ with the correct sign", "Can find coefficients in expansions like (2x − 1)⁵, applying the power to the full 2x"], "prereqs": ["g11.alg.binomial-theorem.general-term"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g11.alg.binomial-theorem.term-count-middle", "parent": "g11.alg.binomial-theorem", "title": "Counting Terms and Middle Terms", "description": "An expansion of (a+b)ⁿ has n + 1 terms; locating the single middle term for even n and the two middle terms for odd n, including expansions like (x + 1/x)ⁿ.", "outcomes": ["Can state the number of terms and identify which position(s) are middle", "Can compute middle terms, simplifying powers when the terms involve 1/x"], "prereqs": ["g11.alg.binomial-theorem.general-term"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g11.alg.sequences-series", "title": "Sequences and Series: AP, GP, AM-GM, Special Sums", "grade": 11, "strand": "alg", "description": "Sequences follow rules; series add them up. Building on arithmetic progressions, you now master geometric progressions — nth term arⁿ⁻¹, finite sums, and the beautiful infinite sum a/(1−r) when |r| < 1 — plus the AM ≥ GM inequality and formulas for Σn, Σn², Σn³. Growth by a constant ratio is the mathematics of compound interest, population growth and radioactive decay.", "prereqs": ["g10.alg.arithmetic-progressions", "g7.num.exponents-intro"], "outcomes": ["Can identify whether a sequence is an AP, a GP or neither, and find common difference/ratio", "Can compute the nth term and the sum of n terms of a GP, and insert geometric means", "Can determine when an infinite GP has a finite sum and compute S∞ = a/(1−r)", "Can apply AM ≥ GM for two positive numbers and use Σn, Σn², Σn³ to evaluate special series"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g11.alg.sequences-series.ap-recap", "parent": "g11.alg.sequences-series", "title": "Arithmetic Progressions: Recap and Sigma View", "description": "Consolidating a + (n−1)d and Sₙ = (n/2)[2a + (n−1)d], testing every formula at n = 1, and meeting Σ notation for writing series compactly.", "outcomes": ["Can find the nth term and sum of an AP and check formulas at n = 1", "Can expand and evaluate simple sigma expressions like Σ(2k + 1)"], "prereqs": ["g10.alg.arithmetic-progressions"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g11.alg.sequences-series.gp-nth-term", "parent": "g11.alg.sequences-series", "title": "Geometric Progressions and the nth Term", "description": "Recognising constant-ratio sequences via the difference-vs-ratio test, and the nth term arⁿ⁻¹ where the exponent counts jumps from the first term.", "outcomes": ["Can decide whether a sequence is an AP, a GP or neither by testing differences and ratios", "Can compute any term of a GP with arⁿ⁻¹, verifying the formula returns a at n = 1"], "prereqs": ["g11.alg.sequences-series.ap-recap", "g7.num.exponents-intro"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.alg.sequences-series.gp-sum", "parent": "g11.alg.sequences-series", "title": "Sum of n Terms of a GP", "description": "Deriving Sₙ = a(rⁿ − 1)/(r − 1) by the multiply-and-subtract trick, applying it to doubling stories like the chessboard legend, and the special case r = 1.", "outcomes": ["Can compute finite GP sums and reproduce the multiply-by-r derivation", "Can handle the r = 1 case, where Sₙ = na"], "prereqs": ["g11.alg.sequences-series.gp-nth-term"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g11.alg.sequences-series.geometric-mean", "parent": "g11.alg.sequences-series", "title": "Geometric Means", "description": "The geometric mean √(ab) of two positive numbers, inserting k geometric means between two numbers, and GM as the middle term of a three-term GP.", "outcomes": ["Can compute the GM of two positive numbers and insert geometric means between them", "Can use the three-term GP trick a/r, a, ar in problems"], "prereqs": ["g11.alg.sequences-series.gp-nth-term", "g8.num.squares-roots"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g11.alg.sequences-series.infinite-gp", "parent": "g11.alg.sequences-series", "title": "Infinite GP: Convergence and S∞", "description": "Watching partial sums settle when |r| < 1 versus explode when |r| ≥ 1; the formula S∞ = a/(1 − r) and its mandatory pre-flight check |r| < 1.", "outcomes": ["Can decide whether an infinite GP has a finite sum before computing anything", "Can compute S∞ = a/(1 − r) for convergent GPs, including bouncing-ball style applications"], "prereqs": ["g11.alg.sequences-series.gp-sum"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g11.alg.sequences-series.am-gm", "parent": "g11.alg.sequences-series", "title": "The AM–GM Inequality", "description": "For positive numbers, (a + b)/2 ≥ √(ab) with equality only when a = b; proving it from (√a − √b)² ≥ 0 and using it for quick min-max facts.", "outcomes": ["Can compute AM and GM of a positive pair and verify AM ≥ GM", "Can state the positivity requirement and the exact equality condition"], "prereqs": ["g11.alg.sequences-series.geometric-mean"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g11.alg.sequences-series.special-sums", "parent": "g11.alg.sequences-series", "title": "Special Sums: Σn, Σn², Σn³", "description": "The closed forms n(n+1)/2, n(n+1)(2n+1)/6 and [n(n+1)/2]², and combining them with sigma algebra to sum series like Σ k(k + 2).", "outcomes": ["Can evaluate Σn, Σn² and Σn³ for a given n", "Can split a polynomial summand with sigma linearity and evaluate the pieces"], "prereqs": ["g11.alg.sequences-series.ap-recap"], "est_minutes": 30, "difficulty": 4, "question": true}]}, {"id": "g11.geo.straight-lines", "title": "Straight Lines: Slope, Forms of Equations, Distance", "grade": 11, "strand": "geo", "description": "Coordinate geometry turns lines into equations: slope measures steepness as tan of the inclination, and a line can be written in point-slope, two-point, slope-intercept, intercept or general form. Parallel lines share slopes; perpendicular slopes multiply to −1; and the distance from a point to a line has a crisp formula. This algebra-geometry dictionary is the foundation for conic sections, calculus tangents, and linear programming.", "prereqs": ["g10.geo.coordinate-geometry", "g9.alg.linear-equations-2var", "g10.tri.intro"], "outcomes": ["Can compute the slope of a line from two points or from its inclination, and interpret zero vs undefined slope", "Can write the equation of a line in point-slope, slope-intercept, two-point, intercept and general forms and convert between them", "Can apply parallelism (equal slopes) and perpendicularity (m₁m₂ = −1) conditions", "Can compute the distance from a point to a line and the distance between parallel lines"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g11.geo.straight-lines.slope-two-points", "parent": "g11.geo.straight-lines", "title": "Slope from Two Points and Inclination", "description": "Slope as rise over run, m = (y₂ − y₁)/(x₂ − x₁), tied to the inclination by m = tan θ — how much y changes per unit of x, like speed is distance per time.", "outcomes": ["Can compute the slope through two points with consistent coordinate order", "Can relate slope to inclination via m = tan θ and to steepness intuition"], "prereqs": ["g10.geo.coordinate-geometry", "g10.tri.intro"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g11.geo.straight-lines.horizontal-vertical", "parent": "g11.geo.straight-lines", "title": "Horizontal and Vertical Lines", "description": "y = c has slope 0 (flat road); x = k has UNDEFINED slope (rise/run divides by zero) and cannot be written as y = mx + c at all.", "outcomes": ["Can write equations of horizontal and vertical lines through a given point", "Can explain the difference between zero slope and undefined slope from rise/run"], "prereqs": ["g11.geo.straight-lines.slope-two-points"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g11.geo.straight-lines.parallel-perpendicular", "parent": "g11.geo.straight-lines", "title": "Parallel and Perpendicular Slope Conditions", "description": "Parallel lines share slopes; perpendicular lines have slopes multiplying to −1 (negative reciprocals), verified numerically before being used abstractly.", "outcomes": ["Can test parallelism and perpendicularity from slopes", "Can find the slope of a line perpendicular to a given line and verify m₁m₂ = −1"], "prereqs": ["g11.geo.straight-lines.slope-two-points"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g11.geo.straight-lines.point-slope-forms", "parent": "g11.geo.straight-lines", "title": "Point-Slope, Two-Point and Slope-Intercept Forms", "description": "Writing a line's equation from a point and slope (y − y₁ = m(x − x₁)), from two points, or from slope and y-intercept, and moving fluidly between these forms.", "outcomes": ["Can write the equation of a line from point + slope or from two points", "Can convert any of these forms into y = mx + c and read off m and c"], "prereqs": ["g11.geo.straight-lines.slope-two-points", "g9.alg.linear-equations-2var"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g11.geo.straight-lines.general-form-slope", "parent": "g11.geo.straight-lines", "title": "General Form and Intercepts", "description": "The general form ax + by + c = 0: extracting slope m = −a/b by solving for y (never by grabbing a coefficient), and the intercept form x/a + y/b = 1.", "outcomes": ["Can rearrange ax + by + c = 0 to find its slope and intercepts", "Can write a line from given x- and y-intercepts using the intercept form"], "prereqs": ["g11.geo.straight-lines.point-slope-forms"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.geo.straight-lines.point-line-distance", "parent": "g11.geo.straight-lines", "title": "Distance from a Point to a Line", "description": "The formula d = |ax₁ + by₁ + c|/√(a² + b²), plus the distance between parallel lines — the absolute value and the √(a² + b²) denominator are both non-negotiable.", "outcomes": ["Can compute the perpendicular distance from a point to a line in general form", "Can compute the distance between two parallel lines"], "prereqs": ["g11.geo.straight-lines.general-form-slope"], "est_minutes": 25, "difficulty": 4, "question": true}]}, {"id": "g11.geo.conic-sections", "title": "Conic Sections: Circle, Parabola, Ellipse, Hyperbola", "grade": 11, "strand": "geo", "description": "Slice a double cone at different angles and you get circles, parabolas, ellipses and hyperbolas — a single family of curves with standard equations: x² + y² = r², y² = 4ax, x²/a² + y²/b² = 1, x²/a² − y²/b² = 1. You will extract centres, foci, vertices, directrices, axes and eccentricity from these equations. Conics are the shapes of planetary orbits, satellite dishes, headlight reflectors and suspension-bridge cables.", "prereqs": ["g11.geo.straight-lines", "g10.alg.quadratic-equations"], "outcomes": ["Can write the equation of a circle from centre and radius, and complete the square to find them from the general form", "Can identify the focus, directrix, axis and latus rectum of a parabola in any of the four standard orientations", "Can find vertices, foci, eccentricity and axes lengths for ellipses and hyperbolas in standard form, using c² = a² − b² or c² = a² + b² appropriately", "Can classify which conic a given second-degree equation in standard form represents"], "difficulty": 4, "est_minutes": 120, "stub": false, "micros": [{"id": "g11.geo.conic-sections.circle-standard", "parent": "g11.geo.conic-sections", "title": "Circle: Centre-Radius Form", "description": "The equation (x − h)² + (y − k)² = r² from the distance definition of a circle; writing equations from centre and radius and reading them back, minding the sign of h, k.", "outcomes": ["Can write the equation of a circle from its centre and radius", "Can read centre and radius from centre-radius form, handling signs like (x + 2)²"], "prereqs": ["g10.geo.coordinate-geometry"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g11.geo.conic-sections.circle-general", "parent": "g11.geo.conic-sections", "title": "Circle: General Form and Completing the Square", "description": "Converting x² + y² + 2gx + 2fy + c = 0 to centre-radius form by completing the square, finding centre (−g, −f) and radius √(g² + f² − c).", "outcomes": ["Can complete the square to find the centre and radius from a general-form circle", "Can determine when a general second-degree equation fails to be a real circle (g² + f² − c < 0)"], "prereqs": ["g11.geo.conic-sections.circle-standard", "g10.alg.quadratic-equations"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.geo.conic-sections.parabola-standard", "parent": "g11.geo.conic-sections", "title": "Parabola: Focus, Directrix and Latus Rectum", "description": "The four standard parabolas y² = ±4ax, x² = ±4ay: solving 4a = coefficient as an explicit step, then locating the focus, directrix, axis and latus rectum (length 4a).", "outcomes": ["Can identify orientation, focus and directrix for any of the four standard parabolas", "Can use the latus rectum to sanity-check the focus position"], "prereqs": ["g11.geo.conic-sections.circle-standard", "g11.geo.straight-lines.horizontal-vertical"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g11.geo.conic-sections.ellipse-standard", "parent": "g11.geo.conic-sections", "title": "Ellipse: Standard Form and Foci", "description": "x²/a² + y²/b² = 1 with a > b: vertices, major/minor axes, and the focal relation c² = a² − b² (subtract, because the foci sit INSIDE, c < a); eccentricity e = c/a.", "outcomes": ["Can extract vertices, foci, axis lengths and eccentricity from a standard ellipse", "Can determine the major axis direction from which denominator is larger"], "prereqs": ["g11.geo.conic-sections.parabola-standard"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g11.geo.conic-sections.hyperbola-standard", "parent": "g11.geo.conic-sections", "title": "Hyperbola: Standard Form and Foci", "description": "x²/a² − y²/b² = 1: two branches, vertices (±a, 0), and the focal relation c² = a² + b² (add, because the foci lie BEYOND the vertices, c > a); eccentricity e = c/a > 1.", "outcomes": ["Can extract vertices, foci, transverse axis and eccentricity from a standard hyperbola", "Can justify c² = a² + b² geometrically (foci beyond vertices) and contrast it with the ellipse"], "prereqs": ["g11.geo.conic-sections.ellipse-standard"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g11.geo.conic-sections.eccentricity-dial", "parent": "g11.geo.conic-sections", "title": "Eccentricity: One Dial for All Conics", "description": "Eccentricity as 'distance from circular': e = 0 circle, 0 < e < 1 ellipse, e = 1 parabola, e > 1 hyperbola — one parameter morphing the whole conic family.", "outcomes": ["Can compute e = c/a for ellipses and hyperbolas and check it lands in the right range", "Can name the conic from its eccentricity alone"], "prereqs": ["g11.geo.conic-sections.ellipse-standard", "g11.geo.conic-sections.hyperbola-standard"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g11.geo.conic-sections.classify-conic", "parent": "g11.geo.conic-sections", "title": "Classifying a Conic from Its Equation", "description": "The checklist for second-degree equations: equal positive squared coefficients → circle; unequal, both positive → ellipse; opposite signs → hyperbola; one squared variable → parabola.", "outcomes": ["Can classify equations like x² + 2y² = 4, x² − 4y² = 4 and y² = 6x at sight", "Can normalise an equation (divide by the constant) into a standard form before extracting parameters"], "prereqs": ["g11.geo.conic-sections.eccentricity-dial"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g11.vec.intro-3d", "title": "Introduction to Three-Dimensional Geometry", "grade": 11, "strand": "vec", "description": "Adding a z-axis turns the coordinate plane into coordinate space: points become ordered triples (x, y, z), space splits into eight octants, and the familiar tools upgrade — distance becomes √(Δx² + Δy² + Δz²) and the section formula gains a third coordinate. Thinking in 3D coordinates is the gateway to vectors, planes and lines in space, and to how GPS, drones and graphics engines locate anything in the world.", "prereqs": ["g10.geo.coordinate-geometry"], "outcomes": ["Can locate and interpret points (x, y, z), including which coordinate planes and octants they relate to", "Can state the coordinates of points on the axes and coordinate planes (which coordinates vanish where)", "Can compute the distance between two points in space and use it to classify triangles or verify collinearity", "Can apply the section formula (internal division) and midpoint formula in 3D"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": [{"id": "g11.vec.intro-3d.axes-octants", "parent": "g11.vec.intro-3d", "title": "Coordinate Axes and Octants", "description": "Adding the z-axis: the room-corner model with three mutually perpendicular axes, ordered triples (x, y, z), and the eight octants determined by sign patterns.", "outcomes": ["Can locate a point (x, y, z) relative to the room-corner model", "Can name the octant of a point from the signs of its coordinates"], "prereqs": ["g10.geo.coordinate-geometry"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g11.vec.intro-3d.coordinate-planes", "parent": "g11.vec.intro-3d", "title": "Points on Coordinate Planes and Axes", "description": "Which coordinates vanish where: on the xy-plane z = 0, on an axis TWO coordinates vanish — the missing coordinate measures how far you have left that plane.", "outcomes": ["Can state the zero-coordinate conditions for each coordinate plane and axis", "Can find the foot of the perpendicular from a point to a coordinate plane or axis"], "prereqs": ["g11.vec.intro-3d.axes-octants"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g11.vec.intro-3d.distance-formula", "parent": "g11.vec.intro-3d", "title": "Distance Between Two Points in Space", "description": "Deriving √(Δx² + Δy² + Δz²) as Pythagoras applied twice — the box diagonal: floor diagonal first, then up the wall — and computing distances between points.", "outcomes": ["Can compute the distance between two points in 3D including the z-term", "Can reproduce the double-Pythagoras derivation with a room/box picture"], "prereqs": ["g11.vec.intro-3d.coordinate-planes", "g10.geo.coordinate-geometry"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.vec.intro-3d.distance-applications", "parent": "g11.vec.intro-3d", "title": "Applications of the 3D Distance Formula", "description": "Using distances to classify triangles (isosceles, equilateral, right-angled via Pythagoras), verify collinearity, and find points equidistant from given points.", "outcomes": ["Can classify a triangle in space from its three side lengths", "Can test collinearity by checking whether one distance equals the sum of the other two"], "prereqs": ["g11.vec.intro-3d.distance-formula"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g11.vec.intro-3d.section-formula", "parent": "g11.vec.intro-3d", "title": "Section and Midpoint Formulas in 3D", "description": "Internal division in ratio m:n gives ((mx₂ + nx₁)/(m+n), ...) — the ratio parts attach to the OPPOSITE endpoints — with the midpoint as the 1:1 special case.", "outcomes": ["Can find the point dividing a segment internally in a given ratio and the midpoint", "Can estimate the answer's position first (e.g. 2:1 lands two-thirds along) to catch swapped ratios"], "prereqs": ["g11.vec.intro-3d.distance-formula"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g11.cal.limits-derivatives", "title": "Limits and Derivatives", "grade": 11, "strand": "cal", "description": "Calculus begins here: a limit captures the value a function approaches — which may exist even where the function itself is undefined, as in (x²−4)/(x−2) at x = 2. The derivative is a limit of slopes of secants, giving the exact instantaneous rate of change and the slope of the tangent line. You will evaluate algebraic and trigonometric limits (including sin x/x → 1), differentiate from first principles, and use the sum, product and quotient rules. Every 'rate' in science — velocity, current, growth — is a derivative.", "prereqs": ["g11.alg.relations-functions", "g10.alg.quadratic-equations", "g11.tri.functions", "g11.geo.straight-lines"], "outcomes": ["Can explain a limit intuitively via left- and right-hand approach, and evaluate limits by substitution where valid", "Can resolve 0/0 forms by factoring, rationalising, or standard limits like lim (xⁿ−aⁿ)/(x−a) = naⁿ⁻¹ and lim sin x/x = 1", "Can compute a derivative from first principles as the limit of a difference quotient", "Can interpret the derivative as instantaneous rate of change and as the slope of the tangent line", "Can differentiate polynomials and trigonometric functions using sum, product and quotient rules"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": [{"id": "g11.cal.limits-derivatives.limit-intuition-tables", "parent": "g11.cal.limits-derivatives", "title": "Limit Intuition via Tables", "description": "The limit as the value a function approaches: tabulating f(x) on both sides of a point and watching values crowd a target — which can exist even where f itself is undefined.", "outcomes": ["Can estimate a limit numerically from two-sided tables", "Can give an example where lim x→a f(x) exists although f(a) is undefined"], "prereqs": ["g11.alg.relations-functions.domain-range"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.cal.limits-derivatives.limit-laws", "parent": "g11.cal.limits-derivatives", "title": "Limit Laws and Algebraic Evaluation", "description": "Sum, product and quotient laws for limits; direct substitution for polynomials; and resolving 0/0 forms by factoring or rationalising — 0/0 means 'investigate', never a verdict.", "outcomes": ["Can evaluate limits of polynomial and rational functions by substitution where valid", "Can resolve 0/0 limits by factoring or by rationalising with a conjugate"], "prereqs": ["g11.cal.limits-derivatives.limit-intuition-tables"], "est_minutes": 30, "difficulty": 3, "question": false}, {"id": "g11.cal.limits-derivatives.one-sided-limits", "parent": "g11.cal.limits-derivatives", "title": "One-Sided Limits and Existence", "description": "Left-hand and right-hand limits, and the existence criterion: the limit exists iff both one-sided limits exist and agree — tested on step-like functions such as |x|/x and [x].", "outcomes": ["Can compute LHL and RHL at a point from a formula or graph", "Can decide whether a two-sided limit exists and justify with both one-sided values"], "prereqs": ["g11.cal.limits-derivatives.limit-intuition-tables", "g11.alg.relations-functions.standard-graphs"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.cal.limits-derivatives.standard-limits-sinx-over-x", "parent": "g11.cal.limits-derivatives", "title": "Standard Limits: sin x/x and (xⁿ − aⁿ)/(x − a)", "description": "The two workhorse limits — sin x/x → 1 as x → 0 (x in radians) and (xⁿ − aⁿ)/(x − a) → naⁿ⁻¹ — and the rescaling discipline: sin kx must sit over kx before the limit applies.", "outcomes": ["Can evaluate limits like sin 3x/2x and tan x/x by rescaling to the standard form", "Can apply (xⁿ − aⁿ)/(x − a) → naⁿ⁻¹ including fractional n"], "prereqs": ["g11.cal.limits-derivatives.limit-laws", "g11.tri.functions.radian-measure"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g11.cal.limits-derivatives.derivative-as-slope", "parent": "g11.cal.limits-derivatives", "title": "The Derivative as Slope and Instantaneous Rate", "description": "Secant slopes over shrinking intervals rotating into the tangent: the derivative as the slope of the tangent line and the speedometer-reading instantaneous rate, versus the trip-average rate.", "outcomes": ["Can distinguish average rate (secant slope) from instantaneous rate (tangent slope) in context", "Can interpret f'(a) graphically as tangent slope and physically as a rate at one instant"], "prereqs": ["g11.cal.limits-derivatives.limit-intuition-tables", "g11.geo.straight-lines.slope-two-points"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.cal.limits-derivatives.first-principles", "parent": "g11.cal.limits-derivatives", "title": "Derivative from First Principles", "description": "Computing f'(x) = lim h→0 [f(x+h) − f(x)]/h for polynomials and simple roots: expand carefully, cancel the h, THEN take the limit.", "outcomes": ["Can differentiate x², x³ and 1/x from first principles, showing every step", "Can explain why the h must be cancelled before letting h → 0"], "prereqs": ["g11.cal.limits-derivatives.derivative-as-slope", "g11.cal.limits-derivatives.limit-laws"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g11.cal.limits-derivatives.derivative-rules-power-sum", "parent": "g11.cal.limits-derivatives", "title": "Power, Constant and Sum Rules", "description": "The power rule d/dx xⁿ = nxⁿ⁻¹, constants passing through, derivatives of sums and differences — differentiating any polynomial term by term.", "outcomes": ["Can differentiate polynomials like 3x⁴ − 2x + 7 fluently", "Can differentiate sin x and cos x and combine them linearly with polynomials"], "prereqs": ["g11.cal.limits-derivatives.first-principles"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.cal.limits-derivatives.product-quotient-rules", "parent": "g11.cal.limits-derivatives", "title": "Product and Quotient Rules", "description": "(fg)' = f'g + fg' — each factor takes a turn — and the quotient rule with its order-sensitive numerator; why (fg)' = f'g' fails even for x·x.", "outcomes": ["Can differentiate products like x cos x and quotients like sin x/x correctly", "Can produce the counterexample showing (fg)' ≠ f'g'"], "prereqs": ["g11.cal.limits-derivatives.derivative-rules-power-sum", "g11.tri.functions.graphs-periodicity"], "est_minutes": 30, "difficulty": 4, "question": true}]}, {"id": "g11.dat.statistics", "title": "Statistics: Measures of Dispersion, Variance, Standard Deviation", "grade": 11, "strand": "dat", "description": "Two datasets can share a mean yet behave completely differently — dispersion measures how spread out the data is. You will compute range, mean deviation, variance and standard deviation for ungrouped and grouped data, and compare the consistency of two datasets using the coefficient of variation. Standard deviation is the workhorse of real analytics, from batting consistency to quality control and finance risk.", "prereqs": ["g10.dat.statistics"], "outcomes": ["Can compute range, mean deviation (about mean or median), variance and standard deviation for ungrouped and grouped data", "Can explain why deviations are squared (or absolute-valued) — raw deviations from the mean always sum to zero", "Can predict the effect on mean, variance and SD of adding a constant to, or scaling, every observation", "Can compare consistency of two datasets with different means using the coefficient of variation CV = (σ/x̄)×100"], "difficulty": 3, "est_minutes": 75, "stub": false, "micros": [{"id": "g11.dat.statistics.dispersion-range", "parent": "g11.dat.statistics", "title": "Why Dispersion? Range as a First Measure", "description": "Two datasets with the same mean can behave completely differently — motivating spread measures, starting with range = max − min and its sensitivity to outliers.", "outcomes": ["Can compute the range and explain what it does and does not capture", "Can give two datasets with equal means but visibly different spreads"], "prereqs": ["g10.dat.statistics"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g11.dat.statistics.mean-deviation", "parent": "g11.dat.statistics", "title": "Mean Deviation about Mean and Median", "description": "Why raw deviations from the mean always sum to zero (the balance point), and fixing it with absolute values: mean deviation for ungrouped and grouped data.", "outcomes": ["Can show Σ(xᵢ − x̄) = 0 for a dataset and explain the see-saw picture", "Can compute mean deviation about the mean or median for small datasets"], "prereqs": ["g11.dat.statistics.dispersion-range"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g11.dat.statistics.variance-sd-ungrouped", "parent": "g11.dat.statistics", "title": "Variance and Standard Deviation (Ungrouped)", "description": "Squaring as the other fix for cancelling deviations: variance σ² as mean squared deviation, and SD σ = √variance so the units return to the data's own units.", "outcomes": ["Can compute variance and SD for ungrouped data via deviations from the mean", "Can state the unit of each (data in cm → variance in cm², SD in cm) and why SD is never negative"], "prereqs": ["g11.dat.statistics.mean-deviation", "g8.num.squares-roots"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g11.dat.statistics.sd-grouped-data", "parent": "g11.dat.statistics", "title": "Variance and SD of Grouped Data", "description": "Extending to frequency distributions: σ² = (1/N)Σfᵢ(xᵢ − x̄)² with class midpoints, and the computational shortcut formula to tame the arithmetic.", "outcomes": ["Can compute variance and SD for a frequency distribution using midpoints", "Can apply the shortcut σ² = (1/N)Σfᵢxᵢ² − x̄² and know when it saves work"], "prereqs": ["g11.dat.statistics.variance-sd-ungrouped", "g10.dat.statistics"], "est_minutes": 30, "difficulty": 4, "question": false}, {"id": "g11.dat.statistics.transformation-effects", "parent": "g11.dat.statistics", "title": "Effect of Shifting and Scaling on Mean and SD", "description": "Adding a constant slides the whole dot-plot — mean shifts, gaps (and SD) untouched; multiplying by k stretches gaps — mean scales by k, SD by |k|, variance by k².", "outcomes": ["Can predict the new mean, variance and SD after x → x + c or x → kx without recomputing", "Can explain with the dot-plot picture why shifts leave SD alone"], "prereqs": ["g11.dat.statistics.variance-sd-ungrouped"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.dat.statistics.coefficient-of-variation", "parent": "g11.dat.statistics", "title": "Coefficient of Variation and Consistency", "description": "Comparing spread across datasets with different scales: CV = (σ/x̄) × 100 divides out the mean, making 'more consistent' a fair, unit-free comparison.", "outcomes": ["Can compute CV and use it to rank datasets by consistency", "Can explain why raw SD comparisons mislead when means differ widely"], "prereqs": ["g11.dat.statistics.variance-sd-ungrouped"], "est_minutes": 25, "difficulty": 3, "question": true}]}, {"id": "g11.dat.probability", "title": "Probability: Random Experiments and the Axiomatic Approach", "grade": 11, "strand": "dat", "description": "Probability is rebuilt on set theory: a random experiment has a sample space, events are subsets, and probability is a function obeying three axioms — non-negativity, P(S) = 1, and additivity for mutually exclusive events. From these flow the complement rule P(not A) = 1 − P(A) and the addition rule P(A∪B) = P(A) + P(B) − P(A∩B). This foundation supports everything from weather forecasts to insurance and machine learning.", "prereqs": ["g10.dat.probability", "g11.alg.sets", "g11.alg.permutations-combinations"], "outcomes": ["Can describe sample spaces and events as sets for experiments like coin tosses, dice and card draws", "Can identify mutually exclusive and exhaustive events and state the axioms of probability", "Can apply the complement rule and the addition rule P(A∪B) = P(A) + P(B) − P(A∩B)", "Can combine counting techniques (permutations/combinations) with equally-likely outcomes to compute probabilities", "Can recognise impossible probability values (outside [0, 1])"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": [{"id": "g11.dat.probability.sample-spaces", "parent": "g11.dat.probability", "title": "Random Experiments and Sample Spaces", "description": "Describing the full outcome set of an experiment — coins, dice, draws — as a set S, and events as subsets, with careful listing before any probability is computed.", "outcomes": ["Can list sample spaces for multi-stage experiments (three coins, two dice) systematically", "Can express events like 'sum is 7' as explicit subsets and count them"], "prereqs": ["g10.dat.probability", "g11.alg.sets.set-notation"], "est_minutes": 25, "difficulty": 2, "question": false}, {"id": "g11.dat.probability.event-algebra", "parent": "g11.dat.probability", "title": "Types of Events and Event Algebra", "description": "Complementary events, 'A or B' as union, 'A and B' as intersection, and the precise meanings of mutually exclusive (disjoint) versus exhaustive (covering S).", "outcomes": ["Can build compound events with union, intersection and complement", "Can classify event pairs as mutually exclusive and/or exhaustive with justification"], "prereqs": ["g11.dat.probability.sample-spaces", "g11.alg.sets.difference-complement"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.dat.probability.axioms", "parent": "g11.dat.probability", "title": "The Axioms of Probability", "description": "Probability as a function on events obeying three axioms — P(E) ≥ 0, P(S) = 1, additivity for disjoint events — and range-checking every answer against [0, 1].", "outcomes": ["Can state the three axioms and check whether a proposed assignment of probabilities is valid", "Can reject impossible values (negative or above 1) on sight"], "prereqs": ["g11.dat.probability.event-algebra"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.dat.probability.complement-rule", "parent": "g11.dat.probability", "title": "The Complement Rule and 'At Least One'", "description": "P(not A) = 1 − P(A) derived from the axioms, and the workhorse pattern: P(at least one ...) = 1 − P(none) — finishing the subtraction every time.", "outcomes": ["Can compute probabilities of complements and 'at least one' events efficiently", "Can decide when the complement shortcut beats direct enumeration"], "prereqs": ["g11.dat.probability.axioms"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g11.dat.probability.addition-rule", "parent": "g11.dat.probability", "title": "The Addition Rule", "description": "P(A∪B) = P(A) + P(B) − P(A∩B), inherited straight from n(A∪B) in Sets; the first written line of every solution is 'are the events mutually exclusive?'.", "outcomes": ["Can apply the addition rule with and without overlap, e.g. 'king or heart' from a deck", "Can detect the double-count error when an answer exceeds 1"], "prereqs": ["g11.dat.probability.axioms", "g11.alg.sets.counting-union"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g11.dat.probability.counting-probability", "parent": "g11.dat.probability", "title": "Probability via Counting Techniques", "description": "Combining nCr counting with equally likely outcomes: P(E) = favourable/total for draws and selections — after verifying the outcomes really are equally likely.", "outcomes": ["Can compute probabilities of card and committee selections using combinations", "Can spot and reject bogus 50-50 reasoning by listing or counting the true sample space"], "prereqs": ["g11.dat.probability.axioms", "g11.alg.permutations-combinations.combinations-ncr"], "est_minutes": 30, "difficulty": 4, "question": true}]}, {"id": "g12.alg.relations-functions", "title": "Relations and Functions: Types, Composition, Invertibility", "grade": 12, "strand": "alg", "description": "Functions acquire structure: relations can be reflexive, symmetric, transitive (equivalence relations), and functions can be one-one (injective), onto (surjective) or both (bijective). Composition chains functions together — (g∘f)(x) = g(f(x)) — and exactly the bijective functions can be undone by an inverse. Invertibility is the deep idea behind every 'decode', 'undo' and 'solve for x' in mathematics, and behind encryption itself.", "prereqs": ["g11.alg.relations-functions", "g11.alg.sets"], "outcomes": ["Can test a relation for reflexivity, symmetry and transitivity and identify equivalence relations and their classes", "Can prove or disprove that a function is one-one and/or onto, with counterexamples where needed", "Can compute compositions g∘f and f∘g, respecting order, and give examples where they differ", "Can decide whether a function is invertible and find f⁻¹ explicitly for simple bijections", "Can restrict domain/codomain to make a non-invertible function invertible"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g12.alg.relations-functions.relation-types", "parent": "g12.alg.relations-functions", "title": "Reflexive, Symmetric and Transitive Relations", "description": "Test a relation on a set for reflexivity, symmetry and transitivity from its defining rule or its list of ordered pairs, producing counterexamples where a property fails.", "outcomes": ["Can check each of the three properties for a relation given as pairs or as a rule", "Can produce a specific counterexample pair whenever a property fails"], "prereqs": ["g11.alg.sets", "g11.alg.relations-functions"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.alg.relations-functions.equivalence-relations", "parent": "g12.alg.relations-functions", "title": "Equivalence Relations and Equivalence Classes", "description": "Recognise relations that are reflexive, symmetric and transitive as equivalence relations, and describe the partition of the set into equivalence classes (e.g. congruence modulo n).", "outcomes": ["Can verify that a relation is an equivalence relation", "Can list the equivalence classes of relations like 'a ≡ b (mod 3)' and explain why classes partition the set"], "prereqs": ["g12.alg.relations-functions.relation-types"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.alg.relations-functions.one-one-functions", "parent": "g12.alg.relations-functions", "title": "One-one (Injective) Functions", "description": "Prove a function is one-one by showing f(x1) = f(x2) forces x1 = x2, or disprove it with two distinct inputs sharing an output; read injectivity off a graph with the horizontal line test.", "outcomes": ["Can prove or disprove injectivity algebraically", "Can state the difference between 'every input has one output' (function) and 'distinct inputs have distinct outputs' (one-one)"], "prereqs": ["g11.alg.relations-functions"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.alg.relations-functions.onto-functions", "parent": "g12.alg.relations-functions", "title": "Onto (Surjective) Functions", "description": "Decide whether every element of the codomain is attained: solve f(x) = y for arbitrary y in the codomain, or exhibit a y with no pre-image. Contrast range with codomain.", "outcomes": ["Can prove or disprove surjectivity for functions like f: R→R, f(x) = x² or f(x) = 2x + 3", "Can adjust the codomain to make a given function onto"], "prereqs": ["g12.alg.relations-functions.one-one-functions"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.alg.relations-functions.composition", "parent": "g12.alg.relations-functions", "title": "Composition of Functions", "description": "Compute (g∘f)(x) = g(f(x)), feeding the output of the inner function into the outer one, and show with examples that g∘f and f∘g generally differ.", "outcomes": ["Can compute g∘f and f∘g for algebraic and trigonometric functions", "Can give an example where g∘f ≠ f∘g and explain why order matters"], "prereqs": ["g11.alg.relations-functions"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.alg.relations-functions.invertibility", "parent": "g12.alg.relations-functions", "title": "Invertible Functions and Finding f⁻¹", "description": "A function has an inverse exactly when it is one-one and onto (bijective). Find f⁻¹ for simple bijections by solving y = f(x) for x, and verify f⁻¹∘f = identity.", "outcomes": ["Can state and apply the bijectivity criterion for invertibility", "Can compute f⁻¹ explicitly for functions like f(x) = 3x + 2 or f(x) = (x−1)/(x+2)", "Can distinguish f⁻¹(x) from the reciprocal 1/f(x)"], "prereqs": ["g12.alg.relations-functions.one-one-functions", "g12.alg.relations-functions.onto-functions", "g12.alg.relations-functions.composition"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.alg.relations-functions.domain-restriction", "parent": "g12.alg.relations-functions", "title": "Restricting Domain and Codomain to Force Invertibility", "description": "A non-bijective function becomes invertible after restricting its domain (to make it one-one) and shrinking its codomain to the range (to make it onto), e.g. x² on [0, ∞).", "outcomes": ["Can choose a restricted domain and codomain that make functions like x² or sin x bijective", "Can explain why the restriction is necessary before an inverse can exist"], "prereqs": ["g12.alg.relations-functions.invertibility"], "est_minutes": 20, "difficulty": 4, "question": false}]}, {"id": "g12.tri.inverse-functions", "title": "Inverse Trigonometric Functions", "grade": 12, "strand": "tri", "description": "Sine, cosine and tangent are periodic, so they can only be inverted after restricting to principal branches: sin⁻¹ maps [−1,1] to [−π/2, π/2], cos⁻¹ to [0, π], tan⁻¹ to (−π/2, π/2). You will evaluate principal values, simplify expressions like sin⁻¹(sin x) — which is NOT always x — and use identities such as sin⁻¹x + cos⁻¹x = π/2. These functions are how calculators, surveyors and navigation systems recover angles from ratios, and their derivatives unlock whole families of integrals.", "prereqs": ["g11.tri.functions", "g12.alg.relations-functions"], "outcomes": ["Can state the principal-value branches (domain and range) of sin⁻¹, cos⁻¹ and tan⁻¹", "Can evaluate principal values such as sin⁻¹(1/2), cos⁻¹(−1/2), tan⁻¹(−1)", "Can simplify sin⁻¹(sin x) and cos⁻¹(cos x) when x lies outside the principal branch", "Can apply identities like sin⁻¹x + cos⁻¹x = π/2 and interpret graphs of inverse trig functions as reflections in y = x"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": [{"id": "g12.tri.inverse-functions.inverse-idea", "parent": "g12.tri.inverse-functions", "title": "What sin⁻¹x Means (and Doesn't)", "description": "sin⁻¹x is the inverse FUNCTION of a restricted sine, not the reciprocal 1/sin x. Because sine is not one-one on R, its domain must be cut down before an inverse can exist.", "outcomes": ["Can explain why sin, cos, tan need restricted domains to be invertible", "Can distinguish sin⁻¹x from cosec x = 1/sin x in notation and meaning"], "prereqs": ["g12.alg.relations-functions.domain-restriction", "g11.tri.functions"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g12.tri.inverse-functions.principal-branches", "parent": "g12.tri.inverse-functions", "title": "Principal-value Branches: Domains and Ranges", "description": "Memorise and justify the principal branches: sin⁻¹: [−1,1] → [−π/2, π/2], cos⁻¹: [−1,1] → [0, π], tan⁻¹: R → (−π/2, π/2), and why these particular intervals are chosen.", "outcomes": ["Can state domain and range of sin⁻¹, cos⁻¹, tan⁻¹ without error", "Can explain why cos⁻¹ needs [0, π] rather than [−π/2, π/2]"], "prereqs": ["g12.tri.inverse-functions.inverse-idea"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g12.tri.inverse-functions.principal-values", "parent": "g12.tri.inverse-functions", "title": "Evaluating Principal Values", "description": "Evaluate expressions like sin⁻¹(1/2), cos⁻¹(−1/2), tan⁻¹(−1), landing in the correct principal branch — especially for negative arguments where sin⁻¹ and tan⁻¹ give negative angles but cos⁻¹ gives an angle in (π/2, π].", "outcomes": ["Can evaluate inverse trig expressions at standard values in the correct branch", "Can use sin⁻¹(−x) = −sin⁻¹x and cos⁻¹(−x) = π − cos⁻¹x correctly"], "prereqs": ["g12.tri.inverse-functions.principal-branches"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.tri.inverse-functions.simplify-compositions", "parent": "g12.tri.inverse-functions", "title": "Simplifying sin⁻¹(sin x) and cos⁻¹(cos x)", "description": "sin⁻¹(sin x) = x only when x is inside [−π/2, π/2]; otherwise the answer is the angle in the principal branch with the same sine. Fold arbitrary angles back into the branch using symmetry.", "outcomes": ["Can evaluate sin⁻¹(sin x) and cos⁻¹(cos x) for x outside the principal branch", "Can explain why blind cancellation fails using the graph of sin⁻¹(sin x)"], "prereqs": ["g12.tri.inverse-functions.principal-values"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g12.tri.inverse-functions.identities-graphs", "parent": "g12.tri.inverse-functions", "title": "Identities and Graphs of Inverse Trig Functions", "description": "Use identities such as sin⁻¹x + cos⁻¹x = π/2 and tan⁻¹x + cot⁻¹x = π/2, and interpret the graphs of sin⁻¹, cos⁻¹, tan⁻¹ as reflections of the restricted originals in the line y = x.", "outcomes": ["Can apply sin⁻¹x + cos⁻¹x = π/2 to evaluate and simplify expressions", "Can sketch inverse trig graphs by reflecting the restricted trig graphs in y = x"], "prereqs": ["g12.tri.inverse-functions.principal-values"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g12.alg.matrices", "title": "Matrices: Operations, Transpose, Invertibility", "grade": 12, "strand": "alg", "description": "A matrix is a rectangular array of numbers that adds entry-wise but multiplies by a row-into-column rule — an operation that is famously NOT commutative and defined only when inner dimensions match. You will master matrix algebra, transposes, symmetric and skew-symmetric matrices, and meet invertible matrices. Matrices encode simultaneous equations, graphics transformations, network links and the entire machinery of modern machine learning.", "prereqs": ["g8.alg.expressions-identities", "g10.alg.linear-pair-2var"], "outcomes": ["Can state the order of a matrix and decide when sums and products are defined", "Can add, scalar-multiply and multiply matrices using the row-by-column rule", "Can give examples showing AB ≠ BA and explain why matrix algebra identities differ from number algebra", "Can compute transposes and classify matrices as symmetric or skew-symmetric", "Can explain why AB = O does not force A = O or B = O, and recognise identity and invertible matrices"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g12.alg.matrices.matrix-basics", "parent": "g12.alg.matrices", "title": "Matrix Notation, Order and Types", "description": "A matrix is a rectangular array a_ij with i indexing rows and j columns. Identify order m×n, equality of matrices, and special types: row, column, square, diagonal, scalar, identity, zero.", "outcomes": ["Can state the order of a matrix and locate the entry a_ij", "Can classify matrices by type and use equality to solve for unknown entries"], "prereqs": ["g8.alg.expressions-identities"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g12.alg.matrices.add-scalar-multiply", "parent": "g12.alg.matrices", "title": "Matrix Addition and Scalar Multiplication", "description": "Add matrices of the same order entrywise and multiply a matrix by a scalar; use the algebra of these operations (commutativity, associativity, additive inverse) to solve matrix equations like 2X + A = B.", "outcomes": ["Can add, subtract and scalar-multiply matrices of matching orders", "Can solve simple matrix equations for an unknown matrix X"], "prereqs": ["g12.alg.matrices.matrix-basics"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g12.alg.matrices.matrix-multiplication", "parent": "g12.alg.matrices", "title": "Matrix Multiplication: the Row-by-Column Rule", "description": "Multiply an m×n matrix by an n×p matrix: the (i,j) entry is the dot product of row i with column j. Check compatibility of orders before multiplying — and never multiply entry-by-entry.", "outcomes": ["Can decide when a product AB is defined and state its order", "Can compute 2×2 and 3×3 products accurately with the row-by-column rule"], "prereqs": ["g12.alg.matrices.add-scalar-multiply"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g12.alg.matrices.non-commutativity", "parent": "g12.alg.matrices", "title": "Why AB ≠ BA: Matrix Algebra Identities", "description": "Matrix multiplication is associative and distributive but NOT commutative. Consequently number-algebra identities mutate: (A+B)² = A² + AB + BA + B², and (A+B)(A−B) = A² − AB + BA − B².", "outcomes": ["Can produce a concrete pair with AB ≠ BA", "Can expand (A+B)² and (A+B)(A−B) correctly without merging AB and BA"], "prereqs": ["g12.alg.matrices.matrix-multiplication"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.alg.matrices.zero-divisors", "parent": "g12.alg.matrices", "title": "AB = O Without A = O or B = O", "description": "Unlike numbers, matrices have zero divisors: nonzero matrices can multiply to the zero matrix, and AB = AC does not allow cancelling A. Build and verify explicit examples.", "outcomes": ["Can exhibit nonzero A, B with AB = O", "Can explain why cancellation fails and connect it to A not being invertible"], "prereqs": ["g12.alg.matrices.matrix-multiplication"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g12.alg.matrices.transpose-symmetric", "parent": "g12.alg.matrices", "title": "Transpose, Symmetric and Skew-symmetric Matrices", "description": "Form the transpose by swapping rows and columns; use (AB)ᵀ = BᵀAᵀ. Classify square matrices as symmetric (Aᵀ = A) or skew-symmetric (Aᵀ = −A), and split any square matrix into a symmetric plus skew-symmetric part.", "outcomes": ["Can compute transposes and apply (A + B)ᵀ, (kA)ᵀ, (AB)ᵀ rules", "Can verify symmetry/skew-symmetry and write A = (A + Aᵀ)/2 + (A − Aᵀ)/2"], "prereqs": ["g12.alg.matrices.matrix-multiplication"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.alg.matrices.invertible-matrices", "parent": "g12.alg.matrices", "title": "Identity Matrix and Invertibility", "description": "The identity matrix I satisfies AI = IA = A. A square matrix A is invertible when some B gives AB = BA = I; the inverse is unique, and (AB)⁻¹ = B⁻¹A⁻¹. Verification by direct multiplication.", "outcomes": ["Can verify a proposed inverse by computing AB and BA", "Can state and use uniqueness of the inverse and the reversal rule (AB)⁻¹ = B⁻¹A⁻¹"], "prereqs": ["g12.alg.matrices.matrix-multiplication", "g12.alg.matrices.non-commutativity"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g12.alg.determinants", "title": "Determinants: Properties, Adjoint, Inverse, Solving Systems", "grade": 12, "strand": "alg", "description": "The determinant condenses a square matrix into a single number that decides everything: invertibility (|A| ≠ 0), the area/volume scaling of the transformation, and solvability of linear systems. You will evaluate 2×2 and 3×3 determinants by cofactor expansion, exploit row/column properties, build inverses via the adjoint A⁻¹ = adj(A)/|A|, and solve systems by the matrix method. It is the algebraic gatekeeper between unique solutions and degeneracy.", "prereqs": ["g12.alg.matrices", "g10.alg.linear-pair-2var"], "outcomes": ["Can evaluate 2×2 and 3×3 determinants by cofactor expansion along any row or column", "Can apply determinant properties: effect of row swaps, common factors, identical rows, and |kA| = kⁿ|A|", "Can compute minors, cofactors and the adjoint, and find A⁻¹ = adj(A)/|A| when |A| ≠ 0", "Can use determinants to test consistency and solve systems of linear equations by the matrix method", "Can interpret |A| = 0 as the matrix being singular (non-invertible) and compute areas of triangles via determinants"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g12.alg.determinants.det-2x2", "parent": "g12.alg.determinants", "title": "2×2 Determinants and What They Detect", "description": "Compute |[[a, b], [c, d]]| = ad − bc, connect a zero determinant to the rows being proportional (singular matrix), and to a pair of linear equations having no unique solution.", "outcomes": ["Can evaluate 2×2 determinants quickly and accurately", "Can link |A| = 0 to proportional rows and to non-unique solutions of linear systems"], "prereqs": ["g12.alg.matrices.matrix-basics", "g10.alg.linear-pair-2var"], "est_minutes": 15, "difficulty": 2, "question": false}, {"id": "g12.alg.determinants.minors-cofactors", "parent": "g12.alg.determinants", "title": "Minors and Cofactors", "description": "The minor M_ij deletes row i and column j and takes the determinant of what remains; the cofactor C_ij = (−1)^(i+j) M_ij attaches the checkerboard sign. Fluency here prevents sign errors in every later computation.", "outcomes": ["Can compute any minor and cofactor of a 3×3 matrix", "Can reproduce the (−1)^(i+j) sign checkerboard from the formula rather than memory"], "prereqs": ["g12.alg.determinants.det-2x2"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g12.alg.determinants.cofactor-expansion-3x3", "parent": "g12.alg.determinants", "title": "Evaluating 3×3 Determinants by Cofactor Expansion", "description": "Expand a 3×3 determinant along any row or column as Σ a_ij C_ij, choosing the row or column with the most zeros. Confirm the answer is independent of the row chosen.", "outcomes": ["Can expand along any row or column and get the same value", "Can pick the expansion line strategically to minimise arithmetic"], "prereqs": ["g12.alg.determinants.minors-cofactors"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.alg.determinants.determinant-properties", "parent": "g12.alg.determinants", "title": "Properties of Determinants", "description": "Row swaps flip the sign; a common factor of one row comes out once, so |kA| = kⁿ|A| for an n×n matrix; identical or proportional rows force zero; |AB| = |A||B| but |A + B| ≠ |A| + |B| in general.", "outcomes": ["Can predict the effect of row operations on a determinant", "Can apply |kA| = kⁿ|A| and |AB| = |A||B|, and refute |A+B| = |A|+|B| with a counterexample"], "prereqs": ["g12.alg.determinants.cofactor-expansion-3x3"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g12.alg.determinants.adjoint-inverse", "parent": "g12.alg.determinants", "title": "Adjoint and Inverse of a Matrix", "description": "adj A is the transpose of the cofactor matrix; A · adj A = |A| I, so A⁻¹ = adj A / |A| whenever |A| ≠ 0. A matrix with |A| = 0 is singular and has no inverse.", "outcomes": ["Can compute adj A for 2×2 and 3×3 matrices", "Can compute A⁻¹ = adj A / |A| and verify AA⁻¹ = I", "Can recognise singular matrices as non-invertible"], "prereqs": ["g12.alg.determinants.cofactor-expansion-3x3", "g12.alg.matrices.invertible-matrices"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.alg.determinants.matrix-method-systems", "parent": "g12.alg.determinants", "title": "Solving Linear Systems by the Matrix Method", "description": "Write a system as AX = B and solve X = A⁻¹B when |A| ≠ 0. When |A| = 0, use (adj A)B to distinguish inconsistent systems from ones with infinitely many solutions.", "outcomes": ["Can solve 2- and 3-variable systems via X = A⁻¹B", "Can classify a system as unique / inconsistent / infinite using |A| and (adj A)B"], "prereqs": ["g12.alg.determinants.adjoint-inverse"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g12.cal.continuity-differentiability", "title": "Continuity and Differentiability", "grade": 12, "strand": "cal", "description": "Continuity at a point demands three things: f(a) exists, the limit exists, and they are equal — 'the pen never leaves the paper'. Differentiability is stronger: the graph must also be smooth, so |x| is continuous everywhere yet not differentiable at its corner. You will test piecewise functions, then differentiate everything in sight — composites via the chain rule, implicit relations, exponential and logarithmic functions, and parametric forms. This is the technical engine room of calculus.", "prereqs": ["g11.cal.limits-derivatives", "g12.alg.relations-functions", "g12.tri.inverse-functions"], "outcomes": ["Can test continuity at a point via left limit, right limit and function value, including for piecewise functions", "Can determine parameter values that make a piecewise function continuous", "Can explain with examples why differentiability implies continuity but not conversely (|x| at 0)", "Can differentiate composite functions with the chain rule, including trig, exponential and logarithmic compositions", "Can perform implicit differentiation, logarithmic differentiation and parametric differentiation, and compute second derivatives"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": [{"id": "g12.cal.continuity-differentiability.continuity-at-a-point", "parent": "g12.cal.continuity-differentiability", "title": "Continuity at a Point: the Three-part Test", "description": "f is continuous at a exactly when the left limit, right limit and f(a) all exist AND are equal. Apply the test to piecewise and rational functions, and classify what fails when a function is discontinuous.", "outcomes": ["Can run the three-part continuity test at a point", "Can name which ingredient fails (limit missing, value missing, or unequal) in a discontinuity"], "prereqs": ["g11.cal.limits-derivatives"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.cal.continuity-differentiability.continuity-parameters", "parent": "g12.cal.continuity-differentiability", "title": "Choosing Parameters for Continuity of Piecewise Functions", "description": "Given a piecewise function with an unknown constant (e.g. f(x) = kx² for x ≤ 2, f(x) = 3 for x > 2), equate the one-sided limits and the value at the joint to solve for the constant.", "outcomes": ["Can set up and solve the matching equation at the junction point", "Can verify the resulting function is continuous by re-running the three-part test"], "prereqs": ["g12.cal.continuity-differentiability.continuity-at-a-point"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g12.cal.continuity-differentiability.differentiability-vs-continuity", "parent": "g12.cal.continuity-differentiability", "title": "Differentiability Implies Continuity — Not Conversely", "description": "Differentiability at a point requires equal left-hand and right-hand derivatives. Every differentiable function is continuous, but |x| at 0 is continuous with a corner: continuity does not buy smoothness.", "outcomes": ["Can check differentiability by comparing one-sided derivatives", "Can state and instantiate the one-way implication with |x| at 0"], "prereqs": ["g12.cal.continuity-differentiability.continuity-at-a-point", "g11.cal.limits-derivatives"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g12.cal.continuity-differentiability.chain-rule", "parent": "g12.cal.continuity-differentiability", "title": "The Chain Rule for Composite Functions", "description": "Differentiate f(g(x)) as f′(g(x)) · g′(x): outer derivative evaluated at the inner function, times the inner derivative. Drill on trig, power and nested compositions until the inner factor is never dropped.", "outcomes": ["Can differentiate compositions like sin(x²), (3x² + 1)⁵, cos³x", "Can handle double compositions such as sin(cos(x²))"], "prereqs": ["g11.cal.limits-derivatives"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.cal.continuity-differentiability.implicit-differentiation", "parent": "g12.cal.continuity-differentiability", "title": "Implicit Differentiation and Inverse Trig Derivatives", "description": "Differentiate relations like x² + y² = 25 term-by-term, attaching dy/dx to every y-derivative via the chain rule, then solve for dy/dx. Derive and use d/dx sin⁻¹x = 1/√(1−x²) and d/dx tan⁻¹x = 1/(1+x²).", "outcomes": ["Can find dy/dx from an implicit relation", "Can differentiate expressions containing sin⁻¹, cos⁻¹, tan⁻¹"], "prereqs": ["g12.cal.continuity-differentiability.chain-rule", "g12.tri.inverse-functions.principal-branches"], "est_minutes": 30, "difficulty": 4, "question": false}, {"id": "g12.cal.continuity-differentiability.exp-log-derivatives", "parent": "g12.cal.continuity-differentiability", "title": "Derivatives of Exponential and Logarithmic Functions", "description": "Use d/dx eˣ = eˣ, d/dx ln x = 1/x, d/dx aˣ = aˣ ln a, combined with the chain rule for forms like e^(3x²) and ln(sin x).", "outcomes": ["Can differentiate exponential and logarithmic compositions", "Can explain why aˣ needs the extra ln a factor"], "prereqs": ["g12.cal.continuity-differentiability.chain-rule"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.cal.continuity-differentiability.logarithmic-differentiation", "parent": "g12.cal.continuity-differentiability", "title": "Logarithmic Differentiation", "description": "For functions of the form u(x)^v(x) or unwieldy products/quotients, take ln of both sides, differentiate implicitly, and multiply back by y. The classic: d/dx xˣ = xˣ(1 + ln x).", "outcomes": ["Can differentiate xˣ and similar variable-power functions", "Can decide when logarithmic differentiation is the efficient route"], "prereqs": ["g12.cal.continuity-differentiability.exp-log-derivatives", "g12.cal.continuity-differentiability.implicit-differentiation"], "est_minutes": 25, "difficulty": 4, "question": false}, {"id": "g12.cal.continuity-differentiability.parametric-second-derivatives", "parent": "g12.cal.continuity-differentiability", "title": "Parametric Differentiation and Second Derivatives", "description": "For x = f(t), y = g(t), compute dy/dx = (dy/dt)/(dx/dt); iterate carefully for d²y/dx² by differentiating dy/dx with respect to t and dividing by dx/dt again. Compute second derivatives of explicit functions.", "outcomes": ["Can compute dy/dx for parametric curves like x = a cos t, y = a sin t", "Can compute second derivatives, including the parametric case"], "prereqs": ["g12.cal.continuity-differentiability.chain-rule"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g12.cal.applications-derivatives", "title": "Applications of Derivatives: Rates, Monotonicity, Maxima and Minima", "grade": 12, "strand": "cal", "description": "Derivatives go to work: related rates connect dA/dt to dr/dt through the chain rule; the sign of f′ tells where a function increases or decreases; and critical points, filtered through the first- or second-derivative test, locate maxima and minima. The crown jewels are optimisation problems — largest area, least cost, fastest route. This chapter is where calculus starts earning its keep in physics, economics and engineering.", "prereqs": ["g12.cal.continuity-differentiability", "g10.alg.quadratic-equations"], "outcomes": ["Can solve related-rates problems by differentiating a geometric relation with respect to time", "Can determine intervals of increase and decrease from the sign of f′", "Can find critical points and classify them using the first- or second-derivative test", "Can recognise critical points that are NOT extrema (e.g. x³ at 0) and check endpoints for absolute extrema on closed intervals", "Can set up and solve optimisation word problems, verifying the nature of the optimum"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": [{"id": "g12.cal.applications-derivatives.rate-of-change", "parent": "g12.cal.applications-derivatives", "title": "Derivative as an Instantaneous Rate of Change", "description": "Interpret dy/dx as the rate of change of y with respect to x in applied units — marginal cost, velocity, rate of area growth with radius — and evaluate rates at specific instants.", "outcomes": ["Can compute and interpret a rate of change with correct units", "Can translate 'rate of change of A with respect to r' into dA/dr"], "prereqs": ["g12.cal.continuity-differentiability.chain-rule"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g12.cal.applications-derivatives.related-rates", "parent": "g12.cal.applications-derivatives", "title": "Related Rates: Differentiating Through Time", "description": "When two quantities are linked by a geometric relation, differentiate the RELATION with respect to time t using the chain rule, and only then substitute the instant's values. Balloons, ladders, melting cubes.", "outcomes": ["Can set up dA/dt = (dA/dr)(dr/dt)-style chains from a geometric formula", "Can explain why substituting values before differentiating destroys the problem"], "prereqs": ["g12.cal.applications-derivatives.rate-of-change"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.cal.applications-derivatives.increasing-decreasing", "parent": "g12.cal.applications-derivatives", "title": "Increasing and Decreasing Functions via the Sign of f′", "description": "f is increasing where f′ > 0 and decreasing where f′ < 0. Solve the inequality f′(x) > 0, present intervals of monotonicity, and keep the sign of f itself firmly separate from the sign of f′.", "outcomes": ["Can find intervals of increase/decrease by solving f′(x) > 0 and f′(x) < 0", "Can articulate why the sign of f says nothing about monotonicity"], "prereqs": ["g12.cal.continuity-differentiability.chain-rule"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.cal.applications-derivatives.critical-points", "parent": "g12.cal.applications-derivatives", "title": "Critical Points and the First-derivative Test", "description": "Find points where f′ = 0 or f′ fails to exist, then classify them by the SIGN CHANGE of f′: + to − gives a local max, − to + a local min, no change (like x³ at 0) gives neither.", "outcomes": ["Can locate critical points and run the first-derivative sign test", "Can exhibit a critical point that is not an extremum"], "prereqs": ["g12.cal.applications-derivatives.increasing-decreasing"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g12.cal.applications-derivatives.second-derivative-test", "parent": "g12.cal.applications-derivatives", "title": "The Second-derivative Test", "description": "At a critical point c with f′(c) = 0: f″(c) < 0 means local max, f″(c) > 0 means local min, and f″(c) = 0 is inconclusive — fall back to the first-derivative test.", "outcomes": ["Can classify critical points using f″", "Can recognise the inconclusive case f″(c) = 0 and switch tests"], "prereqs": ["g12.cal.applications-derivatives.critical-points", "g12.cal.continuity-differentiability.parametric-second-derivatives"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g12.cal.applications-derivatives.absolute-extrema", "parent": "g12.cal.applications-derivatives", "title": "Absolute Extrema on a Closed Interval", "description": "On [a, b], the absolute maximum and minimum occur at critical points OR at the endpoints. Build the candidate list (critical points inside the interval plus both endpoints), evaluate f at each, and compare.", "outcomes": ["Can execute the closed-interval method completely, endpoints included", "Can discard critical points that fall outside the interval"], "prereqs": ["g12.cal.applications-derivatives.critical-points"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.cal.applications-derivatives.optimisation-problems", "parent": "g12.cal.applications-derivatives", "title": "Optimisation Word Problems", "description": "Translate a story (maximum area, minimum cost, fastest route) into a one-variable function using the constraint, find and classify its critical points, and answer in context with the nature of the optimum verified.", "outcomes": ["Can set up the objective function and eliminate a variable via the constraint", "Can verify max/min with a derivative test and state the answer with units"], "prereqs": ["g12.cal.applications-derivatives.second-derivative-test", "g12.cal.applications-derivatives.absolute-extrema", "g10.alg.quadratic-equations"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g12.cal.integrals", "title": "Integrals: Techniques and the Fundamental Theorem of Calculus", "grade": 12, "strand": "cal", "description": "Integration reverses differentiation: an indefinite integral is a whole family of antiderivatives, differing by the constant C. You will build a toolkit — substitution, integration by parts, partial fractions, and standard forms leading to logs and inverse trig — then meet the Fundamental Theorem of Calculus, which computes definite integrals as F(b) − F(a) and welds together the tangent problem and the area problem. It is arguably the single most powerful equation in mathematics.", "prereqs": ["g12.cal.continuity-differentiability", "g11.cal.limits-derivatives", "g12.tri.inverse-functions"], "outcomes": ["Can find antiderivatives of standard functions and always include the constant of integration", "Can integrate by substitution, recognising when an integrand contains a function and its derivative", "Can integrate by parts, choosing u by the ILATE heuristic, and handle products like x·eˣ", "Can evaluate definite integrals via the Fundamental Theorem as F(b) − F(a), respecting order and sign", "Can use partial fractions and properties of definite integrals (e.g. ∫₀ᵃ f(x)dx = ∫₀ᵃ f(a−x)dx) to simplify evaluation"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": [{"id": "g12.cal.integrals.antiderivative-idea", "parent": "g12.cal.integrals", "title": "The Antiderivative Idea and the Constant of Integration", "description": "Integration reverses differentiation: F is an antiderivative of f when F′ = f. Because constants die under d/dx, every answer carries + C — a whole family of curves, one for each constant.", "outcomes": ["Can antidifferentiate power functions with the reversed power rule (exponent up, then divide)", "Can explain why + C is mandatory and what it represents geometrically"], "prereqs": ["g11.cal.limits-derivatives", "g12.cal.continuity-differentiability.chain-rule"], "est_minutes": 20, "difficulty": 2, "question": true}, {"id": "g12.cal.integrals.standard-integrals-table", "parent": "g12.cal.integrals", "title": "The Table of Standard Integrals", "description": "Command the standard forms: xⁿ, 1/x, eˣ, aˣ, sin x, cos x, sec²x, 1/(1+x²), 1/√(1−x²) — each verified by differentiating the claimed answer, with special care on signs (∫sin x dx = −cos x + C).", "outcomes": ["Can quote and apply the standard integral table accurately, signs included", "Can verify any table entry by differentiation"], "prereqs": ["g12.cal.integrals.antiderivative-idea"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.cal.integrals.substitution-method", "parent": "g12.cal.integrals", "title": "Integration by Substitution", "description": "When the integrand contains a function AND (a constant multiple of) its derivative, set u equal to the inner function so du absorbs the derivative factor: ∫2x cos(x²) dx becomes ∫cos u du.", "outcomes": ["Can spot the u–du pair and carry out the substitution completely", "Can convert back to x and verify by differentiating"], "prereqs": ["g12.cal.integrals.standard-integrals-table", "g12.cal.continuity-differentiability.chain-rule"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g12.cal.integrals.integration-by-parts", "parent": "g12.cal.integrals", "title": "Integration by Parts", "description": "∫u dv = uv − ∫v du, with u chosen by ILATE (Inverse trig, Log, Algebraic, Trig, Exponential). Handles products like x·eˣ, x·sin x, ln x that substitution cannot touch.", "outcomes": ["Can choose u and dv sensibly and execute the formula", "Can handle repeated application and the ∫eˣ(f + f′) shortcut"], "prereqs": ["g12.cal.integrals.substitution-method"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.cal.integrals.partial-fractions", "parent": "g12.cal.integrals", "title": "Integration by Partial Fractions", "description": "Split a proper rational function with factorable denominator into simpler fractions — A/(x−a) + B/(x−b), with repeated-factor and quadratic-factor patterns — then integrate each piece to logarithms and arctangents.", "outcomes": ["Can decompose rational integrands with distinct and repeated linear factors", "Can integrate the resulting pieces, e.g. ∫dx/((x−1)(x+2))"], "prereqs": ["g12.cal.integrals.standard-integrals-table", "g10.alg.polynomials"], "est_minutes": 30, "difficulty": 4, "question": false}, {"id": "g12.cal.integrals.definite-integral-as-limit", "parent": "g12.cal.integrals", "title": "The Definite Integral as a Limit of Sums", "description": "∫ₐᵇ f(x) dx is the limit of Riemann sums: slice [a, b] into n strips, sum the strip areas f(xᵢ)·Δx, and let n → ∞. This is what the integral MEANS; the Fundamental Theorem is what makes it computable.", "outcomes": ["Can set up a Riemann sum for a simple function and pass to the limit", "Can interpret the definite integral as signed area accumulated from a to b"], "prereqs": ["g12.cal.integrals.antiderivative-idea", "g11.cal.limits-derivatives"], "est_minutes": 25, "difficulty": 4, "question": false}, {"id": "g12.cal.integrals.fundamental-theorem", "parent": "g12.cal.integrals", "title": "The Fundamental Theorem of Calculus", "description": "If F′ = f on [a, b], then ∫ₐᵇ f(x) dx = F(b) − F(a): upper-limit value minus lower-limit value, in that order, and no + C. The bridge between antiderivatives and areas.", "outcomes": ["Can evaluate definite integrals via F(b) − F(a) with correct order and signs", "Can explain why the constant of integration cancels in definite integrals"], "prereqs": ["g12.cal.integrals.definite-integral-as-limit", "g12.cal.integrals.standard-integrals-table"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.cal.integrals.properties-of-definite-integrals", "parent": "g12.cal.integrals", "title": "Properties of Definite Integrals", "description": "Exploit structure instead of computing: swapping limits flips the sign, ∫₀ᵃ f(x)dx = ∫₀ᵃ f(a−x)dx, splitting at an interior point, and even/odd symmetry on [−a, a] (odd integrands give 0).", "outcomes": ["Can apply the king property f(x) → f(a−x) to evaluate resistant integrals", "Can use even/odd symmetry and limit-splitting to shortcut evaluation"], "prereqs": ["g12.cal.integrals.fundamental-theorem"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g12.cal.applications-integrals", "title": "Applications of Integrals: Areas Under Curves", "grade": 12, "strand": "cal", "description": "The definite integral becomes a measuring tool: the area under a curve is ∫y dx, the area between two curves is the integral of (upper − lower), and regions bounded by parabolas, circles and lines yield to careful setup. The crucial subtlety is that a raw definite integral counts area below the x-axis as negative — geometric area requires splitting at the crossings and taking absolute values. Sketch first, integrate second.", "prereqs": ["g12.cal.integrals", "g11.geo.conic-sections"], "outcomes": ["Can sketch the region described by curves and lines before setting up any integral", "Can compute the area under a curve between two ordinates using a definite integral", "Can split an integral at x-axis crossings and combine absolute values to get true geometric area", "Can compute the area between two curves by integrating (upper − lower) between intersection points found algebraically"], "difficulty": 5, "est_minutes": 90, "stub": false, "micros": [{"id": "g12.cal.applications-integrals.sketch-region", "parent": "g12.cal.applications-integrals", "title": "Sketching the Region Before Integrating", "description": "Draw the curves, lines and axis limits first: find intercepts and intersection points, decide where each curve sits relative to the axis and to the other curve. The sketch dictates the limits and the integrand.", "outcomes": ["Can sketch regions bounded by a parabola/circle/line combination", "Can find intersection points algebraically to serve as integration limits"], "prereqs": ["g11.geo.conic-sections", "g12.cal.integrals.fundamental-theorem"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g12.cal.applications-integrals.area-under-curve", "parent": "g12.cal.applications-integrals", "title": "Area Under a Curve Between Two Ordinates", "description": "For f ≥ 0 on [a, b], the area between the curve, the x-axis and the ordinates x = a, x = b is ∫ₐᵇ f(x) dx. Also compute areas against the y-axis via ∫ x dy.", "outcomes": ["Can compute the area under a non-negative curve as a definite integral", "Can switch to y-integration when the region is naturally bounded by y-limits"], "prereqs": ["g12.cal.applications-integrals.sketch-region"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.cal.applications-integrals.area-sign-crossings", "parent": "g12.cal.applications-integrals", "title": "Handling Regions Below the Axis", "description": "The definite integral counts area below the x-axis as negative. For true geometric area, split the integral at every axis crossing and add ABSOLUTE values of the pieces — never let lobes cancel.", "outcomes": ["Can locate axis crossings and split the integral there", "Can report total geometric area as the sum of absolute lobe areas"], "prereqs": ["g12.cal.applications-integrals.area-under-curve"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g12.cal.applications-integrals.area-between-curves", "parent": "g12.cal.applications-integrals", "title": "Area Between Two Curves", "description": "Find the intersection points, establish which curve is on top over the interval, and integrate (upper − lower). If the curves swap positions, split the integral at the swap point.", "outcomes": ["Can find intersections and identify the upper curve on each sub-interval", "Can compute areas like the region between y = x and y = x²"], "prereqs": ["g12.cal.applications-integrals.area-under-curve"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.cal.applications-integrals.standard-regions", "parent": "g12.cal.applications-integrals", "title": "Areas of Standard Regions: Circles, Ellipses, Parabola–Line", "description": "Assemble the full toolkit on classic board configurations: area of a circle or ellipse by integration (using symmetry and quarter-regions), and mixed regions like a parabola cut by a chord.", "outcomes": ["Can derive the area of a circle x² + y² = a² or ellipse by integrating a quarter and multiplying by 4", "Can compute the area between a parabola and a chord line"], "prereqs": ["g12.cal.applications-integrals.area-between-curves", "g12.cal.applications-integrals.area-sign-crossings"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g12.cal.differential-equations", "title": "Differential Equations: Separable and First-order Linear", "grade": 12, "strand": "cal", "description": "A differential equation relates a function to its derivatives — it describes how something changes and asks you to recover the thing itself. You will read off order and degree, solve separable equations by gathering each variable to its own side, and solve first-order linear equations dy/dx + P(x)y = Q(x) with the integrating factor e^∫P dx. General solutions carry arbitrary constants; initial conditions pin down particular solutions. This is the native language of physics, biology and economics: growth, decay, cooling, circuits, epidemics.", "prereqs": ["g12.cal.integrals"], "outcomes": ["Can determine the order and degree (when defined) of a differential equation", "Can verify that a given function is a solution of a differential equation", "Can solve separable equations, keeping the arbitrary constant and simplifying it legitimately", "Can solve dy/dx + P(x)y = Q(x) using the integrating factor e^∫P dx", "Can apply initial conditions to extract particular solutions and model growth/decay situations"], "difficulty": 5, "est_minutes": 90, "stub": false, "micros": [{"id": "g12.cal.differential-equations.order-degree", "parent": "g12.cal.differential-equations", "title": "Order and Degree of a Differential Equation", "description": "Order = highest derivative present; degree = the power of THAT highest derivative once the equation is polynomial in its derivatives (and undefined otherwise). Two different dials — do not cross the wires.", "outcomes": ["Can read off order and degree, including when radicals must first be cleared", "Can recognise equations where the degree is not defined"], "prereqs": ["g12.cal.continuity-differentiability.parametric-second-derivatives"], "est_minutes": 15, "difficulty": 2, "question": true}, {"id": "g12.cal.differential-equations.verify-solutions", "parent": "g12.cal.differential-equations", "title": "Verifying Solutions of Differential Equations", "description": "Substitute a candidate function into the equation: differentiate it as many times as needed and check the identity holds for all x. Verification builds the meaning of 'solution' before any solving technique.", "outcomes": ["Can verify that a given function satisfies a given differential equation", "Can show a candidate FAILS to be a solution by exhibiting the mismatch"], "prereqs": ["g12.cal.differential-equations.order-degree", "g12.cal.continuity-differentiability.chain-rule"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g12.cal.differential-equations.general-particular", "parent": "g12.cal.differential-equations", "title": "General vs Particular Solutions", "description": "The general solution of an order-n equation carries n independent arbitrary constants; initial conditions pin them down to a particular solution. The number of constants matches the ORDER, not the degree.", "outcomes": ["Can distinguish general from particular solutions and count constants correctly", "Can apply an initial condition to extract the particular solution"], "prereqs": ["g12.cal.differential-equations.verify-solutions"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g12.cal.differential-equations.separable-equations", "parent": "g12.cal.differential-equations", "title": "Solving Separable Equations", "description": "Rewrite dy/dx = g(x)h(y) as dy/h(y) = g(x) dx — a multiplicative separation, never additive — integrate both sides, keep ONE arbitrary constant, and simplify it legitimately (e.g. e^C → A).", "outcomes": ["Can separate variables correctly and integrate both sides", "Can manage the constant of integration through exponentials and note solutions lost by division"], "prereqs": ["g12.cal.integrals.substitution-method", "g12.cal.differential-equations.general-particular"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g12.cal.differential-equations.integrating-factor", "parent": "g12.cal.differential-equations", "title": "First-order Linear Equations and the Integrating Factor", "description": "For dy/dx + P(x)y = Q(x), multiply through by IF = e^(∫P dx) — integrate P FIRST, then exponentiate — so the left side collapses to d/dx(y·IF); then y·IF = ∫Q·IF dx + C.", "outcomes": ["Can compute the integrating factor correctly", "Can solve equations like dy/dx + y/x = x² end to end"], "prereqs": ["g12.cal.differential-equations.separable-equations", "g12.cal.integrals.integration-by-parts"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.cal.differential-equations.growth-decay-models", "parent": "g12.cal.differential-equations", "title": "Modelling with Differential Equations: Growth and Decay", "description": "dy/dt = ky yields y = y₀e^(kt): exponential growth (k > 0) or decay (k < 0). Fit k and y₀ from data, and answer doubling-time / half-life style questions for populations, investments and radioactivity.", "outcomes": ["Can derive y = y₀e^(kt) from dy/dt = ky with an initial condition", "Can solve applied growth/decay problems including doubling time"], "prereqs": ["g12.cal.differential-equations.separable-equations"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g12.vec.algebra", "title": "Vector Algebra: Dot and Cross Products", "grade": 12, "strand": "vec", "description": "Vectors carry magnitude and direction, and two different 'multiplications' extract different geometry: the dot product a·b = |a||b|cos θ is a SCALAR measuring alignment (zero means perpendicular), while the cross product a×b is a VECTOR perpendicular to both, with magnitude |a||b|sin θ equal to the parallelogram's area (zero means parallel). You will compute both in component form, find projections, angles, areas and unit normals. This is the working mathematics of forces, torques and 3D graphics.", "prereqs": ["g11.vec.intro-3d", "g11.tri.functions"], "outcomes": ["Can represent vectors in component form, compute magnitudes, unit vectors and section-formula combinations", "Can compute dot products, use them to find angles and projections, and characterise perpendicularity by a·b = 0", "Can compute cross products via the determinant rule, use |a×b| for areas, and characterise parallelism by a×b = 0", "Can state which product yields a scalar and which a vector, and that a×b = −(b×a) while a·b = b·a"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": [{"id": "g12.vec.algebra.vector-basics", "parent": "g12.vec.algebra", "title": "Vectors in Component Form: Magnitude and Unit Vectors", "description": "Write vectors as xi + yj + zk, compute magnitude |a| = √(x² + y² + z²), build the unit vector a/|a|, and distinguish vectors (magnitude + direction) from scalars.", "outcomes": ["Can compute magnitudes and unit vectors in 3D", "Can identify equal, collinear and coinitial vectors from components"], "prereqs": ["g11.vec.intro-3d"], "est_minutes": 20, "difficulty": 2, "question": false}, {"id": "g12.vec.algebra.addition-section-formula", "parent": "g12.vec.algebra", "title": "Vector Addition and the Section Formula", "description": "Add vectors componentwise (triangle/parallelogram law) — magnitudes do NOT simply add unless the vectors are parallel. Use the section formula (mb + na)/(m + n) for points dividing a segment.", "outcomes": ["Can add and subtract vectors and interpret the triangle law geometrically", "Can find position vectors of internal/external division points"], "prereqs": ["g12.vec.algebra.vector-basics"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.vec.algebra.dot-product", "parent": "g12.vec.algebra", "title": "The Dot Product: a Scalar from Two Vectors", "description": "a·b = |a||b|cos θ = a₁b₁ + a₂b₂ + a₃b₃ — the output is a NUMBER. Use it to find the angle between vectors; it is commutative and distributes over addition.", "outcomes": ["Can compute dot products in component form", "Can extract cos θ = a·b/(|a||b|) and interpret its sign"], "prereqs": ["g12.vec.algebra.vector-basics", "g11.tri.functions"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.vec.algebra.projections", "parent": "g12.vec.algebra", "title": "Projection of One Vector on Another", "description": "The scalar projection of a on b is a·b/|b|, the vector projection is (a·b/|b|²)b. Interpret as the shadow of a along b's direction.", "outcomes": ["Can compute scalar and vector projections", "Can explain the difference between the two and when each is asked for"], "prereqs": ["g12.vec.algebra.dot-product"], "est_minutes": 20, "difficulty": 3, "question": false}, {"id": "g12.vec.algebra.perpendicularity", "parent": "g12.vec.algebra", "title": "Perpendicularity and the Zero Dot Product", "description": "For nonzero vectors, a·b = 0 means a ⊥ b — not that either vector vanishes. Use this test to find unknowns making vectors perpendicular and to verify orthogonality of i, j, k.", "outcomes": ["Can test and impose perpendicularity via a·b = 0", "Can state the correct logic: a·b = 0 ⟹ a = 0 or b = 0 or a ⊥ b"], "prereqs": ["g12.vec.algebra.dot-product"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g12.vec.algebra.cross-product", "parent": "g12.vec.algebra", "title": "The Cross Product via the Determinant Rule", "description": "a×b = |i j k; a₁ a₂ a₃; b₁ b₂ b₃| — the output is a VECTOR perpendicular to both, with |a×b| = |a||b|sin θ. It is anti-commutative: a×b = −(b×a).", "outcomes": ["Can compute cross products with the determinant expansion", "Can state and use a×b = −(b×a) and check the result is perpendicular to both inputs"], "prereqs": ["g12.vec.algebra.dot-product", "g12.alg.determinants.cofactor-expansion-3x3"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.vec.algebra.cross-applications", "parent": "g12.vec.algebra", "title": "Applications of the Cross Product: Areas and Parallelism", "description": "|a×b| is the area of the parallelogram on a and b (half it for the triangle); a×b = 0 for nonzero vectors means they are parallel. Compute areas of triangles from vertex coordinates.", "outcomes": ["Can compute parallelogram and triangle areas via cross products", "Can test collinearity/parallelism with a×b = 0"], "prereqs": ["g12.vec.algebra.cross-product"], "est_minutes": 25, "difficulty": 3, "question": false}]}, {"id": "g12.vec.3d-geometry", "title": "Three-Dimensional Geometry: Lines and Planes", "grade": 12, "strand": "vec", "description": "Vectors turn spatial geometry into computation: a line is r = a + λb (a point plus a direction), specified by direction ratios or the normalized direction cosines with l² + m² + n² = 1. You will find angles between lines using their direction vectors, the shortest distance between skew lines, and work with planes through their normal vectors — including the distance from a point to a plane. This is the geometry of flight paths, laser alignment and 3D modelling.", "prereqs": ["g12.vec.algebra", "g11.vec.intro-3d"], "outcomes": ["Can convert direction ratios to direction cosines by dividing by the magnitude, and verify l² + m² + n² = 1", "Can write vector and Cartesian equations of a line through a point with a given direction, or through two points", "Can compute the angle between two lines from their direction vectors and test parallel/perpendicular conditions", "Can find the shortest distance between skew lines and the distance from a point to a plane", "Can relate the angle between a line and a plane to the angle with the plane's normal (complementary angles)"], "difficulty": 5, "est_minutes": 105, "stub": false, "micros": [{"id": "g12.vec.3d-geometry.direction-cosines", "parent": "g12.vec.3d-geometry", "title": "Direction Ratios and Direction Cosines", "description": "Direction ratios a, b, c fix a line's direction up to scale; direction cosines l, m, n are the ratios NORMALISED by √(a² + b² + c²), so that l² + m² + n² = 1 always.", "outcomes": ["Can convert direction ratios to direction cosines by dividing by the magnitude", "Can verify l² + m² + n² = 1 and recover the angle each axis makes"], "prereqs": ["g12.vec.algebra.vector-basics"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g12.vec.3d-geometry.line-equations", "parent": "g12.vec.3d-geometry", "title": "Equations of a Line in Space", "description": "Write a line through point a with direction b as r = a + λb, and in Cartesian symmetric form (x−x₁)/a = (y−y₁)/b = (z−z₁)/c; also through two given points. Convert fluently between the two forms.", "outcomes": ["Can write vector and Cartesian equations of lines from point + direction or two points", "Can translate between the vector and symmetric forms"], "prereqs": ["g12.vec.3d-geometry.direction-cosines"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.vec.3d-geometry.angle-between-lines", "parent": "g12.vec.3d-geometry", "title": "Angle Between Two Lines; Parallel and Perpendicular Tests", "description": "cos θ = |b₁·b₂|/(|b₁||b₂|) from the direction vectors. Lines are parallel when direction ratios are proportional and perpendicular when a₁a₂ + b₁b₂ + c₁c₂ = 0 — keep the two tests straight.", "outcomes": ["Can compute the angle between lines from direction ratios", "Can apply the proportionality test for parallel and the zero-dot-product test for perpendicular"], "prereqs": ["g12.vec.3d-geometry.line-equations", "g12.vec.algebra.dot-product"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.vec.3d-geometry.skew-lines-distance", "parent": "g12.vec.3d-geometry", "title": "Shortest Distance Between Skew Lines", "description": "Skew lines neither meet nor run parallel. The shortest distance is |(a₂ − a₁)·(b₁×b₂)|/|b₁×b₂| — the projection of the connecting vector onto the common perpendicular direction b₁×b₂.", "outcomes": ["Can classify a pair of lines as intersecting, parallel or skew", "Can compute the shortest distance between skew lines with the formula"], "prereqs": ["g12.vec.3d-geometry.angle-between-lines", "g12.vec.algebra.cross-product"], "est_minutes": 30, "difficulty": 4, "question": false}, {"id": "g12.vec.3d-geometry.plane-equations", "parent": "g12.vec.3d-geometry", "title": "Equations of a Plane", "description": "A plane is fixed by its normal n: r·n = d (normal form) or ax + by + cz + d = 0 in Cartesian form, where (a, b, c) are the normal's direction ratios. Build plane equations from a point and normal, or three points.", "outcomes": ["Can write a plane's equation from point + normal and read off the normal from ax + by + cz + d = 0", "Can test whether points lie on, or lines lie in, a given plane"], "prereqs": ["g12.vec.3d-geometry.line-equations", "g12.vec.algebra.dot-product"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.vec.3d-geometry.angle-line-plane", "parent": "g12.vec.3d-geometry", "title": "Angle Between a Line and a Plane", "description": "The line's direction meets the plane's NORMAL at some angle θ; the angle with the plane itself is the complement 90° − θ, computed via sin φ = |b·n|/(|b||n|). Parallel/perpendicular tests follow from the normal.", "outcomes": ["Can compute the angle between a line and a plane via the normal", "Can state why the line–normal and line–plane angles are complementary"], "prereqs": ["g12.vec.3d-geometry.plane-equations"], "est_minutes": 20, "difficulty": 3, "question": true}, {"id": "g12.vec.3d-geometry.point-plane-distance", "parent": "g12.vec.3d-geometry", "title": "Distance from a Point to a Plane", "description": "Distance from (x₁, y₁, z₁) to ax + by + cz + d = 0 is |ax₁ + by₁ + cz₁ + d| / √(a² + b² + c²) — the division by |n| is what converts the raw substitution into a genuine length.", "outcomes": ["Can compute point-to-plane distances with correct normalisation", "Can find the distance between parallel planes via a point on one of them"], "prereqs": ["g12.vec.3d-geometry.plane-equations"], "est_minutes": 20, "difficulty": 3, "question": true}]}, {"id": "g12.alg.linear-programming", "title": "Linear Programming", "grade": 12, "strand": "alg", "description": "Linear programming optimises a linear objective Z = ax + by subject to linear constraints: graph the inequalities, intersect them into a feasible region, and use the corner-point theorem — the optimum, if it exists, occurs at a vertex. Unbounded regions demand one extra check before declaring victory. Born from wartime logistics, LP now schedules airlines, blends diets, allocates factory time and routes deliveries.", "prereqs": ["g11.alg.linear-inequalities", "g11.geo.straight-lines"], "outcomes": ["Can translate a word problem into decision variables, a linear objective function and linear constraints", "Can graph the constraints and identify the feasible region, including non-negativity restrictions", "Can apply the corner-point method: find vertices, evaluate Z at each, and select the optimum", "Can handle unbounded regions correctly, checking whether the candidate optimum is genuine via the open half-plane test"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": [{"id": "g12.alg.linear-programming.formulate-lpp", "parent": "g12.alg.linear-programming", "title": "Formulating a Linear Programming Problem", "description": "Extract decision variables from the story, write the linear objective function Z to maximise or minimise, and translate every resource limit and requirement into a linear constraint — including x ≥ 0, y ≥ 0.", "outcomes": ["Can define variables and write the objective function from a word problem", "Can list ALL constraints including non-negativity"], "prereqs": ["g11.alg.linear-inequalities"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.alg.linear-programming.feasible-region", "parent": "g12.alg.linear-programming", "title": "Graphing Constraints and the Feasible Region", "description": "Plot each constraint line, shade the correct half-plane (test with the origin), and intersect all shaded regions with the first quadrant to obtain the feasible region — the set of all allowed decisions.", "outcomes": ["Can shade the correct side of each constraint using a test point", "Can identify the feasible region and its vertices from the graph"], "prereqs": ["g12.alg.linear-programming.formulate-lpp", "g11.geo.straight-lines"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.alg.linear-programming.corner-point-method", "parent": "g12.alg.linear-programming", "title": "The Corner-point Method", "description": "For a bounded feasible region, the optimum of a linear objective occurs at a VERTEX: find all corner points (intersections that actually lie in the region), evaluate Z at each, and pick the best.", "outcomes": ["Can find corner points by solving pairs of boundary equations and discarding infeasible intersections", "Can evaluate Z at every vertex and identify maximum and minimum"], "prereqs": ["g12.alg.linear-programming.feasible-region"], "est_minutes": 30, "difficulty": 3, "question": true}, {"id": "g12.alg.linear-programming.unbounded-regions", "parent": "g12.alg.linear-programming", "title": "Optima on Unbounded Feasible Regions", "description": "With an unbounded region the corner-point value is only a CANDIDATE: the optimum exists iff the open half-plane beyond it (Z > M for max, Z < m for min) shares no point with the region. Run this check every time.", "outcomes": ["Can perform the open half-plane test on an unbounded region", "Can decide whether a candidate optimum is genuine or the problem has no optimum"], "prereqs": ["g12.alg.linear-programming.corner-point-method"], "est_minutes": 25, "difficulty": 4, "question": true}, {"id": "g12.alg.linear-programming.applied-problems", "parent": "g12.alg.linear-programming", "title": "Applied LPP: Diet, Manufacturing and Transport", "description": "Solve complete board-style problems end to end: formulate from the story, graph, run the corner-point method, and interpret the optimal vertex as a real decision (units to produce, packets to buy).", "outcomes": ["Can solve a full two-variable LPP word problem from text to interpreted answer", "Can sanity-check the answer against the constraints and context"], "prereqs": ["g12.alg.linear-programming.corner-point-method"], "est_minutes": 30, "difficulty": 4, "question": false}]}, {"id": "g12.dat.probability", "title": "Probability: Conditional Probability, Bayes' Theorem, Random Variables", "grade": 12, "strand": "dat", "description": "Probability learns from information: P(A|B) re-weights chances given that B occurred, the multiplication rule chains events, and independence means P(A∩B) = P(A)P(B). Bayes' theorem reverses conditionals — from P(evidence|cause) to P(cause|evidence) — the logic behind medical testing and spam filters, where base rates routinely humiliate intuition. Random variables then attach numbers to outcomes, with probability distributions and means (expected values) to summarise them.", "prereqs": ["g11.dat.probability"], "outcomes": ["Can compute conditional probabilities from the definition P(A|B) = P(A∩B)/P(B) and from two-way tables", "Can apply the multiplication rule and test events for independence via P(A∩B) = P(A)P(B)", "Can distinguish independent events from mutually exclusive events with examples", "Can apply the total probability theorem and Bayes' theorem to reverse conditional probabilities", "Can construct the probability distribution of a discrete random variable and compute its mean (expected value)"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": [{"id": "g12.dat.probability.conditional-probability", "parent": "g12.dat.probability", "title": "Conditional Probability from the Definition", "description": "P(A|B) = P(A∩B)/P(B) re-scales probability to the world where B has happened. Compute it from given probabilities and from two-way tables, and keep P(A|B) firmly distinct from P(B|A).", "outcomes": ["Can compute conditional probabilities from the definition and from tables", "Can explain with an example why P(A|B) ≠ P(B|A) in general"], "prereqs": ["g11.dat.probability"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.dat.probability.multiplication-rule", "parent": "g12.dat.probability", "title": "The Multiplication Rule for Dependent Events", "description": "P(A∩B) = P(A)·P(B|A): the second factor must be CONDITIONED on the first event having happened. Essential for without-replacement draws, where the sample space shrinks between picks.", "outcomes": ["Can chain conditional probabilities for sequential draws without replacement", "Can decide when the second factor needs updating and when it does not"], "prereqs": ["g12.dat.probability.conditional-probability"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.dat.probability.independence", "parent": "g12.dat.probability", "title": "Independent Events vs Mutually Exclusive Events", "description": "A and B are independent when P(A∩B) = P(A)P(B) — knowing one occurred doesn't change the other's probability. Mutually exclusive events CANNOT co-occur, and (for positive-probability events) are never independent.", "outcomes": ["Can test independence numerically with P(A∩B) = P(A)P(B)", "Can articulate the difference between independent and mutually exclusive with examples"], "prereqs": ["g12.dat.probability.multiplication-rule"], "est_minutes": 25, "difficulty": 3, "question": true}, {"id": "g12.dat.probability.total-probability", "parent": "g12.dat.probability", "title": "The Theorem of Total Probability", "description": "When events E₁, ..., Eₙ partition the sample space, P(A) = Σ P(Eᵢ)P(A|Eᵢ): the overall probability of A is the prior-weighted average over the scenarios. Tree diagrams make the sum visible.", "outcomes": ["Can compute P(A) across a partition using a tree diagram", "Can verify the partition is genuine (exhaustive and mutually exclusive) before applying the theorem"], "prereqs": ["g12.dat.probability.multiplication-rule"], "est_minutes": 25, "difficulty": 4, "question": false}, {"id": "g12.dat.probability.bayes-theorem", "parent": "g12.dat.probability", "title": "Bayes' Theorem: Reversing the Conditional", "description": "P(Eᵢ|A) = P(Eᵢ)P(A|Eᵢ) / Σ P(Eⱼ)P(A|Eⱼ): update a prior in the light of evidence. The denominator is the total probability of the evidence; the prior must never be ignored, however accurate the 'test'.", "outcomes": ["Can set up the Bayes numerator and total-probability denominator correctly", "Can explain base-rate neglect with a rare-disease example"], "prereqs": ["g12.dat.probability.total-probability"], "est_minutes": 30, "difficulty": 4, "question": true}, {"id": "g12.dat.probability.random-variables", "parent": "g12.dat.probability", "title": "Discrete Random Variables and Probability Distributions", "description": "A random variable assigns a number to each outcome; its probability distribution lists each value with its probability, all probabilities non-negative and summing to 1. Build distributions for coin, die and card experiments.", "outcomes": ["Can construct the distribution table of a discrete random variable", "Can use Σpᵢ = 1 to find an unknown probability in a table"], "prereqs": ["g12.dat.probability.multiplication-rule"], "est_minutes": 25, "difficulty": 3, "question": false}, {"id": "g12.dat.probability.expected-value", "parent": "g12.dat.probability", "title": "Mean (Expected Value) of a Random Variable", "description": "E(X) = Σ xᵢpᵢ: the probability-weighted average of the values — the long-run average per trial, not the most likely single outcome. Compute and interpret means of small discrete distributions.", "outcomes": ["Can compute E(X) from a distribution table", "Can interpret the mean as a long-run average, including non-attainable values like 3.5 for a die"], "prereqs": ["g12.dat.probability.random-variables"], "est_minutes": 20, "difficulty": 3, "question": true}]}]};
